# Scratch / temp layout
# --------------------------


def _read_meminfo_bytes() -> Dict[str, int]:
    info: Dict[str, int] = {}
    try:
        for line in Path('/proc/meminfo').read_text().splitlines():
            parts = line.split(':', 1)
            if len(parts) != 2:
                continue
            key = parts[0].strip()
            raw_val = parts[1].strip().split()[0]
            info[key] = int(raw_val) * 1024
    except Exception:
        pass
    return info


def _cgroup_read_int(path: Path) -> Optional[int]:
    try:
        raw = path.read_text().strip()
    except Exception:
        return None
    if not raw or raw == 'max':
        return None
    try:
        value = int(raw)
    except Exception:
        return None
    # cgroup v1 reports "unlimited" as a huge page-rounded sentinel (~2^63).
    if value <= 0 or value >= (1 << 60):
        return None
    return value


def _cgroup_reclaimable_file_bytes(node: Path, *, v2: bool) -> int:
    """Reclaimable file-cache bytes charged to this cgroup subtree (0 when unreadable).

    memory.current/usage_in_bytes charge the job's OWN page cache, and this pipeline
    streams hundreds of GiB through file-backed memmaps and ffmpeg decode, so the raw
    counter sits at the limit as a steady state while the kernel would happily reclaim
    those clean file pages before OOM-killing. Subtract inactive_file (v2) /
    total_inactive_file (v1) to approximate the kernel's own MemAvailable-style
    working-set view — otherwise every workspace silently flips to disk mid-run.
    """
    key = 'inactive_file' if v2 else 'total_inactive_file'
    try:
        for line in (node / 'memory.stat').read_text().splitlines():
            parts = line.split()
            if len(parts) == 2 and parts[0] == key:
                try:
                    return max(0, int(parts[1]))
                except Exception:
                    return 0
    except Exception:
        pass
    return 0


def _cgroup_memory_headroom_bytes() -> Optional[int]:
    """Tightest (limit - working-set usage) across this process's cgroup ancestry, or None if unlimited.

    SLURM's ConstrainRAMSpace enforces --mem through the job cgroup, so /proc/meminfo wildly
    overstates what THIS job may still allocate on a shared node, and exceeding the cgroup limit
    is an uncatchable OOM SIGKILL rather than a MemoryError (v13.2.2 bug #1). The limit may sit on
    any ancestor (job / step / task cgroup), so walk from the leaf to the mount root and keep the
    smallest headroom seen. Usage is corrected for reclaimable file cache (see
    _cgroup_reclaimable_file_bytes).
    """
    try:
        cgroup_text = Path('/proc/self/cgroup').read_text()
    except Exception:
        return None
    headroom: Optional[int] = None
    for line in cgroup_text.splitlines():
        parts = line.split(':', 2)
        if len(parts) != 3:
            continue
        hierarchy_id, controllers, cg_path = parts
        if hierarchy_id == '0' and not controllers:
            # cgroup v2 unified hierarchy.
            is_v2 = True
            base = Path('/sys/fs/cgroup')
            limit_name, usage_name = 'memory.max', 'memory.current'
        elif 'memory' in controllers.split(','):
            # cgroup v1 memory controller.
            is_v2 = False
            base = Path('/sys/fs/cgroup/memory')
            limit_name, usage_name = 'memory.limit_in_bytes', 'memory.usage_in_bytes'
        else:
            continue
        node = base / cg_path.lstrip('/')
        while node == base or base in node.parents:
            limit = _cgroup_read_int(node / limit_name)
            if limit is not None:
                usage = int(_cgroup_read_int(node / usage_name) or 0)
                usage = max(0, usage - _cgroup_reclaimable_file_bytes(node, v2=is_v2))
                level_headroom = max(0, int(limit) - usage)
                headroom = level_headroom if headroom is None else min(headroom, level_headroom)
            if node == base:
                break
            node = node.parent
    return headroom


def available_anon_work_bytes() -> int:
    info = _read_meminfo_bytes()
    mem_avail = int(info.get('MemAvailable', 0))
    swap_free = int(info.get('SwapFree', 0))
    node_avail = max(0, mem_avail + swap_free)
    if _env_flag('YOLO_TTA_IGNORE_CGROUP_MEMORY_LIMIT', False):
        return node_avail
    cgroup_headroom = _cgroup_memory_headroom_bytes()
    if cgroup_headroom is None:
        return node_avail
    # Under a cgroup limit do not count node-wide swap: the cgroup charge is what the OOM killer
    # enforces (cluster cgroups commonly run with memory.swap.max=0 / memsw==mem), and blowing it
    # is an uncatchable SIGKILL that bypasses the MemoryError -> disk-memmap fallback, so err on
    # the tight side.
    return min(node_avail, int(cgroup_headroom))


def _env_float(name: str, default: float) -> float:
    raw = os.environ.get(name, '').strip()
    if not raw:
        return float(default)
    try:
        return float(raw)
    except Exception:
        return float(default)


def _env_int(name: str, default: int) -> int:
    raw = os.environ.get(name, '').strip()
    if not raw:
        return int(default)
    try:
        return int(raw)
    except Exception:
        return int(default)


def _slurm_allocated_cpu_count() -> Optional[int]:
    for env_name in ('SLURM_CPUS_PER_TASK', 'SLURM_CPUS_ON_NODE', 'SLURM_JOB_CPUS_PER_NODE'):
        raw = os.environ.get(env_name, '').strip()
        if not raw:
            continue
        m = re.search(r'(\d+)', raw)
        if m is not None:
            try:
                return max(1, int(m.group(1)))
            except Exception:
                continue
    return None


def _cpu_count() -> int:
    try:
        affinity = os.sched_getaffinity(0)
        if affinity:
            return max(1, int(len(affinity)))
    except Exception:
        pass

    slurm_cpus = _slurm_allocated_cpu_count()
    if slurm_cpus is not None:
        return max(1, int(slurm_cpus))

    return max(1, int(os.cpu_count() or 1))


# --------------------------
# v13.3.5 (N1/N2): NUMA-aware handling — topology discovery, GPU-worker pinning, page interleave
# --------------------------
# Implements 1.E of SPEED_OPTIMIZATIONS_Fable-5_v13.3.2_SLURM.md. Everything here is
# best-effort and Linux-only: a non-Linux box, hidden sysfs topology, an unexpected kernel, or
# a failing syscall degrades to the previous behavior (no pinning, first-touch placement)
# instead of failing the run. No root and no external packages are required (pynvml is used as
# an optional fallback for GPU->node mapping when the driver procfs is unavailable).


def numa_enabled() -> bool:
    """Master switch for all v13.3.5 NUMA handling (YOLO_TTA_NUMA=0 disables)."""
    return sys.platform.startswith('linux') and _env_flag('YOLO_TTA_NUMA', True)


def numa_worker_pin_enabled() -> bool:
    """v13.3.5 (N1): pin each GPU worker's threads to its GPU's NUMA node (=0 disables)."""
    return _env_flag('YOLO_TTA_NUMA_WORKER_PIN', True)


def numa_interleave_enabled() -> bool:
    """v13.3.5 (N2): mbind big shared allocations MPOL_INTERLEAVE (=0 disables)."""
    return _env_flag('YOLO_TTA_NUMA_INTERLEAVE', True)


def _parse_id_list(text: str) -> set:
    """Parse a kernel id-list string ('0-3,8,10-11') into a set of ints."""
    out: set = set()
    for part in str(text).strip().split(','):
        part = part.strip()
        if not part:
            continue
        if '-' in part:
            lo_s, _, hi_s = part.partition('-')
            out.update(range(int(lo_s), int(hi_s) + 1))
        else:
            out.add(int(part))
    return out


_NUMA_TOPOLOGY_CACHE: Optional[Tuple[bool, Optional[Dict[str, object]]]] = None
_NUMA_TOPOLOGY_LOCK = threading.Lock()


def numa_topology() -> Optional[Dict[str, object]]:
    """Allocation-aware NUMA topology, or None when undiscoverable.

    Returns {'node_cpus': {node_id: set(ALLOCATED cpus on that node)},  # only non-empty nodes
             'cpu_to_node': {allocated cpu: node_id},
             'allowed_mems': set(node ids from Mems_allowed_list)}.
    Everything is intersected with this process's cpuset, so lopsided SLURM allocations are
    represented as-is. Cached per process (spawn children re-derive their own view).
    """
    global _NUMA_TOPOLOGY_CACHE
    cached = _NUMA_TOPOLOGY_CACHE
    if cached is not None:
        return cached[1]
    with _NUMA_TOPOLOGY_LOCK:
        cached = _NUMA_TOPOLOGY_CACHE
        if cached is not None:
            return cached[1]
        topo: Optional[Dict[str, object]] = None
        try:
            if numa_enabled() and hasattr(os, 'sched_getaffinity'):
                allowed_cpus = {int(c) for c in os.sched_getaffinity(0)}
                node_root = '/sys/devices/system/node'
                node_cpus: Dict[int, set] = {}
                cpu_to_node: Dict[int, int] = {}
                for entry in sorted(os.listdir(node_root)):
                    m = re.fullmatch(r'node(\d+)', entry)
                    if m is None:
                        continue
                    node_id = int(m.group(1))
                    try:
                        with open(os.path.join(node_root, entry, 'cpulist'), 'r', encoding='ascii') as fh:
                            cpus = _parse_id_list(fh.read()) & allowed_cpus
                    except OSError:
                        continue
                    if cpus:
                        node_cpus[node_id] = cpus
                        for c in cpus:
                            cpu_to_node[int(c)] = node_id
                allowed_mems: set = set()
                try:
                    with open('/proc/self/status', 'r', encoding='ascii', errors='replace') as fh:
                        for line in fh:
                            if line.startswith('Mems_allowed_list:'):
                                allowed_mems = _parse_id_list(line.split(':', 1)[1])
                                break
                except OSError:
                    pass
                if not allowed_mems:
                    allowed_mems = set(node_cpus.keys())
                if node_cpus:
                    topo = {'node_cpus': node_cpus, 'cpu_to_node': cpu_to_node, 'allowed_mems': allowed_mems}
        except Exception:
            topo = None
        _NUMA_TOPOLOGY_CACHE = (True, topo)
        return topo


def _nvidia_gpu_inventory() -> List[Dict[str, object]]:
    """[{'bdf', 'uuid', 'minor'}] for every GPU the NVIDIA driver exposes via procfs."""
    entries: List[Dict[str, object]] = []
    root = '/proc/driver/nvidia/gpus'
    for name in sorted(os.listdir(root)):
        info_path = os.path.join(root, name, 'information')
        uuid: Optional[str] = None
        minor: Optional[int] = None
        try:
            with open(info_path, 'r', encoding='ascii', errors='replace') as fh:
                for line in fh:
                    if line.startswith('GPU UUID'):
                        uuid = line.split(':', 1)[1].strip()
                    elif line.startswith('Device Minor'):
                        try:
                            minor = int(line.split(':', 1)[1].strip())
                        except ValueError:
                            minor = None
        except OSError:
            continue
        entries.append({'bdf': str(name).lower(), 'uuid': uuid, 'minor': minor})
    return entries


def _numa_node_of_pci_device(bdf: str, topo: Dict[str, object]) -> Optional[int]:
    """NUMA node of a PCI device, restricted to nodes that hold allocated cpus."""
    node_cpus: Dict[int, set] = topo['node_cpus']  # type: ignore[assignment]
    base = f'/sys/bus/pci/devices/{str(bdf).lower()}'
    try:
        with open(base + '/numa_node', 'r', encoding='ascii') as fh:
            node = int(fh.read().strip())
        if node >= 0 and node in node_cpus:
            return node
    except (OSError, ValueError):
        pass
    # numa_node can be -1 (BIOS/kernel hides it); local_cpulist often still knows.
    try:
        with open(base + '/local_cpulist', 'r', encoding='ascii') as fh:
            local_cpus = _parse_id_list(fh.read())
        cpu_to_node: Dict[int, int] = topo['cpu_to_node']  # type: ignore[assignment]
        counts: Dict[int, int] = {}
        for c in local_cpus:
            nd = cpu_to_node.get(int(c))
            if nd is not None:
                counts[nd] = counts.get(nd, 0) + 1
        if counts:
            return max(counts.items(), key=lambda kv: kv[1])[0]
    except (OSError, ValueError):
        pass
    return None


def _resolve_gpu_numa_node(cvd_token: str, topo: Dict[str, object]) -> Optional[int]:
    """Map one CUDA_VISIBLE_DEVICES token (minor index or GPU UUID) to its NUMA node.

    Tokens come from the inherited CUDA_VISIBLE_DEVICES (SLURM sets minor indices or GPU
    UUIDs), i.e. the NVML/driver device domain — NOT torch's logical order — so they match
    the driver procfs 'Device Minor' / 'GPU UUID' fields directly. MIG instance tokens are
    not listed there; those resolve to None (worker stays unpinned).
    """
    tok = str(cvd_token).strip()
    if not tok or tok.upper().startswith('MIG-'):
        return None
    try:
        inventory = _nvidia_gpu_inventory()
    except Exception:
        inventory = []
    match: Optional[Dict[str, object]] = None
    if tok.upper().startswith('GPU-'):
        for e in inventory:
            if str(e.get('uuid') or '').lower() == tok.lower():
                match = e
                break
    else:
        try:
            minor = int(tok)
        except ValueError:
            minor = None
        if minor is not None:
            for e in inventory:
                if e.get('minor') == minor:
                    match = e
                    break
    if match is not None:
        node = _numa_node_of_pci_device(str(match['bdf']), topo)
        if node is not None:
            return node
    # Optional fallback: pynvml (pip package), for boxes without the driver procfs.
    try:
        import pynvml  # type: ignore[import-not-found]
        pynvml.nvmlInit()
        try:
            if tok.upper().startswith('GPU-'):
                handle = pynvml.nvmlDeviceGetHandleByUUID(tok.encode('ascii'))
            else:
                handle = pynvml.nvmlDeviceGetHandleByIndex(int(tok))
            pci = pynvml.nvmlDeviceGetPciInfo(handle)
            bus_id = pci.busId.decode('ascii', 'replace') if isinstance(pci.busId, bytes) else str(pci.busId)
            bdf = bus_id.strip().strip('\x00').lower()
            if len(bdf.split(':', 1)[0]) == 8:
                bdf = bdf[4:]  # NVML uses a 32-bit domain; sysfs uses 4 hex digits
            return _numa_node_of_pci_device(bdf, topo)
        finally:
            try:
                pynvml.nvmlShutdown()
            except Exception:
                pass
    except Exception:
        return None


def plan_gpu_worker_affinity(worker_tokens: Sequence[str]) -> List[Optional[List[int]]]:
    """v13.3.5 (N1): per-worker CPU pin sets; None entries stay unpinned.

    Discovery-driven — no GPU<->socket balance is assumed. GPUs and allocated cpus are each
    bucketed by measured NUMA node and every node's cpus are split evenly among ITS OWN
    workers (the last slice absorbs the remainder), so 2+2 / 3+1 / 4+0 splits, lopsided
    cpusets and sub-NUMA clustering all fall out of the same arithmetic. A node whose
    per-worker share is below YOLO_TTA_NUMA_WORKER_MIN_CORES gives each of its workers the
    whole (overlapping) node instead of a starved slice.
    """
    n = len(worker_tokens)
    plan: List[Optional[List[int]]] = [None] * n
    if n == 0 or not (numa_enabled() and numa_worker_pin_enabled()):
        return plan
    topo = numa_topology()
    if topo is None:
        print('[numa] worker pinning inactive: NUMA topology not discoverable')
        return plan
    node_cpus: Dict[int, set] = topo['node_cpus']  # type: ignore[assignment]
    if len(node_cpus) < 2:
        print('[numa] worker pinning inactive: allocation spans a single NUMA node')
        return plan
    node_of: List[Optional[int]] = []
    by_node: Dict[int, List[int]] = {}
    for i, tok in enumerate(worker_tokens):
        node = _resolve_gpu_numa_node(str(tok), topo)
        node_of.append(node)
        if node is not None and node in node_cpus:
            by_node.setdefault(int(node), []).append(i)
    min_cores = max(1, _env_int('YOLO_TTA_NUMA_WORKER_MIN_CORES', 4))
    for node, idxs in sorted(by_node.items()):
        cpus = sorted(node_cpus[int(node)])
        share = len(cpus) // len(idxs)
        if share < min_cores:
            for i in idxs:
                plan[i] = list(cpus)
            continue
        for j, i in enumerate(idxs):
            lo = j * share
            hi = (j + 1) * share if j + 1 < len(idxs) else len(cpus)
            plan[i] = list(cpus[lo:hi])
    for i, tok in enumerate(worker_tokens):
        cpus_i = plan[i]
        if cpus_i is not None:
            print(f'[numa] gpu-worker {i} (token {tok}): node {node_of[i]}, {len(cpus_i)} cpu(s)')
        else:
            reason = 'gpu node unresolved' if node_of[i] is None else f'node {node_of[i]} holds no allocated cpus'
            print(f'[numa] gpu-worker {i} (token {tok}): unpinned ({reason})')
    return plan


def _sched_setaffinity_all_threads(cpus: Sequence[int]) -> bool:
    """Apply a CPU mask to EVERY thread of this process (Linux affinity is per-thread;
    os.sched_setaffinity(0, ...) alone would only move the calling thread)."""
    if not hasattr(os, 'sched_setaffinity'):
        return False
    cpu_set = {int(c) for c in cpus}
    if not cpu_set:
        return False
    try:
        tids = sorted(int(t) for t in os.listdir('/proc/self/task'))
    except (OSError, ValueError):
        tids = [0]  # 0 == calling thread
    ok = False
    for tid in tids:
        try:
            os.sched_setaffinity(tid, cpu_set)
            ok = True
        except OSError:
            continue  # thread exited between listdir and the call
    return ok


# Worker-process pin state (set inside _gpu_inference_worker_main; spawn children only).
_GPU_WORKER_NUMA_PIN: Optional[set] = None
_GPU_WORKER_NUMA_FULL: Optional[set] = None

_NUMA_MBIND_STATE = {'failed': False, 'announced': False}


def _numa_interleave_range(addr: int, nbytes: int, mems: Sequence[int]) -> bool:
    """mbind(start, len, MPOL_INTERLEAVE, nodemask, maxnode, 0) via the raw syscall (no libnuma)."""
    if _NUMA_MBIND_STATE['failed']:
        return False
    try:
        machine = str(os.uname().machine)
    except Exception:
        _NUMA_MBIND_STATE['failed'] = True
        return False
    syscall_nr = {'x86_64': 237, 'aarch64': 235}.get(machine)
    max_node = max(int(m) for m in mems)
    if syscall_nr is None or max_node >= 64:
        _NUMA_MBIND_STATE['failed'] = True
        print(f'Warning: [numa] mbind unsupported here (machine={machine}, max node={max_node}); '
              f'page interleave disabled for this process.')
        return False
    try:
        import ctypes
        libc = ctypes.CDLL(None, use_errno=True)
        page = int(mmap.PAGESIZE)
        start = int(addr) & ~(page - 1)
        length = int(nbytes) + (int(addr) - start)
        mask = 0
        for m in mems:
            mask |= 1 << int(m)
        nodemask = ctypes.c_ulong(mask)
        rc = libc.syscall(
            int(syscall_nr),
            ctypes.c_void_p(start),
            ctypes.c_size_t(length),
            ctypes.c_int(3),  # MPOL_INTERLEAVE
            ctypes.byref(nodemask),
            ctypes.c_ulong(65),  # maxnode: one 64-bit word of nodemask
            ctypes.c_uint(0),
        )
        if int(rc) != 0:
            err = int(ctypes.get_errno())
            _NUMA_MBIND_STATE['failed'] = True
            print(f'Warning: [numa] mbind(MPOL_INTERLEAVE) failed (errno {err}); '
                  f'page interleave disabled for this process.')
            return False
        return True
    except Exception as exc:
        _NUMA_MBIND_STATE['failed'] = True
        print(f'Warning: [numa] mbind unavailable ({exc}); page interleave disabled for this process.')
        return False


def numa_interleave_memory(arr: object, desc: str = '') -> bool:
    """v13.3.5 (N2): round-robin a big shared buffer's pages across the allowed NUMA nodes.

    Called by the ALLOCATION paths right after creating a buffer and before first touch — the
    only moment placement can still be chosen (unprivileged MPOL_MF_MOVE cannot migrate shared
    multi-process pages later). Keyed on how the buffer was allocated, never on a mount point:
    anonymous RAM and tmpfs/shm mappings both take the policy; regular on-disk file mappings
    are silently unaffected. No-ops (returning False) when: NUMA handling is off, topology is
    unknown, only one memory node is allowed, the buffer is below
    YOLO_TTA_NUMA_INTERLEAVE_MIN_MIB, or this process's current affinity sits inside a single
    node (a pinned GPU worker's first-touch is already the better, local placement).
    """
    if arr is None or not (numa_enabled() and numa_interleave_enabled()):
        return False
    topo = numa_topology()
    if topo is None:
        return False
    mems = sorted(int(m) for m in topo['allowed_mems'])  # type: ignore[call-overload]
    if len(mems) < 2:
        return False
    try:
        a = np.asarray(arr)
        if a.nbytes <= 0 or not a.flags['C_CONTIGUOUS']:
            return False
        min_bytes = max(0, _env_int('YOLO_TTA_NUMA_INTERLEAVE_MIN_MIB', 64)) * 1024 * 1024
        if int(a.nbytes) < int(min_bytes):
            return False
        if hasattr(os, 'sched_getaffinity'):
            cpu_to_node: Dict[int, int] = topo['cpu_to_node']  # type: ignore[assignment]
            nodes_now = {cpu_to_node.get(int(c)) for c in os.sched_getaffinity(0)}
            nodes_now.discard(None)
            if len(nodes_now) < 2:
                return False
        addr = int(a.ctypes.data)
        if addr == 0:
            return False
        ok = _numa_interleave_range(addr, int(a.nbytes), mems)
        if ok and not _NUMA_MBIND_STATE['announced']:
            _NUMA_MBIND_STATE['announced'] = True
            print(f'[numa] interleaving big shared allocations across nodes {mems} '
                  f'(first: {desc or "unnamed"}, {a.nbytes / GIB:.1f} GiB; YOLO_TTA_NUMA_INTERLEAVE=0 disables)')
        return ok
    except Exception:
        return False


def default_worker_budget() -> int:
    """Intentional CPU oversubscription for mixed GPU/IO/CPU workloads.

    The v12.2.0 SLURM target has enough CPU headroom that running roughly 2x the visible CPU count
    helps keep in-memory view-volume construction, interpolation planning, and output writers busy while the GPU
    is inferencing or waiting on a different stage.

    This is the WHOLE-BOX oversubscription target (2x visible CPUs). For the inference phase, the
    main process must share that target with the per-GPU inference subprocesses; use
    main_process_worker_budget() to size main-process pools in a GPU-count-aware way. Pre-inference
    stages (decode, cube resize) that run while no GPU is inferencing keep using this full budget.
    """
    return max(1, int(_cpu_count()) * 2)


def multi_gpu_worker_share(gpu_device_count: int) -> int:
    """Per-GPU-subprocess CPU share, mirroring the multi-GPU dispatch's per_worker_workers.

    Each per-GPU inference subprocess sizes its render/postprocess pools to roughly
    floor(visible_cpu / num_gpu) threads (with cv2 single-threaded). This helper computes the same
    floor so the main-process budget can reserve the cores those subprocesses consume.
    """
    cpu = max(1, int(_cpu_count()))
    n = max(1, int(gpu_device_count))
    return max(1, cpu // n)


def main_process_worker_budget(gpu_device_count: int, multi_gpu_active: bool) -> int:
    """v13.1.0 (#2.1): GPU-count-aware main-process worker budget for the inference phase.

    The whole-box oversubscription target is 2x visible CPUs (default_worker_budget()). In multi-GPU
    runs, render + YOLO predict + retina-mask resolution + result union all happen INSIDE the per-GPU
    inference subprocesses, which together consume ~num_gpu * floor(cpu/num_gpu) ~= cpu render threads
    (the GPU-blocking pools). To keep the box at the intended ~2:1 overall instead of stacking another
    flat 2x on top of the subprocesses (~8:1 at 4 GPUs), the GPU-non-blocking main-process pools
    (cleanup/interpolation/output/backprojection) are sized to the remaining headroom,
    2*cpu - num_gpu*floor(cpu/num_gpu).

    In single-GPU (or CPU) runs, inference is in-process, so the GPU-blocking pools live in the main
    process and the full 2x budget is correct -- this returns default_worker_budget() unchanged.
    """
    total = int(default_worker_budget())
    if not bool(multi_gpu_active):
        return max(1, total)
    n = max(1, int(gpu_device_count))
    reserved = int(multi_gpu_worker_share(n)) * n
    return max(1, total - reserved)


def mgpu_direct_union_enabled() -> bool:
    """v13.3.1 (R4): single-angle multi-GPU workers write straight into the per-view union.

    With exactly one --angle, every (view, slice-window) task contributes exactly once and the
    windows are disjoint, so the per-task result file + reopen + OR-union + unlink round trip is
    a pure copy: workers open the shared, pre-zeroed per-view union memmap 'r+' and write their
    window directly (same-host page-cache coherence). Multi-angle runs keep the legacy result
    files (their windows overlap across angles). YOLO_TTA_MGPU_DIRECT_UNION=0 disables.
    """
    return _env_flag('YOLO_TTA_MGPU_DIRECT_UNION', True)


# v13.3.3: default cap for interpolation process-pool workers (was hard-capped at 2). The
# interpolation pass is GIL-bound python inside each child, so extra children are extra usable
# GILs; RAM is the practical bound (each pass workspace can reach ~O(100 GiB) on large volumes,
# but workspace allocation is itself memory-gated with a disk-backed fallback). Also used as the
# default expected parent-interpolation overlap so per-parent thread pools divide accordingly.
INTERPOLATION_PROCESS_WORKER_DEFAULT_CAP = 6


def resolve_parent_interpolation_worker_allocation(
    worker_budget: int,
    parent_postprocess_workers: int,
) -> Tuple[int, int, int]:
    """Resolve per-parent interpolation workers from expected live overlap.

    Parent full-frame interpolation used to divide the global worker budget by the total
    number of parent postprocess workers, which also tracked the number of active views.
    Current scheduling normally completes a view's interpolation before the next parent
    begins and rarely has more than two parent views interpolating at once.  The default
    therefore partitions the global worker budget by expected live overlap instead of by
    total active view count.

    Returns ``(expected_overlap, default_per_parent_workers, resolved_per_parent_workers)``.
    ``YOLO_TTA_INTERPOLATION_CONCURRENT_PARENTS`` changes the overlap estimate and
    ``YOLO_TTA_INTERPOLATION_TASK_WORKERS`` still overrides the final per-parent worker count.

    v13.3.3: with the interpolation process backend active (the default), up to
    INTERPOLATION_PROCESS_WORKER_DEFAULT_CAP passes really do run concurrently, so the default
    overlap matches that cap instead of assuming a single live parent — otherwise each of the
    concurrent passes spawns a full-budget thread pool and the box oversubscribes ~Nx during
    the postprocess tail.
    """
    budget = max(1, int(worker_budget))
    parent_workers = max(1, int(parent_postprocess_workers))
    default_overlap = max(
        1,
        min(
            parent_workers,
            INTERPOLATION_PROCESS_WORKER_DEFAULT_CAP if interpolation_process_backend_enabled() else 1,
        ),
    )
    overlap = max(
        1,
        min(
            parent_workers,
            _env_int('YOLO_TTA_INTERPOLATION_CONCURRENT_PARENTS', default_overlap),
        ),
    )
    default_workers = max(1, budget // max(1, int(overlap)))
    resolved_workers = max(
        1,
        _env_int('YOLO_TTA_INTERPOLATION_TASK_WORKERS', default_workers),
    )
    return int(overlap), int(default_workers), int(resolved_workers)


def resolve_worker_count(requested: int, env_name: str, auto_value: int, max_tasks: Optional[int] = None) -> int:
    workers = int(requested)
    if workers <= 0:
        workers = _env_int(env_name, int(auto_value))
    workers = max(1, int(workers))
    if max_tasks is not None:
        workers = max(1, min(int(workers), int(max_tasks)))
    return workers


def array_nbytes(shape: Sequence[int], dtype: np.dtype | str | type) -> int:
    dtype_obj = np.dtype(dtype)
    total = 1
    for dim in shape:
        total *= int(dim)
    return int(total) * int(dtype_obj.itemsize)


def memmap_msync_enabled() -> bool:
    """v13.3.1 (R3): synchronous scratch-memmap msync is opt-in.

    Every flush_array call in this pipeline targets same-host scratch memmaps, where the
    unified page cache already makes writes visible to sibling threads/processes without
    msync (the v13.2.5 speed #6 rationale), and kernel writeback persists kept artifacts.
    The old behavior — a blocking msync of multi-GB mappings at the end of every stage,
    every worker-task close, and every per-chunk union — is restored with YOLO_TTA_MSYNC=1.
    """
    return _env_flag('YOLO_TTA_MSYNC', False)


def flush_array(arr: object, *, force: bool = False) -> None:
    if arr is None:
        return
    # v13.3.1 (R3): no-op unless synchronous msync is explicitly requested (or forced by a
    # caller with a genuine durability boundary).
    if not force and not memmap_msync_enabled():
        return

    try:
        if isinstance(arr, np.memmap):
            arr.flush()
            return
    except Exception:
        pass

    base = getattr(arr, 'base', None)
    try:
        if isinstance(base, np.memmap):
            base.flush()
    except Exception:
        pass


def allocate_workspace_array(
    shape: Sequence[int],
    dtype: np.dtype | str | type,
    path: Optional[Path],
    desc: str,
    *,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
    reuse_existing: bool = False,
    initialize_zero: bool = True,
) -> np.ndarray:
    dtype_obj = np.dtype(dtype)
    need_bytes = array_nbytes(shape, dtype_obj)
    budget = workspace_budget_summary(need_bytes, reserve_bytes=reserve_bytes)
    use_in_memory = bool(prefer_memory) and should_use_in_memory_workspace(need_bytes, reserve_bytes=reserve_bytes)

    if use_in_memory:
        try:
            print(f"{desc}: in-memory ({budget})")
            shape_tuple = tuple(int(x) for x in shape)
            arr = (
                np.zeros(shape_tuple, dtype=dtype_obj)
                if bool(initialize_zero)
                else np.empty(shape_tuple, dtype=dtype_obj)
            )
            # v13.3.5 (N2): big allocations are still untouched here (>32 MiB glibc allocations
            # are fresh private mmaps, and np.zeros defers to lazily-faulted zero pages), so the
            # interleave policy lands before first touch.
            numa_interleave_memory(arr, desc=desc)
            return arr
        except MemoryError:
            print(f"{desc}: in-memory allocation failed, falling back to disk ({budget})")

    if path is None:
        raise ValueError(f"{desc}: disk fallback requires a filesystem path")

    path.parent.mkdir(parents=True, exist_ok=True)
    if reuse_existing and path.exists():
        print(f"{desc}: disk-backed reuse ({budget}) -> {path}")
        mm = np.memmap(path, dtype=dtype_obj, mode='r+', shape=tuple(int(x) for x in shape))
        numa_interleave_memory(mm, desc=desc)  # v13.3.5 (N2): best-effort (existing pages stay put)
        return mm

    if path.exists():
        path.unlink()
    print(f"{desc}: disk-backed ({budget}) -> {path}")
    mm = np.memmap(path, dtype=dtype_obj, mode='w+', shape=tuple(int(x) for x in shape))
    numa_interleave_memory(mm, desc=desc)  # v13.3.5 (N2)
    return mm


def copy_workspace_array(
    src: np.ndarray,
    path: Optional[Path],
    desc: str,
    *,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
    workers: int = 1,
) -> np.ndarray:
    """Allocate a workspace matching ``src`` and copy the contents in parallel."""
    dst = allocate_workspace_array(
        shape=src.shape,
        dtype=src.dtype,
        path=path,
        desc=desc,
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
        initialize_zero=False,
    )

    if src.ndim <= 1:
        np.copyto(dst, src)
        flush_array(dst)
        return dst

    total = int(src.shape[0])

    def _copy(idx: int) -> None:
        np.copyto(dst[int(idx)], src[int(idx)])

    parallel_for_indices(
        total,
        _copy,
        max_workers=choose_slice_parallel_workers(int(workers), total),
        desc=f'{desc} copy',
        show_progress=False,
    )
    flush_array(dst)
    return dst


# --------------------------
# v13.3.4 (T5): process-wide ThreadPoolExecutor checkout cache
# --------------------------
# The parallel_* helpers below (and a few hot per-call executors elsewhere) used to construct
# and tear down a ThreadPoolExecutor per call — thousands of pool builds per run (every
# labeling pass, every NRRD store, every resize, every prediction task). Pools are now checked
# out of a per-size cache and returned after the call: semantics are unchanged (each call still
# gets a DEDICATED pool bounded at its own max_workers, so nested calls cannot deadlock), but
# sequential calls stop paying thread create/join and OS threads keep their identity (which
# also preserves any future NUMA pinning). Idle cached threads are bounded by
# YOLO_TTA_PARALLEL_POOL_CACHE_MAX_THREADS (excess pools are shut down on release).

_PARALLEL_POOL_CACHE: Dict[int, List[ThreadPoolExecutor]] = {}
_PARALLEL_POOL_CACHE_LOCK = threading.Lock()


def _parallel_pool_cache_max_threads() -> int:
    return max(0, _env_int('YOLO_TTA_PARALLEL_POOL_CACHE_MAX_THREADS', 1024))


def _acquire_parallel_pool(workers: int) -> ThreadPoolExecutor:
    w = max(1, int(workers))
    with _PARALLEL_POOL_CACHE_LOCK:
        stack = _PARALLEL_POOL_CACHE.get(w)
        if stack:
            return stack.pop()
    return ThreadPoolExecutor(max_workers=w, thread_name_prefix=f'parallel-{w}')


def _release_parallel_pool(workers: int, pool: ThreadPoolExecutor) -> None:
    w = max(1, int(workers))
    with _PARALLEL_POOL_CACHE_LOCK:
        idle_threads = sum(int(size) * len(stack) for size, stack in _PARALLEL_POOL_CACHE.items())
        if idle_threads + w <= _parallel_pool_cache_max_threads():
            _PARALLEL_POOL_CACHE.setdefault(w, []).append(pool)
            return
    pool.shutdown(wait=False)


def _settle_parallel_futures(futures: Iterable[Future]) -> None:
    """Cancel-or-wait every future so a pool can safely return to the cache.

    Called on abandoned generators / error paths: pending futures either cancel (never ran)
    or finish; nothing of this call is left running when the pool is released.
    """
    remaining = [f for f in futures if f is not None]
    for fut in remaining:
        try:
            fut.cancel()
        except Exception:
            pass
    for fut in remaining:
        try:
            fut.exception()  # waits for completion; swallows task errors on cleanup paths
        except Exception:
            pass


def parallel_map_in_order(
    func: Callable[[int], object],
    items: Iterable[int],
    *,
    max_workers: int,
    max_pending: Optional[int] = None,
) -> Iterator[object]:
    workers = max(1, int(max_workers))
    if workers <= 1:
        for item in items:
            yield func(int(item))
        return

    pending_limit = max(workers, int(max_pending) if max_pending is not None else workers + 1)
    executor = _acquire_parallel_pool(workers)
    queue: List[Future] = []
    try:
        for item in items:
            queue.append(executor.submit(func, int(item)))
            if len(queue) >= pending_limit:
                fut = queue.pop(0)
                yield fut.result()
        while queue:
            fut = queue.pop(0)
            yield fut.result()
    finally:
        _settle_parallel_futures(queue)
        _release_parallel_pool(workers, executor)


def parallel_map_unordered(
    func: Callable[[int], object],
    items: Iterable[int],
    *,
    max_workers: int,
    max_pending: Optional[int] = None,
) -> Iterator[object]:
    """Bounded parallel map that yields results as soon as tasks complete.

    This is intended for variable-cost tasks whose output order does not affect the
    final binary result, such as interpolation endpoint seed planning.  Unlike
    ``parallel_map_in_order``, one slow early item cannot block result consumption
    or prevent later items from being submitted once the pending bound is reached.
    """
    workers = max(1, int(max_workers))
    if workers <= 1:
        for item in items:
            yield func(int(item))
        return

    pending_limit = max(workers, int(max_pending) if max_pending is not None else workers + 1)
    iterator = iter(items)
    executor = _acquire_parallel_pool(workers)
    pending: set[Future] = set()
    try:
        def _submit_until_full() -> None:
            while len(pending) < pending_limit:
                try:
                    item = next(iterator)
                except StopIteration:
                    break
                pending.add(executor.submit(func, int(item)))

        _submit_until_full()
        while pending:
            done, pending_remainder = wait(pending, return_when=FIRST_COMPLETED)
            pending = set(pending_remainder)
            for fut in done:
                yield fut.result()
            _submit_until_full()
    finally:
        _settle_parallel_futures(pending)
        _release_parallel_pool(workers, executor)


def parallel_for_indices(
    count: int,
    func: Callable[[int], None],
    *,
    max_workers: int,
    desc: str,
    show_progress: bool = True,
) -> None:
    total = max(0, int(count))
    if total <= 0:
        return

    workers = max(1, min(int(max_workers), total))
    if workers <= 1:
        iterable = tqdm(range(total), desc=desc) if show_progress else range(total)
        for idx in iterable:
            func(int(idx))
        return

    executor = _acquire_parallel_pool(workers)
    futures: List[Future] = []
    try:
        futures = [executor.submit(func, int(idx)) for idx in range(total)]
        if show_progress:
            with tqdm(total=total, desc=desc) as pbar:
                for fut in as_completed(futures):
                    fut.result()
                    pbar.update(1)
        else:
            for fut in as_completed(futures):
                fut.result()
    finally:
        _settle_parallel_futures(futures)
        _release_parallel_pool(workers, executor)


def choose_parallel_chunk_size(
    total_items: int,
    max_workers: int,
    *,
    target_chunks_per_worker: int = 4,
    min_chunk_size: int = 1,
    max_chunk_size: Optional[int] = None,
) -> int:
    total = max(0, int(total_items))
    workers = max(1, int(max_workers))
    if total <= 0:
        return max(1, int(min_chunk_size))

    denom = max(1, workers * max(1, int(target_chunks_per_worker)))
    chunk = max(int(min_chunk_size), int(math.ceil(float(total) / float(denom))))
    if max_chunk_size is not None:
        chunk = min(int(chunk), max(1, int(max_chunk_size)))
    return max(1, int(chunk))


def parallel_for_indices_chunked(
    count: int,
    func: Callable[[int], None],
    *,
    max_workers: int,
    desc: str,
    show_progress: bool = True,
    chunk_size: Optional[int] = None,
    target_chunks_per_worker: int = 4,
) -> None:
    total = max(0, int(count))
    if total <= 0:
        return

    workers = max(1, min(int(max_workers), total))
    if workers <= 1:
        iterable = tqdm(range(total), desc=desc) if show_progress else range(total)
        for idx in iterable:
            func(int(idx))
        return

    if chunk_size is None or int(chunk_size) <= 0:
        chunk = choose_parallel_chunk_size(
            total,
            workers,
            target_chunks_per_worker=int(target_chunks_per_worker),
            min_chunk_size=1,
        )
    else:
        chunk = max(1, int(chunk_size))

    ranges = [(int(start), int(min(total, start + chunk))) for start in range(0, total, chunk)]

    def _run_range(range_idx: int) -> int:
        start, stop = ranges[int(range_idx)]
        for idx in range(int(start), int(stop)):
            func(int(idx))
        return int(stop - start)

    executor = _acquire_parallel_pool(workers)
    futures: List[Future] = []
    try:
        futures = [executor.submit(_run_range, int(range_idx)) for range_idx in range(len(ranges))]
        if show_progress:
            with tqdm(total=total, desc=desc) as pbar:
                for fut in as_completed(futures):
                    pbar.update(int(fut.result()))
        else:
            for fut in as_completed(futures):
                fut.result()
    finally:
        _settle_parallel_futures(futures)
        _release_parallel_pool(workers, executor)


def workspace_anon_cap_bytes() -> int:
    """Return the optional anonymous-workspace cap.

    Task overrides remove the previous conservative default fractional cap. Anonymous workspaces are
    only capped when the user explicitly sets YOLO_TTA_MAX_ANON_WORKSPACE_GIB.
    """
    hard_cap_gib = max(0.0, _env_float('YOLO_TTA_MAX_ANON_WORKSPACE_GIB', 0.0))
    if hard_cap_gib <= 0.0:
        return 0
    return int(hard_cap_gib * GIB)


def workspace_budget_summary(required_bytes: int, reserve_bytes: int = 16 * GIB) -> str:
    avail = available_anon_work_bytes()
    cap = workspace_anon_cap_bytes()
    reserve = int(max(0, reserve_bytes))
    parts = [
        f'need={required_bytes / GIB:.1f} GiB',
        f'avail+swap={avail / GIB:.1f} GiB',
        f'reserve={reserve / GIB:.1f} GiB',
    ]
    if cap > 0:
        parts.append(f'anon-cap={cap / GIB:.1f} GiB')
    return ', '.join(parts)


def should_use_in_memory_workspace(required_bytes: int, reserve_bytes: int = 16 * GIB) -> bool:
    if int(required_bytes) <= 0:
        return False

    avail = available_anon_work_bytes()
    reserve = int(max(0, reserve_bytes))
    cap = workspace_anon_cap_bytes()

    if cap > 0 and int(required_bytes) > cap:
        return False
    return avail >= int(required_bytes) + reserve


def choose_slice_parallel_workers(requested_workers: int, num_items: int) -> int:
    return max(1, min(int(requested_workers), int(max(1, num_items))))


def choose_scratch_dir(preferred: Optional[str], out_dir: Path, stem: str) -> Path:
    """Pick the bulk disk-backed scratch root.

      - no longer auto-selects tmpfs locations like /dev/shm for the whole pipeline
      - defaults to {output}/temp so large persistent memmaps stay off tmpfs unless the user explicitly opts in
    """
    candidates: List[Path] = []
    seen: set[str] = set()

    def _add_candidate(p: Path) -> None:
        key = str(p)
        if key in seen:
            return
        seen.add(key)
        candidates.append(p)

    if preferred:
        _add_candidate(Path(preferred).expanduser())
    env_pref = os.environ.get('YOLO_TTA_SCRATCH_DIR', '').strip()
    if env_pref:
        _add_candidate(Path(env_pref).expanduser())
    _add_candidate(out_dir)

    chosen_root: Optional[Path] = None
    for cand in candidates:
        try:
            cand = cand.resolve()
        except Exception:
            cand = cand
        if cand.exists() and os.access(str(cand), os.W_OK):
            chosen_root = cand
            break

    if chosen_root is None:
        chosen_root = out_dir

    if chosen_root == out_dir:
        scratch_dir = out_dir / 'temp'
    else:
        scratch_dir = chosen_root / f'{stem}_{os.getpid()}_temp'

    scratch_dir.mkdir(parents=True, exist_ok=True)
    return scratch_dir


def estimate_voidfill_workspace_bytes(shape: Tuple[int, int, int]) -> int:
    z_dim, h, w = shape
    return int(z_dim) * int(h) * int(w) * np.dtype(np.uint32).itemsize


def estimate_interpolation_workspace_bytes(shape: Tuple[int, int, int]) -> int:
    z_dim, h, w = shape
    voxels = int(z_dim) * int(h) * int(w)
    return voxels * (np.dtype(np.uint32).itemsize + np.dtype(np.uint8).itemsize)


def expose_scratch_in_output(out_dir: Path, scratch_dir: Path) -> Path:
    """Expose the active scratch directory from the output tree when possible."""
    temp_entry = out_dir / 'temp'
    try:
        if temp_entry.exists() or temp_entry.is_symlink():
            if temp_entry.is_symlink() or temp_entry.is_file():
                temp_entry.unlink(missing_ok=True)
            elif temp_entry.resolve() != scratch_dir.resolve():
                shutil.rmtree(temp_entry, ignore_errors=True)
    except Exception:
        pass

    try:
        if temp_entry.resolve() == scratch_dir.resolve():
            return temp_entry
    except Exception:
        pass

    if temp_entry.exists() or temp_entry.is_symlink():
        return temp_entry

    try:
        os.symlink(str(scratch_dir), str(temp_entry), target_is_directory=True)
        return temp_entry
    except Exception:
        temp_entry.mkdir(parents=True, exist_ok=True)
        (temp_entry / 'SCRATCH_LOCATION.txt').write_text(str(scratch_dir) + '\n')
        return temp_entry


def close_memmap_array(arr: object) -> None:
    if arr is None:
        return
    flush_array(arr)
    try:
        if isinstance(arr, np.memmap):
            mmap_obj = getattr(arr, '_mmap', None)
            if mmap_obj is not None:
                mmap_obj.close()
            return
    except Exception:
        pass
    try:
        base = getattr(arr, 'base', None)
        if isinstance(base, np.memmap):
            mmap_obj = getattr(base, '_mmap', None)
            if mmap_obj is not None:
                mmap_obj.close()
    except Exception:
        pass


def close_memmap_array_without_flush(arr: object) -> None:
    """Close a scratch memmap mapping without forcing dirty pages to storage."""
    if arr is None:
        return
    try:
        if isinstance(arr, np.memmap):
            mmap_obj = getattr(arr, '_mmap', None)
            if mmap_obj is not None:
                mmap_obj.close()
            return
    except Exception:
        pass
    try:
        base = getattr(arr, 'base', None)
        if isinstance(base, np.memmap):
            mmap_obj = getattr(base, '_mmap', None)
            if mmap_obj is not None:
                mmap_obj.close()
    except Exception:
        pass


def prediction_volume_build_flush_enabled() -> bool:
    """Return True to force flushing YOLO input volumes before inference."""
    return _env_flag('YOLO_TTA_FLUSH_PREDICTION_VOLUME_ON_BUILD', False)


def prediction_hot_path_flush_enabled() -> bool:
    """Return True to force per-source prediction accumulation memmap flushes."""
    return _env_flag('YOLO_TTA_PREDICT_FLUSH_EACH_VOLUME', False)


# --------------------------
# Interpolation process isolation
# --------------------------

_INTERPOLATION_PROCESS_EXECUTOR: Optional[ProcessPoolExecutor] = None
_INTERPOLATION_PROCESS_MAX_WORKERS = 0
_INTERPOLATION_PROCESS_WORKER = False


def _sanitize_filesystem_token(value: object) -> str:
    token = re.sub(r'[^A-Za-z0-9_.+-]+', '_', str(value).strip()).strip('_')
    return token or 'unnamed'


def interpolation_process_backend_enabled() -> bool:
    """Return True when interpolation passes should run in process workers.

    The default is enabled for v12.2.7 because interpolation seed planning contains
    Python-heavy control flow.  Running the pass in a separate process prevents that
    GIL-bound work from starving prediction-volume builder threads in the main
    process.  Set YOLO_TTA_INTERPOLATION_PROCESS_BACKEND=0 to recover the legacy
    in-process thread-pool path.
    """
    return _env_flag('YOLO_TTA_INTERPOLATION_PROCESS_BACKEND', True)


def interpolation_process_fallback_enabled() -> bool:
    """Allow an in-process fallback if a process interpolation task fails.

    The default is fail-fast so accidental reintroduction of the GIL bottleneck is
    visible.  Set YOLO_TTA_INTERPOLATION_PROCESS_FALLBACK=1 when completing a run is
    preferred over failing on a worker-process exception.
    """
    return _env_flag('YOLO_TTA_INTERPOLATION_PROCESS_FALLBACK', False)


def interpolation_process_start_method() -> str:
    method = os.environ.get('YOLO_TTA_INTERPOLATION_PROCESS_START_METHOD', 'spawn').strip().lower()
    if method not in {'spawn', 'forkserver', 'fork'}:
        method = 'spawn'
    return method


def interpolation_process_cv2_threads() -> int:
    return max(1, _env_int('YOLO_TTA_INTERPOLATION_PROCESS_CV2_THREADS', 1))


def _interpolation_process_initializer() -> None:
    global _INTERPOLATION_PROCESS_WORKER
    _INTERPOLATION_PROCESS_WORKER = True
    try:
        cv2.setNumThreads(int(interpolation_process_cv2_threads()))
    except Exception:
        pass


def create_interpolation_process_executor(max_workers: int) -> Optional[ProcessPoolExecutor]:
    if not interpolation_process_backend_enabled():
        return None
    workers = max(1, int(max_workers))
    start_method = interpolation_process_start_method()
    try:
        ctx = mp.get_context(start_method)
    except Exception:
        start_method = 'spawn'
        ctx = mp.get_context(start_method)
    return ProcessPoolExecutor(
        max_workers=workers,
        mp_context=ctx,
        initializer=_interpolation_process_initializer,
    )


def set_interpolation_process_executor(executor: Optional[ProcessPoolExecutor], max_workers: int = 0) -> None:
    global _INTERPOLATION_PROCESS_EXECUTOR, _INTERPOLATION_PROCESS_MAX_WORKERS
    _INTERPOLATION_PROCESS_EXECUTOR = executor
    _INTERPOLATION_PROCESS_MAX_WORKERS = max(0, int(max_workers))


# --------------------------
# v13.3.4 (T4): GPU worker processes as auxiliary interpolation hosts
# --------------------------
# The multi-GPU inference workers stay alive (idle in task_queue.get()) through the whole CPU
# postprocess tail and are only shut down at the very end of main(). Each is a warm process
# with the module loaded and its own GIL — exactly what the GIL-bound interpolation passes
# queue for. Once the inference queue drains, interpolation passes submit here
# opportunistically (non-blocking slot acquire) BEFORE falling back to the dedicated
# interpolation process pool, adding up to gpu_count extra concurrent passes for free.


def gpu_worker_aux_interpolation_enabled() -> bool:
    return _env_flag('YOLO_TTA_GPU_WORKER_AUX_INTERPOLATION', True)


class _GpuWorkerAuxInterpolationPool:
    """Submission/result bridge between interpolation callers and the GPU worker task queue.

    try_submit is non-blocking (None when the pool is closed, failed, or all worker slots are
    busy); the caller then uses the regular interpolation process executor. Results flow back
    through the workers' shared result queue: the main scheduler thread routes
    'aux_result' messages to complete(), which wakes the waiting submitter thread.
    """

    def __init__(self, task_queue: object, worker_count: int) -> None:
        self._task_queue = task_queue
        self._capacity = max(1, int(worker_count))
        self._slots = threading.Semaphore(self._capacity)
        self._lock = threading.Lock()
        self._pending: Dict[int, Dict[str, object]] = {}
        self._next_task_id = 2_000_000_000  # disjoint from inference task ids
        self._enabled = threading.Event()
        self._failed_reason: Optional[str] = None

    @property
    def capacity(self) -> int:
        return int(self._capacity)

    def enable(self) -> None:
        if not self._enabled.is_set():
            self._enabled.set()
            print(
                f'GPU worker aux interpolation pool open (v13.3.4 T4): up to {self._capacity} '
                'interpolation pass(es) run on the now-idle GPU worker processes.'
            )

    def outstanding(self) -> int:
        with self._lock:
            return int(len(self._pending))

    def mark_failed(self, reason: str) -> None:
        with self._lock:
            if self._failed_reason is None:
                self._failed_reason = str(reason)
            entries = list(self._pending.values())
            self._pending.clear()
        for entry in entries:
            if not entry.get('error'):
                entry['error'] = str(reason)
            entry['event'].set()  # type: ignore[union-attr]

    def try_submit(self, aux_kwargs: Dict[str, object]) -> Optional[Dict[str, object]]:
        if not self._enabled.is_set():
            return None
        with self._lock:
            if self._failed_reason is not None:
                return None
        if not self._slots.acquire(blocking=False):
            return None
        handle: Dict[str, object] = {'event': threading.Event(), 'stats': None, 'error': None}
        with self._lock:
            task_id = int(self._next_task_id)
            self._next_task_id += 1
            handle['task_id'] = task_id
            self._pending[task_id] = handle
        try:
            self._task_queue.put({
                'task_id': int(task_id),
                'task_type': 'interpolation_pass',
                'aux_kwargs': dict(aux_kwargs),
            })
        except Exception:
            with self._lock:
                self._pending.pop(task_id, None)
            self._slots.release()
            return None
        return handle

    def complete(self, task_id: int, ok: bool, stats: Optional[Dict[str, object]], error: Optional[str]) -> None:
        with self._lock:
            handle = self._pending.pop(int(task_id), None)
        if handle is None:
            return
        if bool(ok):
            handle['stats'] = dict(stats or {})
        else:
            handle['error'] = str(error or 'unknown GPU-worker aux interpolation failure')
        self._slots.release()
        handle['event'].set()  # type: ignore[union-attr]

    def wait(self, handle: Dict[str, object], poll_seconds: float = 5.0) -> Dict[str, object]:
        event: threading.Event = handle['event']  # type: ignore[assignment]
        while not event.wait(timeout=float(poll_seconds)):
            with self._lock:
                failed = self._failed_reason
            if failed is not None:
                raise RuntimeError(f'GPU worker aux interpolation pool failed: {failed}')
        err = handle.get('error')
        if err:
            raise RuntimeError(str(err))
        stats = handle.get('stats')
        if not isinstance(stats, dict):
            raise RuntimeError('GPU worker aux interpolation returned no stats')
        return dict(stats)


_GPU_WORKER_AUX_INTERPOLATION_POOL: Optional[_GpuWorkerAuxInterpolationPool] = None


def set_gpu_worker_aux_interpolation_pool(pool: Optional[_GpuWorkerAuxInterpolationPool]) -> None:
    global _GPU_WORKER_AUX_INTERPOLATION_POOL
    _GPU_WORKER_AUX_INTERPOLATION_POOL = pool


def gpu_worker_aux_interpolation_pool() -> Optional[_GpuWorkerAuxInterpolationPool]:
    return _GPU_WORKER_AUX_INTERPOLATION_POOL


def _interpolation_array_backing_path(arr: object) -> Optional[Path]:
    if arr is None:
        return None
    try:
        arr_np = np.asarray(arr)
        if (
            isinstance(arr, np.memmap)
            # A sliced np.memmap is still an np.memmap and inherits the parent's
            # `offset` attribute verbatim (NOT adjusted for the slice), so offset==0
            # alone cannot prove the array starts at byte 0 of the file. Only the
            # root mapping has the raw mmap.mmap buffer as its `base`; views chain
            # to the parent ndarray instead (v13.2.2 bug #5).
            and isinstance(getattr(arr, 'base', None), mmap.mmap)
            and bool(arr_np.flags['C_CONTIGUOUS'])
            and int(getattr(arr, 'offset', 0) or 0) == 0
        ):
            filename = getattr(arr, 'filename', None)
            if not filename:
                return None
            path = Path(filename)
            # The child reopens by (path, shape): the file must actually hold the
            # full array starting at byte 0.
            if path.stat().st_size < int(arr_np.nbytes):
                return None
            return path
    except Exception:
        pass
    # Deliberately do not reuse a base memmap for ndarray views here.  A child
    # process would need the view's byte offset and strides to reopen it exactly;
    # interpolation volumes are expected to be full C-contiguous arrays, so views
    # are copied into a dedicated process memmap instead.
    return None


def _ensure_process_backed_interpolation_volume(
    mask_mm: np.ndarray,
    *,
    work_dir: Path,
    pass_tag: str,
    workers: int,
) -> Tuple[np.ndarray, Path, bool]:
    """Return a memmap-backed volume that a process worker can reopen by path."""
    arr = np.asarray(mask_mm)
    if arr.ndim != 3:
        raise ValueError(f'Interpolation expects a 3D mask volume, got shape {arr.shape}')
    if arr.dtype != np.dtype(np.uint8):
        raise ValueError(f'Interpolation process backend expects uint8 mask volume, got dtype {arr.dtype}')

    backing_path = _interpolation_array_backing_path(mask_mm)
    if backing_path is not None:
        flush_array(mask_mm)
        return mask_mm, Path(backing_path), False

    work_dir = Path(work_dir)
    work_dir.mkdir(parents=True, exist_ok=True)
    process_path = work_dir / f'{_sanitize_filesystem_token(pass_tag)}.process_input.u8.dat'
    process_mm = copy_workspace_array(
        arr,
        process_path,
        desc=f'Interpolation process input {pass_tag}',
        prefer_memory=False,
        workers=int(workers),
    )
    flush_array(process_mm)
    return process_mm, process_path, True


def _interpolation_process_entry(
    *,
    mask_path: str,
    mask_shape: Tuple[int, int, int],
    mask_dtype: str,
    work_dir: str,
    pass_tag: str,
    max_slice_distance: int,
    search_angle_deg: float,
    interpolation_walk_back: int,
    interpolation_candidates: int,
    interpolate_min_radius: float,
    keep_temp: bool,
    reserve_bytes: int,
    workers: int,
    wrap_axis: bool,
    bridge_delta_path: Optional[str] = None,
) -> Dict[str, object]:
    global _INTERPOLATION_PROCESS_WORKER
    _INTERPOLATION_PROCESS_WORKER = True
    try:
        cv2.setNumThreads(int(interpolation_process_cv2_threads()))
    except Exception:
        pass

    mask_mm = np.memmap(
        Path(mask_path),
        dtype=np.dtype(mask_dtype),
        mode='r+',
        shape=tuple(int(x) for x in mask_shape),
    )
    try:
        stats = interpolate_view_volume_pass_inplace(
            mask_mm=mask_mm,
            work_dir=Path(work_dir),
            pass_tag=str(pass_tag),
            max_slice_distance=int(max_slice_distance),
            search_angle_deg=float(search_angle_deg),
            interpolation_walk_back=int(interpolation_walk_back),
            interpolation_candidates=int(interpolation_candidates),
            interpolate_min_radius=float(interpolate_min_radius),
            keep_temp=bool(keep_temp),
            prefer_memory=True,
            reserve_bytes=int(reserve_bytes),
            workers=int(workers),
            wrap_axis=bool(wrap_axis),
            bridge_delta_path=Path(bridge_delta_path) if bridge_delta_path else None,
        )
        stats = dict(stats)
        stats.update({
            'process_backend': 'process_pool_memmap',
            'process_pid': int(os.getpid()),
            'process_workers_inside_pass': int(workers),
            'process_memmap_path': str(mask_path),
        })
        flush_array(mask_mm)
        return stats
    finally:
        close_memmap_array(mask_mm)


def interpolate_view_volume_pass_maybe_process(
    mask_mm: np.ndarray,
    work_dir: Path,
    pass_tag: str,
    max_slice_distance: int,
    search_angle_deg: float,
    interpolation_walk_back: int,
    interpolation_candidates: int,
    interpolate_min_radius: float,
    keep_temp: bool = False,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
    workers: int = 1,
    wrap_axis: bool = False,
    bridge_delta_path: Optional[Path] = None,
) -> Tuple[np.ndarray, Dict[str, object]]:
    """Run one interpolation pass, using a child process when configured.

    The returned array may be a new memmap when the input was an anonymous ndarray.
    Callers must keep using the returned volume for later passes and downstream work.
    """
    executor = _INTERPOLATION_PROCESS_EXECUTOR
    if (
        _INTERPOLATION_PROCESS_WORKER
        or executor is None
        or not interpolation_process_backend_enabled()
    ):
        stats = interpolate_view_volume_pass_inplace(
            mask_mm=mask_mm,
            work_dir=work_dir,
            pass_tag=pass_tag,
            max_slice_distance=int(max_slice_distance),
            search_angle_deg=float(search_angle_deg),
            interpolation_walk_back=int(interpolation_walk_back),
            interpolation_candidates=int(interpolation_candidates),
            interpolate_min_radius=float(interpolate_min_radius),
            keep_temp=bool(keep_temp),
            prefer_memory=bool(prefer_memory),
            reserve_bytes=int(reserve_bytes),
            workers=int(workers),
            wrap_axis=bool(wrap_axis),
            bridge_delta_path=bridge_delta_path,
        )
        stats = dict(stats)
        stats.setdefault('process_backend', 'disabled_or_unconfigured')
        return mask_mm, stats

    process_mm, process_path, copied_to_memmap = _ensure_process_backed_interpolation_volume(
        mask_mm,
        work_dir=Path(work_dir),
        pass_tag=str(pass_tag),
        workers=max(1, min(int(workers), int(mask_mm.shape[0]) if getattr(mask_mm, 'ndim', 0) else int(workers))),
    )
    shape = tuple(int(x) for x in np.asarray(process_mm).shape)
    dtype_str = str(np.asarray(process_mm).dtype)
    flush_array(process_mm)

    pass_entry_kwargs: Dict[str, object] = dict(
        mask_path=str(process_path),
        mask_shape=shape,
        mask_dtype=dtype_str,
        work_dir=str(work_dir),
        pass_tag=str(pass_tag),
        max_slice_distance=int(max_slice_distance),
        search_angle_deg=float(search_angle_deg),
        interpolation_walk_back=int(interpolation_walk_back),
        interpolation_candidates=int(interpolation_candidates),
        interpolate_min_radius=float(interpolate_min_radius),
        keep_temp=bool(keep_temp),
        reserve_bytes=int(reserve_bytes),
        workers=int(workers),
        wrap_axis=bool(wrap_axis),
        bridge_delta_path=str(bridge_delta_path) if bridge_delta_path is not None else None,
    )

    # v13.3.4 (T4): once inference has drained, the warm GPU worker processes serve
    # interpolation passes too — try them first (non-blocking), then the dedicated pool.
    aux_pool = gpu_worker_aux_interpolation_pool()
    if aux_pool is not None:
        aux_handle = aux_pool.try_submit(pass_entry_kwargs)
        if aux_handle is not None:
            try:
                stats = dict(aux_pool.wait(aux_handle))
            except Exception as exc:
                if not interpolation_process_fallback_enabled():
                    raise RuntimeError(
                        f'GPU-worker aux interpolation failed for {pass_tag} at {process_path}. '
                        'Set YOLO_TTA_INTERPOLATION_PROCESS_FALLBACK=1 to rerun failed passes in-process for recovery.'
                    ) from exc
                print(
                    f'Warning: GPU-worker aux interpolation failed for {pass_tag} ({exc}); '
                    'falling back to in-process interpolation because YOLO_TTA_INTERPOLATION_PROCESS_FALLBACK=1.'
                )
                stats = dict(interpolate_view_volume_pass_inplace(
                    mask_mm=process_mm,
                    work_dir=work_dir,
                    pass_tag=pass_tag,
                    max_slice_distance=int(max_slice_distance),
                    search_angle_deg=float(search_angle_deg),
                    interpolation_walk_back=int(interpolation_walk_back),
                    interpolation_candidates=int(interpolation_candidates),
                    interpolate_min_radius=float(interpolate_min_radius),
                    keep_temp=bool(keep_temp),
                    prefer_memory=bool(prefer_memory),
                    reserve_bytes=int(reserve_bytes),
                    workers=int(workers),
                    wrap_axis=bool(wrap_axis),
                    bridge_delta_path=bridge_delta_path,
                ))
                stats['process_backend'] = 'fallback_in_process_after_aux_failure'
            stats.setdefault('process_backend', 'gpu_worker_aux_process')
            stats['process_memmap_copied_from_anonymous_array'] = bool(copied_to_memmap)
            stats['process_pool_workers'] = int(_INTERPOLATION_PROCESS_MAX_WORKERS)
            flush_array(process_mm)
            return process_mm, stats

    fut = executor.submit(_interpolation_process_entry, **pass_entry_kwargs)
    try:
        stats = dict(fut.result())
    except Exception as exc:
        if not interpolation_process_fallback_enabled():
            raise RuntimeError(
                f'Interpolation process worker failed for {pass_tag} at {process_path}. '
                'Set YOLO_TTA_INTERPOLATION_PROCESS_FALLBACK=1 to rerun this pass in-process for recovery.'
            ) from exc
        print(
            f'Warning: interpolation process worker failed for {pass_tag} ({exc}); '
            'falling back to legacy in-process interpolation because YOLO_TTA_INTERPOLATION_PROCESS_FALLBACK=1.'
        )
        stats = interpolate_view_volume_pass_inplace(
            mask_mm=process_mm,
            work_dir=work_dir,
            pass_tag=pass_tag,
            max_slice_distance=int(max_slice_distance),
            search_angle_deg=float(search_angle_deg),
            interpolation_walk_back=int(interpolation_walk_back),
            interpolation_candidates=int(interpolation_candidates),
            interpolate_min_radius=float(interpolate_min_radius),
            keep_temp=bool(keep_temp),
            prefer_memory=bool(prefer_memory),
            reserve_bytes=int(reserve_bytes),
            workers=int(workers),
            wrap_axis=bool(wrap_axis),
            bridge_delta_path=bridge_delta_path,
        )
        stats = dict(stats)
        stats['process_backend'] = 'fallback_in_process_after_worker_failure'

    stats.setdefault('process_backend', 'process_pool_memmap')
    stats['process_memmap_copied_from_anonymous_array'] = bool(copied_to_memmap)
    stats['process_pool_workers'] = int(_INTERPOLATION_PROCESS_MAX_WORKERS)
    flush_array(process_mm)
    return process_mm, stats


# --------------------------
# ffmpeg helpers
# --------------------------

def _require_bin(name: str) -> None:
    if shutil.which(name) is None:
        raise RuntimeError(f"Required executable not found on PATH: {name}")


def ffmpeg_decode_threads() -> int:
    """Return the decoder thread count for input-volume materialization.

    The earlier decode path left FFmpeg to choose its own threading.  On large
    FFV1/Matroska inputs this can silently become a single-decoder bottleneck
    before the first prediction volume is even scheduled.  Default to the full
    visible CPU allocation; set ``YOLO_TTA_FFMPEG_DECODE_THREADS`` to pin a
    smaller value for codecs or filesystems that prefer less parallel decode.
    """
    return max(1, _env_int('YOLO_TTA_FFMPEG_DECODE_THREADS', max(1, _cpu_count())))


class VolumeReadiness:
    """Slice-level readiness gate for streaming decode/cube preprocessing."""

    def __init__(self, total_slices: int, desc: str = 'volume') -> None:
        self.total_slices = max(0, int(total_slices))
        self.desc = str(desc)
        self._slice_events = [threading.Event() for _ in range(self.total_slices)]
        self._all_event = threading.Event()
        self._lock = threading.Lock()
        self._ready_count = 0
        self._exception: Optional[BaseException] = None
        if self.total_slices <= 0:
            self._all_event.set()

    def mark_slice_ready(self, idx: int) -> None:
        idx_i = int(idx)
        if idx_i < 0 or idx_i >= int(self.total_slices):
            return
        ev = self._slice_events[idx_i]
        if ev.is_set():
            return
        with self._lock:
            if not ev.is_set():
                ev.set()
                self._ready_count += 1
                if self._ready_count >= self.total_slices:
                    self._all_event.set()

    def mark_all_ready(self) -> None:
        with self._lock:
            for ev in self._slice_events:
                ev.set()
            self._ready_count = self.total_slices
            self._all_event.set()

    def mark_failed(self, exc: BaseException) -> None:
        with self._lock:
            self._mark_failed_locked(exc)

    def _mark_failed_locked(self, exc: BaseException) -> None:
        # First failure wins: never replace a recorded root cause with a later, more
        # generic one (e.g. the decode finally's returncode error after the real EOF
        # error, or the shutdown abort after a real producer failure).
        if self._exception is None:
            self._exception = exc
        for ev in self._slice_events:
            ev.set()
        self._all_event.set()

    def _raise_if_failed(self) -> None:
        exc = self._exception
        if exc is not None:
            raise RuntimeError(f'{self.desc} producer failed before required slice data was ready') from exc

    def wait_for_slice(self, idx: int) -> None:
        idx_i = int(idx)
        if idx_i < 0 or idx_i >= int(self.total_slices):
            raise IndexError(idx_i)
        self._slice_events[idx_i].wait()
        self._raise_if_failed()

    def wait_all(self) -> None:
        self._all_event.wait()
        self._raise_if_failed()

    def fail_if_incomplete(self, exc: BaseException) -> bool:
        """mark_failed() unless the volume already completed or failed; True if failed here.

        Check and mark happen under one lock hold, so a producer completing concurrently
        cannot be marked failed after the fact, and an already-recorded root-cause
        exception is never replaced by the generic abort error.
        """
        with self._lock:
            if self._all_event.is_set():
                return False
            self._mark_failed_locked(exc)
            return True


_VOLUME_READINESS_BY_ARRAY_ID: Dict[int, VolumeReadiness] = {}

# v13.2.2 bug #7: the streaming decode/resize producers were non-daemon threads with no
# cancellation path, so any fatal main-thread error left threading._shutdown joining a
# multi-hour decode of a volume nobody would consume. Producers poll this event per
# chunk/slice and run as daemon threads; abort_streaming_producers() additionally fails
# every incomplete VolumeReadiness so consumers blocked on wait_for_slice()/wait_all()
# wake with an error instead of hanging.
_STREAMING_PRODUCER_ABORT = threading.Event()


def streaming_producers_aborted() -> bool:
    return _STREAMING_PRODUCER_ABORT.is_set()


def abort_streaming_producers(reason: str = 'pipeline aborted') -> None:
    _STREAMING_PRODUCER_ABORT.set()
    exc = RuntimeError(f'streaming producer aborted: {reason}')
    for readiness in list(_VOLUME_READINESS_BY_ARRAY_ID.values()):
        try:
            readiness.fail_if_incomplete(exc)
        except Exception:
            pass


def streaming_preprocess_enabled() -> bool:
    """Return True when decode/cube preprocessing may run ahead of consumers."""
    return _env_flag('YOLO_TTA_STREAMING_PREPROCESS', True)


def register_volume_readiness(arr: object, readiness: VolumeReadiness) -> None:
    _VOLUME_READINESS_BY_ARRAY_ID[id(arr)] = readiness


def volume_readiness(arr: object) -> Optional[VolumeReadiness]:
    return _VOLUME_READINESS_BY_ARRAY_ID.get(id(arr))


def wait_for_volume_slice_ready(arr: object, idx: int) -> None:
    readiness = volume_readiness(arr)
    if readiness is not None:
        readiness.wait_for_slice(int(idx))


def wait_for_volume_ready(arr: object) -> None:
    readiness = volume_readiness(arr)
    if readiness is not None:
        readiness.wait_all()


def ffprobe_info(video_path: Path) -> Dict[str, object]:
    """Return dict with width, height, fps, num_frames."""
    _require_bin("ffprobe")
    cmd = [
        "ffprobe",
        "-v", "error",
        "-select_streams", "v:0",
        "-show_entries", "stream=width,height,r_frame_rate,avg_frame_rate,nb_frames",
        "-of", "json",
        str(video_path),
    ]
    p = subprocess.run(cmd, capture_output=True, text=True, check=True)
    info = json.loads(p.stdout)
    if "streams" not in info or not info["streams"]:
        raise RuntimeError(f"ffprobe: no video stream found in {video_path}")
    st = info["streams"][0]

    width = int(st.get("width"))
    height = int(st.get("height"))

    def _parse_ratio(r: str) -> float:
        if not r or r == "0/0":
            return 0.0
        num, den = r.split("/")
        den_i = int(den)
        return float(num) / float(den_i) if den_i != 0 else 0.0

    fps = _parse_ratio(str(st.get("avg_frame_rate", "0/0")))
    if fps <= 0:
        fps = _parse_ratio(str(st.get("r_frame_rate", "0/0")))
    if fps <= 0:
        fps = 30.0

    nf = st.get("nb_frames", None)
    if nf is None or str(nf).strip() == "" or str(nf) == "N/A":
        # Fast fallback: count packets without decoding
        fallback_cmd = [
            "ffprobe",
            "-v", "error",
            "-select_streams", "v:0",
            "-count_packets",
            "-show_entries", "stream=nb_read_packets",
            "-of", "json",
            str(video_path),
        ]
        p2 = subprocess.run(fallback_cmd, capture_output=True, text=True, check=True)
        info2 = json.loads(p2.stdout)
        nf = info2["streams"][0].get("nb_read_packets", None)
    if nf is None or str(nf).strip() == "" or str(nf) == "N/A":
        raise RuntimeError(
            "ffprobe could not determine frame count (nb_frames/nb_read_packets missing)."
        )
    num_frames = int(nf)
    return {"width": width, "height": height, "fps": fps, "num_frames": num_frames}


def decode_video_to_memmap_gray8(
    input_video: Path,
    out_dat: Path,
    num_frames: int,
    width: int,
    height: int,
    overwrite: bool = False,
    *,
    prefer_memory: bool = True,
    reserve_bytes: int = 32 * GIB,
) -> np.ndarray:
    """Decode input video to a (T,H,W) uint8 gray/luma workspace.

    ffmpeg's ``gray`` pixel format accepts RGB, YUV, and already single-channel inputs and
    normalizes them to one luma channel. This keeps the source volume and all view-rendering
    intermediates single-channel; color expansion is deferred to optional presentation outputs.
    """
    _require_bin("ffmpeg")

    shape = (int(num_frames), int(height), int(width))
    reuse_existing = bool(not overwrite and out_dat.exists() and not prefer_memory)
    arr = allocate_workspace_array(
        shape=shape,
        dtype=np.uint8,
        path=out_dat,
        desc='Decoded gray8 input volume',
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
        reuse_existing=bool(reuse_existing),
        initialize_zero=False,
    )
    if reuse_existing and isinstance(arr, np.memmap):
        return arr

    raw_bytes = memoryview(np.ascontiguousarray(arr) if not arr.flags['C_CONTIGUOUS'] else arr).cast('B')
    if raw_bytes.obj is not arr:
        arr = np.asarray(raw_bytes.obj).reshape(shape)
        raw_bytes = memoryview(arr).cast('B')

    frame_bytes = int(width) * int(height)
    chunk_frames = max(1, min(128, max(1, (256 * 1024 * 1024) // max(1, frame_bytes))))

    cmd = [
        "ffmpeg",
        "-v", "error",
        "-threads", str(ffmpeg_decode_threads()),
        "-i", str(input_video),
        "-f", "rawvideo",
        "-pix_fmt", "gray",
        "-vsync", "0",
        "-",
    ]
    print(f'FFmpeg gray8 decode threads: {ffmpeg_decode_threads()}')
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    assert proc.stdout is not None

    try:
        with tqdm(total=num_frames, desc='Decoding input volume (gray8)') as pbar:
            for start in range(0, num_frames, chunk_frames):
                nframes = min(chunk_frames, num_frames - start)
                need = int(nframes) * int(frame_bytes)
                offset = int(start) * int(frame_bytes)
                view = raw_bytes[offset:offset + need]
                filled = 0
                while filled < need:
                    nread = proc.stdout.readinto(view[filled:])
                    if nread is None or nread <= 0:
                        raise RuntimeError(f'Unexpected EOF while decoding frames starting at {start}/{num_frames}')
                    filled += int(nread)
                pbar.update(int(nframes))
        flush_array(arr)
    finally:
        if proc.stdout:
            proc.stdout.close()
        _, err = proc.communicate()
        if proc.returncode not in (0, None):
            msg = err.decode("utf-8", errors="ignore") if isinstance(err, (bytes, bytearray)) else str(err)
            raise RuntimeError(f"ffmpeg decode failed: {msg}")
    return arr


def decode_video_to_memmap_gray8_streaming(
    input_video: Path,
    out_dat: Path,
    num_frames: int,
    width: int,
    height: int,
    overwrite: bool = False,
    *,
    prefer_memory: bool = True,
    reserve_bytes: int = 32 * GIB,
) -> np.ndarray:
    """Start ffmpeg gray8 decode in the background and return its destination array immediately."""
    _require_bin("ffmpeg")
    shape = (int(num_frames), int(height), int(width))
    reuse_existing = bool(not overwrite and out_dat.exists() and not prefer_memory)
    arr = allocate_workspace_array(
        shape=shape,
        dtype=np.uint8,
        path=out_dat,
        desc='Decoded gray8 input volume [streaming producer]',
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
        reuse_existing=bool(reuse_existing),
        initialize_zero=False,
    )
    readiness = VolumeReadiness(int(num_frames), desc='streaming ffmpeg gray8 decode')
    register_volume_readiness(arr, readiness)
    if reuse_existing and isinstance(arr, np.memmap):
        readiness.mark_all_ready()
        return arr

    raw_bytes = memoryview(np.ascontiguousarray(arr) if not arr.flags['C_CONTIGUOUS'] else arr).cast('B')
    if raw_bytes.obj is not arr:
        arr = np.asarray(raw_bytes.obj).reshape(shape)
        raw_bytes = memoryview(arr).cast('B')
        register_volume_readiness(arr, readiness)

    frame_bytes = int(width) * int(height)
    chunk_frames = max(1, min(128, max(1, (256 * 1024 * 1024) // max(1, frame_bytes))))

    def _decode_worker() -> None:
        cmd = [
            "ffmpeg", "-v", "error", "-threads", str(ffmpeg_decode_threads()),
            "-i", str(input_video), "-f", "rawvideo", "-pix_fmt", "gray", "-vsync", "0", "-",
        ]
        print(f'FFmpeg gray8 streaming decode threads: {ffmpeg_decode_threads()}')
        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        assert proc.stdout is not None
        try:
            with tqdm(total=num_frames, desc='Streaming decode input volume (gray8)') as pbar:
                for start in range(0, int(num_frames), int(chunk_frames)):
                    if streaming_producers_aborted():
                        raise RuntimeError('streaming gray8 decode aborted by pipeline shutdown')
                    nframes = min(int(chunk_frames), int(num_frames) - int(start))
                    need = int(nframes) * int(frame_bytes)
                    offset = int(start) * int(frame_bytes)
                    view = raw_bytes[offset:offset + need]
                    filled = 0
                    while filled < need:
                        nread = proc.stdout.readinto(view[filled:])
                        if nread is None or nread <= 0:
                            raise RuntimeError(f'Unexpected EOF while decoding frames starting at {start}/{num_frames}')
                        filled += int(nread)
                    for frame_idx in range(int(start), int(start) + int(nframes)):
                        readiness.mark_slice_ready(int(frame_idx))
                    pbar.update(int(nframes))
            flush_array(arr)
            readiness.mark_all_ready()
        except BaseException as exc:
            readiness.mark_failed(exc)
            # Unblock the finally's communicate(): a decode we are abandoning must not be
            # waited on while it still streams the remainder of the input (v13.2.2 bug #7).
            try:
                if proc.poll() is None:
                    proc.kill()
            except Exception:
                pass
            raise
        finally:
            if proc.stdout:
                proc.stdout.close()
            _out, err = proc.communicate()
            if proc.returncode not in (0, None):
                msg = err.decode("utf-8", errors="ignore") if isinstance(err, (bytes, bytearray)) else str(err)
                readiness.mark_failed(RuntimeError(f"ffmpeg decode failed: {msg}"))

    # daemon=True (v13.2.2 bug #7): if main dies without reaching abort_streaming_producers(),
    # interpreter shutdown must not join a producer that may have hours of decode left.
    threading.Thread(target=_decode_worker, name='streaming-gray8-decode', daemon=True).start()
    return arr


def compute_cube_resize_shape(
    t_dim: int,
    h_dim: int,
    w_dim: int,
    tolerance: float = 0.05,
) -> Tuple[int, int, int]:
    """Return the minimal processing shape whose dimensions are within tolerance of the longest axis.

    v12.2.0 requires the orthogonal working volume to be approximately cubic.  The implementation
    preserves any axis that is already within the tolerated band and upsamples shorter axes only
    enough to reach ``(1 - tolerance) * longest``.  This avoids unnecessary XY resampling for the
    common 3072x3072x1930 case while still satisfying the 5% cube constraint.
    """
    t_i = max(1, int(t_dim))
    h_i = max(1, int(h_dim))
    w_i = max(1, int(w_dim))
    longest = max(t_i, h_i, w_i)
    lower_bound = int(math.ceil(float(longest) * (1.0 - float(tolerance))))
    return (
        max(t_i, lower_bound),
        max(h_i, lower_bound),
        max(w_i, lower_bound),
    )


def processing_volume_mode() -> str:
    """Return the v13.0.0 processing geometry mode.

    v13.0.0 (bug fix) defaults to the approximately-cubic working geometry required by spec
    item 2: the virtual working dimensions (X', Y', t') must be within 5% of the longest source
    axis before views are derived.  v12.2.15 had defaulted to ``native`` decoded geometry, which
    left the Transverse stacking axis (t) ~37% short of the longest axis for the common
    3072x3072x1930 case and violated the 5% band.  The literal cubic volume is materialized here
    as the simplest implementation of the virtual working geometry; the decoded->view reslice
    still scales to --imgsz in a single pass.  Set ``YOLO_TTA_PROCESSING_VOLUME_MODE=native`` to
    opt back into the v12.2.15 decoded-native geometry for strict regression/comparison only.
    """
    if _env_flag('YOLO_TTA_FORCE_PROCESSING_CUBE', False):
        return 'cube'
    raw = os.environ.get('YOLO_TTA_PROCESSING_VOLUME_MODE', '').strip().lower()
    if not raw:
        raw = os.environ.get('YOLO_TTA_PROCESSING_GEOMETRY', '').strip().lower()
    aliases = {
        '': 'cube',
        'native': 'native',
        'decoded': 'native',
        'input': 'native',
        'none': 'native',
        'no_resize': 'native',
        'no-resize': 'native',
        'cube': 'cube',
        'cubic': 'cube',
        'legacy': 'cube',
        'legacy_cube': 'cube',
        'v12': 'cube',
        'v12.2.0': 'cube',
        'v950': 'cube',
        'v13': 'cube',
        'v13.0.0': 'cube',
    }
    mode = aliases.get(raw)
    if mode is None:
        print(f"Warning: unsupported YOLO_TTA_PROCESSING_VOLUME_MODE={raw!r}; using approximately-cubic working geometry.")
        return 'cube'
    return str(mode)


def should_resize_to_processing_cube(input_shape: Tuple[int, int, int], cube_shape: Tuple[int, int, int]) -> bool:
    mode = processing_volume_mode()
    if mode != 'cube':
        return False
    return tuple(int(x) for x in input_shape) != tuple(int(x) for x in cube_shape)


def _linear_source_index(out_idx: int, out_count: int, in_count: int) -> float:
    if int(out_count) <= 1 or int(in_count) <= 1:
        return 0.0
    return float(out_idx) * float(in_count - 1) / float(out_count - 1)


def _resize_gray_slice_nearest_or_linear(
    frame: np.ndarray,
    out_w: int,
    out_h: int,
    interpolation: int,
) -> np.ndarray:
    frame_arr = np.asarray(frame, dtype=np.uint8)
    if int(frame_arr.shape[0]) == int(out_h) and int(frame_arr.shape[1]) == int(out_w):
        return np.ascontiguousarray(frame_arr)
    return cv2.resize(
        np.ascontiguousarray(frame_arr),
        (int(out_w), int(out_h)),
        interpolation=int(interpolation),
    )


def _cube_t_axis_resize_backend() -> str:
    """Backend used when cubic resizing only changes the slice axis.

    ``slab`` is the default because the common 3072x3072x1930 -> approximately
    cubic case does not need XY resampling.  It processes row slabs through
    OpenCV's native vertical resize and fans the slabs out across Python worker
    threads.  ``slice_exact`` preserves the older endpoint-aligned per-output-slice
    interpolation path for regression testing.
    """
    backend = os.environ.get('YOLO_TTA_CUBE_T_RESIZE_BACKEND', 'slab').strip().lower()
    if backend not in {'slab', 'slice_exact'}:
        backend = 'slab'
    return backend


def _cube_t_axis_slab_rows(in_w: int, in_t: int, out_t: int, workers: int) -> int:
    """Choose a bounded row-slab height for T-axis-only cubic resizing."""
    del in_t, out_t
    env_rows = _env_int('YOLO_TTA_CUBE_T_RESIZE_SLAB_ROWS', 0)
    if env_rows > 0:
        return max(1, int(env_rows))

    # Keep OpenCV's temporary 2D image width below conservative historical limits,
    # while also keeping per-task input/output buffers comfortably bounded.
    max_cv_width = max(1, _env_int('YOLO_TTA_CUBE_T_RESIZE_MAX_CV_WIDTH', 32760))
    rows_by_width = max(1, int(max_cv_width) // max(1, int(in_w)))

    target_mib = max(16, _env_int('YOLO_TTA_CUBE_T_RESIZE_TARGET_MIB_PER_TASK', 384))
    bytes_per_row = max(1, int(in_w)) * 2  # one input byte + one output byte, approximate
    rows_by_memory = max(1, int((target_mib * 1024 * 1024) // max(1, bytes_per_row * max(1, workers))))
    return max(1, min(rows_by_width, rows_by_memory, 16))


def resize_volume_t_axis_only_gray8_slab(
    volume_gray: np.ndarray,
    out_t: int,
    out_path: Path,
    *,
    workers: int = 1,
    prefer_memory: bool = True,
    reserve_bytes: int = 32 * GIB,
) -> np.ndarray:
    """Resize only the first/T axis by processing independent row slabs.

    This is optimized for the dominant SLURM input geometry where X/Y are already
    at the target size and only the shorter frame axis is upsampled to satisfy the
    approximate-cube requirement.  Each task views a ``(T, rows*X)`` slab as a 2D
    OpenCV image and resizes only its height to ``out_t``.
    """
    in_t, in_h, in_w = (int(volume_gray.shape[0]), int(volume_gray.shape[1]), int(volume_gray.shape[2]))
    out_t_i = int(out_t)
    if int(in_t) == out_t_i:
        return volume_gray

    out_mm = allocate_workspace_array(
        shape=(out_t_i, in_h, in_w),
        dtype=np.uint8,
        path=out_path,
        desc='v12.2.0 cubic processing volume (parallel T-axis slab resize)',
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
        initialize_zero=False,
    )

    worker_count = choose_slice_parallel_workers(int(workers), int(in_h))
    rows_per_slab = _cube_t_axis_slab_rows(int(in_w), int(in_t), int(out_t_i), worker_count)
    ranges = [(int(y0), int(min(in_h, y0 + rows_per_slab))) for y0 in range(0, int(in_h), int(rows_per_slab))]
    cv_threads = max(1, _env_int('YOLO_TTA_CUBE_T_RESIZE_CV2_THREADS', 1))

    try:
        previous_cv_threads = cv2.getNumThreads()
    except Exception:
        previous_cv_threads = None
    try:
        cv2.setNumThreads(int(cv_threads))
    except Exception:
        pass

    print(
        'Cubic resize T-axis slab backend: '
        f'in=(t,Y,X)=({in_t},{in_h},{in_w}) -> out_t={out_t_i}, '
        f'slab_rows={rows_per_slab}, slab_tasks={len(ranges)}, workers={worker_count}, '
        f'cv2_threads_per_task={cv_threads}'
    )

    def _resize_slab(range_idx: int) -> None:
        y0, y1 = ranges[int(range_idx)]
        rows = int(y1 - y0)
        slab = np.ascontiguousarray(volume_gray[:, y0:y1, :], dtype=np.uint8)
        slab_2d = slab.reshape((int(in_t), int(rows) * int(in_w)))
        resized_2d = cv2.resize(
            slab_2d,
            (int(rows) * int(in_w), int(out_t_i)),
            interpolation=cv2.INTER_LINEAR,
        )
        out_mm[:, y0:y1, :] = np.ascontiguousarray(resized_2d.reshape((int(out_t_i), int(rows), int(in_w))))

    try:
        parallel_for_indices_chunked(
            len(ranges),
            _resize_slab,
            max_workers=worker_count,
            desc='Resizing orthogonal volume to v12.2.0 cube (T-axis slabs)',
            show_progress=True,
            chunk_size=1,
        )
    finally:
        if previous_cv_threads is not None:
            try:
                cv2.setNumThreads(int(previous_cv_threads))
            except Exception:
                pass

    flush_array(out_mm)
    return out_mm


def resize_volume_to_processing_cube_gray8(
    volume_gray: np.ndarray,
    out_shape: Tuple[int, int, int],
    out_path: Path,
    *,
    workers: int = 1,
    prefer_memory: bool = True,
    reserve_bytes: int = 32 * GIB,
) -> np.ndarray:
    """Resample a gray8 (t,Y,X) volume to the v12.2.0 approximately-cubic processing shape."""
    in_t, in_h, in_w = (int(volume_gray.shape[0]), int(volume_gray.shape[1]), int(volume_gray.shape[2]))
    out_t, out_h, out_w = (int(out_shape[0]), int(out_shape[1]), int(out_shape[2]))
    if (in_t, in_h, in_w) == (out_t, out_h, out_w):
        return volume_gray

    if in_h == out_h and in_w == out_w and _cube_t_axis_resize_backend() == 'slab':
        return resize_volume_t_axis_only_gray8_slab(
            volume_gray,
            out_t,
            out_path,
            workers=int(workers),
            prefer_memory=bool(prefer_memory),
            reserve_bytes=int(reserve_bytes),
        )

    out_mm = allocate_workspace_array(
        shape=(out_t, out_h, out_w),
        dtype=np.uint8,
        path=out_path,
        desc='v12.2.0 cubic processing volume',
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
        initialize_zero=False,
    )

    worker_count = choose_slice_parallel_workers(int(workers), int(out_t))
    chunk_size = choose_parallel_chunk_size(out_t, worker_count, target_chunks_per_worker=2, min_chunk_size=1)

    def _render_target_slice(out_z: int) -> None:
        src_z = _linear_source_index(int(out_z), int(out_t), int(in_t))
        z0 = int(math.floor(src_z))
        z1 = min(in_t - 1, z0 + 1)
        alpha = float(src_z - float(z0))

        f0 = _resize_gray_slice_nearest_or_linear(volume_gray[z0], out_w, out_h, cv2.INTER_LINEAR)
        if z1 == z0 or alpha <= 1e-7:
            out_mm[int(out_z), :, :] = f0
            return
        f1 = _resize_gray_slice_nearest_or_linear(volume_gray[z1], out_w, out_h, cv2.INTER_LINEAR)
        blended = cv2.addWeighted(
            np.ascontiguousarray(f0),
            float(1.0 - alpha),
            np.ascontiguousarray(f1),
            float(alpha),
            0.0,
        )
        out_mm[int(out_z), :, :] = blended

    parallel_for_indices_chunked(
        int(out_t),
        _render_target_slice,
        max_workers=worker_count,
        desc='Resizing orthogonal volume to v12.2.0 cube',
        chunk_size=chunk_size,
    )
    flush_array(out_mm)
    return out_mm


def resize_volume_to_processing_cube_gray8_streaming(
    volume_gray: np.ndarray,
    out_shape: Tuple[int, int, int],
    out_path: Path,
    *,
    workers: int = 1,
    prefer_memory: bool = True,
    reserve_bytes: int = 32 * GIB,
) -> np.ndarray:
    """Start cubic gray8 preprocessing in the background and return its output array immediately."""
    in_t, in_h, in_w = (int(volume_gray.shape[0]), int(volume_gray.shape[1]), int(volume_gray.shape[2]))
    out_t, out_h, out_w = (int(out_shape[0]), int(out_shape[1]), int(out_shape[2]))
    if (in_t, in_h, in_w) == (out_t, out_h, out_w):
        input_ready = volume_readiness(volume_gray)
        if input_ready is not None:
            register_volume_readiness(volume_gray, input_ready)
        return volume_gray

    out_mm = allocate_workspace_array(
        shape=(out_t, out_h, out_w), dtype=np.uint8, path=out_path,
        desc='v12.2.0 cubic processing volume [streaming producer]',
        prefer_memory=bool(prefer_memory), reserve_bytes=int(reserve_bytes), initialize_zero=False,
    )
    readiness = VolumeReadiness(int(out_t), desc='streaming cubic processing volume')
    register_volume_readiness(out_mm, readiness)
    worker_count = choose_slice_parallel_workers(int(workers), int(out_t))
    chunk_size = choose_parallel_chunk_size(out_t, worker_count, target_chunks_per_worker=2, min_chunk_size=1)

    def _render_target_slice(out_z: int) -> None:
        if streaming_producers_aborted():
            raise RuntimeError('streaming cubic resize aborted by pipeline shutdown')
        src_z = _linear_source_index(int(out_z), int(out_t), int(in_t))
        z0 = int(math.floor(src_z))
        z1 = min(in_t - 1, z0 + 1)
        alpha = float(src_z - float(z0))
        wait_for_volume_slice_ready(volume_gray, int(z0))
        f0 = _resize_gray_slice_nearest_or_linear(volume_gray[z0], out_w, out_h, cv2.INTER_LINEAR)
        if z1 == z0 or alpha <= 1e-7:
            out_mm[int(out_z), :, :] = f0
            readiness.mark_slice_ready(int(out_z))
            return
        wait_for_volume_slice_ready(volume_gray, int(z1))
        f1 = _resize_gray_slice_nearest_or_linear(volume_gray[z1], out_w, out_h, cv2.INTER_LINEAR)
        out_mm[int(out_z), :, :] = cv2.addWeighted(np.ascontiguousarray(f0), float(1.0 - alpha), np.ascontiguousarray(f1), float(alpha), 0.0)
        readiness.mark_slice_ready(int(out_z))

    def _resize_worker() -> None:
        try:
            print(
                'Streaming cubic resize producer: '
                f'in=(t,Y,X)=({in_t},{in_h},{in_w}) -> out=(t,Y,X)=({out_t},{out_h},{out_w}), '
                f'workers={int(worker_count)}, chunk_size={int(chunk_size)}'
            )
            parallel_for_indices_chunked(
                int(out_t), _render_target_slice, max_workers=worker_count,
                desc='Streaming resize orthogonal volume to v12.2.0 cube', chunk_size=chunk_size,
            )
            flush_array(out_mm)
            readiness.mark_all_ready()
        except BaseException as exc:
            readiness.mark_failed(exc)
            raise

    # daemon=True (v13.2.2 bug #7): see the streaming decode producer.
    threading.Thread(target=_resize_worker, name='streaming-cubic-resize', daemon=True).start()
    return out_mm


def restore_mask_volume_to_original_shape(
    mask_u8: np.ndarray,
    out_shape: Tuple[int, int, int],
    out_path: Path,
    *,
    workers: int = 1,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
) -> np.ndarray:
    """Map a processing-space binary mask back to the input video's original (t,Y,X) shape."""
    in_t, in_h, in_w = (int(mask_u8.shape[0]), int(mask_u8.shape[1]), int(mask_u8.shape[2]))
    out_t, out_h, out_w = (int(out_shape[0]), int(out_shape[1]), int(out_shape[2]))
    if (in_t, in_h, in_w) == (out_t, out_h, out_w):
        return mask_u8

    out_mm = allocate_workspace_array(
        shape=(out_t, out_h, out_w),
        dtype=np.uint8,
        path=out_path,
        desc='Restored final mask in original input geometry',
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
        initialize_zero=False,
    )
    worker_count = choose_slice_parallel_workers(int(workers), int(out_t))
    chunk_size = choose_parallel_chunk_size(out_t, worker_count, target_chunks_per_worker=2, min_chunk_size=1)

    def _resize_mask_to_output_xy(frame: np.ndarray) -> np.ndarray:
        frame_u8 = (np.asarray(frame, dtype=np.uint8) > 0).astype(np.uint8, copy=False)
        if int(frame_u8.shape[0]) == int(out_h) and int(frame_u8.shape[1]) == int(out_w):
            return np.ascontiguousarray(frame_u8)
        interp = cv2.INTER_AREA if (int(frame_u8.shape[0]) >= int(out_h) and int(frame_u8.shape[1]) >= int(out_w)) else cv2.INTER_NEAREST
        scaled = cv2.resize(
            np.ascontiguousarray(frame_u8 * np.uint8(255)),
            (int(out_w), int(out_h)),
            interpolation=int(interp),
        )
        return (scaled > 0).astype(np.uint8, copy=False)

    def _restore_slice(out_z: int) -> None:
        if int(in_t) >= int(out_t):
            src_start = int(math.floor(float(out_z) * float(in_t) / float(out_t)))
            src_stop = int(math.ceil(float(out_z + 1) * float(in_t) / float(out_t)))
            src_start = int(np.clip(src_start, 0, in_t - 1))
            src_stop = int(np.clip(max(src_start + 1, src_stop), 1, in_t))
            restored = np.zeros((int(out_h), int(out_w)), dtype=np.uint8)
            for src_idx in range(src_start, src_stop):
                restored |= _resize_mask_to_output_xy(mask_u8[int(src_idx)])
            out_mm[int(out_z), :, :] = restored
            return

        src_z = _linear_source_index(int(out_z), int(out_t), int(in_t))
        src_idx = int(np.clip(int(round(src_z)), 0, in_t - 1))
        out_mm[int(out_z), :, :] = _resize_mask_to_output_xy(mask_u8[src_idx])

    parallel_for_indices_chunked(
        int(out_t),
        _restore_slice,
        max_workers=worker_count,
        desc='Restoring final mask to original input geometry',
        chunk_size=chunk_size,
    )
    flush_array(out_mm)
    return out_mm


def resolve_radial_azimuth_angle(
    requested_angle: Optional[float],
    *,
    enable_radial: bool,
    diameter: int,
) -> float:
    """Resolve v12.2.0 radial activation and default full-coverage angle."""
    if requested_angle is not None:
        if float(requested_angle) <= 0.0:
            return 0.0
        return float(requested_angle)
    if bool(enable_radial):
        return radial_full_coverage_angle_deg(int(diameter))
    return 0.0


def ffmpeg_rawvideo_writer(
    out_path: Path,
    width: int,
    height: int,
    fps: float,
    pix_fmt_in: str = "gray",
    codec: str = "ffv1",
    pix_fmt_out: Optional[str] = "gray",
    codec_args: Optional[Sequence[str]] = None,
) -> subprocess.Popen:
    """Return a Popen with stdin open for writing raw frames."""
    _require_bin("ffmpeg")
    out_path.parent.mkdir(parents=True, exist_ok=True)
    cmd = [
        "ffmpeg",
        "-y",
        "-v", "error",
        "-f", "rawvideo",
        "-pix_fmt", pix_fmt_in,
        "-s", f"{width}x{height}",
        "-r", f"{fps}",
        "-i", "-",
        "-an",
    ]

    if str(codec) == 'ffv1':
        # v13.2.5 (speed #5): FFV1 slice-threading scales to the slice count; the old
        # "-threads 4" cap left a 30-slice encoder nearly serial on large boxes.
        ffv1_threads = max(1, _env_int('YOLO_TTA_FFV1_THREADS', 16))
        cmd.extend(["-c:v", "ffv1", "-level", "3", "-slices", "30", "-threads", str(int(ffv1_threads))])
    else:
        cmd.extend(["-c:v", str(codec)])

    if codec_args:
        cmd.extend([str(x) for x in codec_args])

    if pix_fmt_out:
        cmd.extend(["-pix_fmt", str(pix_fmt_out)])

    cmd.append(str(out_path))
    proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    assert proc.stdin is not None
    return proc


def ffmpeg_ffv1_gray_writer(
    out_path: Path,
    width: int,
    height: int,
    fps: float,
) -> subprocess.Popen:
    """FFV1 MKV writer for single-channel temporary, prediction, and binary videos."""
    return ffmpeg_rawvideo_writer(
        out_path=out_path,
        width=int(width),
        height=int(height),
        fps=float(fps),
        pix_fmt_in='gray',
        codec='ffv1',
        pix_fmt_out='gray',
    )


def ffmpeg_ffv1_rgb_writer(
    out_path: Path,
    width: int,
    height: int,
    fps: float,
) -> subprocess.Popen:
    """FFV1 MKV writer for color presentation overlays."""
    return ffmpeg_rawvideo_writer(
        out_path=out_path,
        width=int(width),
        height=int(height),
        fps=float(fps),
        pix_fmt_in='rgb24',
        codec='ffv1',
        pix_fmt_out='yuv444p',
    )


def close_ffmpeg_writer(proc: subprocess.Popen) -> None:
    """Close an ffmpeg writer Popen safely (Python 3.12+ compatible).

    IMPORTANT:
      Calling proc.stdin.close() and then proc.communicate() triggers
      'ValueError: flush of closed file' on Python 3.12, because communicate()
      tries to flush stdin even if it is already closed. We therefore:
        1) close stdin (if open)
        2) set proc.stdin = None
        3) call communicate() to drain stdout/stderr
    """
    if proc.stdin is not None and not proc.stdin.closed:
        try:
            proc.stdin.close()
        except Exception:
            pass

    # Prevent subprocess.communicate() from flushing a closed stdin (Py3.12 behavior)
    proc.stdin = None  # type: ignore[attr-defined]

    _, err = proc.communicate()
    if proc.returncode not in (0, None):
        msg = err.decode("utf-8", errors="ignore") if isinstance(err, (bytes, bytearray)) else str(err)
        raise RuntimeError(f"ffmpeg write failed: {msg}")


def _path_is_relative_to(path: Path, root: Path) -> bool:
    try:
        Path(path).resolve().relative_to(Path(root).resolve())
        return True
    except Exception:
        return False


def purge_temporary_mkv(
    video_path: Optional[Path],
    *,
    temp_dir: Path,
    keep_temp: bool,
    reason: str = '',
) -> bool:
    """Delete one temporary MKV once its last pipeline consumer has finished.

    The guard is intentionally narrow: only ``*.mkv`` files below the active scratch/temp
    directory are eligible. Final output MKVs live in the output directory and are never
    removed through this helper.
    """
    if bool(keep_temp) or video_path is None:
        return False

    path = Path(video_path)
    if path.suffix.lower() != '.mkv':
        return False
    if not _path_is_relative_to(path, Path(temp_dir)):
        return False
    if not path.exists():
        return False

    try:
        path.unlink(missing_ok=True)
        if reason:
            print(f'Purged temporary MKV after last use ({reason}): {path.name}')
        return True
    except Exception as exc:
        print(f'Warning: failed to purge temporary MKV {path} ({exc})')
        return False


def purge_remaining_temporary_mkvs(temp_dir: Path, *, keep_temp: bool) -> int:
    """Best-effort final sweep for temporary MKVs that survived targeted lifecycle deletion."""
    if bool(keep_temp):
        return 0
    root = Path(temp_dir)
    if not root.exists():
        return 0

    purged = 0
    for path in list(root.rglob('*.mkv')):
        if purge_temporary_mkv(path, temp_dir=root, keep_temp=False, reason='final scratch sweep'):
            purged += 1
    return int(purged)


# --------------------------
# Affine transforms
# --------------------------

@dataclass(frozen=True)
class AffineSpec:
    view: str
    angle_deg: float
    src_w: int
    src_h: int
    out_size: int
    canvas_w: int
    canvas_h: int
    pad_size: int
    pad_off_x: float
    pad_off_y: float
    M_out_to_src: np.ndarray      # 2x3 float32
    M_src_to_out: np.ndarray      # 2x3 float32
    M_canvas_to_src: np.ndarray   # 2x3 float32, pre-scale augmented canvas -> native view
    M_src_to_canvas: np.ndarray   # 2x3 float32, native view -> pre-scale augmented canvas


@dataclass(frozen=True)
class AugJob:
    aug_id: str
    angle_deg: float
    meta_path: Path
    aff: AffineSpec


def _expanded_pad_size(w: int, h: int, angle_deg: float) -> int:
    """Square canvas size P to fit a WxH rectangle rotated by angle_deg."""
    theta = math.radians(angle_deg % 360.0)
    c = abs(math.cos(theta))
    s = abs(math.sin(theta))
    w_rot = w * c + h * s
    h_rot = w * s + h * c
    P = int(math.ceil(max(w_rot, h_rot)))
    return max(P, max(w, h))


def _affine2x3_to_3x3(M: np.ndarray) -> np.ndarray:
    out = np.eye(3, dtype=np.float64)
    out[:2, :3] = np.asarray(M, dtype=np.float64)
    return out


def _format_angle_aug_id(angle_deg: float) -> str:
    token = f'{float(angle_deg):g}'.replace('-', 'm').replace('.', 'p')
    return f'a{token}'


def build_affine(
    view: str,
    src_w: int,
    src_h: int,
    out_size: int,
    angle_deg: float,
    pad_mode: str,
) -> AffineSpec:
    """
    Build a single affine transform that performs, in one pass:

      source(native view) -> optional black-padding canvas -> rotation around canvas center
      -> scale to out_size x out_size

    Cartesian views (Transverse, Sagittal, Coronal, and Tilted View in-plane rotation) use
    pad_mode='clamp', which rotates directly on the source-sized canvas so non-90° content that
    leaves the source frame is discarded. Radial uses pad_mode='pad' so non-90° radial rotations are
    black-padded before scaling.
    """
    if pad_mode not in ("clamp", "pad"):
        raise ValueError("pad_mode must be 'clamp' or 'pad'")

    if pad_mode == "pad":
        canvas_w = canvas_h = _expanded_pad_size(src_w, src_h, angle_deg)
    else:
        canvas_w = src_w
        canvas_h = src_h

    off_x = (canvas_w - src_w) / 2.0
    off_y = (canvas_h - src_h) / 2.0

    cx_canvas = (canvas_w - 1) / 2.0
    cy_canvas = (canvas_h - 1) / 2.0
    cx_out = (out_size - 1) / 2.0
    cy_out = (out_size - 1) / 2.0

    M_pad = np.array(
        [
            [1.0, 0.0, off_x],
            [0.0, 1.0, off_y],
            [0.0, 0.0, 1.0],
        ],
        dtype=np.float64,
    )

    M_rot = _affine2x3_to_3x3(cv2.getRotationMatrix2D((cx_canvas, cy_canvas), angle_deg, 1.0))

    sx = out_size / float(canvas_w)
    sy = out_size / float(canvas_h)
    M_scale = np.array(
        [
            [sx, 0.0, cx_out - sx * cx_canvas],
            [0.0, sy, cy_out - sy * cy_canvas],
            [0.0, 0.0, 1.0],
        ],
        dtype=np.float64,
    )

    M_src_to_canvas3 = M_rot @ M_pad
    M_canvas_to_src3 = np.linalg.inv(M_src_to_canvas3)
    M_src_to_out3 = M_scale @ M_src_to_canvas3
    M_out_to_src3 = np.linalg.inv(M_src_to_out3)

    return AffineSpec(
        view=view,
        angle_deg=float(angle_deg),
        src_w=src_w,
        src_h=src_h,
        out_size=out_size,
        canvas_w=int(canvas_w),
        canvas_h=int(canvas_h),
        pad_size=int(max(canvas_w, canvas_h)),
        pad_off_x=float(off_x),
        pad_off_y=float(off_y),
        M_out_to_src=M_out_to_src3[:2, :3].astype(np.float32),
        M_src_to_out=M_src_to_out3[:2, :3].astype(np.float32),
        M_canvas_to_src=M_canvas_to_src3[:2, :3].astype(np.float32),
        M_src_to_canvas=M_src_to_canvas3[:2, :3].astype(np.float32),
    )


# --------------------------
# View slicing
# --------------------------

TILTED_VIEW_FAMILY = 'tilted'


@dataclass(frozen=True)
class ViewInfo:
    name: str
    num_slices: int
    src_h: int
    src_w: int
    pad_mode: str  # 'clamp' or 'pad'
    family: str = 'orthogonal'
    summary_family: str = 'transverse'
    display_name: str = 'Transverse'
    azimuths_deg: Tuple[float, ...] = ()
    diameter: int = 0
    center_x: float = 0.0
    center_y: float = 0.0
    roi_radius: float = 0.0
    full_t: int = 0
    full_h: int = 0
    full_w: int = 0
    tilt_angle_deg: float = 0.0
    tilt_direction: str = ''
    tilt_frame_start: int = 0
    tilt_frame_stop: int = 0
    tilt_base_view: str = ''
    horizontal_axis: str = ''
    vertical_axis: str = ''
    stack_axis: str = ''


def is_tilted_view(view: ViewInfo) -> bool:
    """Return True for v12.2.0 generalized Tilted Views."""
    return str(view.family) == TILTED_VIEW_FAMILY


def tilted_base_view_name(view: ViewInfo) -> str:
    if str(view.tilt_base_view):
        return str(view.tilt_base_view)
    return str(view.name)


def cartesian_view_axis_spec(base_view: str, T: int, H: int, W: int) -> Dict[str, object]:
    base = str(base_view).lower()
    if base == 'transverse':
        return {
            'name': 'transverse',
            'display_name': 'Transverse',
            'num_slices': int(T),
            'src_h': int(H),
            'src_w': int(W),
            'summary_family': 'transverse',
            'horizontal_axis': 'x',
            'vertical_axis': 'y',
            'stack_axis': 't',
        }
    if base == 'sagittal':
        return {
            'name': 'sagittal',
            'display_name': 'Sagittal',
            'num_slices': int(H),
            'src_h': int(T),
            'src_w': int(W),
            'summary_family': 'sagittal',
            'horizontal_axis': 'x',
            'vertical_axis': 't',
            'stack_axis': 'y',
        }
    if base == 'coronal':
        return {
            'name': 'coronal',
            'display_name': 'Coronal',
            'num_slices': int(W),
            'src_h': int(T),
            'src_w': int(H),
            'summary_family': 'coronal',
            'horizontal_axis': 'y',
            'vertical_axis': 't',
            'stack_axis': 'x',
        }
    raise ValueError(f'Unsupported Cartesian base view: {base_view}')


def tilted_stack_axis_length(view: ViewInfo) -> int:
    axis = str(view.stack_axis or cartesian_view_axis_spec(tilted_base_view_name(view), view.full_t, view.full_h, view.full_w)['stack_axis'])
    if axis == 't':
        return int(view.full_t)
    if axis == 'y':
        return int(view.full_h)
    if axis == 'x':
        return int(view.full_w)
    raise ValueError(f'Unsupported Tilted View stacking axis: {axis}')


def build_radial_azimuths(azimuth_angle: float) -> List[float]:
    if float(azimuth_angle) <= 0.0:
        return []
    out: List[float] = []
    a = 0.0
    step = float(azimuth_angle)
    while a < 180.0 - 1e-9:
        out.append(float(a))
        a += step
    if not out:
        out.append(0.0)
    return out


def tilted_frame_center(view: ViewInfo, frame_idx: int) -> int:
    return int(view.tilt_frame_start) + int(frame_idx)


def _format_signed_angle_token(angle_deg: float) -> str:
    sign = 'p' if float(angle_deg) >= 0.0 else 'm'
    mag = f'{abs(float(angle_deg)):g}'.replace('.', 'p')
    return f'{sign}{mag}'


def _format_signed_angle_label(angle_deg: float) -> str:
    sign = '+' if float(angle_deg) >= 0.0 else '-'
    return f'{sign}{abs(float(angle_deg)):g}°'


def pretty_view_name(view: ViewInfo) -> str:
    return str(view.display_name)


def view_output_token(view: ViewInfo) -> str:
    if is_tilted_view(view):
        base = str(tilted_base_view_name(view)).capitalize()
        direction = str(view.tilt_direction or 'vertical').capitalize()
        return f'Tilted{base}_{direction}_{_format_signed_angle_token(float(view.tilt_angle_deg))}'
    return pretty_view_name(view).replace(' ', '_')


def get_view_infos(
    T: int,
    H: int,
    W: int,
    disable_multiplanar: Optional[bool] = None,
    azimuth_angle: float = 0.0,
    include_radial: bool = True,
    tilt_views: Optional[Sequence[str]] = None,
    tilt_angles: Optional[Sequence[float]] = None,
    tilt_directions: Optional[Sequence[str]] = None,
    enable_sagittal: bool = False,
    enable_coronal: bool = False,
    radial_native_raster: int = 0,
) -> List[ViewInfo]:
    # Backward-compatible alias for older command lines; v12.2.0 controls Sagittal and
    # Coronal independently via --enable_sagittal and --enable_coronal.
    if disable_multiplanar is not None:
        enable_sagittal = bool(enable_sagittal or (not bool(disable_multiplanar)))
        enable_coronal = bool(enable_coronal or (not bool(disable_multiplanar)))

    transverse_spec = cartesian_view_axis_spec('transverse', T, H, W)
    views = [
        ViewInfo(
            name=str(transverse_spec['name']),
            num_slices=int(transverse_spec['num_slices']),
            src_h=int(transverse_spec['src_h']),
            src_w=int(transverse_spec['src_w']),
            pad_mode='clamp',
            family='orthogonal',
            summary_family=str(transverse_spec['summary_family']),
            display_name=str(transverse_spec['display_name']),
            full_t=T,
            full_h=H,
            full_w=W,
            tilt_base_view='transverse',
            horizontal_axis=str(transverse_spec['horizontal_axis']),
            vertical_axis=str(transverse_spec['vertical_axis']),
            stack_axis=str(transverse_spec['stack_axis']),
        ),
    ]
    if bool(enable_sagittal):
        spec = cartesian_view_axis_spec('sagittal', T, H, W)
        views.append(ViewInfo(
            name=str(spec['name']),
            num_slices=int(spec['num_slices']),
            src_h=int(spec['src_h']),
            src_w=int(spec['src_w']),
            pad_mode='clamp',
            family='orthogonal',
            summary_family=str(spec['summary_family']),
            display_name=str(spec['display_name']),
            full_t=T,
            full_h=H,
            full_w=W,
            tilt_base_view='sagittal',
            horizontal_axis=str(spec['horizontal_axis']),
            vertical_axis=str(spec['vertical_axis']),
            stack_axis=str(spec['stack_axis']),
        ))
    if bool(enable_coronal):
        spec = cartesian_view_axis_spec('coronal', T, H, W)
        views.append(ViewInfo(
            name=str(spec['name']),
            num_slices=int(spec['num_slices']),
            src_h=int(spec['src_h']),
            src_w=int(spec['src_w']),
            pad_mode='clamp',
            family='orthogonal',
            summary_family=str(spec['summary_family']),
            display_name=str(spec['display_name']),
            full_t=T,
            full_h=H,
            full_w=W,
            tilt_base_view='coronal',
            horizontal_axis=str(spec['horizontal_axis']),
            vertical_axis=str(spec['vertical_axis']),
            stack_axis=str(spec['stack_axis']),
        ))

    if include_radial and float(azimuth_angle) > 0.0:
        azimuths = tuple(build_radial_azimuths(float(azimuth_angle)))
        diameter = int(min(W, H))
        roi_radius = float(max(0.0, (diameter - 1) / 2.0))
        # v13.2.5 (speed #1): fold the --imgsz downscale into the radial sampling raster.
        # When radial_native_raster (= --imgsz) is smaller than the native pitch, the radial
        # view's native frame is sampled DIRECTLY at (raster t-rows x raster u-samples) —
        # Lanczos-3 taps at the coarser u pitch plus a linear t-row lerp — instead of
        # rendering the full (T x diameter) frame and warping it down to --imgsz afterwards.
        # This removes one full interpolation pass per radial frame, makes the angle-0 model
        # render an identity (speed #10), and shrinks every downstream radial-native volume.
        # diameter/roi_radius/azimuth spacing stay in PHYSICAL working pixels.
        raster = int(radial_native_raster)
        radial_rows = int(min(T, raster)) if raster > 0 else int(T)
        radial_u = int(min(diameter, raster)) if raster > 0 else int(diameter)
        views.append(
            ViewInfo(
                name='radial',
                num_slices=len(azimuths),
                src_h=radial_rows,
                src_w=radial_u,
                pad_mode='pad',
                family='radial',
                summary_family='radial',
                display_name='Radial',
                full_t=T,
                azimuths_deg=azimuths,
                diameter=diameter,
                center_x=float((W - 1) / 2.0),
                center_y=float((H - 1) / 2.0),
                roi_radius=roi_radius,
                full_h=H,
                full_w=W,
                horizontal_axis='r',
                vertical_axis='t',
                stack_axis='azimuth',
            )
        )

    # Scheduling order in v12.2.0 is Cartesian upright views, then Radial, then Tilted.
    # Tilted variants themselves are deterministic: base view Transverse/Sagittal/Coronal,
    # direction horizontal/vertical, signed angle positive/negative, angle value ascending.
    tilt_angles_resolved = sorted({float(a) for a in (tilt_angles or []) if float(a) > 0.0})
    requested_dirs = set(resolve_tilt_directions(tilt_directions if tilt_directions is not None else ['vertical']))
    tilt_dirs_resolved = [d for d in ('horizontal', 'vertical') if d in requested_dirs]
    tilt_views_requested = set(resolve_tilt_views(tilt_views if tilt_views is not None else ['transverse']))
    tilt_views_resolved = [base for base in ('transverse', 'sagittal', 'coronal') if base in tilt_views_requested]
    for base_view in tilt_views_resolved:
        spec = cartesian_view_axis_spec(str(base_view), T, H, W)
        for tilt_direction in tilt_dirs_resolved:
            for tilt_angle in tilt_angles_resolved:
                for sign in (+1.0, -1.0):
                    signed_angle = float(sign * tilt_angle)
                    token = _format_signed_angle_token(signed_angle)
                    tilt_frame_start, tilt_frame_stop = 0, int(spec['num_slices']) - 1
                    base_label = str(spec['display_name'])
                    direction_label = str(tilt_direction).capitalize()
                    views.append(ViewInfo(
                        name=f'tilted_{base_view}_{tilt_direction}_{token}',
                        num_slices=int(spec['num_slices']),
                        src_h=int(spec['src_h']),
                        src_w=int(spec['src_w']),
                        pad_mode='clamp',
                        family=TILTED_VIEW_FAMILY,
                        summary_family=f'tilted_{base_view}_{tilt_direction}_{token}',
                        display_name=f'Tilted {base_label} {direction_label} {_format_signed_angle_label(signed_angle)}',
                        full_t=T,
                        full_h=H,
                        full_w=W,
                        tilt_angle_deg=signed_angle,
                        tilt_direction=str(tilt_direction),
                        tilt_frame_start=int(tilt_frame_start),
                        tilt_frame_stop=int(tilt_frame_stop),
                        tilt_base_view=str(base_view),
                        horizontal_axis=str(spec['horizontal_axis']),
                        vertical_axis=str(spec['vertical_axis']),
                        stack_axis=str(spec['stack_axis']),
                    ))

    return views


def orthogonal_views_only(views: Sequence[ViewInfo]) -> List[ViewInfo]:
    return [v for v in views if v.family == 'orthogonal']


@dataclass(frozen=True)
class RadialSampler:
    angle_deg: float
    diameter: int
    x_idx: np.ndarray
    y_idx: np.ndarray
    x_w: np.ndarray
    y_w: np.ndarray
    nn_x: np.ndarray
    nn_y: np.ndarray


_RADIAL_SAMPLER_CACHE: Dict[Tuple[int, int, int, float], RadialSampler] = {}

RADIAL_LANCZOS_A = 3


def _lanczos_kernel(x: np.ndarray, a: int = RADIAL_LANCZOS_A) -> np.ndarray:
    x = np.asarray(x, dtype=np.float32)
    out = np.sinc(x) * np.sinc(x / float(a))
    out[np.abs(x) >= float(a)] = 0.0
    return out.astype(np.float32, copy=False)


def _lanczos_offsets(a: int = RADIAL_LANCZOS_A) -> np.ndarray:
    """Integer support offsets for a Lanczos-a kernel around floor(sample)."""
    a_i = max(1, int(a))
    return np.arange(-(a_i - 1), a_i + 1, dtype=np.int32)


def _lanczos_tap_count(a: int = RADIAL_LANCZOS_A) -> int:
    return int(_lanczos_offsets(int(a)).size)


def get_radial_sampler(view: ViewInfo, angle_deg: float) -> RadialSampler:
    if view.family != 'radial':
        raise ValueError('Radial sampler requested for a non-radial view')

    # v13.2.5 (speed #1): the u sample count is the radial view's native raster width
    # (view.src_w, which folds the --imgsz downscale in); view.diameter stays the physical
    # working-pixel diameter that positions the taps along the full ROI diameter.
    n_u = int(view.src_w) if int(view.src_w) > 0 else int(view.diameter)
    key = (int(view.full_w), int(view.full_h), int(view.diameter), int(n_u), round(float(angle_deg), 6))
    cached = _RADIAL_SAMPLER_CACHE.get(key)
    if cached is not None:
        return cached

    diameter = int(n_u)
    coords = np.linspace(-float(view.roi_radius), float(view.roi_radius), diameter, dtype=np.float32)
    theta = math.radians(float(angle_deg))
    xs = np.asarray(float(view.center_x) + coords * math.cos(theta), dtype=np.float32)
    ys = np.asarray(float(view.center_y) + coords * math.sin(theta), dtype=np.float32)

    offsets = _lanczos_offsets(RADIAL_LANCZOS_A)
    x0 = np.floor(xs).astype(np.int32, copy=False)
    y0 = np.floor(ys).astype(np.int32, copy=False)

    x_idx_raw = x0[:, None] + offsets[None, :]
    y_idx_raw = y0[:, None] + offsets[None, :]

    x_w = _lanczos_kernel(xs[:, None] - x_idx_raw, a=RADIAL_LANCZOS_A)
    y_w = _lanczos_kernel(ys[:, None] - y_idx_raw, a=RADIAL_LANCZOS_A)

    x_valid = (x_idx_raw >= 0) & (x_idx_raw < int(view.full_w))
    y_valid = (y_idx_raw >= 0) & (y_idx_raw < int(view.full_h))
    x_w *= x_valid.astype(np.float32, copy=False)
    y_w *= y_valid.astype(np.float32, copy=False)

    # v13.2.4 (task #3): renormalize each sample's separable taps after out-of-bounds zeroing.
    # The windowed-sinc taps do not sum exactly to 1 even fully in-bounds, and zeroing the
    # out-of-bounds taps at the diameter endpoints (which land on the image edge for a centered
    # ROI) previously left the boundary samples summing to < 1, darkening the first/last pixels
    # of every radial line. Rows whose taps are all out-of-bounds stay zero (black fill).
    x_w_sum = np.sum(x_w, axis=1, keepdims=True)
    np.divide(x_w, x_w_sum, out=x_w, where=np.abs(x_w_sum) > 1e-6)
    y_w_sum = np.sum(y_w, axis=1, keepdims=True)
    np.divide(y_w, y_w_sum, out=y_w, where=np.abs(y_w_sum) > 1e-6)

    x_idx = np.clip(x_idx_raw, 0, int(view.full_w) - 1).astype(np.int32, copy=False)
    y_idx = np.clip(y_idx_raw, 0, int(view.full_h) - 1).astype(np.int32, copy=False)

    sampler = RadialSampler(
        angle_deg=float(angle_deg),
        diameter=diameter,
        x_idx=x_idx,
        y_idx=y_idx,
        x_w=x_w.astype(np.float32, copy=False),
        y_w=y_w.astype(np.float32, copy=False),
        nn_x=np.clip(np.rint(xs).astype(np.int32, copy=False), 0, int(view.full_w) - 1),
        nn_y=np.clip(np.rint(ys).astype(np.int32, copy=False), 0, int(view.full_h) - 1),
    )
    _RADIAL_SAMPLER_CACHE[key] = sampler
    return sampler


def choose_radial_exact_block_frames(diameter: int, target_bytes: int = 256 * 1024 * 1024) -> int:
    env = os.environ.get('YOLO_TTA_RADIAL_EXACT_BLOCK_FRAMES', '').strip()
    if env:
        try:
            return max(1, int(env))
        except Exception:
            pass

    bytes_per_frame = max(1, int(diameter) * _lanczos_tap_count(RADIAL_LANCZOS_A) * np.dtype(np.float32).itemsize)
    block = max(1, int(target_bytes // bytes_per_frame))
    return max(1, min(256, block))


def _radial_sampler_flat_taps(sampler: RadialSampler, image_w: int) -> Tuple[np.ndarray, np.ndarray]:
    """Per-sample flattened 36-tap indices and combined separable weights.

    v13.2.5 (speed #2): one fancy gather over flat (row-major) indices with precombined
    y*x weights replaces six separate 3D gathers plus per-tap float temps. Rebuilt per call
    (sub-millisecond for a 2048-sample line) so the per-angle sampler cache stays small.
    """
    u_len = int(sampler.diameter)
    flat_idx = (
        sampler.y_idx.astype(np.int64)[:, :, None] * int(image_w)
        + sampler.x_idx.astype(np.int64)[:, None, :]
    ).reshape(u_len, -1)
    w2d = (
        sampler.y_w.astype(np.float32)[:, :, None]
        * sampler.x_w.astype(np.float32)[:, None, :]
    ).reshape(u_len, -1)
    return flat_idx, w2d


def extract_radial_slice_frame(
    volume_rgb: np.ndarray,
    sampler: RadialSampler,
    out_rows: Optional[int] = None,
) -> np.ndarray:
    """Extract one radial diameter frame.

    v13.2.5 (speed #1/#2): the u axis is Lanczos-3 sampled at the sampler's raster pitch via a
    single flat gather + einsum per t block; when ``out_rows`` folds the t axis (radial native
    raster < native t), native rows are reduced to ``out_rows`` with the same center-aligned
    linear interpolation cv2.warpAffine previously applied when scaling the frame to --imgsz.
    """
    t_dim = int(volume_rgb.shape[0])
    u_len = int(sampler.diameter)
    rows = int(out_rows) if out_rows is not None and int(out_rows) > 0 else t_dim
    fold_t = int(rows) != int(t_dim)

    image_w = int(volume_rgb.shape[2])
    flat_idx, w2d = _radial_sampler_flat_taps(sampler, image_w)
    block_frames = choose_radial_exact_block_frames(u_len)

    plane_len = int(volume_rgb.shape[1]) * image_w
    proj = np.empty((t_dim, u_len), dtype=np.float32) if fold_t else None
    out = None if fold_t else np.empty((t_dim, u_len), dtype=np.uint8)

    for start in range(0, t_dim, block_frames):
        stop = min(t_dim, start + block_frames)
        block2d = np.asarray(volume_rgb[start:stop]).reshape(stop - start, plane_len)
        samples = block2d[:, flat_idx].astype(np.float32, copy=False)
        acc = np.einsum('tuk,uk->tu', samples, w2d)
        if fold_t:
            proj[start:stop, :] = acc
        else:
            out[start:stop, :] = np.clip(np.rint(acc), 0.0, 255.0).astype(np.uint8)

    if not fold_t:
        return out

    # Center-aligned linear t reduction (matches the former warpAffine INTER_LINEAR scale).
    rf = (np.arange(rows, dtype=np.float64) + 0.5) * (float(t_dim) / float(rows)) - 0.5
    r0 = np.clip(np.floor(rf).astype(np.int64), 0, t_dim - 1)
    r1 = np.minimum(r0 + 1, t_dim - 1)
    alpha = np.clip(rf - r0, 0.0, 1.0).astype(np.float32)[:, None]
    folded = proj[r0] * (np.float32(1.0) - alpha) + proj[r1] * alpha
    return np.clip(np.rint(folded), 0.0, 255.0).astype(np.uint8)


def _env_flag(name: str, default: bool = False) -> bool:
    raw = os.environ.get(name)
    if raw is None:
        return bool(default)
    s = str(raw).strip().lower()
    if s in ("", "0", "false", "no", "off"):
        return False
    return True


def write_aug_job_meta(job: AugJob, view: ViewInfo) -> None:
    job.meta_path.parent.mkdir(parents=True, exist_ok=True)
    job.meta_path.write_text(
        json.dumps(
            {
                'view': view.name,
                'family': view.family,
                'num_slices': int(view.num_slices),
                'full_t': int(view.full_t),
                'angle_deg': float(job.angle_deg),
                'src_w': view.src_w,
                'src_h': view.src_h,
                'tilt_angle_deg': float(view.tilt_angle_deg),
                'tilt_direction': str(view.tilt_direction),
                'tilt_base_view': str(view.tilt_base_view),
                'horizontal_axis': str(view.horizontal_axis),
                'vertical_axis': str(view.vertical_axis),
                'stack_axis': str(view.stack_axis),
                'tilt_frame_start': int(view.tilt_frame_start),
                'tilt_frame_stop': int(view.tilt_frame_stop),
                'out_size': int(job.aff.out_size),
                'pad_mode': view.pad_mode,
                'canvas_w': int(job.aff.canvas_w),
                'canvas_h': int(job.aff.canvas_h),
                'pad_size': int(job.aff.pad_size),
                'pad_off_x': float(job.aff.pad_off_x),
                'pad_off_y': float(job.aff.pad_off_y),
                'M_out_to_src': job.aff.M_out_to_src.tolist(),
                'M_src_to_out': job.aff.M_src_to_out.tolist(),
            },
            indent=2,
        )
    )


def build_aug_jobs_for_view(
    view: ViewInfo,
    angles: Sequence[float],
    out_size: int,
    temp_dir: Path,
) -> List[AugJob]:
    aug_dir = temp_dir / 'aug' / view.name
    jobs: List[AugJob] = []

    for angle in angles:
        aug_id = _format_angle_aug_id(float(angle))
        aff = build_affine(
            view=view.name,
            src_w=view.src_w,
            src_h=view.src_h,
            out_size=out_size,
            angle_deg=float(angle),
            pad_mode=view.pad_mode,
        )
        jobs.append(
            AugJob(
                aug_id=aug_id,
                angle_deg=float(angle),
                meta_path=aug_dir / f'{view.name}_{aug_id}.meta.json',
                aff=aff,
            )
        )
    return jobs


def iter_aug_jobs_round_robin(
    views: Sequence[ViewInfo],
    aug_jobs_by_view: Dict[str, Sequence[AugJob]],
) -> Iterator[Tuple[ViewInfo, AugJob]]:
    """Yield augmentation jobs one round per view so later view families start earlier.

    The prior FIFO submission order rendered every augmentation for early views before later
    views even entered the render queue. That could leave later families, notably tilted
    transverse variants, sitting behind a long tail of earlier canvas/tile work even while the GPU
    had no ready inference job. Round-robin submission starts one job per active view first, then
    the second job per view, and so on.
    """
    queues: Dict[str, deque[AugJob]] = {
        str(view.name): deque(aug_jobs_by_view.get(view.name, ()))
        for view in views
    }
    while True:
        emitted = False
        for view in views:
            q = queues[str(view.name)]
            if not q:
                continue
            emitted = True
            yield view, q.popleft()
        if not emitted:
            break


@dataclass(frozen=True)
class TileConfig:
    tile_size: int
    tile_stride: int
    config_id: str


def resolve_tile_configs(tile_sizes_raw: Sequence[str] | str | int | None, tile_strides_raw: Sequence[str] | str | int | None) -> List[TileConfig]:
    """Resolve v12 dense tile configurations as PAIRED size/stride entries.

    v13.2.5 (ruling A2): ``--tile_size`` and ``--tile_stride`` are index-paired, not a
    Cartesian product. ``--tile_size 1536,2048 --tile_stride 256,512`` creates exactly two
    tile configurations (1536/256 and 2048/512). A single stride value is broadcast across
    every tile size; otherwise the counts must match. Each stride is validated against its
    OWN paired size only.
    """
    tile_sizes = _parse_int_list(tile_sizes_raw)
    tile_strides = _parse_int_list(tile_strides_raw)

    if not tile_sizes:
        tile_sizes = [0]
    if not tile_strides:
        tile_strides = [0]

    if any(int(v) == 0 for v in tile_sizes):
        if len(tile_sizes) == 1 and int(tile_sizes[0]) == 0:
            if any(int(v) != 0 for v in tile_strides):
                raise ValueError('--tile_stride must be 0 when --tile_size disables tiled predictions')
            return []
        raise ValueError('--tile_size 0 cannot be mixed with active tile sizes')

    if any(int(v) <= 0 for v in tile_sizes):
        raise ValueError('--tile_size values must be > 0 when dense tiling is active')
    if any(int(v) <= 0 for v in tile_strides):
        raise ValueError('--tile_stride values must be > 0 when dense tiling is active')

    if len(tile_strides) == 1 and len(tile_sizes) > 1:
        tile_strides = [int(tile_strides[0])] * len(tile_sizes)
    if len(tile_strides) != len(tile_sizes):
        raise ValueError(
            f'--tile_size and --tile_stride are paired (ruling A2): got {len(tile_sizes)} size value(s) '
            f'and {len(tile_strides)} stride value(s); provide matching counts or a single stride'
        )

    configs: List[TileConfig] = []
    seen: set[str] = set()
    for tile_size, tile_stride in zip(tile_sizes, tile_strides):
        if int(tile_stride) > int(tile_size):
            raise ValueError(
                f'--tile_stride {int(tile_stride)} must be less than or equal to its paired '
                f'--tile_size {int(tile_size)}'
            )
        config_id = f's{int(tile_size)}_st{int(tile_stride)}'
        if config_id in seen:
            raise ValueError(f'Duplicate dense tile configuration: tile_size={int(tile_size)}, tile_stride={int(tile_stride)}')
        seen.add(config_id)
        configs.append(TileConfig(tile_size=int(tile_size), tile_stride=int(tile_stride), config_id=config_id))

    return configs


@dataclass(frozen=True)
class DenseTileJob:
    view: str
    aug_id: str
    config_id: str
    tile_id: str
    tile_x: int
    tile_y: int
    tile_size: int
    tile_stride: int
    out_size: int
    meta_path: Path
    M_out_to_src: np.ndarray
    M_src_to_out: np.ndarray


@dataclass
class PredictionVolumeRef:
    """One active YOLO input job.

    ``array`` is used by the legacy dense-materialization path.  v12.2.12 normally
    uses ``source``: an Ultralytics-compatible streaming source that renders a
    bounded prefetch window of slices and lets YOLO start on the first ready batch.
    """

    array: Optional[np.ndarray]
    path: Optional[Path]
    name: str
    view_name: str
    job_id: str
    kind: str = 'fullframe'
    source: Optional[object] = None


def close_prediction_volume_ref(ref: Optional[PredictionVolumeRef], *, keep_temp: bool = False) -> None:
    """Release one prediction source and remove any fallback backing file."""
    if ref is None:
        return

    close_fn = getattr(getattr(ref, 'source', None), 'close', None)
    if callable(close_fn):
        try:
            close_fn()
        except Exception as exc:
            print(f'Warning: failed to close streaming prediction source {ref.name} ({exc})')

    arr = getattr(ref, 'array', None)
    path = getattr(ref, 'path', None)
    if arr is not None:
        if bool(keep_temp):
            close_memmap_array(arr)
        else:
            close_memmap_array_without_flush(arr)
    if not bool(keep_temp) and path is not None:
        try:
            Path(path).unlink(missing_ok=True)
        except Exception:
            pass


class InMemoryYoloVolumeSource:
    """Ultralytics-compatible in-memory source that streams fixed-size slice batches.

    Ultralytics' public Python API accepts in-memory numpy inputs, but its built-in
    ``LoadPilAndNumpy`` loader treats a list of arrays as one large batch.  This
    loader is registered as an in-memory loader so the predictor consumes a 3-D
    slice volume incrementally with ``stream=True`` and the requested ``--batch``.
    Slices are yielded as single-channel ``H×W×1`` uint8 arrays; this intentionally
    avoids the older gray-to-BGR expansion path so single-channel YOLO models receive
    a single input channel.  The final batch is padded by repeating the final real
    slice so fixed-batch engines, e.g. TensorRT without dynamic=True, always receive
    the same batch size.  Downstream accumulation discards synthetic padded results.
    """

    def __init__(self, volume_gray: np.ndarray, name: str, batch_size: int = 1, max_frames: Optional[int] = None) -> None:
        if volume_gray is None:
            raise ValueError('InMemoryYoloVolumeSource requires a volume array')
        self.volume_gray = np.asarray(volume_gray)
        if self.volume_gray.ndim == 4:
            if int(self.volume_gray.shape[3]) != 1:
                raise ValueError(
                    f'Prediction volume must be single-channel with shape (N,H,W) or (N,H,W,1); got {self.volume_gray.shape}'
                )
        elif self.volume_gray.ndim != 3:
            raise ValueError(f'Prediction volume must have shape (N,H,W) or (N,H,W,1); got {self.volume_gray.shape}')
        self.name = re.sub(r'[^A-Za-z0-9_.-]+', '_', str(name)).strip('_') or 'in_memory_volume'
        self.nf = int(self.volume_gray.shape[0])
        if max_frames is not None:
            self.nf = max(0, min(self.nf, int(max_frames)))
        self.bs = max(1, int(batch_size))
        self.yield_nf = int(math.ceil(float(self.nf) / float(self.bs)) * self.bs) if self.nf > 0 else 0
        self.synthetic_count = max(0, int(self.yield_nf) - int(self.nf))
        self.mode = 'image'
        self.count = 0
        try:
            from ultralytics.data.loaders import SourceTypes  # type: ignore
            self.source_type = SourceTypes(stream=False, screenshot=False, from_img=True, tensor=False)
        except Exception:
            # Older/forked Ultralytics builds only require these attributes.
            self.source_type = argparse.Namespace(stream=False, screenshot=False, from_img=True, tensor=False)

    def __iter__(self) -> 'InMemoryYoloVolumeSource':
        self.count = 0
        return self

    def __len__(self) -> int:
        return int(math.ceil(float(self.nf) / float(self.bs))) if self.nf > 0 else 0

    @staticmethod
    def _frame_to_single_channel(frame: np.ndarray) -> np.ndarray:
        """Return one prediction frame as contiguous H×W×1 uint8, never H×W×3."""
        frame_u8 = np.asarray(frame, dtype=np.uint8)
        if frame_u8.ndim == 2:
            return np.ascontiguousarray(frame_u8[:, :, None])
        if frame_u8.ndim == 3 and int(frame_u8.shape[2]) == 1:
            return np.ascontiguousarray(frame_u8)
        raise ValueError(f'Unsupported non-single-channel prediction frame shape for YOLO source: {frame_u8.shape}')

    def __next__(self) -> Tuple[List[str], List[np.ndarray], List[str]]:
        if self.count >= self.yield_nf:
            raise StopIteration
        if self.nf <= 0:
            raise StopIteration
        start = int(self.count)
        stop = min(int(self.yield_nf), start + int(self.bs))
        self.count = int(stop)
        paths: List[str] = []
        imgs: List[np.ndarray] = []
        info: List[str] = []
        last_real_idx = max(0, int(self.nf) - 1)
        for idx in range(start, stop):
            real_idx = int(idx) if int(idx) < int(self.nf) else int(last_real_idx)
            synthetic = int(idx) >= int(self.nf)
            suffix = '_synthetic' if synthetic else ''
            paths.append(f'{self.name}_{idx + 1:06d}{suffix}.png')
            imgs.append(self._frame_to_single_channel(self.volume_gray[int(real_idx)]))
            if synthetic:
                info.append(f'in-memory {self.name} synthetic padded slice {idx + 1}/{self.yield_nf} repeats real slice {real_idx + 1}/{self.nf}: ')
            else:
                info.append(f'in-memory {self.name} slice {idx + 1}/{self.nf}: ')
        return paths, imgs, info


class StreamingYoloVolumeSource:
    """Ultralytics-compatible source that renders prediction slices just ahead of YOLO.

    The legacy v12 path first materialized a complete ``(N,imgsz,imgsz)`` uint8
    array for every full-frame/tile job.  This source keeps only a bounded window
    of rendered futures alive: the first batch can enter YOLO as soon as those
    frames are ready, while CPU workers continue rendering later slices behind the
    GPU stream.
    """

    def __init__(
        self,
        renderer: Callable[[int], np.ndarray],
        *,
        num_frames: int,
        name: str,
        batch_size: int = 1,
        max_frames: Optional[int] = None,
        out_size: Optional[int] = None,
        render_workers: int = 1,
        prefetch_frames: Optional[int] = None,
        autostart: bool = True,
        shared_executor: Optional[ThreadPoolExecutor] = None,
    ) -> None:
        self.renderer = renderer
        self.name = re.sub(r'[^A-Za-z0-9_.-]+', '_', str(name)).strip('_') or 'streaming_volume'
        self.nf = max(0, int(num_frames))
        if max_frames is not None:
            self.nf = max(0, min(self.nf, int(max_frames)))
        self.out_size = None if out_size is None else int(out_size)
        self.bs = max(1, int(batch_size))
        self.yield_nf = int(math.ceil(float(self.nf) / float(self.bs)) * self.bs) if self.nf > 0 else 0
        self.synthetic_count = max(0, int(self.yield_nf) - int(self.nf))
        self.render_workers = max(1, min(int(render_workers), max(1, int(self.nf))))
        default_prefetch = streaming_prediction_source_prefetch_frames(self.bs)
        self.prefetch_frames = max(self.bs, int(prefetch_frames if prefetch_frames is not None else default_prefetch))
        self.mode = 'image'
        self.count = 0
        self._next_submit = 0
        self._futures: Dict[int, Future] = {}
        self._external_executor = shared_executor
        self._executor: Optional[ThreadPoolExecutor] = shared_executor
        self._owns_executor = shared_executor is None
        self._lock = threading.Lock()
        self._closed = False
        try:
            from ultralytics.data.loaders import SourceTypes  # type: ignore
            self.source_type = SourceTypes(stream=False, screenshot=False, from_img=True, tensor=False)
        except Exception:
            self.source_type = argparse.Namespace(stream=False, screenshot=False, from_img=True, tensor=False)
        if bool(autostart):
            self.start()

    def __len__(self) -> int:
        return int(math.ceil(float(self.nf) / float(self.bs))) if self.nf > 0 else 0

    def __iter__(self) -> 'StreamingYoloVolumeSource':
        self.start()
        self.count = 0
        self._fill_prefetch_locked(target_index=0)
        return self

    @staticmethod
    def _frame_to_single_channel(frame: np.ndarray) -> np.ndarray:
        return InMemoryYoloVolumeSource._frame_to_single_channel(frame)

    def _ensure_executor_locked(self) -> ThreadPoolExecutor:
        if self._executor is not None:
            return self._executor
        if self._external_executor is not None:
            self._executor = self._external_executor
            self._owns_executor = False
            return self._executor
        self._executor = ThreadPoolExecutor(
            max_workers=int(self.render_workers),
            thread_name_prefix=f'yolo-render-{self.name[:24]}',
        )
        self._owns_executor = True
        return self._executor

    def start(self) -> None:
        with self._lock:
            if self._closed:
                raise RuntimeError(f'Streaming YOLO source {self.name} is already closed')
            self._ensure_executor_locked()
            self._fill_prefetch_locked(target_index=0)

    def close(self) -> None:
        executor: Optional[ThreadPoolExecutor]
        futures_to_cancel: List[Future]
        owns_executor: bool
        with self._lock:
            self._closed = True
            executor = self._executor
            owns_executor = bool(self._owns_executor)
            futures_to_cancel = list(self._futures.values())
            self._executor = None
            self._futures.clear()
        for fut in futures_to_cancel:
            try:
                fut.cancel()
            except Exception:
                pass
        if executor is not None and owns_executor:
            try:
                executor.shutdown(wait=False, cancel_futures=True)
            except TypeError:
                executor.shutdown(wait=False)

    def _submit_locked(self, idx: int) -> None:
        idx_i = int(idx)
        if idx_i in self._futures or idx_i >= int(self.nf):
            return
        executor = self._ensure_executor_locked()
        self._futures[idx_i] = executor.submit(self._render_one, idx_i)
        self._next_submit = max(int(self._next_submit), idx_i + 1)

    def _fill_prefetch_locked(self, target_index: int) -> None:
        if self._closed or int(self.nf) <= 0:
            return
        submit_stop = min(int(self.nf), max(int(self._next_submit), int(target_index) + int(self.prefetch_frames)))
        while int(self._next_submit) < int(submit_stop):
            self._submit_locked(int(self._next_submit))

    def _ensure_submitted(self, stop_exclusive: int) -> None:
        with self._lock:
            self._fill_prefetch_locked(target_index=max(0, int(stop_exclusive)))
            while int(self._next_submit) < min(int(self.nf), int(stop_exclusive)):
                self._submit_locked(int(self._next_submit))

    def _render_one(self, idx: int) -> np.ndarray:
        frame = np.asarray(self.renderer(int(idx)), dtype=np.uint8)
        if frame.ndim == 3 and int(frame.shape[-1]) == 1:
            frame = frame[:, :, 0]
        if frame.ndim != 2:
            raise ValueError(f'{self.name}: renderer returned unsupported frame shape {frame.shape} for slice {idx}')
        if self.out_size is not None and (int(frame.shape[0]) != int(self.out_size) or int(frame.shape[1]) != int(self.out_size)):
            raise ValueError(f'{self.name}: renderer returned {frame.shape}, expected ({int(self.out_size)}, {int(self.out_size)})')
        return np.ascontiguousarray(frame, dtype=np.uint8)

    def _get_real_frame(self, idx: int) -> np.ndarray:
        idx_i = int(np.clip(int(idx), 0, max(0, int(self.nf) - 1)))
        self._ensure_submitted(idx_i + 1)
        with self._lock:
            fut = self._futures.get(idx_i)
        if fut is None:
            # Should only happen if close() raced with iteration; render synchronously so the
            # YOLO stream can still finish deterministically.
            return self._render_one(idx_i)
        frame = fut.result()
        with self._lock:
            self._futures.pop(idx_i, None)
        return frame

    def __next__(self) -> Tuple[List[str], List[np.ndarray], List[str]]:
        if self.count >= self.yield_nf or self.nf <= 0:
            self.close()
            raise StopIteration
        self.start()
        start = int(self.count)
        stop = min(int(self.yield_nf), start + int(self.bs))
        # Ensure the actual batch is ready or rendering before waiting for ordered frames.
        self._ensure_submitted(min(int(stop), int(self.nf)))
        paths: List[str] = []
        imgs: List[np.ndarray] = []
        info: List[str] = []
        last_real_idx = max(0, int(self.nf) - 1)
        for idx in range(start, stop):
            real_idx = int(idx) if int(idx) < int(self.nf) else int(last_real_idx)
            synthetic = int(idx) >= int(self.nf)
            suffix = '_synthetic' if synthetic else ''
            frame = self._get_real_frame(real_idx)
            paths.append(f'{self.name}_{idx + 1:06d}{suffix}.png')
            imgs.append(self._frame_to_single_channel(frame))
            if synthetic:
                info.append(f'streaming {self.name} synthetic padded slice {idx + 1}/{self.yield_nf} repeats real slice {real_idx + 1}/{self.nf}: ')
            else:
                info.append(f'streaming {self.name} slice {idx + 1}/{self.nf}: ')
        self.count = int(stop)
        with self._lock:
            self._fill_prefetch_locked(target_index=int(self.count))
        return paths, imgs, info


class GpuPrefetchedYoloBatch(list):
    """List-like orig-image batch whose YOLO tensor is already staged in GPU VRAM.

    Ultralytics still receives a list of H×W×1 uint8 images for result-shape bookkeeping,
    while the patched preprocess path consumes ``_tta_gpu_tensor`` directly.  The tensor is
    BCHW, normalized to [0,1], and already on the requested CUDA device.  A CUDA event is
    attached when staging used a non-default copy stream so the predictor stream can wait
    without forcing a CPU synchronization.
    """

    def __init__(
        self,
        frames: Sequence[np.ndarray],
        *,
        gpu_tensor: object,
        ready_event: Optional[object] = None,
        source_label: str = '',
        cpu_tensor_ref: Optional[object] = None,
    ) -> None:
        super().__init__(frames)
        self._tta_gpu_tensor = gpu_tensor
        self._tta_gpu_ready_event = ready_event
        self._tta_source_label = str(source_label)
        self._tta_cpu_tensor_ref = cpu_tensor_ref
        self._tta_normalized = True

    def wait_ready(self) -> object:
        tensor = self._tta_gpu_tensor
        event = self._tta_gpu_ready_event
        if event is not None:
            try:
                import torch  # type: ignore
                current_stream = torch.cuda.current_stream(device=tensor.device)  # type: ignore[attr-defined]
                current_stream.wait_event(event)
                record_stream = getattr(tensor, 'record_stream', None)
                if callable(record_stream):
                    record_stream(current_stream)
            except Exception:
                try:
                    synchronize = getattr(event, 'synchronize', None)
                    if callable(synchronize):
                        synchronize()
                    self._tta_cpu_tensor_ref = None
                except Exception:
                    pass
        return tensor


class GpuPrefetchingYoloSource:
    """Wrap a YOLO source and keep a bounded queue of preprocessed CUDA input batches.

    This queue is intentionally separate from Ultralytics' ``--batch``.  ``--batch`` remains the
    number of slices in each inference call; ``queue_batches`` controls how many complete batches
    are staged in VRAM ahead of the predictor loop.
    """

    def __init__(
        self,
        base_source: object,
        *,
        cfg: 'PredictConfig',
        source_label: str,
        queue_batches: int = 8,
        pin_memory: bool = True,
        staging_reservation_bytes: int = 0,
    ) -> None:
        self.base_source = base_source
        self.cfg = cfg
        self.source_label = re.sub(r'[^A-Za-z0-9_.-]+', '_', str(source_label)).strip('_') or 'gpu_prefetch_source'
        self.queue_batches = max(1, int(queue_batches))
        self.pin_memory = bool(pin_memory)
        self.mode = getattr(base_source, 'mode', 'image')
        self.count = 0
        self.bs = max(1, int(getattr(base_source, 'bs', getattr(cfg, 'batch', 1))))
        self.nf = int(getattr(base_source, 'nf', 0) or 0)
        self.yield_nf = int(getattr(base_source, 'yield_nf', 0) or 0)
        self.synthetic_count = int(getattr(base_source, 'synthetic_count', max(0, self.yield_nf - self.nf)))
        self.source_type = getattr(base_source, 'source_type', argparse.Namespace(stream=False, screenshot=False, from_img=True, tensor=False))
        self._queue: 'queue.Queue[object]' = queue.Queue(maxsize=self.queue_batches)
        self._stop_event = threading.Event()
        self._producer_thread: Optional[threading.Thread] = None
        self._started = False
        self._closed = False
        self._sentinel = object()
        self._copy_stream: Optional[object] = None
        self._device_str = canonical_single_device(str(cfg.device))
        self._dtype_name = 'float16' if bool(cfg.half) and str(self._device_str).startswith('cuda') else 'float32'
        # v13.3.2 (R10): ring of reusable PINNED u8 BCHW staging buffers ([tensor, reuse_event]
        # pairs). The producer loop is single-threaded, so a small ring with per-buffer H2D
        # completion events is race-free.
        self._pinned_ring: Optional[List[List[object]]] = None
        self._pinned_ring_next = 0
        # v13.2.2 bug #8: VRAM admitted for this source by gpu_input_staging_preflight_reserve;
        # handed back to the ledger as staged batches materialize, remainder released on close().
        self._staging_reservation_remaining = max(0, int(staging_reservation_bytes))

    def _consume_staging_reservation(self, staged_bytes: int) -> None:
        step_cap = max(0, int(staged_bytes))
        if step_cap <= 0:
            return
        with _GPU_STAGING_RESERVATION_LOCK:
            remaining = int(self._staging_reservation_remaining)
            step = min(remaining, step_cap)
            if step <= 0:
                return
            self._staging_reservation_remaining = remaining - step
            key = str(self._device_str)
            ledger = int(_GPU_STAGING_RESERVED_BYTES.get(key, 0)) - step
            if ledger > 0:
                _GPU_STAGING_RESERVED_BYTES[key] = ledger
            else:
                _GPU_STAGING_RESERVED_BYTES.pop(key, None)

    def __len__(self) -> int:
        try:
            return int(len(self.base_source))  # type: ignore[arg-type]
        except Exception:
            if self.yield_nf > 0 and self.bs > 0:
                return int(math.ceil(float(self.yield_nf) / float(self.bs)))
            if self.nf > 0 and self.bs > 0:
                return int(math.ceil(float(self.nf) / float(self.bs)))
            return 0

    def __iter__(self) -> 'GpuPrefetchingYoloSource':
        self.start()
        return self

    def start(self) -> None:
        if self._started:
            return
        self._started = True
        self._producer_thread = threading.Thread(
            target=self._producer_loop,
            name=f'yolo-gpu-stage-{self.source_label[:32]}',
            daemon=True,
        )
        self._producer_thread.start()

    def close(self) -> None:
        self._closed = True
        self._stop_event.set()
        close_fn = getattr(self.base_source, 'close', None)
        if callable(close_fn):
            try:
                close_fn()
            except Exception:
                pass
        thread = self._producer_thread
        if thread is not None and thread.is_alive():
            try:
                thread.join(timeout=2.0)
            except Exception:
                pass
        # v13.2.2 bug #3: drop staged batches that were still queued when iteration
        # stopped; abandoned GpuPrefetchedYoloBatch items otherwise keep their CUDA
        # tensors (and pinned CPU tensors) alive for the life of the process.
        try:
            while True:
                self._queue.get_nowait()
        except queue.Empty:
            pass
        # v13.2.2 bug #8: release any admission reservation this source never materialized.
        try:
            self._consume_staging_reservation(int(self._staging_reservation_remaining))
        except Exception:
            pass

    @staticmethod
    def _normalize_single_channel_frames(imgs: Sequence[np.ndarray]) -> Tuple[List[np.ndarray], List[np.ndarray]]:
        """Return (contiguous 2D u8 frames, H×W×1 views for ultralytics result bookkeeping)."""
        frames: List[np.ndarray] = []
        for item in imgs:
            arr = np.asarray(item)
            if arr.ndim == 2:
                gray = arr
            elif arr.ndim == 3 and int(arr.shape[2]) == 1:
                gray = arr[:, :, 0]
            else:
                raise ValueError(f'GPU input staging expects H×W or H×W×1 uint8 frames, got {arr.shape}')
            frames.append(np.ascontiguousarray(gray, dtype=np.uint8))
        shapes = {tuple(int(v) for v in frame.shape) for frame in frames}
        if len(shapes) != 1:
            raise ValueError(f'GPU input staging batch contains mixed shapes: {sorted(shapes)}')
        # A trailing size-1 axis on a contiguous 2D array is already contiguous — pure views.
        return frames, [frame[:, :, None] for frame in frames]

    @staticmethod
    def _stack_single_channel_cpu_tensor(imgs: Sequence[np.ndarray]) -> Tuple[object, List[np.ndarray]]:
        frames, cpu_frames = GpuPrefetchingYoloSource._normalize_single_channel_frames(imgs)
        import torch  # type: ignore
        batch = np.stack(frames, axis=0)[:, None, :, :]  # BCHW, C=1
        return torch.from_numpy(np.ascontiguousarray(batch)), cpu_frames

    def _acquire_pinned_staging_entry(self, torch_mod: object, b: int, h: int, w: int) -> List[object]:
        """v13.3.2 (R10): next pinned-u8 ring entry; waits for the buffer's prior H2D to finish."""
        want = (max(int(self.bs), int(b)), 1, int(h), int(w))
        ring = self._pinned_ring
        if ring is None or tuple(int(x) for x in ring[0][0].shape) != want:
            ring = [
                [torch_mod.empty(want, dtype=torch_mod.uint8, pin_memory=True), None]
                for _ in range(3)
            ]
            self._pinned_ring = ring
            self._pinned_ring_next = 0
        entry = ring[self._pinned_ring_next]
        self._pinned_ring_next = (self._pinned_ring_next + 1) % len(ring)
        evt = entry[1]
        if evt is not None:
            evt.synchronize()  # type: ignore[attr-defined]
            entry[1] = None
        return entry

    def _stage_batch(self, batch: object) -> object:
        paths, imgs, info = batch  # type: ignore[misc]
        import torch  # type: ignore
        if not str(self._device_str).startswith('cuda'):
            return batch
        if not bool(torch.cuda.is_available()):
            return batch

        target_device = torch.device(self._device_str)
        target_dtype = torch.float16 if self._dtype_name == 'float16' else torch.float32
        ready_event: Optional[object] = None
        gpu_tensor: Optional[object] = None
        cpu_tensor_ref: Optional[object] = None
        frames, cpu_frames = self._normalize_single_channel_frames(list(imgs))

        if bool(self.pin_memory):
            try:
                # v13.3.2 (R10): frames go straight into a pooled PINNED u8 BCHW buffer (the
                # np.stack + pin_memory() double copy is gone), the wire carries uint8 (half
                # the bytes of fp16), and the dtype cast + /255 normalization run ON DEVICE on
                # the copy stream. The old mixed .to(device, dtype) materialized the cast on
                # the CPU into an UNPINNED temp — which also degraded non_blocking to a
                # pageable, producer-blocking copy.
                b = len(frames)
                h, w = (int(v) for v in frames[0].shape)
                entry = self._acquire_pinned_staging_entry(torch, b, h, w)
                pin_view = entry[0][:b]
                pin_np = pin_view.numpy()
                for i, frame in enumerate(frames):
                    np.copyto(pin_np[i, 0], frame)
                if self._copy_stream is None:
                    self._copy_stream = torch.cuda.Stream(device=target_device)
                with torch.cuda.stream(self._copy_stream):
                    gpu_u8 = pin_view.to(device=target_device, non_blocking=True)
                    reuse_event = torch.cuda.Event()
                    reuse_event.record(self._copy_stream)
                    entry[1] = reuse_event  # buffer reusable once the u8 H2D completes
                    gpu_tensor = gpu_u8.to(target_dtype)
                    gpu_tensor.div_(255.0)
                    ready_event = torch.cuda.Event()
                    ready_event.record(self._copy_stream)
            except Exception:
                gpu_tensor = None
                ready_event = None

        if gpu_tensor is None:
            # Fallback (pinning unavailable or the pooled path failed): legacy stack + mixed
            # .to(); still removes the RAM->GPU copy from the predictor hot path.
            cpu_tensor, cpu_frames = self._stack_single_channel_cpu_tensor(list(imgs))
            if bool(self.pin_memory):
                try:
                    cpu_tensor = cpu_tensor.pin_memory()
                except Exception:
                    pass
            try:
                if self._copy_stream is None:
                    self._copy_stream = torch.cuda.Stream(device=target_device)
                with torch.cuda.stream(self._copy_stream):
                    gpu_tensor = cpu_tensor.to(device=target_device, dtype=target_dtype, non_blocking=True)
                    gpu_tensor.div_(255.0)
                    ready_event = torch.cuda.Event()
                    ready_event.record(self._copy_stream)
            except Exception:
                gpu_tensor = cpu_tensor.to(device=target_device, dtype=target_dtype, non_blocking=False)
                gpu_tensor.div_(255.0)
                ready_event = None
            cpu_tensor_ref = cpu_tensor

        gpu_batch = GpuPrefetchedYoloBatch(
            cpu_frames,
            gpu_tensor=gpu_tensor,
            ready_event=ready_event,
            source_label=self.source_label,
            cpu_tensor_ref=cpu_tensor_ref,
        )
        # This batch's VRAM is now visible to mem_get_info; stop double-counting it in
        # the admission ledger (v13.2.2 bug #8).
        try:
            self._consume_staging_reservation(int(gpu_tensor.numel()) * int(gpu_tensor.element_size()))
        except Exception:
            pass
        return paths, gpu_batch, info

    def _put_queue_item(self, item: object) -> None:
        while not self._stop_event.is_set():
            try:
                self._queue.put(item, timeout=0.05)
                return
            except queue.Full:
                continue

    def _producer_loop(self) -> None:
        try:
            for batch in self.base_source:  # type: ignore[operator]
                if self._stop_event.is_set():
                    break
                self._put_queue_item(self._stage_batch(batch))
            self._put_queue_item(self._sentinel)
        except BaseException as exc:
            self._put_queue_item(exc)
            self._put_queue_item(self._sentinel)

    def __next__(self) -> Tuple[List[str], object, List[str]]:
        self.start()
        while True:
            if self._closed and self._queue.empty():
                raise StopIteration
            try:
                item = self._queue.get(timeout=0.05)
            except queue.Empty:
                continue
            if item is self._sentinel:
                self.close()
                raise StopIteration
            if isinstance(item, BaseException):
                self.close()
                raise item
            self.count += 1
            return item  # type: ignore[return-value]


def gpu_input_staging_enabled(cfg: 'PredictConfig') -> bool:
    """Return True when a small queue of YOLO input batches should be staged in VRAM."""
    if os.environ.get('YOLO_TTA_GPU_INPUT_STAGING') is not None:
        requested = _env_flag('YOLO_TTA_GPU_INPUT_STAGING', True)
    else:
        requested = _env_flag('YOLO_TTA_GPU_PREFETCH', True)
    if not bool(requested):
        return False
    target = canonical_single_device(str(cfg.device))
    if not str(target).startswith('cuda'):
        return False
    try:
        import torch  # type: ignore
        return bool(torch.cuda.is_available())
    except Exception:
        return False


def gpu_input_staging_queue_batches() -> int:
    if os.environ.get('YOLO_TTA_GPU_INPUT_STAGING_BATCHES') is not None:
        return max(0, _env_int('YOLO_TTA_GPU_INPUT_STAGING_BATCHES', 8))
    return max(0, _env_int('YOLO_TTA_GPU_PREFETCH_BATCHES', 8))


def gpu_input_staging_pin_memory_enabled() -> bool:
    return _env_flag('YOLO_TTA_GPU_INPUT_STAGING_PIN_MEMORY', True)


def gpu_input_staging_min_free_after_bytes() -> int:
    return int(max(0.0, _env_float('YOLO_TTA_GPU_INPUT_STAGING_MIN_FREE_AFTER_GIB', 2.0)) * GIB)


def _source_prediction_out_size(source: object) -> Optional[int]:
    out_size = getattr(source, 'out_size', None)
    if out_size is not None:
        try:
            return int(out_size)
        except Exception:
            pass
    volume = getattr(source, 'volume_gray', None)
    if volume is not None:
        try:
            arr = np.asarray(volume)
            if arr.ndim >= 3:
                return int(arr.shape[1])
        except Exception:
            pass
    return None


# v13.2.2 bug #8: the staging preflight used to compare a one-shot torch.cuda.mem_get_info()
# snapshot against a single source's need. Eager staging wraps several queued sources within
# milliseconds, so multiple preflights passed against the same stale free value (TOCTOU) and
# their producers then cumulatively staged past the reserve. Admission now debits a per-device
# reservation ledger under a lock; the ledger entry is credited back as the wrapper actually
# materializes staged batches (at which point the usage is visible to mem_get_info) and any
# remainder is released by GpuPrefetchingYoloSource.close().
_GPU_STAGING_RESERVATION_LOCK = threading.Lock()
_GPU_STAGING_RESERVED_BYTES: Dict[str, int] = {}


def _release_gpu_staging_reservation(device_str: str, release_bytes: int) -> None:
    release = max(0, int(release_bytes))
    if release <= 0:
        return
    key = str(device_str)
    with _GPU_STAGING_RESERVATION_LOCK:
        remaining = int(_GPU_STAGING_RESERVED_BYTES.get(key, 0)) - release
        if remaining > 0:
            _GPU_STAGING_RESERVED_BYTES[key] = remaining
        else:
            _GPU_STAGING_RESERVED_BYTES.pop(key, None)


def gpu_input_staging_preflight_reserve(source: object, cfg: 'PredictConfig', queue_batches: int, source_label: str) -> Optional[int]:
    """Admit one source into CUDA input staging, reserving its VRAM need in the ledger.

    Returns the reserved byte count (0 when the need cannot be estimated) or None when
    staging must be skipped for this source.
    """
    out_size = _source_prediction_out_size(source)
    if out_size is None or int(out_size) <= 0:
        return 0
    try:
        import torch  # type: ignore
        device_str = canonical_single_device(str(cfg.device))
        device = torch.device(device_str)
        try:
            with torch.cuda.device(device):
                free_bytes, _total_bytes = torch.cuda.mem_get_info()
        except Exception:
            free_bytes, _total_bytes = torch.cuda.mem_get_info()
        dtype_bytes = 2 if bool(cfg.half) else 4
        frame_slots = int(max(1, queue_batches)) * int(max(1, cfg.batch))
        need_bytes = int(frame_slots) * int(out_size) * int(out_size) * int(dtype_bytes)
        reserve_bytes = int(gpu_input_staging_min_free_after_bytes())
        with _GPU_STAGING_RESERVATION_LOCK:
            already_reserved = int(_GPU_STAGING_RESERVED_BYTES.get(str(device_str), 0))
            admitted = int(free_bytes) - already_reserved >= int(need_bytes) + int(reserve_bytes)
            if admitted:
                _GPU_STAGING_RESERVED_BYTES[str(device_str)] = already_reserved + int(need_bytes)
        if not admitted:
            print(
                f'CUDA input staging skipped for {source_label}: need≈{need_bytes / GIB:.2f} GiB '
                f'for {int(queue_batches)} queued batch(es) at --batch={int(cfg.batch)}, imgsz={int(out_size)}, '
                f'dtype_bytes={int(dtype_bytes)}; free={int(free_bytes) / GIB:.2f} GiB, '
                f'pending_reservations={already_reserved / GIB:.2f} GiB, '
                f'reserve={int(reserve_bytes) / GIB:.2f} GiB.'
            )
            return None
        return int(need_bytes)
    except Exception as exc:
        print(f'CUDA input staging preflight failed for {source_label} ({exc}); using CPU source path.')
        return None


def maybe_wrap_source_with_gpu_input_staging(source: object, cfg: 'PredictConfig', source_label: str) -> object:
    if isinstance(source, GpuPrefetchingYoloSource):
        return source
    # v13.3.0 (R21): GPU-rendered sources already produce device-resident normalized batches;
    # CPU-side staging would be a pointless host round trip.
    if isinstance(source, GpuRenderedYoloSource):
        return source
    if not gpu_input_staging_enabled(cfg):
        return source
    queue_batches = gpu_input_staging_queue_batches()
    if int(queue_batches) <= 0:
        return source
    staging_reservation = gpu_input_staging_preflight_reserve(source, cfg, int(queue_batches), str(source_label))
    if staging_reservation is None:
        return source
    try:
        ensure_ultralytics_accepts_in_memory_volume_source()
        print(
            f'CUDA input staging active for {source_label}: '
            f'queue_batches={int(queue_batches)} ({int(queue_batches) * max(1, int(cfg.batch))} frame slots), '
            f'--batch={int(cfg.batch)}, device={canonical_single_device(str(cfg.device))}, '
            f'dtype={"float16" if bool(cfg.half) else "float32"}'
        )
        return GpuPrefetchingYoloSource(
            source,
            cfg=cfg,
            source_label=str(source_label),
            queue_batches=int(queue_batches),
            pin_memory=gpu_input_staging_pin_memory_enabled(),
            staging_reservation_bytes=int(staging_reservation),
        )
    except BaseException:
        # No wrapper owns the reservation yet — credit it back or the phantom pending
        # bytes silently veto every later staging preflight on this device.
        _release_gpu_staging_reservation(canonical_single_device(str(cfg.device)), int(staging_reservation))
        raise


def gpu_input_staging_ahead_sources(default_queue_slots: int) -> int:
    """Number of queued prediction sources allowed to pre-stage CUDA batches.

    This is intentionally separate from YOLO_TTA_GPU_INPUT_STAGING_BATCHES, which
    is the number of batches inside each source.  v13 removes the old fixed four-source
    default: queued-source CUDA staging now scales with the visible CPU allocation and
    the resolved source queue, while per-source VRAM preflight still skips staging when
    the device does not have enough free memory.
    """
    raw = os.environ.get('YOLO_TTA_GPU_INPUT_STAGING_AHEAD_SOURCES', '').strip()
    if not raw and os.environ.get('YOLO_TTA_GPU_PREFETCH_AHEAD_SOURCES') is not None:
        raw = os.environ.get('YOLO_TTA_GPU_PREFETCH_AHEAD_SOURCES', '').strip()
    if raw:
        try:
            return max(0, int(raw))
        except Exception:
            return 0
    default_ahead = max(1, _env_int('YOLO_TTA_GPU_INPUT_STAGING_AHEAD_DEFAULT', max(1, _cpu_count())))
    return max(0, min(max(1, int(default_queue_slots)), int(default_ahead)))


def _prediction_ref_has_gpu_input_staging(ref: PredictionVolumeRef) -> bool:
    return isinstance(getattr(ref, 'source', None), GpuPrefetchingYoloSource)


def maybe_eager_stage_prediction_ref_on_gpu(prediction_ref: PredictionVolumeRef, cfg: 'PredictConfig') -> PredictionVolumeRef:
    """Wrap and start one queued prediction source's CUDA input staging queue.

    The ordinary predict path also wraps sources, but only after they become the
    active source.  Eager staging lets queued sources render and copy their first
    batches into VRAM while the GPU is still inferencing the previous source.
    """
    if _prediction_ref_has_gpu_input_staging(prediction_ref):
        source = prediction_ref.source
    else:
        source = getattr(prediction_ref, 'source', None)
        if source is None:
            if prediction_ref.array is None:
                return prediction_ref
            source = make_in_memory_yolo_source(
                prediction_ref.array,
                prediction_ref.name,
                batch_size=max(1, int(cfg.batch)),
                max_frames=None,
            )
        wrapped = maybe_wrap_source_with_gpu_input_staging(source, cfg, prediction_ref.name)
        prediction_ref.source = wrapped
        source = wrapped
    start_fn = getattr(source, 'start', None)
    if callable(start_fn):
        try:
            start_fn()
        except Exception as exc:
            print(f'Warning: eager CUDA input staging could not start for {prediction_ref.name} ({exc}); source will stage on demand.')
    return prediction_ref


def streaming_prediction_sources_enabled() -> bool:
    """Return True when YOLO input slices should be rendered lazily instead of prebuilt."""
    if os.environ.get('YOLO_TTA_STREAMING_PREDICTION_SOURCES') is not None:
        return _env_flag('YOLO_TTA_STREAMING_PREDICTION_SOURCES', True)
    if os.environ.get('YOLO_TTA_STREAM_RENDERED_PREDICTION_SOURCES') is not None:
        return _env_flag('YOLO_TTA_STREAM_RENDERED_PREDICTION_SOURCES', True)
    return _env_flag('YOLO_TTA_STREAM_RENDERED_PREDICTION', True)


def streaming_prediction_source_autostart_enabled() -> bool:
    """Return True to let every constructed streaming source immediately pre-render.

    v13 source creation is unbounded by default, so the default autostart policy is now
    scheduler-controlled CPU warmup rather than every queued source starting its prefetch
    window at construction time.  Set YOLO_TTA_STREAMING_SOURCE_AUTOSTART=1 to restore
    eager autostart for every source.
    """
    if os.environ.get('YOLO_TTA_STREAMING_SOURCE_AUTOSTART') is not None:
        return _env_flag('YOLO_TTA_STREAMING_SOURCE_AUTOSTART', True)
    if os.environ.get('YOLO_TTA_STREAM_RENDER_AUTOSTART') is not None:
        return _env_flag('YOLO_TTA_STREAM_RENDER_AUTOSTART', True)
    return False


def queued_streaming_source_cpu_warmup_slots(default_queue_slots: int) -> int:
    """Resolve how many ready queued streaming sources may pre-render on CPU.

    This keeps v13 source creation unbounded without allowing every future tile/view to enqueue
    a full prefetch window at once.  The active source can still use the full shared render pool;
    a bounded number of upcoming sources are kept warm to overlap CPU rendering with inference.
    """
    raw = os.environ.get('YOLO_TTA_STREAMING_SOURCE_WARMUP_SOURCES', '').strip()
    if not raw and os.environ.get('YOLO_TTA_STREAM_RENDER_WARMUP_SOURCES') is not None:
        raw = os.environ.get('YOLO_TTA_STREAM_RENDER_WARMUP_SOURCES', '').strip()
    if raw:
        try:
            return max(0, int(raw))
        except Exception:
            return 0
    default_slots = max(1, _env_int('YOLO_TTA_STREAMING_SOURCE_WARMUP_DEFAULT', max(2, min(8, _cpu_count()))))
    return max(0, min(max(1, int(default_queue_slots)), int(default_slots)))


def streaming_prediction_source_prefetch_frames(batch_size: int) -> int:
    explicit = _env_int('YOLO_TTA_STREAMING_SOURCE_PREFETCH_FRAMES', 0)
    if explicit <= 0 and os.environ.get('YOLO_TTA_STREAM_RENDER_PREFETCH_FRAMES') is not None:
        explicit = _env_int('YOLO_TTA_STREAM_RENDER_PREFETCH_FRAMES', 0)
    if explicit > 0:
        return max(1, int(explicit))
    batches = max(1, _env_int('YOLO_TTA_STREAMING_SOURCE_PREFETCH_BATCHES', _env_int('YOLO_TTA_STREAM_RENDER_PREFETCH_BATCHES', 32)))
    max_frames = max(1, _env_int('YOLO_TTA_STREAMING_SOURCE_PREFETCH_MAX_FRAMES', _env_int('YOLO_TTA_STREAM_RENDER_PREFETCH_MAX_FRAMES', 2048)))
    return max(1, min(int(max_frames), max(int(batch_size), int(batch_size) * int(batches))))


def streaming_prediction_source_workers(default_workers: int, num_frames: int) -> int:
    """Resolve the render-worker budget visible to one streaming source.

    v13 gives an active source/view the full CPU allocation by default.  When sources
    are attached to the shared streaming render pool, this value documents the per-source
    budget and keeps legacy per-source executors full-budget if the shared pool is disabled.
    """
    full_cpu_default = max(1, _env_int('YOLO_TTA_STREAMING_SOURCE_DEFAULT_WORKERS', max(1, _cpu_count())))
    min_workers = max(1, _env_int('YOLO_TTA_STREAMING_SOURCE_MIN_WORKERS', full_cpu_default))
    default_resolved = max(1, int(default_workers), int(min_workers), int(full_cpu_default))
    requested = _env_int('YOLO_TTA_STREAMING_SOURCE_WORKERS', _env_int('YOLO_TTA_STREAM_RENDER_WORKERS', int(default_resolved)))
    return choose_slice_parallel_workers(max(1, int(requested)), max(1, int(num_frames)))


def shared_streaming_render_pool_enabled() -> bool:
    """Return True when all streaming YOLO sources should share one CPU render pool."""
    if os.environ.get('YOLO_TTA_SHARED_STREAMING_RENDER_POOL') is not None:
        return _env_flag('YOLO_TTA_SHARED_STREAMING_RENDER_POOL', True)
    return _env_flag('YOLO_TTA_SHARED_RENDER_POOL', True)


def resolve_prediction_render_workers(default_workers: int, max_frames: int) -> int:
    requested = _env_int(
        'YOLO_TTA_PREDICTION_RENDER_WORKERS',
        _env_int('YOLO_TTA_STREAMING_RENDER_WORKERS', int(default_workers)),
    )
    return choose_slice_parallel_workers(max(1, int(requested)), max(1, int(max_frames)))


def resolve_prediction_source_queue_slots(total_tasks: int, *, streaming_sources: bool = True) -> int:
    """Resolve how many future YOLO sources may be created.

    v13 makes streaming source creation unbounded by default because a streaming ref is
    lightweight and the expensive CPU work is separately governed by the shared render
    executor and per-source prefetch windows.  Legacy dense prediction-volume materialization
    keeps the older CPU-count-scaled default to avoid materializing every source in RAM.
    Explicitly set YOLO_TTA_PREDICTION_VOLUME_QUEUE_SLOTS to a positive value to cap it,
    or to 0 to queue every remaining source in either mode.
    """
    total = max(1, int(total_tasks))
    raw = os.environ.get('YOLO_TTA_PREDICTION_VOLUME_QUEUE_SLOTS', '').strip()
    if raw:
        try:
            requested = int(raw)
        except Exception:
            requested = 0
        if int(requested) <= 0:
            return int(total)
        return max(1, min(int(total), int(requested)))
    if bool(streaming_sources):
        return int(total)
    default_slots = max(8, min(int(total), max(1, int(_cpu_count()))))
    return int(default_slots)


def ensure_ultralytics_accepts_in_memory_volume_source() -> None:
    """Register the v12 in-memory volume loader with Ultralytics' source checker."""
    try:
        import ultralytics.data.build as ultralytics_build  # type: ignore
    except Exception as exc:  # pragma: no cover - ultralytics is imported lazily on SLURM
        raise RuntimeError(f'Unable to import ultralytics.data.build for in-memory prediction source registration: {exc}') from exc

    loaders = getattr(ultralytics_build, 'LOADERS', ())
    try:
        loaders_tuple = tuple(loaders)
    except Exception:
        loaders_tuple = ()
    additions: List[object] = []
    for loader_cls in (InMemoryYoloVolumeSource, StreamingYoloVolumeSource, GpuPrefetchingYoloSource, GpuRenderedYoloSource):
        if loader_cls not in loaders_tuple:
            additions.append(loader_cls)
    if additions:
        setattr(ultralytics_build, 'LOADERS', loaders_tuple + tuple(additions))


def make_in_memory_yolo_source(
    volume_gray: np.ndarray,
    name: str,
    *,
    batch_size: int = 1,
    max_frames: Optional[int] = None,
) -> InMemoryYoloVolumeSource:
    ensure_ultralytics_accepts_in_memory_volume_source()
    return InMemoryYoloVolumeSource(volume_gray, name=name, batch_size=max(1, int(batch_size)), max_frames=max_frames)


def make_prediction_ref_yolo_source(
    prediction_volume: PredictionVolumeRef,
    *,
    batch_size: int = 1,
    max_frames: Optional[int] = None,
) -> object:
    ensure_ultralytics_accepts_in_memory_volume_source()
    source = getattr(prediction_volume, 'source', None)
    if source is not None:
        return source
    if prediction_volume.array is None:
        raise ValueError(f'Prediction input {prediction_volume.name} has neither source nor array')
    return make_in_memory_yolo_source(
        prediction_volume.array,
        prediction_volume.name,
        batch_size=max(1, int(batch_size)),
        max_frames=max_frames,
    )


def _center_preserving_scale_matrix(src_w: int, src_h: int, out_w: int, out_h: int) -> np.ndarray:
    cx_src = (int(src_w) - 1) / 2.0
    cy_src = (int(src_h) - 1) / 2.0
    cx_out = (int(out_w) - 1) / 2.0
    cy_out = (int(out_h) - 1) / 2.0
    sx = float(out_w) / float(src_w)
    sy = float(out_h) / float(src_h)
    return np.array(
        [
            [sx, 0.0, cx_out - sx * cx_src],
            [0.0, sy, cy_out - sy * cy_src],
            [0.0, 0.0, 1.0],
        ],
        dtype=np.float64,
    )


def dense_tile_positions(length: int, tile_size: int, stride: int) -> List[int]:
    length = int(length)
    tile_size = int(tile_size)
    stride = int(stride)
    if tile_size <= 0:
        return []
    if stride <= 0:
        raise ValueError('tile stride must be > 0 when dense tiling is enabled')

    last = max(0, length - tile_size)
    starts = list(range(0, last + 1, stride)) if last > 0 else [0]
    if not starts:
        starts = [0]
    if starts[-1] != last:
        starts.append(last)
    return [int(x) for x in starts]


def build_dense_tile_jobs_for_aug(
    view: ViewInfo,
    aug_job: AugJob,
    tile_cfg: TileConfig,
    out_size: int,
    temp_dir: Path,
) -> List[DenseTileJob]:
    tile_dir = temp_dir / 'tiles' / view.name / tile_cfg.config_id / aug_job.aug_id
    xs = dense_tile_positions(int(aug_job.aff.canvas_w), int(tile_cfg.tile_size), int(tile_cfg.tile_stride))
    ys = dense_tile_positions(int(aug_job.aff.canvas_h), int(tile_cfg.tile_size), int(tile_cfg.tile_stride))
    jobs: List[DenseTileJob] = []

    M_src_to_canvas3 = _affine2x3_to_3x3(aug_job.aff.M_src_to_canvas)
    for tile_y in ys:
        for tile_x in xs:
            tile_id = f'{tile_cfg.config_id}_{aug_job.aug_id}_x{int(tile_x):04d}_y{int(tile_y):04d}'
            M_crop = np.array(
                [
                    [1.0, 0.0, -float(tile_x)],
                    [0.0, 1.0, -float(tile_y)],
                    [0.0, 0.0, 1.0],
                ],
                dtype=np.float64,
            )
            M_scale = _center_preserving_scale_matrix(int(tile_cfg.tile_size), int(tile_cfg.tile_size), int(out_size), int(out_size))
            M_src_to_out3 = M_scale @ M_crop @ M_src_to_canvas3
            M_out_to_src3 = np.linalg.inv(M_src_to_out3)
            jobs.append(
                DenseTileJob(
                    view=view.name,
                    aug_id=aug_job.aug_id,
                    config_id=tile_cfg.config_id,
                    tile_id=tile_id,
                    tile_x=int(tile_x),
                    tile_y=int(tile_y),
                    tile_size=int(tile_cfg.tile_size),
                    tile_stride=int(tile_cfg.tile_stride),
                    out_size=int(out_size),
                    meta_path=tile_dir / f'{view.name}_{tile_id}.meta.json',
                    M_out_to_src=M_out_to_src3[:2, :3].astype(np.float32),
                    M_src_to_out=M_src_to_out3[:2, :3].astype(np.float32),
                )
            )
    return jobs


def write_dense_tile_job_meta(job: DenseTileJob) -> None:
    job.meta_path.parent.mkdir(parents=True, exist_ok=True)
    job.meta_path.write_text(
        json.dumps(
            {
                'view': job.view,
                'aug_id': job.aug_id,
                'config_id': job.config_id,
                'tile_id': job.tile_id,
                'tile_x': int(job.tile_x),
                'tile_y': int(job.tile_y),
                'tile_size': int(job.tile_size),
                'tile_stride': int(job.tile_stride),
                'out_size': int(job.out_size),
                'M_out_to_src': job.M_out_to_src.tolist(),
                'M_src_to_out': job.M_src_to_out.tolist(),
            },
            indent=2,
        )
    )


@dataclass(frozen=True)
class TiltedRenderPlan:
    x_idx: np.ndarray
    y_idx: np.ndarray
    valid_xy: np.ndarray
    axis_offset: np.ndarray
    # v13.3.2 (R5): frame-invariant hoists. The tilted frame center is always an integer, so
    # floor/frac of the sheared stack coordinate, the flat in-plane gather index, and each
    # pixel's valid frame-center interval [c_lo, c_hi] are all constant across frames — only a
    # scalar integer offset varies per frame. row_* fields describe the separable fast path
    # (per-row constant stack coordinate + contiguous in-plane row reads); flat/2D fields back
    # the generic single-flat-gather path. Exactly one of the two families is populated.
    stack_stride: int = 0
    row_c_lo: Optional[np.ndarray] = None      # int32 (H,): min valid frame center per row (sentinel +INT when row empty)
    row_c_hi: Optional[np.ndarray] = None      # int32 (H,): max valid frame center per row (sentinel -INT)
    row_fast: bool = False
    row_sb0: Optional[np.ndarray] = None       # int32 (H,): per-row floor(tan*offset)
    row_alpha: Optional[np.ndarray] = None     # float32 (H,): per-row frac(tan*offset)
    row_v: Optional[np.ndarray] = None         # int32 (H,): per-row fixed in-plane index
    row_u0: Optional[np.ndarray] = None        # int32 (H,): first valid output column
    row_u1: Optional[np.ndarray] = None        # int32 (H,): one past last valid output column
    row_su0: Optional[np.ndarray] = None       # int32 (H,): source u of the first valid column
    flat_base: Optional[np.ndarray] = None     # int64 (H,W): in-plane flat index + sb0*stack_stride
    alpha2d: Optional[np.ndarray] = None       # float32 (H,W)
    om_alpha2d: Optional[np.ndarray] = None    # float32 (H,W): 1 - alpha (kept so the lerp matches the legacy fp32 ops bit-for-bit)
    c_lo2d: Optional[np.ndarray] = None        # int32 (H,W)
    c_hi2d: Optional[np.ndarray] = None        # int32 (H,W)


# v13.2.2 bugs #9/#10: the tilted plan cache was an unbounded plain dict with a lock-free
# check-then-act. Every render-pool thread that started a tilted view simultaneously missed the
# cache together and each rebuilt the same ~100+ MB plan (a transient multi-GiB spike), and every
# (view, grid, matrix) key ever built stayed resident for the rest of the run. The cache is now
# LRU-bounded by bytes and per-key single-flight: one thread builds while the others wait.
_TILTED_RENDER_PLAN_CACHE: 'OrderedDict[Tuple[str, int, int, Tuple[float, ...]], TiltedRenderPlan]' = OrderedDict()
_TILTED_RENDER_PLAN_CACHE_BYTES = 0
_TILTED_RENDER_PLAN_CACHE_LOCK = threading.Lock()
_TILTED_RENDER_PLAN_BUILDS_IN_FLIGHT: Dict[Tuple[str, int, int, Tuple[float, ...]], threading.Event] = {}


def tilted_render_plan_cache_max_bytes() -> int:
    return int(max(0.0, _env_float('YOLO_TTA_TILTED_PLAN_CACHE_GIB', 4.0)) * GIB)


def _tilted_render_plan_nbytes(plan: TiltedRenderPlan) -> int:
    total = int(plan.x_idx.nbytes) + int(plan.y_idx.nbytes) + int(plan.valid_xy.nbytes) + int(plan.axis_offset.nbytes)
    # v13.3.2 (R5): the hoisted frame-invariant arrays count against the LRU byte budget too.
    for extra in (
        plan.row_c_lo, plan.row_c_hi, plan.row_sb0, plan.row_alpha, plan.row_v,
        plan.row_u0, plan.row_u1, plan.row_su0,
        plan.flat_base, plan.alpha2d, plan.om_alpha2d, plan.c_lo2d, plan.c_hi2d,
    ):
        if extra is not None:
            total += int(extra.nbytes)
    return total


def _tilted_plan_cache_key(view: ViewInfo, M_grid_to_src: np.ndarray, grid_h: int, grid_w: int) -> Tuple[str, int, int, Tuple[float, ...]]:
    mat = tuple(round(float(x), 6) for x in np.asarray(M_grid_to_src, dtype=np.float32).reshape(-1).tolist())
    return (str(view.name), int(grid_h), int(grid_w), mat)


def get_tilted_render_plan(
    view: ViewInfo,
    M_grid_to_src: np.ndarray,
    grid_h: int,
    grid_w: int,
) -> TiltedRenderPlan:
    if not is_tilted_view(view):
        raise ValueError('Tilted render plan requested for a non-tilted view')

    key = _tilted_plan_cache_key(view, M_grid_to_src, int(grid_h), int(grid_w))
    while True:
        with _TILTED_RENDER_PLAN_CACHE_LOCK:
            cached = _TILTED_RENDER_PLAN_CACHE.get(key)
            if cached is not None:
                _TILTED_RENDER_PLAN_CACHE.move_to_end(key)
                return cached
            in_flight = _TILTED_RENDER_PLAN_BUILDS_IN_FLIGHT.get(key)
            if in_flight is None:
                _TILTED_RENDER_PLAN_BUILDS_IN_FLIGHT[key] = threading.Event()
                break
        # Another thread is building this exact plan; wait instead of duplicating the
        # multi-hundred-MB temporaries. If the builder fails, the loop retries here.
        in_flight.wait()
    try:
        plan = _build_tilted_render_plan(view, M_grid_to_src, int(grid_h), int(grid_w))
        global _TILTED_RENDER_PLAN_CACHE_BYTES
        with _TILTED_RENDER_PLAN_CACHE_LOCK:
            _TILTED_RENDER_PLAN_CACHE[key] = plan
            _TILTED_RENDER_PLAN_CACHE.move_to_end(key)
            _TILTED_RENDER_PLAN_CACHE_BYTES += _tilted_render_plan_nbytes(plan)
            budget = tilted_render_plan_cache_max_bytes()
            # Evict LRU entries down to the byte budget, always keeping the entry just
            # inserted (a single oversized plan must still be usable).
            while _TILTED_RENDER_PLAN_CACHE_BYTES > budget and len(_TILTED_RENDER_PLAN_CACHE) > 1:
                evict_key, evicted = _TILTED_RENDER_PLAN_CACHE.popitem(last=False)
                _TILTED_RENDER_PLAN_CACHE_BYTES -= _tilted_render_plan_nbytes(evicted)
                # Visible signal: frequent evictions mean the active working set exceeds
                # the budget and plans are being rebuilt — raise YOLO_TTA_TILTED_PLAN_CACHE_GIB.
                print(
                    f'Tilted render plan cache evicted {evict_key[0]} '
                    f'{int(evict_key[1])}x{int(evict_key[2])} '
                    f'({_tilted_render_plan_nbytes(evicted) / GIB:.2f} GiB freed, '
                    f'{_TILTED_RENDER_PLAN_CACHE_BYTES / GIB:.2f} GiB cached).'
                )
        return plan
    finally:
        with _TILTED_RENDER_PLAN_CACHE_LOCK:
            done_event = _TILTED_RENDER_PLAN_BUILDS_IN_FLIGHT.pop(key, None)
        if done_event is not None:
            done_event.set()


def _build_tilted_render_plan(
    view: ViewInfo,
    M_grid_to_src: np.ndarray,
    grid_h: int,
    grid_w: int,
) -> TiltedRenderPlan:
    yy, xx = np.indices((int(grid_h), int(grid_w)), dtype=np.float32)
    M = np.asarray(M_grid_to_src, dtype=np.float32)
    src_x = (M[0, 0] * xx) + (M[0, 1] * yy) + M[0, 2]
    src_y = (M[1, 0] * xx) + (M[1, 1] * yy) + M[1, 2]

    x_nn = np.rint(src_x).astype(np.int32, copy=False)
    y_nn = np.rint(src_y).astype(np.int32, copy=False)
    valid_xy = (
        (x_nn >= 0) & (x_nn < int(view.src_w)) &
        (y_nn >= 0) & (y_nn < int(view.src_h))
    )
    x_idx = np.clip(x_nn, 0, int(view.src_w) - 1).astype(np.int32, copy=False)
    y_idx = np.clip(y_nn, 0, int(view.src_h) - 1).astype(np.int32, copy=False)

    if str(view.tilt_direction) == 'vertical':
        axis_offset = src_y - float((int(view.src_h) - 1) / 2.0)
    elif str(view.tilt_direction) == 'horizontal':
        axis_offset = src_x - float((int(view.src_w) - 1) / 2.0)
    else:  # pragma: no cover
        raise ValueError(f'Unsupported tilt direction: {view.tilt_direction}')

    valid_xy = valid_xy.astype(bool, copy=False)
    axis_offset = np.asarray(axis_offset, dtype=np.float32)

    # v13.3.2 (R5): hoist every frame-invariant term. The frame center c is an integer
    # (tilted_frame_center), so with b = tan(tilt)*axis_offset (fp32):
    #   stack coordinate = c + b, floor = c + floor(b), frac = b - floor(b),
    #   valid  <=>  c >= -floor(b)  and  c <= (stack_len-1) - floor(b) - [frac > 0].
    base_view = tilted_base_view_name(view)
    stack_len = int(tilted_stack_axis_length(view))
    full_h = int(view.full_h)
    full_w = int(view.full_w)
    grid_h_i = int(grid_h)
    grid_w_i = int(grid_w)
    tan_alpha = np.float32(math.tan(math.radians(float(view.tilt_angle_deg))))
    b = axis_offset * tan_alpha
    sb0 = np.floor(b).astype(np.int32, copy=False)
    alpha = (b - sb0).astype(np.float32, copy=False)
    last = np.int32(max(0, stack_len - 1))
    c_lo2d = (-sb0).astype(np.int32, copy=False)
    c_hi2d = (last - sb0 - (alpha > 0)).astype(np.int32, copy=False)
    pos_sent = np.int32(2 ** 31 - 1)
    neg_sent = np.int32(-(2 ** 31) + 1)
    row_c_lo = np.where(valid_xy, c_lo2d, pos_sent).min(axis=1).astype(np.int32, copy=False)
    row_c_hi = np.where(valid_xy, c_hi2d, neg_sent).max(axis=1).astype(np.int32, copy=False)

    # Separable fast path: per-row constant stack coordinate AND contiguous in-plane row reads
    # (base u axis is the volume's fastest axis, i.e. transverse/sagittal bases).
    row_fast = False
    row_sb0 = row_alpha = row_v = row_u0 = row_u1 = row_su0 = None
    if base_view in ('transverse', 'sagittal') and stack_len > 0 and grid_w_i > 1:
        rows_const = (
            bool(np.all(sb0 == sb0[:, :1]))
            and bool(np.all(alpha == alpha[:, :1]))
            and bool(np.all(y_idx == y_idx[:, :1]))
        )
        if rows_const:
            counts = valid_xy.sum(axis=1)
            first = np.argmax(valid_xy, axis=1)
            last_col = grid_w_i - 1 - np.argmax(valid_xy[:, ::-1], axis=1)
            contiguous = bool(np.all((counts == 0) | (counts == (last_col - first + 1))))
            if contiguous:
                pair_valid = valid_xy[:, 1:] & valid_xy[:, :-1]
                consecutive = bool(np.all((np.diff(x_idx, axis=1) == 1) | ~pair_valid))
                if consecutive:
                    row_fast = True
                    row_sb0 = np.ascontiguousarray(sb0[:, 0])
                    row_alpha = np.ascontiguousarray(alpha[:, 0])
                    row_v = np.ascontiguousarray(y_idx[:, 0])
                    row_u0 = first.astype(np.int32, copy=False)
                    row_u1 = np.where(counts > 0, last_col + 1, first).astype(np.int32, copy=False)
                    row_su0 = x_idx[np.arange(grid_h_i), np.minimum(first, grid_w_i - 1)].astype(np.int32, copy=False)

    flat_base = alpha2d = om_alpha2d = None
    if base_view == 'transverse':
        stack_stride = full_h * full_w
        inplane = y_idx.astype(np.int64) * np.int64(full_w) + x_idx
    elif base_view == 'sagittal':
        stack_stride = full_w
        inplane = y_idx.astype(np.int64) * np.int64(full_h * full_w) + x_idx
    elif base_view == 'coronal':
        stack_stride = 1
        inplane = y_idx.astype(np.int64) * np.int64(full_h * full_w) + x_idx.astype(np.int64) * np.int64(full_w)
    else:  # pragma: no cover
        raise ValueError(f'Unsupported Tilted View base: {base_view}')
    if not row_fast:
        flat_base = inplane + sb0.astype(np.int64) * np.int64(stack_stride)
        alpha2d = alpha
        om_alpha2d = (np.float32(1.0) - alpha).astype(np.float32, copy=False)

    return TiltedRenderPlan(
        x_idx=x_idx,
        y_idx=y_idx,
        valid_xy=valid_xy,
        axis_offset=axis_offset,
        stack_stride=int(stack_stride),
        row_c_lo=row_c_lo,
        row_c_hi=row_c_hi,
        row_fast=bool(row_fast),
        row_sb0=row_sb0,
        row_alpha=row_alpha,
        row_v=row_v,
        row_u0=row_u0,
        row_u1=row_u1,
        row_su0=row_su0,
        flat_base=flat_base,
        alpha2d=alpha2d,
        om_alpha2d=om_alpha2d,
        c_lo2d=None if row_fast else c_lo2d,
        c_hi2d=None if row_fast else c_hi2d,
    )


_TILTED_RENDER_TLS = threading.local()


def _tilted_tls_buffer(name: str, count: int, dtype: object) -> np.ndarray:
    """v13.3.2 (R5): reusable per-render-thread flat scratch buffer (grow-only)."""
    bufs = getattr(_TILTED_RENDER_TLS, 'bufs', None)
    if bufs is None:
        bufs = {}
        _TILTED_RENDER_TLS.bufs = bufs
    key = (str(name), np.dtype(dtype).str)
    cur = bufs.get(key)
    if cur is None or int(cur.size) < int(count):
        cur = np.empty((int(count),), dtype=np.dtype(dtype))
        bufs[key] = cur
    return cur[: int(count)]


def _render_tilted_array_on_grid(
    volume_arr: np.ndarray,
    view: ViewInfo,
    frame_idx: int,
    M_grid_to_src: np.ndarray,
    grid_h: int,
    grid_w: int,
    *,
    mask_mode: bool,
    block_rows: int = 256,
) -> np.ndarray:
    """Render one generalized v12 Tilted View frame.

    ``M_grid_to_src`` maps output/grid pixels into the selected Cartesian base view's
    native raster coordinates.  The two in-plane axes are rounded to their native
    grid, while the base view's stacking coordinate is linearly interpolated after
    applying the signed shear.  This covers Tilted Transverse, Tilted Sagittal, and
    Tilted Coronal without expanding the output canvas.

    v13.3.2 (R5): all frame-invariant math lives in the cached TiltedRenderPlan; per frame only
    an integer offset remains. Rows whose stack coordinate is constant and whose in-plane reads
    are contiguous render via row slices + a scalar lerp (GIL-free); everything else uses ONE
    clipped flat gather per lerp end restricted to the valid row band, with thread-local
    reusable buffers and a multiply merge instead of a masked scatter. The legacy per-block
    double fancy gather survives as the reference/fallback path.
    """
    if not is_tilted_view(view):
        raise ValueError('Tilted rendering requested for a non-tilted view')

    # A tilted output frame can sample a sheared range of the base stack. Wait for
    # the streaming preprocessing producer to finish before using these views.
    wait_for_volume_ready(volume_arr)

    plan = get_tilted_render_plan(view, M_grid_to_src, int(grid_h), int(grid_w))
    stack_len = int(tilted_stack_axis_length(view))
    out = np.zeros((int(grid_h), int(grid_w)), dtype=np.uint8)
    if stack_len <= 0:
        return out

    vol = np.asarray(volume_arr)
    expected_shape = (int(view.full_t), int(view.full_h), int(view.full_w))
    hoisted_usable = (
        int(plan.stack_stride) > 0
        and plan.row_c_lo is not None
        and tuple(int(x) for x in vol.shape) == expected_shape
        and (bool(plan.row_fast) or (plan.flat_base is not None and bool(vol.flags['C_CONTIGUOUS'])))
    )
    if not hoisted_usable:
        return _render_tilted_array_on_grid_reference(
            volume_arr, view, int(frame_idx), M_grid_to_src, int(grid_h), int(grid_w),
            mask_mode=bool(mask_mode), block_rows=int(block_rows),
        )

    c = int(tilted_frame_center(view, int(frame_idx)))
    band = np.flatnonzero((plan.row_c_lo <= c) & (c <= plan.row_c_hi))
    if band.size == 0:
        return out
    last = int(stack_len - 1)

    if bool(plan.row_fast):
        sagittal = tilted_base_view_name(view) == 'sagittal'
        row_a = _tilted_tls_buffer('rowfast_a', int(grid_w), np.float32)
        row_b = _tilted_tls_buffer('rowfast_b', int(grid_w), np.float32)
        for r in band:
            r_i = int(r)
            u0 = int(plan.row_u0[r_i])
            u1 = int(plan.row_u1[r_i])
            n = u1 - u0
            if n <= 0:
                continue
            s0 = int(plan.row_sb0[r_i]) + c  # band guarantees 0 <= s0 <= last (alpha-aware)
            s1 = s0 + 1 if s0 < last else last
            a = float(plan.row_alpha[r_i])
            v = int(plan.row_v[r_i])
            su0 = int(plan.row_su0[r_i])
            if sagittal:
                f0 = vol[v, s0, su0:su0 + n]
                f1 = vol[v, s1, su0:su0 + n]
            else:
                f0 = vol[s0, v, su0:su0 + n]
                f1 = vol[s1, v, su0:su0 + n]
            orow = out[r_i, u0:u1]
            if a == 0.0:
                if bool(mask_mode):
                    np.greater_equal(f0, 1, out=orow)
                else:
                    orow[:] = f0
            else:
                va = row_a[:n]
                vb = row_b[:n]
                np.multiply(f0, np.float32(1.0 - a), out=va)
                np.multiply(f1, np.float32(a), out=vb)
                np.add(va, vb, out=va)
                if bool(mask_mode):
                    np.greater_equal(va, 0.5, out=orow)
                else:
                    np.rint(va, out=va)
                    np.clip(va, 0.0, 255.0, out=va)
                    np.copyto(orow, va, casting='unsafe')
        return out

    r0 = int(band[0])
    r1 = int(band[-1]) + 1
    nrows = r1 - r0
    n = nrows * int(grid_w)
    shape2 = (nrows, int(grid_w))
    idx = _tilted_tls_buffer('flat_idx', n, np.int64).reshape(shape2)
    f0 = _tilted_tls_buffer('flat_f0', n, np.uint8).reshape(shape2)
    f1 = _tilted_tls_buffer('flat_f1', n, np.uint8).reshape(shape2)
    val = _tilted_tls_buffer('flat_val', n, np.float32).reshape(shape2)
    val2 = _tilted_tls_buffer('flat_val2', n, np.float32).reshape(shape2)
    valid = _tilted_tls_buffer('flat_valid', n, np.bool_).reshape(shape2)
    valid2 = _tilted_tls_buffer('flat_valid2', n, np.bool_).reshape(shape2)

    vol_flat = vol.reshape(-1)
    stride = np.int64(plan.stack_stride)
    np.add(plan.flat_base[r0:r1], np.int64(c) * stride, out=idx)
    # mode='clip' bounds out-of-volume indices; those pixels are zeroed by the validity merge.
    np.take(vol_flat, idx, mode='clip', out=f0)
    np.add(idx, stride, out=idx)
    # Where s0 == last (only valid with alpha == 0) this reads the clipped neighbor, but its
    # lerp weight is exactly 0, so the value never contributes.
    np.take(vol_flat, idx, mode='clip', out=f1)

    np.less_equal(plan.c_lo2d[r0:r1], c, out=valid)
    np.greater_equal(plan.c_hi2d[r0:r1], c, out=valid2)
    np.logical_and(valid, valid2, out=valid)
    np.logical_and(valid, plan.valid_xy[r0:r1], out=valid)

    # Same fp32 expression as the reference path: (1-alpha)*f0 + alpha*f1.
    np.multiply(f0, plan.om_alpha2d[r0:r1], out=val)
    np.multiply(f1, plan.alpha2d[r0:r1], out=val2)
    np.add(val, val2, out=val)

    if bool(mask_mode):
        np.greater_equal(val, 0.5, out=valid2)
        np.logical_and(valid2, valid, out=valid2)
        out[r0:r1, :] = valid2
    else:
        np.rint(val, out=val)
        np.clip(val, 0.0, 255.0, out=val)
        rendered = f0  # reuse the u8 buffer for the quantized output
        np.copyto(rendered, val, casting='unsafe')
        np.multiply(rendered, valid, out=rendered)
        out[r0:r1, :] = rendered
    return out


def _render_tilted_array_on_grid_reference(
    volume_arr: np.ndarray,
    view: ViewInfo,
    frame_idx: int,
    M_grid_to_src: np.ndarray,
    grid_h: int,
    grid_w: int,
    *,
    mask_mode: bool,
    block_rows: int = 256,
) -> np.ndarray:
    """Legacy exact tilted render (per-block double fancy gather); v13.3.2 fallback/reference."""
    plan = get_tilted_render_plan(view, M_grid_to_src, int(grid_h), int(grid_w))
    tan_alpha = float(math.tan(math.radians(float(view.tilt_angle_deg))))
    stack_len = int(tilted_stack_axis_length(view))
    base_view = tilted_base_view_name(view)
    out = np.zeros((int(grid_h), int(grid_w)), dtype=np.uint8)
    if stack_len <= 0:
        return out

    for y0 in range(0, int(grid_h), int(block_rows)):
        y1 = min(int(grid_h), y0 + int(block_rows))
        valid_xy = np.asarray(plan.valid_xy[y0:y1], dtype=bool)
        if not np.any(valid_xy):
            continue

        frame_center = float(tilted_frame_center(view, int(frame_idx)))
        stack_src = frame_center + tan_alpha * np.asarray(plan.axis_offset[y0:y1], dtype=np.float32)
        valid = valid_xy & (stack_src >= 0.0) & (stack_src <= float(stack_len - 1))
        if not np.any(valid):
            continue

        s0 = np.floor(stack_src).astype(np.int32, copy=False)
        s1 = np.clip(s0 + 1, 0, stack_len - 1).astype(np.int32, copy=False)
        s0 = np.clip(s0, 0, stack_len - 1).astype(np.int32, copy=False)
        alpha = (stack_src - s0).astype(np.float32, copy=False)

        u_idx = np.asarray(plan.x_idx[y0:y1], dtype=np.int32)  # base-view horizontal axis
        v_idx = np.asarray(plan.y_idx[y0:y1], dtype=np.int32)  # base-view vertical axis
        if base_view == 'transverse':
            f0 = np.asarray(volume_arr[s0, v_idx, u_idx], dtype=np.float32)
            f1 = np.asarray(volume_arr[s1, v_idx, u_idx], dtype=np.float32)
        elif base_view == 'sagittal':
            # Sagittal in-plane axes are (X, t); stacking axis is Y.
            f0 = np.asarray(volume_arr[v_idx, s0, u_idx], dtype=np.float32)
            f1 = np.asarray(volume_arr[v_idx, s1, u_idx], dtype=np.float32)
        elif base_view == 'coronal':
            # Coronal in-plane axes are (Y, t); stacking axis is X.
            f0 = np.asarray(volume_arr[v_idx, u_idx, s0], dtype=np.float32)
            f1 = np.asarray(volume_arr[v_idx, u_idx, s1], dtype=np.float32)
        else:  # pragma: no cover
            raise ValueError(f'Unsupported Tilted View base: {base_view}')

        values = ((1.0 - alpha) * f0) + (alpha * f1)
        if bool(mask_mode):
            rendered = (values >= 0.5).astype(np.uint8, copy=False)
        else:
            rendered = np.clip(np.rint(values), 0.0, 255.0).astype(np.uint8)
        out_block = out[y0:y1]
        out_block[valid] = rendered[valid]

    return out


def render_tilted_frame_on_grid(
    volume_rgb: np.ndarray,
    view: ViewInfo,
    frame_idx: int,
    M_grid_to_src: np.ndarray,
    grid_h: int,
    grid_w: int,
    block_rows: int = 256,
) -> np.ndarray:
    return _render_tilted_array_on_grid(
        volume_rgb,
        view,
        int(frame_idx),
        M_grid_to_src,
        int(grid_h),
        int(grid_w),
        mask_mode=False,
        block_rows=int(block_rows),
    )


def render_tilted_canvas_frame(
    volume_rgb: np.ndarray,
    view: ViewInfo,
    frame_idx: int,
    aff: AffineSpec,
    block_rows: int = 256,
) -> np.ndarray:
    return render_tilted_frame_on_grid(
        volume_rgb=volume_rgb,
        view=view,
        frame_idx=int(frame_idx),
        M_grid_to_src=aff.M_canvas_to_src,
        grid_h=int(aff.canvas_h),
        grid_w=int(aff.canvas_w),
        block_rows=int(block_rows),
    )


_TILTED_NATIVE_AFFINE_CACHE: Dict[Tuple[str, int, int], AffineSpec] = {}


def get_tilted_native_affine(view: ViewInfo) -> AffineSpec:
    if not is_tilted_view(view):
        raise ValueError('Tilted native affine requested for a non-tilted view')
    key = (str(view.name), int(view.src_w), int(view.src_h))
    cached = _TILTED_NATIVE_AFFINE_CACHE.get(key)
    if cached is not None:
        return cached
    aff = build_affine(
        view=view.name,
        src_w=int(view.src_w),
        src_h=int(view.src_h),
        out_size=max(int(view.src_w), int(view.src_h), 1),
        angle_deg=0.0,
        pad_mode='clamp',
    )
    _TILTED_NATIVE_AFFINE_CACHE[key] = aff
    return aff


def render_tilted_native_frame(volume_rgb: np.ndarray, view: ViewInfo, frame_idx: int) -> np.ndarray:
    aff = get_tilted_native_affine(view)
    return render_tilted_canvas_frame(volume_rgb, view, int(frame_idx), aff)


def render_fullframe_frame_for_job(
    volume_rgb: np.ndarray,
    view: ViewInfo,
    job: AugJob,
    frame_idx: int,
    view_frames: Optional[np.ndarray] = None,
) -> np.ndarray:
    if is_tilted_view(view):
        return render_tilted_frame_on_grid(
            volume_rgb=volume_rgb,
            view=view,
            frame_idx=int(frame_idx),
            M_grid_to_src=job.aff.M_out_to_src,
            grid_h=int(job.aff.out_size),
            grid_w=int(job.aff.out_size),
        )

    native_frame = np.ascontiguousarray(get_view_frame_by_index(volume_rgb, view, int(frame_idx), view_frames=view_frames))
    # v13.2.5 (speed #10): identity fast path — a rotation-free job whose native frame already
    # matches the model raster (e.g. every imgsz-folded radial frame at --angle 0) needs no warp.
    aff = job.aff
    if (
        int(aff.src_w) == int(aff.out_size)
        and int(aff.src_h) == int(aff.out_size)
        and int(aff.canvas_w) == int(aff.src_w)
        and int(aff.canvas_h) == int(aff.src_h)
        and float(aff.angle_deg) % 360.0 == 0.0
    ):
        # Defensive copy only when the frame aliases the source volume (e.g. a transverse slice).
        return native_frame.copy() if native_frame.base is not None else native_frame
    return cv2.warpAffine(
        native_frame,
        aff.M_src_to_out,
        dsize=(int(aff.out_size), int(aff.out_size)),
        flags=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_CONSTANT,
        borderValue=0,
    )


def render_dense_tile_frame_for_job(
    volume_rgb: np.ndarray,
    view: ViewInfo,
    tile_job: DenseTileJob,
    frame_idx: int,
    view_frames: Optional[np.ndarray] = None,
) -> np.ndarray:
    """Render one dense-tile inference range directly from the native view volume.

    This replaces the legacy canvas-video -> crop -> scale FFmpeg path with the
    same transform collapsed into one in-memory reslice.  ``tile_job.M_src_to_out``
    maps native view coordinates directly to the tile's ``--imgsz`` inference
    raster; for Tilted Views the inverse grid-to-native transform is passed into
    the tilted sampler so the stacking-axis shear, in-plane augmentation, crop,
    and scale are sampled in one pass.
    """
    if is_tilted_view(view):
        return render_tilted_frame_on_grid(
            volume_rgb=volume_rgb,
            view=view,
            frame_idx=int(frame_idx),
            M_grid_to_src=tile_job.M_out_to_src,
            grid_h=int(tile_job.out_size),
            grid_w=int(tile_job.out_size),
        )

    native_frame = np.ascontiguousarray(get_view_frame_by_index(volume_rgb, view, int(frame_idx), view_frames=view_frames))
    return cv2.warpAffine(
        native_frame,
        tile_job.M_src_to_out,
        dsize=(int(tile_job.out_size), int(tile_job.out_size)),
        flags=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_CONSTANT,
        borderValue=0,
    )


def _materialize_prediction_volume_from_renderer(
    *,
    num_slices: int,
    out_size: int,
    out_path: Path,
    desc: str,
    renderer: Callable[[int], np.ndarray],
    workers: int = 1,
    show_progress: bool = True,
    view_name: str = '',
    job_id: str = '',
    kind: str = 'fullframe',
) -> PredictionVolumeRef:
    """Return a YOLO-ready prediction input for one rendered view job.

    v12.2.12 defaults to a lazy render-backed source instead of building a
    complete ``(slice,--imgsz,--imgsz)`` volume before inference. YOLO can
    consume the first ready batch while CPU workers continue resizing/warping
    later slices. Set ``YOLO_TTA_STREAMING_PREDICTION_SOURCES=0`` to recover
    the legacy whole-volume materialization path for regression testing.
    """
    stream_name = str(desc).replace('Materializing in-memory ', 'Streaming render-backed ')
    if streaming_prediction_sources_enabled():
        stream_workers = streaming_prediction_source_workers(max(1, int(workers)), max(1, int(num_slices)))
        stream_prefetch = streaming_prediction_source_prefetch_frames(inference_batch_size())
        if bool(show_progress):
            print(
                f'{stream_name}: streaming source active '
                f'(frames={int(num_slices)}, out_size={int(out_size)}, '
                f'workers={stream_workers}, prefetch_frames={stream_prefetch}, '
                f'autostart={bool(streaming_prediction_source_autostart_enabled())})'
            )
        source = StreamingYoloVolumeSource(
            renderer,
            num_frames=int(num_slices),
            name=stream_name,
            batch_size=inference_batch_size(),
            out_size=int(out_size),
            render_workers=stream_workers,
            prefetch_frames=stream_prefetch,
            autostart=streaming_prediction_source_autostart_enabled(),
        )
        return PredictionVolumeRef(
            array=None,
            path=None,
            name=stream_name,
            view_name=str(view_name),
            job_id=str(job_id),
            kind=str(kind),
            source=source,
        )

    out_path.parent.mkdir(parents=True, exist_ok=True)
    pred_volume = allocate_workspace_array(
        shape=(int(num_slices), int(out_size), int(out_size)),
        dtype=np.uint8,
        path=out_path,
        desc=desc,
        prefer_memory=True,
        reserve_bytes=32 * GIB,
        initialize_zero=False,
    )
    worker_count = choose_slice_parallel_workers(int(workers), int(num_slices))
    chunk_size = choose_parallel_chunk_size(int(num_slices), worker_count, target_chunks_per_worker=2, min_chunk_size=1)

    def _render(idx: int) -> None:
        pred_volume[int(idx), :, :] = np.ascontiguousarray(renderer(int(idx)), dtype=np.uint8)

    parallel_for_indices_chunked(
        int(num_slices),
        _render,
        max_workers=worker_count,
        desc=desc,
        show_progress=bool(show_progress),
        chunk_size=chunk_size,
    )
    if prediction_volume_build_flush_enabled():
        flush_array(pred_volume)
    return PredictionVolumeRef(
        array=pred_volume,
        path=out_path if isinstance(pred_volume, np.memmap) else None,
        name=str(desc),
        view_name=str(view_name),
        job_id=str(job_id),
        kind=str(kind),
    )


def materialize_fullframe_prediction_volume_for_job(
    volume_rgb: np.ndarray,
    view: ViewInfo,
    job: AugJob,
    *,
    out_path: Path,
    view_frames: Optional[np.ndarray] = None,
    workers: int = 1,
    show_progress: bool = True,
) -> PredictionVolumeRef:
    """Create the model-sized full-frame prediction volume for one view/angle in RAM."""
    if not job.meta_path.exists():
        write_aug_job_meta(job, view)

    def _render(idx: int) -> np.ndarray:
        return render_fullframe_frame_for_job(
            volume_rgb=volume_rgb,
            view=view,
            job=job,
            frame_idx=int(idx),
            view_frames=view_frames,
        )

    return _materialize_prediction_volume_from_renderer(
        num_slices=int(view.num_slices),
        out_size=int(job.aff.out_size),
        out_path=out_path,
        desc=f'Materializing in-memory full-frame prediction volume {view.name}/{job.aug_id}',
        renderer=_render,
        workers=max(1, int(workers)),
        show_progress=bool(show_progress),
        view_name=str(view.name),
        job_id=str(job.aug_id),
        kind='fullframe',
    )


def materialize_dense_tile_prediction_volume_for_job(
    volume_rgb: np.ndarray,
    view: ViewInfo,
    tile_job: DenseTileJob,
    *,
    out_path: Path,
    view_frames: Optional[np.ndarray] = None,
    workers: int = 1,
    show_progress: bool = True,
) -> PredictionVolumeRef:
    """Create one dense-tile prediction range as an in-memory YOLO volume."""
    if not tile_job.meta_path.exists():
        write_dense_tile_job_meta(tile_job)

    def _render(idx: int) -> np.ndarray:
        return render_dense_tile_frame_for_job(
            volume_rgb=volume_rgb,
            view=view,
            tile_job=tile_job,
            frame_idx=int(idx),
            view_frames=view_frames,
        )

    return _materialize_prediction_volume_from_renderer(
        num_slices=int(view.num_slices),
        out_size=int(tile_job.out_size),
        out_path=out_path,
        desc=f'Materializing in-memory tile prediction volume {view.name}/{tile_job.tile_id}',
        renderer=_render,
        workers=max(1, int(workers)),
        show_progress=bool(show_progress),
        view_name=str(view.name),
        job_id=str(tile_job.tile_id),
        kind='tile',
    )


def should_cache_view_frames(view: ViewInfo, dense_tiling_active: bool) -> bool:
    """Return True when precomputing native single-channel frames is worthwhile for this view.

    Radial frame caches can be useful for dense-tile throughput, but building the entire
    radial cache before inference creates a large time-to-first-prediction barrier.  v12.2.12
    therefore keeps this prebuild opt-in; streaming sources render only the slices they need.
    """
    return bool(_env_flag('YOLO_TTA_PREBUILD_VIEW_FRAME_CACHES', False)) and bool(dense_tiling_active) and view.family == 'radial'


def build_view_frame_cache(
    volume_rgb: np.ndarray,
    view: ViewInfo,
    out_path: Path,
    desc: str,
    *,
    prefer_memory: bool = True,
    reserve_bytes: int = 64 * GIB,
    workers: int = 1,
) -> np.ndarray:
    """Materialize native single-channel frames for a view into a reusable cache volume.

    This is used primarily for the radial view when dense tiling is enabled so later tile video
    generation no longer recomputes the same radial slices for every tile location.
    """
    cache_mm = allocate_workspace_array(
        shape=(int(view.num_slices), int(view.src_h), int(view.src_w)),
        dtype=np.uint8,
        path=out_path,
        desc=desc,
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
        initialize_zero=False,
    )

    worker_count = choose_slice_parallel_workers(int(workers), int(view.num_slices))
    print(
        f"Preparing reusable native single-channel frame cache for view '{view.name}' over {int(view.num_slices)} slice(s) "
        f"with {int(worker_count)} worker thread(s)"
    )

    def _build(idx: int) -> None:
        cache_mm[int(idx), :, :] = np.ascontiguousarray(
            get_view_frame_by_index(volume_rgb, view, int(idx), view_frames=None)
        )

    parallel_for_indices(
        int(view.num_slices),
        _build,
        max_workers=worker_count,
        desc=f'Caching {view.name} native frames',
        show_progress=False,
    )
    flush_array(cache_mm)
    return cache_mm


# v13.3.2 (R14): coronal frames are stride-W column gathers of the (t, Y, X) volume — every
# useful byte drags a whole cache line (~64x DRAM traffic amplification over 3072 frames).
# Extract K-column transposed blocks once (per-t 2D tile transposes stay inside L2) and serve
# frames as contiguous (T, H) views of the cached block. Single-flight per block; tiny LRU.
# Sagittal frames need none of this: volume[:, y, :] rows are contiguous in x (full cache-line
# use in both read and write directions).
_CORONAL_BLOCK_CACHE: 'OrderedDict[Tuple[int, Tuple[int, int, int], int], np.ndarray]' = OrderedDict()
_CORONAL_BLOCK_CACHE_LOCK = threading.Lock()
_CORONAL_BLOCK_BUILDS_IN_FLIGHT: Dict[Tuple[int, Tuple[int, int, int], int], threading.Event] = {}


def coronal_block_cols() -> int:
    """v13.3.2 (R14): columns per cached coronal block (64 x 1 B = one full cache line)."""
    return max(8, _env_int('YOLO_TTA_CORONAL_BLOCK_COLS', 64))


def coronal_block_cache_blocks() -> int:
    """v13.3.2 (R14): coronal block LRU capacity, in blocks (each K*T*H bytes)."""
    return max(1, _env_int('YOLO_TTA_CORONAL_BLOCK_CACHE', 2))


def _coronal_block_cache_key(volume: np.ndarray, block_idx: int) -> Tuple[int, Tuple[int, int, int], int]:
    ptr = int(volume.__array_interface__['data'][0])
    return (ptr, tuple(int(x) for x in volume.shape), int(block_idx))


def _build_coronal_block(volume: np.ndarray, x0: int, x1: int) -> np.ndarray:
    T, H, _W = (int(v) for v in volume.shape)
    blk = np.empty((int(x1) - int(x0), T, H), dtype=volume.dtype)
    # Per-t (H, K) -> (K, H) tile transpose: the tile (~H*K bytes) stays cache-resident, source
    # reads use full cache lines (K consecutive bytes per row), and destination rows are
    # contiguous. All copies are numpy strided loops (GIL-releasing).
    for t in range(T):
        blk[:, t, :] = volume[t, :, int(x0):int(x1)].T
    return blk


def _coronal_frame_from_block_cache(volume: np.ndarray, x: int) -> np.ndarray:
    K = int(coronal_block_cols())
    W = int(volume.shape[2])
    block_idx = int(x) // K
    key = _coronal_block_cache_key(volume, block_idx)
    while True:
        with _CORONAL_BLOCK_CACHE_LOCK:
            cached = _CORONAL_BLOCK_CACHE.get(key)
            if cached is not None:
                _CORONAL_BLOCK_CACHE.move_to_end(key)
                return cached[int(x) - block_idx * K]
            in_flight = _CORONAL_BLOCK_BUILDS_IN_FLIGHT.get(key)
            if in_flight is None:
                _CORONAL_BLOCK_BUILDS_IN_FLIGHT[key] = threading.Event()
                break
        in_flight.wait()
    try:
        x0 = block_idx * K
        blk = _build_coronal_block(volume, x0, min(W, x0 + K))
        with _CORONAL_BLOCK_CACHE_LOCK:
            _CORONAL_BLOCK_CACHE[key] = blk
            _CORONAL_BLOCK_CACHE.move_to_end(key)
            while len(_CORONAL_BLOCK_CACHE) > coronal_block_cache_blocks():
                _CORONAL_BLOCK_CACHE.popitem(last=False)
        # Returned frames are views of blk; an evicted block stays alive while any frame view
        # still references it, so eviction can never invalidate an in-flight consumer.
        return blk[int(x) - x0]
    finally:
        with _CORONAL_BLOCK_CACHE_LOCK:
            done = _CORONAL_BLOCK_BUILDS_IN_FLIGHT.pop(key, None)
        if done is not None:
            done.set()


def get_view_frame_by_index(
    volume_rgb: np.ndarray,
    view: ViewInfo,
    index: int,
    view_frames: Optional[np.ndarray] = None,
) -> np.ndarray:
    if view_frames is not None:
        return np.asarray(view_frames[int(index)])

    T, H, W = volume_rgb.shape

    if view.name == 'transverse':
        wait_for_volume_slice_ready(volume_rgb, int(index))
        return np.asarray(volume_rgb[int(index)])
    if view.name == 'sagittal':
        wait_for_volume_ready(volume_rgb)
        return np.ascontiguousarray(volume_rgb[:, int(index), :])
    if view.name == 'coronal':
        wait_for_volume_ready(volume_rgb)
        # v13.3.2 (R14): serve from K-column transposed blocks instead of a strided gather.
        if volume_rgb.ndim == 3 and bool(volume_rgb.flags['C_CONTIGUOUS']):
            return _coronal_frame_from_block_cache(volume_rgb, int(index))
        return np.ascontiguousarray(volume_rgb[:, :, int(index)])
    if view.name == 'radial':
        wait_for_volume_ready(volume_rgb)
        angle_deg = float(view.azimuths_deg[int(index)])
        sampler = get_radial_sampler(view, angle_deg)
        # v13.2.5 (speed #1): sample directly at the (possibly imgsz-folded) native raster.
        return np.ascontiguousarray(extract_radial_slice_frame(volume_rgb, sampler, out_rows=int(view.src_h)))
    if is_tilted_view(view):
        wait_for_volume_ready(volume_rgb)
        return render_tilted_native_frame(volume_rgb, view, int(index))

    raise ValueError(f'Unknown view: {view.name}')


