def _gray_to_rgb_frame(frame_gray: np.ndarray) -> np.ndarray:
    arr = np.asarray(frame_gray, dtype=np.uint8)
    if arr.ndim == 3 and arr.shape[-1] == 3:
        return np.ascontiguousarray(arr)
    if arr.ndim == 3 and arr.shape[-1] == 1:
        arr = arr[:, :, 0]
    if arr.ndim != 2:
        raise ValueError(f'Expected a 2D gray frame, got shape {arr.shape}')
    return np.repeat(arr[:, :, None], 3, axis=2)


def write_overlay_video(
    volume_rgb: np.memmap,  # (T,H,W) gray/luma
    mask_u8: np.ndarray,    # (T,H,W) 0/1
    out_path: Path,
    fps: float,
    show_progress: bool = True,
) -> None:
    """Overlay blue masks (50% alpha) on transverse frames.

    The working source volume is single-channel; frames are expanded to RGB only for this
    presentation video so the segmentation can remain blue.
    """
    T, H, W = volume_rgb.shape
    assert mask_u8.shape == (T, H, W)

    proc = ffmpeg_ffv1_rgb_writer(
        out_path,
        width=W,
        height=H,
        fps=fps,
    )

    blue = np.array([0, 0, 255], dtype=np.uint8)  # RGB blue

    try:
        assert proc.stdin is not None
        for t in tqdm(range(T), desc=f"Writing overlay video ({out_path.name})", disable=not show_progress):
            frame = _gray_to_rgb_frame(np.asarray(volume_rgb[t]))
            m = mask_u8[t].astype(bool)
            if m.any():
                frame[m] = ((frame[m].astype(np.uint16) + blue.astype(np.uint16)) // 2).astype(np.uint8)
            proc.stdin.write(np.ascontiguousarray(frame).tobytes())
    finally:
        close_ffmpeg_writer(proc)


def mask_to_yolo_polygons(mask01: np.ndarray) -> List[List[Tuple[float, float]]]:
    """Convert a binary mask (H,W) to a list of external polygons with normalized coords."""
    h, w = mask01.shape
    m = (mask01.astype(np.uint8) * 255)
    contours, _ = cv2.findContours(m, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

    polys: List[List[Tuple[float, float]]] = []
    for cnt in contours:
        if cnt is None or len(cnt) < 3:
            continue
        approx = cv2.approxPolyDP(cnt, epsilon=1.0, closed=True)
        if approx is None or len(approx) < 3:
            continue
        pts = approx.reshape(-1, 2)
        polys.append([(float(x) / float(w), float(y) / float(h)) for (x, y) in pts])
    return polys


DEFAULT_LABEL_PATTERN = "labels/{Filename}_%04d.txt"
DEFAULT_BINARY_PATTERN = "binary_masks/{Filename}_Binary_%04d.tiff"


def _resolve_output_pattern(pattern_value: Optional[str], default_pattern: str, out_dir: Path, stem: str) -> Optional[Path]:
    if pattern_value is None:
        return None
    pattern = default_pattern if str(pattern_value) == "__DEFAULT__" else str(pattern_value)
    pattern = pattern.replace("{Filename}", stem)
    path = Path(pattern)
    if not path.is_absolute():
        path = out_dir / path
    return path


def _tag_frame_pattern(path: Path, tag: str) -> Path:
    parent = path.parent
    if parent.name:
        parent = parent.with_name(f"{parent.name}_{tag.lower()}")

    name = path.name
    m = re.search(r"(%0\d+d)", name)
    if m is not None:
        prefix = name[:m.start()]
        if prefix.endswith("_"):
            name = prefix + f"{tag}_" + name[m.start():]
        else:
            name = prefix + f"_{tag}_" + name[m.start():]
    else:
        suffix = "".join(path.suffixes)
        base = name[:-len(suffix)] if suffix else name
        name = f"{base}_{tag}{suffix}"
    return parent / name


def _format_frame_path(pattern_path: Path, frame_idx_1based: int) -> Path:
    as_str = str(pattern_path)
    if "%" in as_str:
        try:
            return Path(as_str % int(frame_idx_1based))
        except TypeError:
            pass
    return pattern_path.with_name(f"{pattern_path.stem}_{int(frame_idx_1based):04d}{pattern_path.suffix}")


def _write_label_file_from_mask(mask2d: np.ndarray, out_path: Path) -> None:
    out_path.parent.mkdir(parents=True, exist_ok=True)
    m = np.asarray(mask2d) > 0
    if not np.any(m):
        out_path.write_text("")
        return

    polys = mask_to_yolo_polygons(m.astype(np.uint8))
    if not polys:
        out_path.write_text("")
        return

    lines: List[str] = []
    for poly in polys:
        coords: List[str] = []
        for x, y in poly:
            coords.append(f"{x:.6f}")
            coords.append(f"{y:.6f}")
        lines.append("0 " + " ".join(coords))
    out_path.write_text("\n".join(lines) + "\n")


def _write_binary_tiff_frame(mask2d: np.ndarray, out_path: Path) -> None:
    """Write one true bilevel binary TIFF frame with DEFLATE compression.

    tifffile stores bool arrays as 1 bit/sample.  This satisfies the required monob
    TIFF sequence while keeping mask semantics unambiguous: False = black, True = white.
    """
    out_path.parent.mkdir(parents=True, exist_ok=True)
    mask_bool = np.asarray(mask2d, dtype=bool)
    tifffile.imwrite(
        str(out_path),
        mask_bool,
        photometric='minisblack',
        compression='deflate',
    )


def write_yolo_labels_from_pattern(
    mask_u8: np.ndarray,
    pattern_path: Path,
    workers: int = 1,
    show_progress: bool = True,
) -> Path:
    pattern_path.parent.mkdir(parents=True, exist_ok=True)
    total = int(mask_u8.shape[0])

    def _write_frame(t: int) -> None:
        fp = _format_frame_path(pattern_path, int(t) + 1)
        _write_label_file_from_mask(np.asarray(mask_u8[int(t)]), fp)

    parallel_for_indices(
        total,
        _write_frame,
        max_workers=choose_slice_parallel_workers(int(workers), total),
        desc=f"Writing YOLO labels ({pattern_path.parent.name})",
        show_progress=show_progress,
    )
    return pattern_path.parent


def write_binary_tiff_sequence_from_pattern(
    mask_u8: np.ndarray,
    pattern_path: Path,
    workers: int = 1,
    show_progress: bool = True,
) -> Path:
    pattern_path.parent.mkdir(parents=True, exist_ok=True)
    total = int(mask_u8.shape[0])

    def _write_frame(t: int) -> None:
        fp = _format_frame_path(pattern_path, int(t) + 1)
        _write_binary_tiff_frame(np.asarray(mask_u8[int(t)]), fp)

    parallel_for_indices(
        total,
        _write_frame,
        max_workers=choose_slice_parallel_workers(int(workers), total),
        desc=f"Writing binary TIFF sequence ({pattern_path.parent.name})",
        show_progress=show_progress,
    )
    return pattern_path.parent


def write_binary_video_from_mask_volume(
    mask_u8: np.ndarray,
    video_path: Path,
    fps: float,
    show_progress: bool = True,
) -> Path:
    T, H, W = mask_u8.shape
    proc = ffmpeg_ffv1_gray_writer(
        video_path,
        width=W,
        height=H,
        fps=fps,
    )
    try:
        assert proc.stdin is not None
        for t in tqdm(range(T), desc=f"Writing binary MKV ({video_path.name})", disable=not show_progress):
            gray = (np.asarray(mask_u8[t]) * 255).astype(np.uint8)
            proc.stdin.write(np.ascontiguousarray(gray).tobytes())
    finally:
        close_ffmpeg_writer(proc)
    return video_path


def _nrrd_ascii_header_text(value: object) -> str:
    """Return ASCII-safe text for pynrrd header fields.

    pynrrd writes headers as ASCII.  View names can contain characters such as the
    degree sign, so normalize those before they reach the header.  The sidecar JSON
    manifest keeps the full Unicode names.
    """
    text = str(value)
    replacements = {
        '°': 'deg',
        '±': '+/-',
        'µ': 'u',
        '–': '-',
        '—': '-',
        '−': '-',
        '\u00a0': ' ',
    }
    for src, dst in replacements.items():
        text = text.replace(src, dst)
    text = text.encode('ascii', 'ignore').decode('ascii')
    return text


def _nrrd_space_directions_matrix(
    spatial_axes: int = 3,
    list_axis: bool = False,
    list_axis_position: str = 'first',
) -> np.ndarray:
    """Return a NRRD ``space directions`` matrix with optional non-spatial list axis.

    Non-spatial axes are represented by a row of NaNs, which serializes as
    ``none``.  ``list_axis_position='last'`` is used by decomposed segmentation
    NRRDs so the on-disk byte stream is one complete ``(t,Y,X)`` layer block
    followed by the next layer.
    """
    spatial_axes_i = max(1, int(spatial_axes))
    if bool(list_axis):
        position = str(list_axis_position).strip().lower()
        mat = np.full((spatial_axes_i + 1, spatial_axes_i), np.nan, dtype=np.float64)
        if position == 'last':
            mat[:spatial_axes_i, :] = np.eye(spatial_axes_i, dtype=np.float64)
        elif position == 'first':
            mat[1:, :] = np.eye(spatial_axes_i, dtype=np.float64)
        else:
            raise ValueError("list_axis_position must be 'first' or 'last'")
        return mat
    return np.eye(spatial_axes_i, dtype=np.float64)


def nrrd_slicer_header(mask_shape_zyx: Tuple[int, int, int]) -> Dict[str, object]:
    t_dim, h, w = (int(mask_shape_zyx[0]), int(mask_shape_zyx[1]), int(mask_shape_zyx[2]))
    return {
        "space": NRRD_SPACE,
        "kinds": ["domain", "domain", "domain"],
        "space directions": _nrrd_space_directions_matrix(spatial_axes=3, list_axis=False),
        "space origin": np.zeros((3,), dtype=np.float64),
        "content": f"binary segmentation mask; source_shape_tyx=({t_dim},{h},{w}); exported_axes=(X,Y,t)",
    }


# v13.2.3: 3D Slicer segmentation tagging for the single-layer NRRD exports. Each component
# layer is written as {Filestem}_{suffix}.seg.nrrd carrying the Slicer segmentation custom
# header fields, so Slicer imports it as a Segmentation node named after the file with a
# stable per-layer color instead of a scalar volume that renders every layer the same green.
_SLICER_SEGMENT_COLOR_PALETTE: Tuple[Tuple[float, float, float], ...] = (
    (0.83, 0.16, 0.16),  # red
    (0.12, 0.47, 0.71),  # blue
    (1.00, 0.60, 0.07),  # orange
    (0.17, 0.63, 0.17),  # green
    (0.58, 0.40, 0.74),  # purple
    (0.09, 0.75, 0.81),  # cyan
    (0.89, 0.47, 0.76),  # pink
    (0.74, 0.74, 0.13),  # olive
    (0.55, 0.34, 0.29),  # brown
    (0.98, 0.75, 0.37),  # light orange
    (0.68, 0.78, 0.91),  # light blue
    (0.60, 0.87, 0.54),  # light green
    (1.00, 0.60, 0.59),  # salmon
    (0.77, 0.69, 0.84),  # lavender
    (0.62, 0.85, 0.90),  # pale cyan
    (0.95, 0.90, 0.45),  # yellow
    (0.78, 0.58, 0.45),  # tan
    (0.96, 0.71, 0.82),  # light pink
    (0.47, 0.05, 0.53),  # violet
    (0.10, 0.35, 0.20),  # dark green
)


def _stable_layer_color_index(token: str) -> int:
    """Deterministic FNV-1a hash of a layer token.

    Python's builtin hash() is salted per process, which would shuffle segment colors
    between runs; the palette pick must be reproducible for the same layer suffix.
    """
    h = 0x811C9DC5
    for b in str(token).encode('utf-8', errors='ignore'):
        h = ((h ^ int(b)) * 0x01000193) & 0xFFFFFFFF
    return int(h)


def slicer_segment_palette_color(token: str) -> Tuple[float, float, float]:
    """Deterministic palette color for a layer token (no in-run collision probing)."""
    palette = _SLICER_SEGMENT_COLOR_PALETTE
    return palette[_stable_layer_color_index(str(token)) % len(palette)]


def _slicer_segment_name_for_out_path(out_path: Path) -> str:
    name = Path(out_path).name
    for ext in ('.seg.nrrd', '.nrrd'):
        if name.lower().endswith(ext):
            return name[:-len(ext)]
    return Path(out_path).stem


def _slicer_segment_extent_for_output(
    ref: 'NrrdLayerRef',
    output_shape_tyx: Tuple[int, int, int],
) -> NrrdSegmentExtent:
    """Map the layer's backing-store segment extent into the output geometry.

    Returns the inclusive Slicer (minX maxX minY maxY minT maxT) extent in the exported
    (X,Y,t) axis order. Extents are expanded outward when the output geometry is scaled
    (e.g. low-quality downbins) and fall back to the full output extent when the backing
    extent is unknown or empty, so the header never understates where mask voxels live.
    """
    out_t, out_h, out_w = (int(output_shape_tyx[0]), int(output_shape_tyx[1]), int(output_shape_tyx[2]))
    full: NrrdSegmentExtent = (0, max(0, out_w - 1), 0, max(0, out_h - 1), 0, max(0, out_t - 1))
    extent = _coerce_segment_extent(getattr(ref, 'segment_extent_ijk', None))
    if extent is None:
        return full
    x0, x1, y0, y1, t0, t1 = (int(v) for v in extent)
    if x1 < x0 or y1 < y0 or t1 < t0:
        return full
    in_t, in_h, in_w = (int(v) for v in getattr(ref, 'segment_extent_shape_tyx', (0, 0, 0)))
    if in_t <= 0 or in_h <= 0 or in_w <= 0:
        return full

    def _axis(lo: int, hi: int, n_in: int, n_out: int) -> Tuple[int, int]:
        if int(n_in) != int(n_out):
            scale = float(n_out) / float(n_in)
            lo = int(math.floor(float(lo) * scale))
            hi = int(math.ceil((float(hi) + 1.0) * scale)) - 1
        return (max(0, min(int(lo), int(n_out) - 1)), max(0, min(int(hi), int(n_out) - 1)))

    x_lo, x_hi = _axis(x0, x1, in_w, out_w)
    y_lo, y_hi = _axis(y0, y1, in_h, out_h)
    t_lo, t_hi = _axis(t0, t1, in_t, out_t)
    return (x_lo, x_hi, y_lo, y_hi, t_lo, t_hi)


def slicer_segmentation_header_fields(
    *,
    segment_name: str,
    color_rgb: Tuple[float, float, float],
    extent_xyt: NrrdSegmentExtent,
) -> Dict[str, object]:
    """3D Slicer .seg.nrrd custom header fields for one single-segment binary labelmap.

    All keys are non-standard NRRD fields, so _write_nrrd_ascii_header emits them with the
    key:=value separator Slicer expects. Segment0_LabelValue matches the uint8 mask value 1.
    """
    r, g, b = (float(color_rgb[0]), float(color_rgb[1]), float(color_rgb[2]))
    return {
        'Segmentation_ContainedRepresentationNames': 'Binary labelmap|',
        'Segmentation_MasterRepresentation': 'Binary labelmap',
        'Segment0_ID': 'Segment_1',
        'Segment0_Name': str(segment_name),
        'Segment0_NameAutoGenerated': '0',
        'Segment0_Color': f'{r:.6g} {g:.6g} {b:.6g}',
        'Segment0_ColorAutoGenerated': '0',
        'Segment0_LabelValue': '1',
        'Segment0_Layer': '0',
        'Segment0_Extent': ' '.join(str(int(v)) for v in extent_xyt),
        'Segment0_Tags': (
            'TerminologyEntry:Segmentation category and type - 3D Slicer General Anatomy list'
            '~SCT^85756007^Tissue~SCT^85756007^Tissue~^^~Anatomic codes - DICOM master list~^^~^^|'
        ),
    }


def nrrd_pigz_compresslevel() -> int:
    """Compression level passed to pigz for NRRD gzip-encoding.

    v13.3.1 (R24): default 6 -> 3. The payloads are sparse binary masks whose deflate ratio
    barely moves between levels, while level 3 compresses 2-3x faster per core.
    """
    return int(np.clip(_env_int('YOLO_TTA_NRRD_PIGZ_LEVEL', 3), 0, 9))


def nrrd_z_chunk_cap() -> int:
    """v13.3.1 (R7b): cap on one NRRD payload block, in output t-slices.

    The RAM-scaled buffer previously resolved to the WHOLE payload on large-RAM nodes, so the
    writer filled an ~payload-sized block in one thread before pigz saw a byte. Bounded blocks
    let the (parallel) fill and pigz compression pipeline; two blocks per in-flight write are
    resident (double buffering).
    """
    return max(1, _env_int('YOLO_TTA_NRRD_Z_CHUNK_SLICES', 128))


def nrrd_fill_workers() -> int:
    """v13.3.1 (R7b): threads filling one NRRD payload block.

    The per-slice fill work (raw-bbox store decode memcpys, cv2 restore resizes) releases the
    GIL, so a small pool per write scales; the sink runs up to nrrd_layer_sink_workers() writes
    concurrently. v13.3.3: default cores//8 -> min(32, cores//4) — fill threads are only live
    while a block is being decoded, and the write tail runs on an otherwise idle box.
    """
    return max(2, _env_int('YOLO_TTA_NRRD_FILL_WORKERS', max(2, min(32, _cpu_count() // 4))))


def nrrd_pigz_threads() -> int:
    default_threads = max(1, min(_cpu_count(), _env_int('YOLO_TTA_NRRD_PIGZ_MAX_THREADS', max(1, _cpu_count()))))
    return max(1, _env_int('YOLO_TTA_NRRD_PIGZ_THREADS', int(default_threads)))


def nrrd_single_layer_pigz_threads() -> int:
    """pigz thread count for one single-layer NRRD write.

    v13.2.0 writes one small single-layer NRRD per component layer, often several
    concurrently (e.g. the Transverse layer compresses while Tiled Transverse is still
    inferencing).  Capping per-write pigz threads keeps many concurrent layer writes from
    oversubscribing the box against the GPU-feeding render/postprocess pools.
    """
    cores = max(1, _cpu_count())
    default_threads = max(1, min(cores, max(1, cores // 4)))
    return max(1, _env_int('YOLO_TTA_NRRD_SINGLE_LAYER_PIGZ_THREADS', int(default_threads)))


def nrrd_stream_buffer_bytes(required_bytes: Optional[int] = None) -> int:
    """Return the RAM budget for one NRRD streaming payload slab.

    v12.2.1 intentionally avoided materializing the full decomposed NRRD payload.
    v12.2.2 keeps that safety property but uses the hundreds of GiB that are normally
    free under the SLURM allocation to make the streaming slabs much larger.  An
    explicit YOLO_TTA_NRRD_STREAM_BUFFER_MIB still wins; otherwise the buffer is a
    bounded fraction of currently available anonymous memory after a reserve.
    """
    explicit = os.environ.get('YOLO_TTA_NRRD_STREAM_BUFFER_MIB', '').strip()
    if explicit:
        mib = max(1, _env_int('YOLO_TTA_NRRD_STREAM_BUFFER_MIB', 4096))
        target = int(mib) * 1024 * 1024
    else:
        min_mib = max(1, _env_int('YOLO_TTA_NRRD_STREAM_BUFFER_MIN_MIB', 4096))
        reserve_gib = max(1.0, _env_float('YOLO_TTA_NRRD_STREAM_BUFFER_RESERVE_GIB', 192.0))
        max_gib = max(1.0, _env_float('YOLO_TTA_NRRD_STREAM_BUFFER_MAX_GIB', 384.0))
        fraction = min(0.90, max(0.01, _env_float('YOLO_TTA_NRRD_STREAM_BUFFER_FRACTION', 0.35)))
        avail = int(available_anon_work_bytes())
        usable = max(0, int(avail) - int(reserve_gib * GIB))
        target = int(max(int(min_mib) * 1024 * 1024, min(float(max_gib) * float(GIB), float(usable) * float(fraction))))
    if required_bytes is not None and int(required_bytes) > 0:
        target = min(int(target), int(required_bytes))
    return max(1, int(target))


def _nrrd_full_slice_z_chunk(layer_count: int, width: int, height: int, depth: int) -> int:
    full_slice_bytes = max(1, int(layer_count) * int(width) * int(height) * np.dtype(np.uint8).itemsize)
    full_payload_bytes = full_slice_bytes * max(1, int(depth))
    target = nrrd_stream_buffer_bytes(full_payload_bytes)
    if target < full_slice_bytes:
        return 1
    # v13.3.1 (R7b): bound the block so fill and compression pipeline instead of the writer
    # materializing (and single-threadedly filling) the entire payload before pigz starts.
    return max(1, min(int(depth), int(target // full_slice_bytes), int(nrrd_z_chunk_cap())))


def nrrd_madvise_dontneed_interval() -> int:
    # 0 disables advisory cache dropping.  The default keeps NRRD source-layer page cache
    # bounded without issuing a syscall after every single slice.
    return max(0, _env_int('YOLO_TTA_NRRD_MADVISE_DONTNEED_INTERVAL', 16))


class _PigzPayloadWriter:
    """Small file-like wrapper that gzip-encodes NRRD payload bytes through pigz."""

    def __init__(self, fh: object, *, threads: Optional[int] = None) -> None:
        _require_bin('pigz')
        level = int(nrrd_pigz_compresslevel())
        threads = int(nrrd_pigz_threads()) if threads is None else max(1, int(threads))
        level_arg = f'-{level}' if level > 0 else '-0'
        cmd = ['pigz', '-c', '-n', '-p', str(threads), level_arg]
        try:
            flush_fn = getattr(fh, 'flush', None)
            if callable(flush_fn):
                flush_fn()
        except Exception:
            pass
        self.proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=fh, stderr=subprocess.PIPE)
        if self.proc.stdin is None:
            raise RuntimeError('pigz stdin was not opened')
        self.stdin = self.proc.stdin
        self.cmd = cmd

    def write(self, data: bytes | bytearray | memoryview) -> int:
        if self.stdin.closed:
            raise RuntimeError('Cannot write to closed pigz payload stream')
        written = self.stdin.write(data)
        return int(0 if written is None else written)

    def close(self) -> None:
        if self.proc.stdin is not None and not self.proc.stdin.closed:
            try:
                self.proc.stdin.close()
            except Exception:
                pass
        self.proc.stdin = None  # type: ignore[assignment]
        _out, err = self.proc.communicate()
        if self.proc.returncode not in (0, None):
            msg = err.decode('utf-8', errors='ignore') if isinstance(err, (bytes, bytearray)) else str(err)
            raise RuntimeError(f'pigz NRRD payload compression failed: {msg}')

    def __enter__(self) -> '_PigzPayloadWriter':
        return self

    def __exit__(self, exc_type: object, exc: object, tb: object) -> None:
        if exc_type is None:
            self.close()
        else:
            try:
                if self.proc.stdin is not None and not self.proc.stdin.closed:
                    self.proc.stdin.close()
            except Exception:
                pass
            try:
                self.proc.kill()
            except Exception:
                pass
            try:
                self.proc.wait(timeout=5)
            except Exception:
                pass


def _open_pigz_payload_writer(fh: object, *, threads: Optional[int] = None) -> _PigzPayloadWriter:
    return _PigzPayloadWriter(fh, threads=threads)


# --------------------------
# v13.3.3 (S4): in-process parallel gzip for NRRD payloads
# --------------------------
# The pigz pipe capped every layer write at what ONE feeder thread can push through a 64 KiB
# kernel pipe, regardless of pigz's thread count, and burned a subprocess + ~GBs of pipe
# copying per file. This replaces it with pigz's own framing done in-process: fixed-size chunks
# are raw-deflated concurrently on one shared pool (deflate releases the GIL in both zlib and
# python-isal), each chunk ends on a byte-aligned Z_FULL_FLUSH boundary, and the chunks are
# concatenated into a single standard gzip member whose trailer CRC is assembled with
# crc32_combine. All-zero chunks (empty slices and margins dominate these mask volumes) are
# served from a tiny cache of precompressed blocks — no deflate, no CRC pass.
# python-isal (pip install isal) is picked up automatically for a further ~3-5x deflate
# speedup; plain zlib is the fallback. YOLO_TTA_NRRD_INPROCESS_GZIP=0 restores the pigz pipe.


def nrrd_inprocess_gzip_enabled() -> bool:
    return _env_flag('YOLO_TTA_NRRD_INPROCESS_GZIP', True)


def nrrd_gzip_workers() -> int:
    """Size of the shared in-process deflate pool (all concurrent layer writes share it)."""
    cores = max(1, _cpu_count())
    return max(2, _env_int('YOLO_TTA_NRRD_GZIP_WORKERS', max(4, cores // 2)))


def nrrd_gzip_chunk_bytes() -> int:
    return max(1, _env_int('YOLO_TTA_NRRD_GZIP_CHUNK_MIB', 16)) * 1024 * 1024


_NRRD_GZIP_EXECUTOR: Optional[ThreadPoolExecutor] = None
_NRRD_GZIP_EXECUTOR_LOCK = threading.Lock()


def _nrrd_gzip_executor() -> ThreadPoolExecutor:
    global _NRRD_GZIP_EXECUTOR
    with _NRRD_GZIP_EXECUTOR_LOCK:
        if _NRRD_GZIP_EXECUTOR is None:
            _NRRD_GZIP_EXECUTOR = ThreadPoolExecutor(
                max_workers=int(nrrd_gzip_workers()), thread_name_prefix='nrrd-gzip',
            )
        return _NRRD_GZIP_EXECUTOR


def _nrrd_deflate_backend() -> Tuple[str, Callable[[], object], Callable[..., int], int, int]:
    """Return (name, compressobj_factory, crc32_fn, full_flush_const, effective_level).

    python-isal exposes the zlib API at ISA-L speed but only levels 0-3 on its own scale;
    the configured deflate level (nrrd_pigz_compresslevel, 0-9) is mapped onto it and
    YOLO_TTA_NRRD_ISAL_LEVEL overrides the mapping.
    """
    level = int(nrrd_pigz_compresslevel())
    try:
        from isal import isal_zlib  # type: ignore

        isal_level = 0 if level <= 0 else (1 if level <= 4 else (2 if level <= 7 else 3))
        isal_level = int(np.clip(_env_int('YOLO_TTA_NRRD_ISAL_LEVEL', isal_level), 0, 3))
        full_flush = int(getattr(isal_zlib, 'Z_FULL_FLUSH', zlib.Z_FULL_FLUSH))

        def _make_isal() -> object:
            return isal_zlib.compressobj(isal_level, isal_zlib.DEFLATED, -15)

        return 'isal', _make_isal, isal_zlib.crc32, full_flush, int(isal_level)
    except Exception:
        def _make_zlib() -> object:
            return zlib.compressobj(level, zlib.DEFLATED, -15)

        return 'zlib', _make_zlib, zlib.crc32, int(zlib.Z_FULL_FLUSH), int(level)


def _gf2_matrix_times(mat: List[int], vec: int) -> int:
    total = 0
    idx = 0
    while vec:
        if vec & 1:
            total ^= mat[idx]
        vec >>= 1
        idx += 1
    return total


def _gf2_matrix_square(square: List[int], mat: List[int]) -> None:
    for n in range(32):
        square[n] = _gf2_matrix_times(mat, mat[n])


def _crc32_combine(crc1: int, crc2: int, len2: int) -> int:
    """Combine CRC-32s of two concatenated byte ranges (port of zlib's crc32_combine)."""
    if int(len2) <= 0:
        return int(crc1) & 0xFFFFFFFF
    even: List[int] = [0] * 32
    odd: List[int] = [0] * 32
    odd[0] = 0xEDB88320  # CRC-32 polynomial, reflected
    row = 1
    for n in range(1, 32):
        odd[n] = row
        row <<= 1
    _gf2_matrix_square(even, odd)
    _gf2_matrix_square(odd, even)
    crc1 = int(crc1) & 0xFFFFFFFF
    crc2 = int(crc2) & 0xFFFFFFFF
    n2 = int(len2)
    while True:
        _gf2_matrix_square(even, odd)
        if n2 & 1:
            crc1 = _gf2_matrix_times(even, crc1)
        n2 >>= 1
        if n2 == 0:
            break
        _gf2_matrix_square(odd, even)
        if n2 & 1:
            crc1 = _gf2_matrix_times(odd, crc1)
        n2 >>= 1
        if n2 == 0:
            break
    return (crc1 ^ crc2) & 0xFFFFFFFF


# Cache of deflated all-zero chunks keyed by (backend, level, byte length): the compressed
# bytes AND the CRC of a zero run are pure functions of the length.
_NRRD_GZIP_ZERO_CACHE: Dict[Tuple[str, int, int], Tuple[bytes, int]] = {}
_NRRD_GZIP_ZERO_CACHE_LOCK = threading.Lock()


class _ParallelGzipPayloadWriter:
    """File-like gzip encoder compressing NRRD payload chunks in parallel, in process.

    ``write(data)`` returns only after every chunk of the call is compressed and appended to
    the output file, so callers may immediately reuse the buffer behind ``data`` — the same
    contract as the blocking pigz pipe write it replaces.
    """

    GZIP_HEADER = b'\x1f\x8b\x08\x00\x00\x00\x00\x00\x00\x03'  # deflate, no name/mtime, unix

    def __init__(self, fh: object, *, chunk_bytes: Optional[int] = None) -> None:
        backend, factory, crc_fn, full_flush, eff_level = _nrrd_deflate_backend()
        self.fh = fh
        self.backend = str(backend)
        self.factory = factory
        self.crc_fn = crc_fn
        self.full_flush = int(full_flush)
        self.eff_level = int(eff_level)
        self.chunk_bytes = int(chunk_bytes) if chunk_bytes else int(nrrd_gzip_chunk_bytes())
        self.crc = 0
        self.isize = 0
        self.closed = False
        self.fh.write(self.GZIP_HEADER)

    def _compress_chunk(self, mv: memoryview) -> Tuple[bytes, int, int]:
        ln = len(mv)
        arr = np.frombuffer(mv, dtype=np.uint8)
        if not arr.any():
            key = (self.backend, self.eff_level, int(ln))
            with _NRRD_GZIP_ZERO_CACHE_LOCK:
                cached = _NRRD_GZIP_ZERO_CACHE.get(key)
            if cached is None:
                cobj = self.factory()
                comp = cobj.compress(mv) + cobj.flush(self.full_flush)
                cached = (bytes(comp), int(self.crc_fn(mv)) & 0xFFFFFFFF)
                with _NRRD_GZIP_ZERO_CACHE_LOCK:
                    _NRRD_GZIP_ZERO_CACHE[key] = cached
            return cached[0], cached[1], int(ln)
        cobj = self.factory()
        comp = cobj.compress(mv) + cobj.flush(self.full_flush)
        return comp, int(self.crc_fn(mv)) & 0xFFFFFFFF, int(ln)

    def write(self, data: bytes | bytearray | memoryview) -> int:
        if self.closed:
            raise RuntimeError('Cannot write to a closed gzip payload stream')
        mv = data if isinstance(data, memoryview) else memoryview(data)
        mv = mv.cast('B')
        total = len(mv)
        if total <= 0:
            return 0
        executor = _nrrd_gzip_executor()
        futures = [
            executor.submit(self._compress_chunk, mv[off:off + self.chunk_bytes])
            for off in range(0, total, self.chunk_bytes)
        ]
        for fut in futures:
            comp, crc, ln = fut.result()
            self.fh.write(comp)
            self.crc = _crc32_combine(self.crc, int(crc), int(ln))
            self.isize = (self.isize + int(ln)) & 0xFFFFFFFF
        return int(total)

    def close(self) -> None:
        if self.closed:
            return
        self.closed = True
        # Terminate the single deflate stream with an empty FINAL static-huffman block (the
        # same termination pigz emits after its full-flushed chunks), then the gzip trailer.
        self.fh.write(b'\x03\x00')
        self.fh.write(struct.pack('<II', self.crc & 0xFFFFFFFF, self.isize & 0xFFFFFFFF))

    def __enter__(self) -> '_ParallelGzipPayloadWriter':
        return self

    def __exit__(self, exc_type: object, exc: object, tb: object) -> None:
        if exc_type is None:
            self.close()
        else:
            self.closed = True  # broken stream: do not emit a trailer over partial output


_NRRD_INPROCESS_GZIP_OK: Optional[bool] = None
_NRRD_INPROCESS_GZIP_TEST_LOCK = threading.Lock()


def _nrrd_inprocess_gzip_self_test() -> bool:
    """One-time end-to-end validation (framing + CRC combine + zero cache + backend flush).

    Failure of any part quietly reverts every NRRD payload write to the pigz pipe, so a
    surprising isal/zlib build can never produce corrupt output.
    """
    global _NRRD_INPROCESS_GZIP_OK
    if _NRRD_INPROCESS_GZIP_OK is not None:
        return bool(_NRRD_INPROCESS_GZIP_OK)
    with _NRRD_INPROCESS_GZIP_TEST_LOCK:
        if _NRRD_INPROCESS_GZIP_OK is not None:
            return bool(_NRRD_INPROCESS_GZIP_OK)
        try:
            import gzip as _gzip
            part_a = bytes(range(256)) * 41 + b'\x00' * 3000  # spans chunk boundaries
            part_b = b'\x00' * 8192                            # exercises the zero cache
            part_c = b'nrrd-inprocess-gzip-self-test' * 99
            sink = io.BytesIO()
            writer = _ParallelGzipPayloadWriter(sink, chunk_bytes=4096)
            writer.write(part_a)
            writer.write(part_b)
            writer.write(part_c)
            writer.close()
            _NRRD_INPROCESS_GZIP_OK = bool(_gzip.decompress(sink.getvalue()) == part_a + part_b + part_c)
        except Exception:
            _NRRD_INPROCESS_GZIP_OK = False
        if not _NRRD_INPROCESS_GZIP_OK:
            print('Warning: in-process NRRD gzip self-test failed; using the pigz pipe for NRRD payloads.')
        return bool(_NRRD_INPROCESS_GZIP_OK)


def _open_nrrd_payload_writer(fh: object, *, threads: Optional[int] = None) -> object:
    """v13.3.3 (S4): in-process parallel gzip when enabled and validated, else the pigz pipe."""
    if nrrd_inprocess_gzip_enabled() and _nrrd_inprocess_gzip_self_test():
        return _ParallelGzipPayloadWriter(fh)
    return _PigzPayloadWriter(fh, threads=threads)

def _madvise_array_mmap(arr: object, advice_name: str) -> None:
    try:
        import mmap as _mmap_module  # local import so non-POSIX platforms remain unaffected
        advice = getattr(_mmap_module, str(advice_name), None)
        if advice is None:
            return
        mmap_obj = getattr(arr, '_mmap', None)
        if mmap_obj is None:
            base = getattr(arr, 'base', None)
            mmap_obj = getattr(base, '_mmap', None)
        madvise_fn = getattr(mmap_obj, 'madvise', None)
        if callable(madvise_fn):
            madvise_fn(advice)
    except Exception:
        pass


def _nrrd_float_text(value: float) -> str:
    value_f = float(value)
    if math.isnan(value_f):
        return 'none'
    if math.isinf(value_f):
        return 'inf' if value_f > 0 else '-inf'
    return f'{value_f:.17g}'


def _nrrd_vector_text(values: Sequence[object]) -> str:
    return '(' + ','.join(_nrrd_float_text(float(v)) for v in values) + ')'


def _nrrd_space_directions_text(value: object) -> str:
    arr = np.asarray(value, dtype=np.float64)
    if arr.ndim == 1:
        return _nrrd_vector_text(arr.tolist())
    if arr.ndim != 2:
        raise ValueError(f'NRRD space directions must be 1D or 2D, got shape {arr.shape}')
    parts: List[str] = []
    for row in arr:
        if np.all(np.isnan(row)):
            parts.append('none')
        else:
            parts.append(_nrrd_vector_text(row.tolist()))
    return ' '.join(parts)


def _nrrd_header_value_text(key: str, value: object) -> str:
    key_l = str(key).strip().lower()
    if key_l == 'space directions':
        return _nrrd_space_directions_text(value)
    if key_l in {'space origin', 'measurement frame'}:
        arr = np.asarray(value, dtype=np.float64)
        if arr.ndim == 1:
            return _nrrd_vector_text(arr.tolist())
    if isinstance(value, np.ndarray):
        arr = value
        if arr.ndim == 1:
            return ' '.join(_nrrd_float_text(float(v)) for v in arr.tolist())
        return ' '.join(_nrrd_vector_text(row) for row in arr.tolist())
    if isinstance(value, (list, tuple)):
        return ' '.join(_nrrd_ascii_header_text(v) for v in value)
    if isinstance(value, bool):
        return 'true' if value else 'false'
    return _nrrd_ascii_header_text(value).replace('\n', ' ').replace('\r', ' ')


_NRRD_STANDARD_FIELDS = {
    'type', 'dimension', 'sizes', 'spacings', 'thicknesses', 'axis mins', 'axis maxs',
    'centers', 'labels', 'units', 'min', 'max', 'old min', 'old max', 'endian',
    'encoding', 'line skip', 'byte skip', 'data file', 'content', 'sample units',
    'space', 'space dimension', 'space units', 'space origin', 'space directions',
    'measurement frame', 'kinds', 'block size',
}


def _nrrd_field_separator(key: str) -> str:
    return ':' if str(key).strip().lower() in _NRRD_STANDARD_FIELDS else ':='


def _write_nrrd_ascii_header(
    fh: object,
    *,
    header: Dict[str, object],
    sizes: Sequence[int],
    dimension: int,
    data_type: str = 'uint8',
    encoding: str = 'gzip',
) -> None:
    header_copy: Dict[str, object] = dict(header)
    for reserved in ('type', 'dimension', 'sizes'):
        header_copy.pop(reserved, None)
    header_copy['encoding'] = str(encoding)

    standard_order = [
        'space', 'space dimension', 'kinds', 'space directions', 'space origin',
        'measurement frame', 'content', 'encoding', 'endian',
    ]

    lines: List[str] = [
        'NRRD0005',
        '# Complete NRRD file generated by Fable-5_v13.2.5_SLURM.py',
        f'type: {str(data_type)}',
        f'dimension: {int(dimension)}',
        'sizes: ' + ' '.join(str(int(v)) for v in sizes),
    ]

    emitted: set[str] = set()
    for key in standard_order:
        if key in header_copy:
            lines.append(f'{key}: {_nrrd_header_value_text(key, header_copy[key])}')
            emitted.add(key)

    for key, value in header_copy.items():
        if key in emitted or key in {'type', 'dimension', 'sizes'}:
            continue
        sep = _nrrd_field_separator(str(key))
        value_text = _nrrd_header_value_text(str(key), value)
        if sep == ':=':
            lines.append(f'{str(key)}{sep}{value_text}')
        else:
            lines.append(f'{str(key)}{sep} {value_text}')

    text = '\n'.join(lines) + '\n\n'
    fh.write(text.encode('ascii', errors='ignore'))


def nrrd_layer_output_suffix(
    *,
    view_token: str,
    source: str,
    mask_kind: str,
    pass_index: int = 0,
    tile_acceptance: str = '',
    stage: str = '',
) -> str:
    """Return the v13.2.0 single-layer NRRD filename suffix for one component layer.

    The decomposition is now one single-layer NRRD per component layer (spec 7), named
    ``{Filestem}_{suffix}.seg.nrrd`` with the model name dropped (a model-ensemble holdover).
    """
    source_l = str(source).strip().lower()
    mask_kind_l = str(mask_kind).strip().lower()
    stage_l = str(stage).strip().lower()
    if source_l == 'global':
        if stage_l.startswith('final_output'):
            return 'Global_final_output'
        if mask_kind_l == 'smoothing_result':
            return f'Global_smoothing_pass{int(pass_index):02d}'
        return 'Global_union_presmoothing'
    vt = _sanitize_nrrd_layer_token(view_token) or 'view'
    if source_l == 'fullframe':
        if mask_kind_l == 'bridge':
            return f'{vt}_fullframe_bridge_pass{int(pass_index):02d}'
        return f'{vt}_fullframe_yolo'
    if source_l == 'tile':
        if mask_kind_l == 'bridge':
            return f'{vt}_tile_bridge_pass{int(pass_index):02d}'
        acceptance = _sanitize_nrrd_layer_token(tile_acceptance) or 'parent_support'
        return f'{vt}_tile_yolo_{acceptance}'
    parts = [vt, source_l or 'layer', mask_kind_l or 'mask']
    if int(pass_index) > 0:
        parts.append(f'pass{int(pass_index):02d}')
    if tile_acceptance:
        parts.append(_sanitize_nrrd_layer_token(tile_acceptance))
    return '_'.join(p for p in parts if p)


def write_single_layer_nrrd_from_ref(
    ref: 'NrrdLayerRef',
    output_shape: Tuple[int, int, int],
    out_path: Path,
    *,
    pigz_threads: Optional[int] = None,
    segment_name: Optional[str] = None,
    segment_color: Optional[Tuple[float, float, float]] = None,
    block_consumer: Optional[Callable[[int, np.ndarray], None]] = None,
) -> Path:
    """Write one component layer as its own single-layer 3D Slicer segmentation NRRD (X, Y, t).

    The layer is restored from its backing-store geometry directly to the final output
    geometry while streaming, reusing the same per-layer restore/stream path as the legacy
    decomposed writer.  Each file holds one uint8 binary mask, fits in RAM, and is gzip
    compressed in one pigz pass.  v13.2.3 tags the header with the 3D Slicer segmentation
    fields so the .seg.nrrd imports as a Segmentation node; segment_name defaults to the
    output filename stem and segment_color to the deterministic palette pick for that name.
    """
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_t, out_h, out_w = (int(output_shape[0]), int(output_shape[1]), int(output_shape[2]))
    header = nrrd_slicer_header((out_t, out_h, out_w))
    seg_name = str(segment_name) if segment_name else _slicer_segment_name_for_out_path(out_path)
    seg_color = segment_color if segment_color is not None else slicer_segment_palette_color(seg_name)
    header.update(slicer_segmentation_header_fields(
        segment_name=seg_name,
        color_rgb=seg_color,
        extent_xyt=_slicer_segment_extent_for_output(ref, (out_t, out_h, out_w)),
    ))
    z_chunk = _nrrd_full_slice_z_chunk(1, out_w, out_h, out_t)
    threads = int(nrrd_single_layer_pigz_threads()) if pigz_threads is None else max(1, int(pigz_threads))
    with open(out_path, 'wb') as fh:
        _write_nrrd_ascii_header(
            fh,
            header=header,
            sizes=(out_w, out_h, out_t),
            dimension=3,
            data_type='unsigned char',
            encoding='gzip',
        )
        # v13.3.3 (S4): in-process parallel gzip by default (pigz pipe as validated fallback).
        with _open_nrrd_payload_writer(fh, threads=threads) as payload_writer:
            _write_one_decomposed_nrrd_layer_payload(
                ref,
                (out_t, out_h, out_w),
                payload_writer,
                z_chunk=int(z_chunk),
                block_consumer=block_consumer,
            )
    return out_path


def write_layer_nrrd_with_low_quality_mirrors(
    ref: 'NrrdLayerRef',
    output_shape: Tuple[int, int, int],
    out_path: Path,
    mirrors: Sequence[Tuple[Tuple[int, int, int], Path]],
    *,
    pigz_threads: Optional[int] = None,
    segment_name: Optional[str] = None,
    segment_color: Optional[Tuple[float, float, float]] = None,
) -> Path:
    """v13.3.3 (S4): write the full-quality layer AND its low-quality mirrors in ONE pass.

    Each low-quality mirror used to be an independent write that re-decoded the full-resolution
    layer store per output slice (3-4 full-res decodes + INTER_AREA resizes per slice, per
    downbin spec). Here the full-quality write streams exactly as before, and every payload
    block is additionally folded into small in-RAM mirror volumes (one resize per full-res
    slice per spec, OR'd into the covering mirror slices — the same resize helper and union
    semantics as the legacy per-mirror reader, composed through the output geometry, so bin-edge
    voxels may differ sub-slice from the legacy double-resample). The mirror files are then
    gzip-encoded straight from RAM. Any tee failure falls back to the legacy per-mirror writer
    so the full-quality file is never at risk.
    """
    out_t = int(output_shape[0])
    mirror_jobs: List[Dict[str, object]] = []
    for m_shape, m_path in mirrors:
        m_t, m_h, m_w = (int(m_shape[0]), int(m_shape[1]), int(m_shape[2]))
        # Invert the mirror's t mapping once: for each full-quality output z, the mirror
        # slice(s) whose source range contains it (matches _restore_source_indices_for_output_z).
        tmp: List[List[int]] = [[] for _ in range(out_t)]
        for mz in range(m_t):
            for sz in _restore_source_indices_for_output_z(out_t, m_t, int(mz)):
                if 0 <= int(sz) < out_t:
                    tmp[int(sz)].append(int(mz))
        mirror_jobs.append({
            'shape': (m_t, m_h, m_w),
            'path': Path(m_path),
            'volume': np.zeros((m_t, m_h, m_w), dtype=np.uint8),
            'src_to_m': [tuple(v) for v in tmp],
            'locks': [threading.Lock() for _ in range(16)],
            'failed': False,
        })

    tee_workers = max(1, min(int(nrrd_fill_workers()), 16))

    def _tee(z0: int, block: np.ndarray) -> None:
        live_jobs = [j for j in mirror_jobs if not bool(j['failed'])]
        if not live_jobs:
            return
        z_count = int(block.shape[0])

        def _tee_one(zi: int) -> None:
            full_z = int(z0) + int(zi)
            if full_z >= out_t:
                return
            frame = block[int(zi)]
            for job in live_jobs:
                if bool(job['failed']):
                    continue
                try:
                    targets = job['src_to_m'][full_z]
                    if not targets:
                        continue
                    m_t, m_h, m_w = job['shape']  # type: ignore[misc]
                    resized = _resize_binary_mask_frame_to_output_shape(frame, int(m_h), int(m_w))
                    vol = job['volume']
                    locks = job['locks']
                    for mz in targets:
                        # Adjacent full-z frames can map to the same mirror slice; stripe locks
                        # keep the read-modify-write OR race-free without serializing the block.
                        with locks[int(mz) % len(locks)]:  # type: ignore[index]
                            np.bitwise_or(vol[int(mz)], resized, out=vol[int(mz)])  # type: ignore[index]
                except Exception:
                    job['failed'] = True

        if z_count > 1 and tee_workers > 1:
            parallel_for_indices_chunked(
                z_count, _tee_one, max_workers=tee_workers, desc='', show_progress=False,
                target_chunks_per_worker=1,
            )
        else:
            for zi in range(z_count):
                _tee_one(int(zi))

    result = write_single_layer_nrrd_from_ref(
        ref, output_shape, out_path,
        pigz_threads=pigz_threads, segment_name=segment_name, segment_color=segment_color,
        block_consumer=(_tee if mirror_jobs else None),
    )

    for job in mirror_jobs:
        m_t, m_h, m_w = job['shape']  # type: ignore[misc]
        m_path: Path = job['path']  # type: ignore[assignment]
        try:
            if bool(job['failed']):
                raise RuntimeError('mirror tee failed during full-quality streaming')
            m_path.parent.mkdir(parents=True, exist_ok=True)
            header = nrrd_slicer_header((int(m_t), int(m_h), int(m_w)))
            seg_name = str(segment_name) if segment_name else _slicer_segment_name_for_out_path(m_path)
            seg_color = segment_color if segment_color is not None else slicer_segment_palette_color(seg_name)
            header.update(slicer_segmentation_header_fields(
                segment_name=seg_name,
                color_rgb=seg_color,
                extent_xyt=_slicer_segment_extent_for_output(ref, (int(m_t), int(m_h), int(m_w))),
            ))
            vol: np.ndarray = job['volume']  # type: ignore[assignment]
            step = max(1, int(_nrrd_full_slice_z_chunk(1, int(m_w), int(m_h), int(m_t))))
            with open(m_path, 'wb') as fh:
                _write_nrrd_ascii_header(
                    fh, header=header, sizes=(int(m_w), int(m_h), int(m_t)),
                    dimension=3, data_type='unsigned char', encoding='gzip',
                )
                with _open_nrrd_payload_writer(fh, threads=pigz_threads) as payload_writer:
                    for z0 in range(0, int(m_t), step):
                        z1 = min(int(m_t), int(z0) + step)
                        payload_writer.write(memoryview(vol[z0:z1]).cast('B'))
        except Exception as exc:
            print(
                f'Warning: low-quality NRRD mirror tee failed for {m_path.name} ({exc}); '
                're-encoding that mirror from the layer store.'
            )
            write_single_layer_nrrd_from_ref(
                ref, (int(m_t), int(m_h), int(m_w)), m_path,
                pigz_threads=pigz_threads, segment_name=segment_name, segment_color=segment_color,
            )
        finally:
            job['volume'] = None
    return result


class NrrdLayerSink:
    """Writes one single-layer NRRD per component layer as the layers are produced.

    v13.2.0 reworks ``--save_nrrd`` from one mega 4D decomposed NRRD assembled at the very
    end into a set of small single-layer NRRDs created during the intermediate pipeline
    steps (e.g. the Transverse layer NRRD is compressed while Tiled Transverse is still being
    inferenced).  Layers are submitted from whichever background postprocess/interpolation
    thread produced them, written on a small dedicated pool so the writes overlap inference
    and each other, and recorded in one sidecar manifest.
    """

    def __init__(
        self,
        *,
        nrrd_dir: Path,
        stem: str,
        output_shape_tyx: Tuple[int, int, int],
        max_workers: int,
        pigz_threads: int,
        low_quality_specs: Optional[Sequence['LowQualityDownbinSpec']] = None,
        low_quality_root: Optional[Path] = None,
    ) -> None:
        self.nrrd_dir = Path(nrrd_dir)
        self.nrrd_dir.mkdir(parents=True, exist_ok=True)
        self.stem = str(stem)
        self.output_shape = (int(output_shape_tyx[0]), int(output_shape_tyx[1]), int(output_shape_tyx[2]))
        self.pigz_threads = max(1, int(pigz_threads))
        self.executor = ThreadPoolExecutor(max_workers=max(1, int(max_workers)), thread_name_prefix='nrrd-layer')
        self._lock = threading.Lock()
        self._futures: List[Future] = []
        self._manifest: List[Dict[str, object]] = []
        self._suffix_counts: Dict[str, int] = {}
        # v13.2.3: Slicer segment colors already assigned in this run, so two layers whose
        # suffix hashes collide still render distinctly (deterministic forward probing).
        self._segment_colors_in_use: set = set()
        # v13.2.1: low-quality NRRDs now mirror the full-quality decomposition instead of being one
        # combined volume written at the tail.  Each downbin spec gets its own
        # one-single-layer-NRRD-per-component decomposition under low_quality/<token>/nrrd/, restored
        # from the same NrrdLayerRef and submitted here as each view completes (identical scheduling).
        self.low_quality_specs: List['LowQualityDownbinSpec'] = list(low_quality_specs or [])
        self.low_quality_root = Path(low_quality_root) if low_quality_root is not None else None
        self._lq_manifests: Dict[str, List[Dict[str, object]]] = {}
        if self.low_quality_specs and self.low_quality_root is not None:
            for spec in self.low_quality_specs:
                self._lq_nrrd_dir(spec).mkdir(parents=True, exist_ok=True)

    def _lq_nrrd_dir(self, spec: 'LowQualityDownbinSpec') -> Path:
        if self.low_quality_root is None:
            raise RuntimeError('low-quality NRRD directory requested without a low_quality_root')
        return self.low_quality_root / str(spec.token) / 'nrrd'

    def _segment_color_for_suffix(self, unique_suffix: str) -> Tuple[float, float, float]:
        # Called with self._lock held. Deterministic palette pick keyed off the layer suffix
        # (stable across runs), probing forward past colors already used this run; beyond the
        # palette size, a golden-ratio HSV walk keeps every additional layer distinct.
        palette = _SLICER_SEGMENT_COLOR_PALETTE
        base = _stable_layer_color_index(str(unique_suffix))
        for probe in range(len(palette)):
            color = palette[(base + probe) % len(palette)]
            if color not in self._segment_colors_in_use:
                self._segment_colors_in_use.add(color)
                return color
        hue = (float(base % 4096) / 4096.0 + 0.61803398875 * float(len(self._segment_colors_in_use))) % 1.0
        r, g, b = colorsys.hsv_to_rgb(hue, 0.72, 0.88)
        color = (round(float(r), 6), round(float(g), 6), round(float(b), 6))
        self._segment_colors_in_use.add(color)
        return color

    def submit_layer(self, ref: Optional['NrrdLayerRef'], suffix: str) -> Optional[Path]:
        if ref is None:
            return None
        with self._lock:
            seen = int(self._suffix_counts.get(str(suffix), 0))
            self._suffix_counts[str(suffix)] = seen + 1
            unique_suffix = str(suffix) if seen == 0 else f'{suffix}_{seen + 1:02d}'
            # v13.2.3: .seg.nrrd + Slicer segmentation header fields; the segment is named
            # after the file and colored from the deterministic per-suffix palette.
            out_path = self.nrrd_dir / f'{self.stem}_{unique_suffix}.seg.nrrd'
            segment_name = f'{self.stem}_{unique_suffix}'
            segment_color = self._segment_color_for_suffix(unique_suffix)
            self._manifest.append({
                'filename': out_path.name,
                'suffix': unique_suffix,
                'view_name': getattr(ref, 'view_name', ''),
                'view_family': getattr(ref, 'view_family', ''),
                'source': getattr(ref, 'source', ''),
                'mask_kind': getattr(ref, 'mask_kind', ''),
                'pass_index': int(getattr(ref, 'pass_index', 0)),
                'tile_acceptance': getattr(ref, 'tile_acceptance', ''),
                'stage': getattr(ref, 'stage', ''),
                'description': getattr(ref, 'description', ''),
                'backing_shape_tyx': [int(v) for v in getattr(ref, 'shape', (0, 0, 0))],
                'output_shape_tyx': [int(v) for v in self.output_shape],
                'exported_axes': '(X, Y, t)',
                'segment_name': segment_name,
                'segment_color_rgb': [round(float(c), 6) for c in segment_color],
            })
            # v13.2.1: mirror this component layer into each low-quality downbin decomposition,
            # scheduled now (as the view completes) exactly like the full-quality layer and sharing
            # the same unique suffix so a low-quality layer maps 1:1 to its full-quality layer.
            # v13.3.3 (S4): the mirrors are derived from the full-quality payload blocks inside ONE
            # combined write task (write_layer_nrrd_with_low_quality_mirrors) instead of each
            # re-decoding the full-resolution layer store as an independent task.
            lq_mirror_args: List[Tuple[Tuple[int, int, int], Path]] = []
            for spec in self.low_quality_specs:
                if self.low_quality_root is None:
                    break
                lq_shape = (
                    int(spec.output_shape_t_y_x[0]),
                    int(spec.output_shape_t_y_x[1]),
                    int(spec.output_shape_t_y_x[2]),
                )
                lq_path = self._lq_nrrd_dir(spec) / f'{self.stem}_{unique_suffix}.seg.nrrd'
                lq_mirror_args.append((lq_shape, lq_path))
                self._lq_manifests.setdefault(str(spec.token), []).append({
                    'filename': lq_path.name,
                    'suffix': unique_suffix,
                    'view_name': getattr(ref, 'view_name', ''),
                    'view_family': getattr(ref, 'view_family', ''),
                    'source': getattr(ref, 'source', ''),
                    'mask_kind': getattr(ref, 'mask_kind', ''),
                    'pass_index': int(getattr(ref, 'pass_index', 0)),
                    'tile_acceptance': getattr(ref, 'tile_acceptance', ''),
                    'stage': getattr(ref, 'stage', ''),
                    'description': getattr(ref, 'description', ''),
                    'backing_shape_tyx': [int(v) for v in getattr(ref, 'shape', (0, 0, 0))],
                    'output_shape_tyx': [int(v) for v in lq_shape],
                    'downbin_value': str(spec.raw_value),
                    'downbin_token': str(spec.token),
                    'downbin_scale': float(spec.scale),
                    'exported_axes': '(X, Y, t)',
                    'segment_name': segment_name,
                    'segment_color_rgb': [round(float(c), 6) for c in segment_color],
                })
            if lq_mirror_args:
                fut = self.executor.submit(
                    write_layer_nrrd_with_low_quality_mirrors, ref, self.output_shape, out_path,
                    lq_mirror_args,
                    pigz_threads=self.pigz_threads, segment_name=segment_name, segment_color=segment_color,
                )
            else:
                fut = self.executor.submit(
                    write_single_layer_nrrd_from_ref, ref, self.output_shape, out_path,
                    pigz_threads=self.pigz_threads, segment_name=segment_name, segment_color=segment_color,
                )
            self._futures.append(fut)
        return out_path

    def layer_count(self) -> int:
        with self._lock:
            return len(self._manifest)

    def low_quality_layer_count(self) -> int:
        with self._lock:
            return int(sum(len(entries) for entries in self._lq_manifests.values()))

    def wait(self) -> None:
        with self._lock:
            futures = list(self._futures)
        first_error: Optional[BaseException] = None
        for fut in futures:
            try:
                fut.result()
            except BaseException as exc:  # pragma: no cover - surfaced to main
                if first_error is None:
                    first_error = exc
        if first_error is not None:
            raise RuntimeError('Single-layer NRRD writing failed') from first_error

    def shutdown(self) -> None:
        self.executor.shutdown(wait=True)

    def write_manifest(self) -> Optional[Path]:
        with self._lock:
            manifest_layers = list(self._manifest)
            lq_manifests = {token: list(entries) for token, entries in self._lq_manifests.items()}
        # v13.2.1: one manifest per low-quality downbin decomposition, mirroring the full-quality
        # sidecar so each low-quality nrrd/ folder is self-describing and recomposable on its own.
        if self.low_quality_root is not None:
            for spec in self.low_quality_specs:
                entries = lq_manifests.get(str(spec.token), [])
                if not entries:
                    continue
                lq_shape = (
                    int(spec.output_shape_t_y_x[0]),
                    int(spec.output_shape_t_y_x[1]),
                    int(spec.output_shape_t_y_x[2]),
                )
                lq_manifest_path = self._lq_nrrd_dir(spec) / f'{self.stem}_nrrd_manifest.json'
                lq_manifest_path.write_text(json.dumps({
                    'layout': 'one_single_layer_nrrd_per_component',
                    'quality': 'low_quality',
                    'downbin_value': str(spec.raw_value),
                    'downbin_token': str(spec.token),
                    'downbin_scale': float(spec.scale),
                    'exported_axes': '(X, Y, t)',
                    'output_shape_tyx': [int(v) for v in lq_shape],
                    'full_quality_output_shape_tyx': [int(v) for v in self.output_shape],
                    'layer_count': len(entries),
                    'layers': entries,
                    'notes': [
                        'Low-quality distribution decomposition: the same component layers as the full-quality '
                        'nrrd/ folder, isotropically downbinned to this spec and written as each view completes.',
                        'Each NRRD is one uint8 binary mask in source output geometry (X, Y, t), downbinned.',
                        'v13.2.3: each file is a 3D Slicer segmentation (.seg.nrrd) sharing its full-quality layer\'s segment name and color.',
                        'Layer suffixes match the full-quality layers, so each low-quality layer maps 1:1 to its full-quality layer.',
                    ],
                }, indent=2))
        if not manifest_layers:
            return None
        manifest_path = self.nrrd_dir / f'{self.stem}_nrrd_manifest.json'
        manifest = {
            'layout': 'one_single_layer_nrrd_per_component',
            'exported_axes': '(X, Y, t)',
            'output_shape_tyx': [int(v) for v in self.output_shape],
            'layer_count': len(manifest_layers),
            'layers': manifest_layers,
            'notes': [
                'Each NRRD is one uint8 binary mask in source output geometry (X, Y, t).',
                'v13.2.3: each file is a 3D Slicer segmentation (.seg.nrrd) holding one segment named after the file; segment_color_rgb records the assigned Slicer color.',
                'Files can be recombined (union) or omitted after a full run to build a custom volume without rerunning.',
                'YOLO layers are cleaned masks before interpolation bridges; bridge layers contain only voxels added by that pass.',
                'Global_final_output is the final segmentation after all postprocessing and is not intended for recomposition.',
            ],
        }
        manifest_path.write_text(json.dumps(manifest, indent=2))
        return manifest_path


_NRRD_LAYER_SINK: Optional[NrrdLayerSink] = None


def set_nrrd_layer_sink(sink: Optional[NrrdLayerSink]) -> None:
    global _NRRD_LAYER_SINK
    _NRRD_LAYER_SINK = sink


def nrrd_layer_sink() -> Optional[NrrdLayerSink]:
    return _NRRD_LAYER_SINK


def nrrd_layer_sink_workers() -> int:
    # v13.3.3: default cap 4 -> 12. With ~72 queued files (layers x low-quality mirrors) the
    # 4-slot pool left the box near-idle through the whole write tail; most of the write volume
    # lands after inference has drained, so a wider pool is safe.
    cores = max(1, _cpu_count())
    default_workers = max(1, min(12, max(1, cores // 8)))
    return max(1, _env_int('YOLO_TTA_NRRD_LAYER_SINK_WORKERS', int(default_workers)))


def _nrrd_layer_ref_is_raw_bbox_store(ref: NrrdLayerRef) -> bool:
    return str(getattr(ref, 'storage_format', 'raw_u8')) in MASK_STORE_FORMATS or Path(ref.path).is_dir()


def _open_nrrd_layer_ref(ref: NrrdLayerRef) -> object:
    if _nrrd_layer_ref_is_raw_bbox_store(ref):
        return RawBBoxMaskStore.open(
            ref.path,
            cache_payload_in_ram=bool(nrrd_cache_raw_bbox_layers_in_ram_enabled()),
        )
    return np.memmap(
        ref.path,
        dtype=np.dtype(ref.dtype),
        mode='r',
        shape=tuple(int(x) for x in ref.shape),
    )


def _close_nrrd_layer_source(src: object) -> None:
    if isinstance(src, RawBBoxMaskStore):
        src.close()
        return
    close_memmap_array(src)


def _drop_nrrd_raw_store_chunks_ram_cache(src: object) -> None:
    if not isinstance(src, RawBBoxMaskStore):
        return
    # v13.2.2 bug #15: release (refcount) rather than evict — sibling full-quality /
    # low-quality writers for the same layer may still hold the entry.
    if not bool(getattr(src, '_ram_cache_ref_held', False)):
        return
    src._ram_cache_ref_held = False
    _release_raw_store_chunks_ram_cache(src.chunks_path)


def compute_segment_extent_zyx(mask_zyx: np.ndarray) -> Tuple[int, int, int, int, int, int]:
    """Return Slicer SegmentN_Extent as ``minI maxI minJ maxJ minK maxK``.

    The pipeline layer is ``(t,Y,X)``.  The NRRD payload stores that as spatial
    ``(X,Y,t)``, so Slicer I/J/K map to X/Y/t respectively.
    """
    src = np.asarray(mask_zyx)
    if src.ndim != 3:
        raise ValueError(f'compute_segment_extent_zyx expects a 3D (t,Y,X) layer, got {src.shape}')

    t_dim, h_dim, w_dim = (int(src.shape[0]), int(src.shape[1]), int(src.shape[2]))
    min_t, max_t = t_dim, -1
    min_y, max_y = h_dim, -1
    min_x, max_x = w_dim, -1

    for t_idx in range(t_dim):
        sl = np.asarray(src[int(t_idx)], dtype=bool)
        if not np.any(sl):
            continue
        row_has_fg = np.any(sl, axis=1)
        col_has_fg = np.any(sl, axis=0)
        ys = np.flatnonzero(row_has_fg)
        xs = np.flatnonzero(col_has_fg)
        if xs.size <= 0 or ys.size <= 0:
            continue
        min_t = min(min_t, int(t_idx))
        max_t = max(max_t, int(t_idx))
        min_y = min(min_y, int(ys[0]))
        max_y = max(max_y, int(ys[-1]))
        min_x = min(min_x, int(xs[0]))
        max_x = max(max_x, int(xs[-1]))

    if max_t < 0:
        return _nrrd_empty_segment_extent()
    return (int(min_x), int(max_x), int(min_y), int(max_y), int(min_t), int(max_t))


def _restore_source_indices_for_output_z(in_t: int, out_t: int, out_z: int) -> List[int]:
    in_t_i = max(1, int(in_t))
    out_t_i = max(1, int(out_t))
    out_z_i = int(np.clip(int(out_z), 0, out_t_i - 1))
    if in_t_i >= out_t_i:
        src_start = int(math.floor(float(out_z_i) * float(in_t_i) / float(out_t_i)))
        src_stop = int(math.ceil(float(out_z_i + 1) * float(in_t_i) / float(out_t_i)))
        src_start = int(np.clip(src_start, 0, in_t_i - 1))
        src_stop = int(np.clip(max(src_start + 1, src_stop), 1, in_t_i))
        return [int(v) for v in range(src_start, src_stop)]

    src_z = _linear_source_index(out_z_i, out_t_i, in_t_i)
    return [int(np.clip(int(round(src_z)), 0, in_t_i - 1))]


def _resize_binary_mask_frame_to_output_shape(frame: np.ndarray, out_h: int, out_w: int) -> np.ndarray:
    frame_u8 = (np.asarray(frame, dtype=np.uint8) > 0).astype(np.uint8, copy=False)
    if int(frame_u8.shape[0]) == int(out_h) and int(frame_u8.shape[1]) == int(out_w):
        return np.ascontiguousarray(frame_u8)
    interp = cv2.INTER_AREA if (int(frame_u8.shape[0]) >= int(out_h) and int(frame_u8.shape[1]) >= int(out_w)) else cv2.INTER_NEAREST
    scaled = cv2.resize(
        np.ascontiguousarray(frame_u8 * np.uint8(255)),
        (int(out_w), int(out_h)),
        interpolation=int(interp),
    )
    return (scaled > 0).astype(np.uint8, copy=False)


def _read_layer_slice_in_output_shape(
    src: object,
    output_shape: Tuple[int, int, int],
    out_z: int,
) -> np.ndarray:
    """Return one output-geometry ``(Y,X)`` slice for an NRRD layer without materializing the full layer."""
    in_t, in_h, in_w = _volume_shape_tuple(src)
    out_t, out_h, out_w = (int(output_shape[0]), int(output_shape[1]), int(output_shape[2]))
    out_z_i = int(np.clip(int(out_z), 0, out_t - 1))

    if (in_t, in_h, in_w) == (out_t, out_h, out_w):
        return _read_binary_volume_slice_u8(src, out_z_i)

    source_indices = _restore_source_indices_for_output_z(in_t, out_t, out_z_i)
    if in_h == out_h and in_w == out_w:
        if len(source_indices) == 1:
            return _read_binary_volume_slice_u8(src, int(source_indices[0]))
        restored = np.zeros((out_h, out_w), dtype=np.uint8)
        for src_idx in source_indices:
            restored |= _read_binary_volume_slice_bool(src, int(src_idx)).astype(np.uint8, copy=False)
        return restored

    restored = np.zeros((out_h, out_w), dtype=np.uint8)
    for src_idx in source_indices:
        restored |= _resize_binary_mask_frame_to_output_shape(_read_binary_volume_slice_u8(src, int(src_idx)), out_h, out_w)
    return restored


def _write_one_decomposed_nrrd_layer_payload(
    ref: NrrdLayerRef,
    output_shape: Tuple[int, int, int],
    payload_writer: object,
    *,
    z_chunk: int,
    pbar: Optional[object] = None,
    layer_idx: int = 0,
    block_consumer: Optional[Callable[[int, np.ndarray], None]] = None,
) -> None:
    """Write exactly one decomposed NRRD layer payload in native layer order.

    The caller decides whether this layer is appended into an already-open gzip
    stream or into its own gzip member.  In either case the uncompressed bytes for
    one layer are written as native ``(t,Y,X)`` C-order, which matches the NRRD
    attached payload order for sizes ``(X,Y,t,layer)`` when the list axis is last.

    v13.3.3 (S4): ``block_consumer(z0, block)`` (if given) observes every output-geometry
    payload block right after it is materialized — the low-quality mirror tee derives its
    downbinned volumes from these blocks instead of re-decoding the layer store per mirror.
    The consumer must treat the block as read-only and return before reuse; in the
    double-buffered path it runs on the caller thread while the block's compression proceeds
    on the writer thread (both only read).
    """
    out_t, out_h, out_w = (int(output_shape[0]), int(output_shape[1]), int(output_shape[2]))
    z_chunk_i = max(1, int(z_chunk))
    madvise_interval = nrrd_madvise_dontneed_interval()
    src: Optional[object] = None
    try:
        src = _open_nrrd_layer_ref(ref)
        _madvise_array_mmap(src, 'MADV_SEQUENTIAL')
        in_t, in_h, in_w = _volume_shape_tuple(src)
        direct_native_stream = (
            (int(in_t), int(in_h), int(in_w)) == (int(out_t), int(out_h), int(out_w))
            and not isinstance(src, RawBBoxMaskStore)
        )
        raw_store_native_stream = (
            isinstance(src, RawBBoxMaskStore)
            and (int(in_t), int(in_h), int(in_w)) == (int(out_t), int(out_h), int(out_w))
        )

        if bool(direct_native_stream):
            # The memmap is already a native (t,Y,X) C-order layer.  Write chunks of
            # it directly; no transpose, no Fortran conversion, and no layer interleave.
            for z0 in range(0, out_t, int(z_chunk_i)):
                z1 = min(out_t, int(z0) + int(z_chunk_i))
                chunk = np.asarray(src[int(z0):int(z1)], dtype=np.uint8)
                if not chunk.flags['C_CONTIGUOUS']:
                    chunk = np.ascontiguousarray(chunk)
                if block_consumer is not None:
                    block_consumer(int(z0), chunk)
                payload_writer.write(memoryview(chunk).cast('B'))
                if pbar is not None:
                    pbar.update(int(z1 - z0))
                if madvise_interval > 0 and (int(z1) % int(madvise_interval) == 0):
                    _madvise_array_mmap(src, 'MADV_DONTNEED')
            return

        # v13.3.1 (R7b): shared bounded-block streamer — each block is filled by a small
        # GIL-releasing thread pool (store decode memcpys / cv2 restores) and handed to a
        # one-thread writer with double buffering, so decode/restore overlaps the pigz
        # compression instead of a single thread filling the whole payload before pigz starts.
        fill_workers = int(nrrd_fill_workers())

        def _stream_filled_blocks(fill_one: Callable[[int, np.ndarray], None], *, madvise_src: bool) -> None:
            local_z_chunk = int(z_chunk_i)
            buffers: List[np.ndarray] = []
            for _ in range(2):
                try:
                    buffers.append(np.empty((int(local_z_chunk), int(out_h), int(out_w)), dtype=np.uint8, order='C'))
                except MemoryError:
                    break
            if not buffers:
                if int(local_z_chunk) != 1:
                    print(
                        f'Warning: NRRD payload block allocation failed for layer {int(layer_idx)}; '
                        'falling back to one output t-slice at a time.'
                    )
                local_z_chunk = 1
                buffers = [np.empty((1, int(out_h), int(out_w)), dtype=np.uint8, order='C')]

            # v13.3.4 (T5): checkout-cached single-thread writer pool (was one build per layer).
            writer_pool = _acquire_parallel_pool(1)
            pending: Optional[Future] = None
            try:
                for block_idx, z0 in enumerate(range(0, out_t, int(local_z_chunk))):
                    z1 = min(out_t, int(z0) + int(local_z_chunk))
                    z_count = int(z1 - z0)
                    if len(buffers) < 2 and pending is not None:
                        # Single-buffer fallback: the previous write must finish before refill.
                        pending.result()
                        pending = None
                    block = buffers[int(block_idx) % len(buffers)][:z_count, :, :]

                    if int(fill_workers) > 1 and int(z_count) > 1:
                        def _fill(zi: int, _z0: int = int(z0), _block: np.ndarray = block) -> None:
                            fill_one(int(_z0 + int(zi)), _block[int(zi)])
                        parallel_for_indices_chunked(
                            int(z_count),
                            _fill,
                            max_workers=min(int(fill_workers), int(z_count)),
                            desc='',
                            show_progress=False,
                            target_chunks_per_worker=1,
                        )
                    else:
                        for zi in range(int(z_count)):
                            fill_one(int(z0 + zi), block[int(zi)])

                    if pending is not None:
                        pending.result()
                    pending = writer_pool.submit(payload_writer.write, memoryview(block).cast('B'))
                    # v13.3.3 (S4): the mirror tee reads the block on this thread while the
                    # writer thread compresses it — both are read-only; the next refill of this
                    # buffer is still gated on pending.result() two iterations out.
                    if block_consumer is not None:
                        block_consumer(int(z0), block)
                    if pbar is not None:
                        pbar.update(int(z_count))
                    if bool(madvise_src) and madvise_interval > 0 and (int(z1) % int(madvise_interval) == 0):
                        _madvise_array_mmap(src, 'MADV_DONTNEED')
                if pending is not None:
                    pending.result()
                    pending = None
            finally:
                if pending is not None:
                    try:
                        pending.result()
                    except Exception:
                        pass
                _release_parallel_pool(1, writer_pool)

        if bool(raw_store_native_stream):
            # Target_Dummy layout keeps the list axis last, so one complete layer is a
            # native (t,Y,X) byte block.  For cvol/ctile sources, fill the reusable block
            # directly from each slice bbox payload instead of allocating one full decoded
            # zeros slice per frame and copying it again into the NRRD write buffer.
            _stream_filled_blocks(
                lambda z, out2d: src.fill_decoded_slice_into(int(z), out2d),
                madvise_src=False,
            )
            return

        def _fill_restored(z: int, out2d: np.ndarray) -> None:
            np.copyto(out2d, np.asarray(_read_layer_slice_in_output_shape(src, output_shape, int(z)), dtype=np.uint8))

        _stream_filled_blocks(_fill_restored, madvise_src=True)
    finally:
        if src is not None:
            _madvise_array_mmap(src, 'MADV_DONTNEED')
            _close_nrrd_layer_source(src)
            _drop_nrrd_raw_store_chunks_ram_cache(src)


def write_native_view_overlay_video(
    volume_rgb: np.ndarray,
    native_mask_u8: np.ndarray,
    view: ViewInfo,
    out_path: Path,
    fps: float,
    *,
    show_progress: bool = True,
) -> Path:
    """Write a v12.2.0 troubleshooting overlay in a view's own slice space.

    The mask is already flattened in the native raster consumed by/produced for
    the view: shape (view.num_slices, view.src_h, view.src_w). Source frames are
    resliced from the single-channel orthogonal processing volume only for the
    presentation overlay.
    """
    if tuple(int(x) for x in np.asarray(native_mask_u8).shape) != (int(view.num_slices), int(view.src_h), int(view.src_w)):
        raise ValueError(
            f'Troubleshooting overlay for {view.name} expected native mask shape '
            f'{(int(view.num_slices), int(view.src_h), int(view.src_w))}, got {tuple(np.asarray(native_mask_u8).shape)}'
        )

    proc = ffmpeg_ffv1_rgb_writer(
        out_path,
        width=int(view.src_w),
        height=int(view.src_h),
        fps=float(fps),
    )
    blue = np.array([0, 0, 255], dtype=np.uint8)
    try:
        assert proc.stdin is not None
        for idx in tqdm(
            range(int(view.num_slices)),
            total=int(view.num_slices),
            desc=f'Writing troubleshooting overlay {view.name} ({out_path.name})',
            disable=not bool(show_progress),
        ):
            frame_gray = get_view_frame_by_index(volume_rgb, view, int(idx))
            frame = _gray_to_rgb_frame(np.asarray(frame_gray))
            m = np.asarray(native_mask_u8[int(idx)], dtype=bool)
            if np.any(m):
                frame[m] = ((frame[m].astype(np.uint16) + blue.astype(np.uint16)) // 2).astype(np.uint8)
            proc.stdin.write(np.ascontiguousarray(frame).tobytes())
    finally:
        close_ffmpeg_writer(proc)
    return out_path


def collect_troubleshooting_overlay_futures(
    executor: ThreadPoolExecutor,
    *,
    volume_rgb: np.ndarray,
    model_name: str,
    views: Sequence[ViewInfo],
    native_view_support: Dict[str, np.ndarray],
    consolidated_tile_masks: Dict[str, np.ndarray],
    out_dir: Path,
    stem: str,
    fps: float,
    show_progress: bool = False,
) -> Tuple[Dict[str, Path], List[Future]]:
    """Schedule simplified v12.2.0 troubleshooting overlay MKVs."""
    result_paths: Dict[str, Path] = {}
    futures: List[Future] = []
    troubleshooting_dir = Path(out_dir) / 'troubleshooting'
    troubleshooting_dir.mkdir(parents=True, exist_ok=True)

    for view in views:
        view_token = view_output_token(view)
        full_mask = native_view_support.get(str(view.name))
        if full_mask is not None:
            overlay_path = troubleshooting_dir / f'{stem}_Troubleshooting_{view_token}_FullFrame_Overlay.mkv'
            futures.append(executor.submit(
                write_native_view_overlay_video,
                volume_rgb,
                full_mask,
                view,
                overlay_path,
                fps,
                show_progress=show_progress,
            ))
            result_paths[f'troubleshooting_{view.name}_fullframe_overlay'] = overlay_path

        tile_mask = consolidated_tile_masks.get(str(view.name))
        if tile_mask is not None:
            overlay_path = troubleshooting_dir / f'{stem}_Troubleshooting_{view_token}_Tiles_Overlay.mkv'
            futures.append(executor.submit(
                write_native_view_overlay_video,
                volume_rgb,
                tile_mask,
                view,
                overlay_path,
                fps,
                show_progress=show_progress,
            ))
            result_paths[f'troubleshooting_{view.name}_tiles_overlay'] = overlay_path

    if not futures:
        note_path = troubleshooting_dir / f'{stem}_Troubleshooting_NoActiveMasks.txt'
        note_path.write_text(
            f'No full-frame or consolidated tiled native-view masks were available for model {model_name}.\n'
        )
        result_paths['troubleshooting_note'] = note_path

    return result_paths, futures


@dataclass(frozen=True)
class LowQualityDownbinSpec:
    raw_value: str
    token: str
    scale: float
    output_shape_t_y_x: Tuple[int, int, int]
    warning: str = ''


def _nearest_multiple_of_four(value: float) -> int:
    return max(4, int(math.floor(float(value) / 4.0 + 0.5)) * 4)


def _round_low_quality_dimension(value: float) -> int:
    # Large SLURM volumes should round to multiples of 4 per spec. For tiny synthetic
    # tests, avoid changing a sub-4 dimension to 4 unless the scaled value warrants it.
    value_f = max(1.0, float(value))
    if value_f < 4.0:
        return max(1, int(round(value_f)))
    return _nearest_multiple_of_four(value_f)


def _low_quality_token(raw: str, shape_t_y_x: Tuple[int, int, int]) -> str:
    safe_raw = str(raw).strip().replace('-', 'm').replace('.', 'p').replace(',', '_')
    t_dim, h_dim, w_dim = (int(shape_t_y_x[0]), int(shape_t_y_x[1]), int(shape_t_y_x[2]))
    return f'{safe_raw}_{int(w_dim)}x{int(h_dim)}x{int(t_dim)}'


def resolve_low_quality_downbin_specs(
    downbin_values: Sequence[str] | str | None,
    low_quality_requested: bool,
    source_shape_t_y_x: Tuple[int, int, int],
) -> Tuple[List[LowQualityDownbinSpec], List[str]]:
    """Resolve v12.2.1 isotropic low-quality downbins in native input geometry."""
    if downbin_values is None and not bool(low_quality_requested):
        return [], []

    raw_tokens = _parse_token_list(downbin_values) if downbin_values is not None else []
    if not raw_tokens:
        raw_tokens = ['1024']

    in_t, in_h, in_w = (int(source_shape_t_y_x[0]), int(source_shape_t_y_x[1]), int(source_shape_t_y_x[2]))
    max_dim = max(1, int(in_t), int(in_h), int(in_w))
    specs: List[LowQualityDownbinSpec] = []
    warnings: List[str] = []
    seen_shapes: set[Tuple[int, int, int]] = set()

    for raw in raw_tokens:
        raw_s = str(raw).strip()
        if not raw_s:
            continue
        try:
            value = float(raw_s)
        except Exception as exc:
            raise ValueError(f'--save_low_quality_downbin value is not numeric: {raw_s!r}') from exc
        if not math.isfinite(value) or value <= 0.0:
            raise ValueError('--save_low_quality_downbin values must be positive finite numbers')

        warning = ''
        raw_lower = raw_s.lower()
        looks_float = ('.' in raw_s) or ('e' in raw_lower)
        if looks_float and value <= 1.0:
            scale = float(value)
        else:
            nearest_int = int(round(value))
            if abs(float(value) - float(nearest_int)) > 1e-6:
                raise ValueError('Integer --save_low_quality_downbin values >= 1 must be whole numbers; use a fraction such as 0.5 for scale factors')
            if nearest_int <= 0:
                raise ValueError('--save_low_quality_downbin integer targets must be positive')
            rounded_target = _nearest_multiple_of_four(float(nearest_int))
            if int(rounded_target) != int(nearest_int):
                warning = (
                    f'--save_low_quality_downbin {int(nearest_int)} is not a multiple of 4; '
                    f'rounded to {int(rounded_target)} for isotropic low-quality output.'
                )
                warnings.append(warning)
            scale = float(rounded_target) / float(max_dim)

        out_t = _round_low_quality_dimension(float(in_t) * float(scale))
        out_h = _round_low_quality_dimension(float(in_h) * float(scale))
        out_w = _round_low_quality_dimension(float(in_w) * float(scale))
        shape = (int(out_t), int(out_h), int(out_w))
        if shape in seen_shapes:
            continue
        seen_shapes.add(shape)
        specs.append(LowQualityDownbinSpec(
            raw_value=raw_s,
            token=_low_quality_token(raw_s, shape),
            scale=float(scale),
            output_shape_t_y_x=shape,
            warning=warning,
        ))

    return specs, warnings


def resize_gray_volume_to_shape(
    volume_gray: np.ndarray,
    out_shape: Tuple[int, int, int],
    out_path: Path,
    *,
    workers: int = 1,
    prefer_memory: bool = True,
    reserve_bytes: int = 8 * GIB,
    desc: str = 'Resizing gray volume',
) -> np.ndarray:
    in_t, in_h, in_w = (int(volume_gray.shape[0]), int(volume_gray.shape[1]), int(volume_gray.shape[2]))
    out_t, out_h, out_w = (int(out_shape[0]), int(out_shape[1]), int(out_shape[2]))
    if (in_t, in_h, in_w) == (out_t, out_h, out_w):
        return volume_gray

    out_mm = allocate_workspace_array(
        shape=(out_t, out_h, out_w),
        dtype=np.uint8,
        path=out_path,
        desc=desc,
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
    )
    worker_count = choose_slice_parallel_workers(int(workers), int(out_t))
    chunk_size = choose_parallel_chunk_size(out_t, worker_count, target_chunks_per_worker=2, min_chunk_size=1)
    xy_interp = cv2.INTER_AREA if (out_h <= in_h and out_w <= in_w) else cv2.INTER_LINEAR

    def _render_target_slice(out_z: int) -> None:
        src_z = _linear_source_index(int(out_z), int(out_t), int(in_t))
        z0 = int(math.floor(src_z))
        z1 = min(in_t - 1, z0 + 1)
        alpha = float(src_z - float(z0))
        f0 = _resize_gray_slice_nearest_or_linear(volume_gray[z0], out_w, out_h, xy_interp)
        if z1 == z0 or alpha <= 1e-7:
            out_mm[int(out_z), :, :] = f0
            return
        f1 = _resize_gray_slice_nearest_or_linear(volume_gray[z1], out_w, out_h, xy_interp)
        blended = np.clip(
            np.rint((1.0 - alpha) * f0.astype(np.float32, copy=False) + alpha * f1.astype(np.float32, copy=False)),
            0.0,
            255.0,
        ).astype(np.uint8)
        out_mm[int(out_z), :, :] = blended

    parallel_for_indices_chunked(
        int(out_t),
        _render_target_slice,
        max_workers=worker_count,
        desc=desc,
        chunk_size=chunk_size,
        show_progress=True,
    )
    flush_array(out_mm)
    return out_mm


def resize_binary_mask_volume_to_shape(
    mask_u8: np.ndarray,
    out_shape: Tuple[int, int, int],
    out_path: Path,
    *,
    workers: int = 1,
    prefer_memory: bool = True,
    reserve_bytes: int = 8 * GIB,
    desc: str = 'Resizing binary mask volume',
) -> np.ndarray:
    in_t, in_h, in_w = (int(mask_u8.shape[0]), int(mask_u8.shape[1]), int(mask_u8.shape[2]))
    out_t, out_h, out_w = (int(out_shape[0]), int(out_shape[1]), int(out_shape[2]))
    if (in_t, in_h, in_w) == (out_t, out_h, out_w):
        return mask_u8

    out_mm = allocate_workspace_array(
        shape=(out_t, out_h, out_w),
        dtype=np.uint8,
        path=out_path,
        desc=desc,
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
    )
    worker_count = choose_slice_parallel_workers(int(workers), int(out_t))
    chunk_size = choose_parallel_chunk_size(out_t, worker_count, target_chunks_per_worker=2, min_chunk_size=1)

    def _resize_mask_xy(frame: np.ndarray) -> np.ndarray:
        frame_u8 = (np.asarray(frame, dtype=np.uint8) > 0).astype(np.uint8, copy=False)
        if int(frame_u8.shape[0]) == int(out_h) and int(frame_u8.shape[1]) == int(out_w):
            return np.ascontiguousarray(frame_u8)
        if int(out_h) <= int(frame_u8.shape[0]) and int(out_w) <= int(frame_u8.shape[1]):
            scaled = cv2.resize(
                np.ascontiguousarray(frame_u8 * np.uint8(255)),
                (int(out_w), int(out_h)),
                interpolation=cv2.INTER_AREA,
            )
            return (scaled > 0).astype(np.uint8, copy=False)
        scaled = cv2.resize(
            np.ascontiguousarray(frame_u8),
            (int(out_w), int(out_h)),
            interpolation=cv2.INTER_NEAREST,
        )
        return (scaled > 0).astype(np.uint8, copy=False)

    def _restore_slice(out_z: int) -> None:
        src_start = int(math.floor(float(out_z) * float(in_t) / float(out_t)))
        src_stop = int(math.ceil(float(out_z + 1) * float(in_t) / float(out_t)))
        src_start = int(np.clip(src_start, 0, in_t - 1))
        src_stop = int(np.clip(max(src_start + 1, src_stop), 1, in_t))
        restored = np.zeros((int(out_h), int(out_w)), dtype=np.uint8)
        for src_idx in range(src_start, src_stop):
            restored |= _resize_mask_xy(mask_u8[int(src_idx)])
        out_mm[int(out_z), :, :] = restored

    parallel_for_indices_chunked(
        int(out_t),
        _restore_slice,
        max_workers=worker_count,
        desc=desc,
        chunk_size=chunk_size,
        show_progress=True,
    )
    flush_array(out_mm)
    return out_mm


def x264_preset() -> str:
    """v13.3.1 (R25): x264 preset for the low-quality MP4 writers.

    'slow' cost 2-4x the encode CPU of 'medium' for marginal size gain on these
    distribution-quality copies, competing with the NRRD tail for cores.
    """
    preset = os.environ.get('YOLO_TTA_X264_PRESET', '').strip().lower()
    return preset or 'medium'


def ffmpeg_h264_rgb_writer(out_path: Path, width: int, height: int, fps: float) -> subprocess.Popen:
    return ffmpeg_rawvideo_writer(
        out_path=out_path,
        width=int(width),
        height=int(height),
        fps=float(fps),
        pix_fmt_in='rgb24',
        codec='libx264',
        pix_fmt_out='yuv420p',
        codec_args=['-preset', x264_preset()],
    )


def ffmpeg_h264_gray_writer(out_path: Path, width: int, height: int, fps: float) -> subprocess.Popen:
    return ffmpeg_rawvideo_writer(
        out_path=out_path,
        width=int(width),
        height=int(height),
        fps=float(fps),
        pix_fmt_in='gray',
        codec='libx264',
        pix_fmt_out='yuv420p',
        codec_args=['-preset', x264_preset()],
    )


def write_low_quality_overlay_video(
    volume_gray: np.ndarray,
    mask_u8: np.ndarray,
    out_path: Path,
    fps: float,
    show_progress: bool = True,
) -> Path:
    t_dim, h_dim, w_dim = volume_gray.shape
    assert mask_u8.shape == (t_dim, h_dim, w_dim)
    proc = ffmpeg_h264_rgb_writer(out_path, int(w_dim), int(h_dim), float(fps))
    blue = np.array([0, 0, 255], dtype=np.uint8)
    try:
        assert proc.stdin is not None
        for t in tqdm(range(int(t_dim)), desc=f'Writing low-quality overlay ({out_path.name})', disable=not show_progress):
            frame = _gray_to_rgb_frame(np.asarray(volume_gray[int(t)]))
            m = np.asarray(mask_u8[int(t)], dtype=bool)
            if np.any(m):
                frame[m] = ((frame[m].astype(np.uint16) + blue.astype(np.uint16)) // 2).astype(np.uint8)
            proc.stdin.write(np.ascontiguousarray(frame).tobytes())
    finally:
        close_ffmpeg_writer(proc)
    return out_path


def write_low_quality_binary_video(
    mask_u8: np.ndarray,
    out_path: Path,
    fps: float,
    show_progress: bool = True,
) -> Path:
    t_dim, h_dim, w_dim = mask_u8.shape
    proc = ffmpeg_h264_gray_writer(out_path, int(w_dim), int(h_dim), float(fps))
    try:
        assert proc.stdin is not None
        for t in tqdm(range(int(t_dim)), desc=f'Writing low-quality binary ({out_path.name})', disable=not show_progress):
            frame = (np.asarray(mask_u8[int(t)], dtype=np.uint8) > 0).astype(np.uint8) * np.uint8(255)
            proc.stdin.write(np.ascontiguousarray(frame).tobytes())
    finally:
        close_ffmpeg_writer(proc)
    return out_path


def low_quality_per_bin_output_workers(requested_workers: int) -> int:
    """Number of output writer tasks launched inside one low-quality bin."""
    default_value = max(1, min(3, int(requested_workers)))
    return max(1, min(3, _env_int('YOLO_TTA_LOW_QUALITY_OUTPUT_WORKERS_PER_BIN', int(default_value))))


def save_single_low_quality_output(
    *,
    volume_gray: np.ndarray,
    mask_u8: np.ndarray,
    spec: LowQualityDownbinSpec,
    out_dir: Path,
    stem: str,
    fps: float,
    temp_dir: Path,
    save_nrrd: bool = False,
    workers: int = 1,
    show_progress: bool = True,
) -> Dict[str, Path]:
    """Write one low-quality downbin's overlay and binary videos, overlapped.

    v13.2.1: the low-quality NRRD is no longer written here as one combined volume.  When
    ``--save_nrrd`` is active the low-quality decomposition now follows the full-quality format and
    schedule -- one single-layer NRRD per component layer, downbinned and written by the
    NrrdLayerSink as each view completes (see NrrdLayerSink.submit_layer).  ``save_nrrd`` is retained
    for call-site compatibility but no longer drives any NRRD write in this function.
    """
    low_root = Path(out_dir) / 'low_quality'
    low_root.mkdir(parents=True, exist_ok=True)
    source_t = max(1, int(mask_u8.shape[0]))
    out_t, out_h, out_w = (
        int(spec.output_shape_t_y_x[0]),
        int(spec.output_shape_t_y_x[1]),
        int(spec.output_shape_t_y_x[2]),
    )
    spec_dir = low_root / spec.token
    spec_dir.mkdir(parents=True, exist_ok=True)
    fps_lq = max(1e-6, float(fps) * float(out_t) / float(source_t))
    print(
        f'Low-quality downbin {spec.raw_value}: native (t,Y,X)=({source_t},{int(mask_u8.shape[1])},{int(mask_u8.shape[2])}) '
        f'-> ({out_t},{out_h},{out_w}); playback fps adjusted {float(fps):g} -> {fps_lq:g}; '
        f'per-bin output writer concurrency={low_quality_per_bin_output_workers(int(workers))}'
    )

    gray_lq = resize_gray_volume_to_shape(
        volume_gray,
        (out_t, out_h, out_w),
        Path(temp_dir) / 'low_quality' / spec.token / 'source.gray8.dat',
        workers=int(workers),
        prefer_memory=True,
        desc=f'Low-quality source resize {spec.token}',
    )
    mask_lq = resize_binary_mask_volume_to_shape(
        mask_u8,
        (out_t, out_h, out_w),
        Path(temp_dir) / 'low_quality' / spec.token / 'mask.u8.dat',
        workers=int(workers),
        prefer_memory=True,
        desc=f'Low-quality mask resize {spec.token}',
    )
    result_paths: Dict[str, Path] = {'low_quality_dir': low_root}
    try:
        overlay_path = spec_dir / f'{stem}_Overlay_LowQuality_{spec.token}.mp4'
        binary_path = spec_dir / f'{stem}_Binary_LowQuality_{spec.token}.mp4'

        def _write_lq_overlay() -> Path:
            return write_low_quality_overlay_video(gray_lq, mask_lq, overlay_path, fps_lq, show_progress=show_progress)

        def _write_lq_binary() -> Path:
            return write_low_quality_binary_video(mask_lq, binary_path, fps_lq, show_progress=show_progress)

        # v13.2.1: the low-quality NRRD decomposition is produced per component layer by the
        # NrrdLayerSink as views complete, not here. Only the distribution videos are written below.
        writer_thunks = [_write_lq_overlay, _write_lq_binary]

        writer_count = low_quality_per_bin_output_workers(int(workers))
        if writer_count <= 1:
            for thunk in writer_thunks:
                thunk()
        else:
            with ThreadPoolExecutor(max_workers=int(writer_count), thread_name_prefix=f'lq-writer-{spec.token[:16]}') as executor:
                futures = [executor.submit(thunk) for thunk in writer_thunks]
                for fut in as_completed(futures):
                    fut.result()

        result_paths[f'low_quality_{spec.token}_overlay'] = overlay_path
        result_paths[f'low_quality_{spec.token}_binary_video'] = binary_path
        return result_paths
    finally:
        if gray_lq is not volume_gray:
            close_memmap_array(gray_lq)
        if mask_lq is not mask_u8:
            close_memmap_array(mask_lq)


def collect_low_quality_output_futures(
    executor: ThreadPoolExecutor,
    *,
    volume_gray: np.ndarray,
    mask_u8: np.ndarray,
    out_dir: Path,
    stem: str,
    fps: float,
    downbin_specs: Sequence[LowQualityDownbinSpec],
    temp_dir: Path,
    save_nrrd: bool = False,
    workers: int = 1,
    show_progress: bool = True,
) -> Tuple[Dict[str, Path], List[Future]]:
    """Submit each low-quality downbin as an independent background job."""
    result_paths = planned_low_quality_output_paths(
        out_dir=out_dir,
        stem=stem,
        downbin_specs=downbin_specs,
        save_nrrd=save_nrrd,
    )
    futures: List[Future] = []
    for spec in list(downbin_specs):
        futures.append(executor.submit(
            save_single_low_quality_output,
            volume_gray=volume_gray,
            mask_u8=mask_u8,
            out_dir=out_dir,
            stem=stem,
            fps=float(fps),
            spec=spec,
            temp_dir=temp_dir,
            save_nrrd=save_nrrd,
            workers=int(workers),
            show_progress=show_progress,
        ))
    return result_paths, futures


def planned_low_quality_output_paths(
    *,
    out_dir: Path,
    stem: str,
    downbin_specs: Sequence[LowQualityDownbinSpec],
    save_nrrd: bool = False,
) -> Dict[str, Path]:
    """Return the paths that the per-bin low-quality writers (save_single_low_quality_output) will create.

    This lets the background output manager launch the low-quality distribution videos at the
    same time as the full-size outputs instead of waiting for the full-size output group to finish.

    v13.2.1: low-quality NRRDs are no longer planned here; they are emitted per component layer by
    the NrrdLayerSink under low_quality/<token>/nrrd/ on the view-completion schedule. ``save_nrrd``
    is retained for call-site compatibility.
    """
    low_root = out_dir / 'low_quality'
    result_paths: Dict[str, Path] = {'low_quality_dir': low_root}
    for spec in downbin_specs:
        spec_dir = low_root / spec.token
        overlay_path = spec_dir / f'{stem}_Overlay_LowQuality_{spec.token}.mp4'
        binary_path = spec_dir / f'{stem}_Binary_LowQuality_{spec.token}.mp4'
        result_paths[f'low_quality_{spec.token}_overlay'] = overlay_path
        result_paths[f'low_quality_{spec.token}_binary_video'] = binary_path
    return result_paths


@dataclass
class BackgroundOutputSubmission:
    label: str
    result_paths: Dict[str, Path]
    futures: List[Future] = field(default_factory=list)
    resources: List[object] = field(default_factory=list)

    def wait(self) -> Dict[str, Path]:
        error: Optional[BaseException] = None
        try:
            for fut in self.futures:
                fut.result()
        except BaseException as exc:  # pragma: no cover - surfaced to main
            error = exc
        finally:
            for resource in self.resources:
                close_memmap_array(resource)
        if error is not None:
            raise RuntimeError(f'Background output generation failed for {self.label}') from error
        return self.result_paths


class BackgroundOutputManager:
    def __init__(self, max_workers: int) -> None:
        self.max_workers = max(1, int(max_workers))
        self.executor = ThreadPoolExecutor(max_workers=self.max_workers, thread_name_prefix='yolo-output')
        self.pending: List[BackgroundOutputSubmission] = []

    def submit(self, submission: BackgroundOutputSubmission) -> Dict[str, Path]:
        self.pending.append(submission)
        return submission.result_paths

    def reap_completed(self) -> None:
        remaining: List[BackgroundOutputSubmission] = []
        for submission in self.pending:
            if all(fut.done() for fut in submission.futures):
                submission.wait()
            else:
                remaining.append(submission)
        self.pending = remaining

    def wait(self) -> None:
        error: Optional[BaseException] = None
        try:
            while self.pending:
                submission = self.pending.pop(0)
                try:
                    submission.wait()
                except BaseException as exc:  # pragma: no cover - surfaced to main
                    if error is None:
                        error = exc
        finally:
            self.executor.shutdown(wait=True)
        if error is not None:
            raise error


def collect_pipeline_output_futures(
    executor: ThreadPoolExecutor,
    *,
    volume_rgb: np.memmap,
    mask_u8: np.ndarray,
    out_dir: Path,
    stem: str,
    fps: float,
    save_binary_pattern_value: Optional[str],
    save_labels_pattern_value: Optional[str],
    save_nrrd_flag: bool,
    tag: Optional[str] = None,
    frame_workers: int = 1,
    show_progress: bool = False,
    nrrd_layer_refs: Optional[Sequence[NrrdLayerRef]] = None,
    nrrd_temp_dir: Optional[Path] = None,
    nrrd_workers: int = 1,
) -> Tuple[Dict[str, Path], List[Future]]:
    futures: List[Future] = []
    result_paths: Dict[str, Path] = {}
    tag_suffix = f"_{tag}" if tag else ""

    overlay_path = out_dir / f"{stem}_Overlay{tag_suffix}.mkv"
    futures.append(executor.submit(
        write_overlay_video,
        volume_rgb,
        mask_u8,
        overlay_path,
        fps,
        show_progress=show_progress,
    ))
    result_paths["overlay"] = overlay_path

    labels_pattern = _resolve_output_pattern(save_labels_pattern_value, DEFAULT_LABEL_PATTERN, out_dir, stem)
    if labels_pattern is not None:
        if tag is not None:
            labels_pattern = _tag_frame_pattern(labels_pattern, tag)
        futures.append(executor.submit(write_yolo_labels_from_pattern, mask_u8, labels_pattern, int(frame_workers), show_progress))
        result_paths["labels_dir"] = labels_pattern.parent

    binary_pattern = _resolve_output_pattern(save_binary_pattern_value, DEFAULT_BINARY_PATTERN, out_dir, stem)
    if binary_pattern is not None:
        if tag is not None:
            binary_pattern = _tag_frame_pattern(binary_pattern, tag)
        binary_video_path = out_dir / f"{stem}_Binary{tag_suffix}.mkv"
        futures.append(executor.submit(write_binary_tiff_sequence_from_pattern, mask_u8, binary_pattern, int(frame_workers), show_progress))
        futures.append(executor.submit(write_binary_video_from_mask_volume, mask_u8, binary_video_path, fps, show_progress))
        result_paths["binary_tiff_dir"] = binary_pattern.parent
        result_paths["binary_video"] = binary_video_path

    # v13.2.0: --save_nrrd no longer assembles one mega 4D decomposed NRRD here. Each component
    # layer is written as its own single-layer NRRD by the NrrdLayerSink during the intermediate
    # pipeline steps (and the Global_final_output layer is materialized in the tail), so this
    # background output group has no NRRD work. The unused save_nrrd_flag / nrrd_* parameters are
    # retained for call-site stability.

    return result_paths, futures


def write_view_images(
    volume_rgb: np.ndarray,
    view: ViewInfo,
    out_dir: Path,
    stem: str,
    *,
    workers: int = 1,
    show_progress: bool = True,
) -> Path:
    view_dir = out_dir / 'images' / view.name
    view_dir.mkdir(parents=True, exist_ok=True)
    total = int(view.num_slices)

    def _write_frame(idx: int) -> None:
        frame = np.ascontiguousarray(get_view_frame_by_index(volume_rgb, view, int(idx)))
        out_path = view_dir / f'{stem}_{view.name}_{int(idx) + 1:04d}.png'
        if not cv2.imwrite(str(out_path), frame):
            raise RuntimeError(f'Failed to write image: {out_path}')

    parallel_for_indices(
        total,
        _write_frame,
        max_workers=choose_slice_parallel_workers(int(workers), total),
        desc=f'Writing {view.name} image sequence',
        show_progress=show_progress,
    )
    return view_dir


def write_summary_file(
    out_path: Path,
    *,
    command: str,
    input_path: Path,
    out_dir: Path,
    scratch_dir: Path,
    source_shape_x_y_t: Tuple[int, int, int],
    volume_shape: Tuple[int, int, int],
    fps: float,
    model_paths: Sequence[str],
    view_names: Sequence[str],
    view_prediction_stats: Dict[str, int],
    interpolation_stats: List[Dict[str, object]],
    enable_3d_void_fill: bool,
    gaussian_smoothing_stats: Optional[Dict[str, int | float]],
    keep_objects_stats: Optional[Dict[str, int]],
    voxel_volume: Optional[int],
    final_paths: Dict[str, Path],
    augmentation_workers: int,
    slice_postprocess_workers: int,
    interpolation_workers: int,
    output_workers: int,
    spec_notes: Optional[Sequence[str]] = None,
    view_prediction_labels: Optional[Dict[str, str]] = None,
) -> Path:
    lines: List[str] = []
    lines.append(f'Command: {command}')
    lines.append(f'Input: {input_path}')
    lines.append(f'Output directory: {out_dir}')
    lines.append(f'Source dimensions before cubic resizing (X, Y, t): {source_shape_x_y_t}')
    lines.append(f'Processing volume shape (t, Y, X): {volume_shape}')
    lines.append(f'FPS: {fps}')
    lines.append(f'Scratch directory: {scratch_dir}')
    lines.append('Workspace policy: in-memory first with disk fallback when the working set exceeds available RAM/swap')
    lines.append(f'3D void fill: {"enabled" if bool(enable_3d_void_fill) else "disabled"}; when enabled, it is applied once after the final global union')
    if bool(enable_3d_void_fill):
        lines.append('3D void fill background connectivity: default 6-connected; override with YOLO_TTA_VOIDFILL_CONNECTIVITY=18 or 26 if needed')
    lines.append(f'Augmentation workers: {int(augmentation_workers)}')
    lines.append(f'Slice-parallel postprocess workers: {int(slice_postprocess_workers)}')
    lines.append(f'Interpolation workers: {int(interpolation_workers)}')
    lines.append(f'Output workers: {int(output_workers)}')
    lines.append('Worker oversubscription: intentional; the default worker budget targets 2x the visible CPU allocation to overlap GPU waits, ffmpeg IO, and slice-parallel CPU work.')
    lines.append(f'Model: {str(Path(model_paths[0])) if model_paths else "<none>"}')
    lines.append(f'Views: {", ".join(view_names)}')
    if spec_notes:
        lines.append('')
        lines.append('Specification notes:')
        for note in spec_notes:
            lines.append(f'  - {note}')

    lines.append('')
    lines.append('View statistics:')
    total_prediction_count = 0
    labels = dict(view_prediction_labels or {})
    ordered_keys: List[str] = [k for k in ('transverse', 'sagittal', 'coronal', 'radial') if k in view_prediction_stats]
    tilted_keys = [k for k in view_prediction_stats.keys() if str(k).startswith('tilted_')]
    other_keys = [k for k in view_prediction_stats.keys() if k not in set(ordered_keys) and k not in set(tilted_keys)]
    for view_key in ordered_keys + sorted(tilted_keys, key=lambda k: labels.get(k, k)) + sorted(other_keys):
        label = labels.get(view_key, str(view_key).replace('_', ' ').title())
        count = int(view_prediction_stats.get(view_key, 0))
        total_prediction_count += count
        lines.append(f'  {label}: predictions={count}')
    lines.append(f'  Total prediction count: {int(total_prediction_count)}')

    if interpolation_stats:
        lines.append('')
        lines.append('Interpolation statistics (per pass):')
        pass_indices = sorted({int(s.get('pass_index', 0)) for s in interpolation_stats})
        for pass_idx in pass_indices:
            stats_this_pass = [s for s in interpolation_stats if int(s.get('pass_index', 0)) == pass_idx]
            total_objects = sum(int(s.get('num_objects', 0)) for s in stats_this_pass)
            total_endpoints = sum(int(s.get('num_endpoints', 0)) for s in stats_this_pass)
            total_candidates = sum(int(s.get('candidate_connections', 0)) for s in stats_this_pass)
            total_accepted = sum(int(s.get('accepted_connections', 0)) for s in stats_this_pass)
            total_default_bridges = sum(int(s.get('default_bridges', 0)) for s in stats_this_pass)
            total_walk_back = sum(int(s.get('walk_back_bridges', 0)) for s in stats_this_pass)
            total_skipped = sum(int(s.get('skipped_by_min_radius', 0)) for s in stats_this_pass)
            total_added_voxels = sum(int(s.get('added_voxels', 0)) for s in stats_this_pass)
            lines.append(
                f'  Pass {pass_idx}: objects={total_objects}, endpoints={total_endpoints}, '
                f'candidate_connections={total_candidates}, accepted_connections={total_accepted}, '
                f'default_bridges={total_default_bridges}, walk_back_bridges={total_walk_back}, '
                f'bridges_skipped_by_--interpolate_min_radius={total_skipped}, added_voxels={total_added_voxels}'
            )
            for s in sorted(stats_this_pass, key=lambda d: (str(d.get('model', '')), str(d.get('view', '')))):
                lines.append(
                    f"    {s.get('model', '?')}/{s.get('view', '?')}: "
                    f"objects={int(s.get('num_objects', 0))}, "
                    f"endpoints={int(s.get('num_endpoints', 0))}, "
                    f"candidate_connections={int(s.get('candidate_connections', 0))}, "
                    f"accepted_connections={int(s.get('accepted_connections', 0))}, "
                    f"default_bridges={int(s.get('default_bridges', 0))}, "
                    f"walk_back_bridges={int(s.get('walk_back_bridges', 0))}, "
                    f"bridges_skipped_by_--interpolate_min_radius={int(s.get('skipped_by_min_radius', 0))}, "
                    f"added_voxels={int(s.get('added_voxels', 0))}, "
                    f"skipped={bool(s.get('skipped', False))}"
                )

    lines.append('')
    if gaussian_smoothing_stats is not None and int(gaussian_smoothing_stats.get('enabled', 0)) > 0:
        lines.append(
            'Gaussian smoothing: enabled; '
            f"sigma={float(gaussian_smoothing_stats.get('sigma', 0.0)):g}, "
            f"passes_requested={int(gaussian_smoothing_stats.get('passes_requested', 0))}, "
            f"passes_completed={int(gaussian_smoothing_stats.get('passes_completed', 0))}"
        )
        lines.append(
            '  voxel changes after thresholding: '
            f"added={int(gaussian_smoothing_stats.get('total_added_voxels', 0))}, "
            f"removed={int(gaussian_smoothing_stats.get('total_removed_voxels', 0))}"
        )
    else:
        lines.append('Gaussian smoothing: disabled')

    if keep_objects_stats is not None:
        lines.append('')
        lines.append(
            'keep_objects: '
            f"enabled, objects={int(keep_objects_stats.get('num_objects', 0))}, "
            f"kept={int(keep_objects_stats.get('kept_objects', 0))}, "
            f"removed_objects={int(keep_objects_stats.get('removed_objects', 0))}, "
            f"removed_voxels={int(keep_objects_stats.get('removed_voxels', 0))}"
        )
    else:
        lines.append('')
        lines.append('keep_objects: disabled')

    if voxel_volume is not None:
        lines.append('')
        lines.append(f'voxel_volume_native_input_space: {int(voxel_volume)}')

    lines.append('')
    lines.append('Final outputs:')
    for key in sorted(final_paths.keys()):
        lines.append(f'{key}: {final_paths[key]}')

    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines) + "\n")
    return out_path


# --------------------------
# Main
# --------------------------


def main() -> None:
    args = build_argparser().parse_args()

    input_path = Path(args.input).expanduser().resolve()
    if not input_path.exists():
        raise FileNotFoundError(input_path)

    model_path = str(args.model).strip()
    if not model_path:
        raise ValueError('--model must specify one YOLO segmentation model path')
    if ',' in model_path:
        raise ValueError('v12.2.0_SLURM accepts a single --model path; multiple-model inference has been removed')
    model_path_resolved = str(Path(model_path).expanduser().resolve())
    if not Path(model_path_resolved).exists():
        raise FileNotFoundError(model_path_resolved)
    model_paths = [model_path_resolved]
    model_name = Path(model_paths[0]).stem

    model_load_executor: Optional[ThreadPoolExecutor] = None
    model_load_future: Optional[Future] = None
    if background_model_load_enabled():
        print(f'Loading model in background while input volume is prepared: {model_name} ({model_paths[0]})')
        model_load_executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix='model-load')
        model_load_future = model_load_executor.submit(load_ultralytics_model, model_paths[0], 'segment')

    angles = _parse_angles(args.angle) or [0.0, 120.0, 240.0]
    single_angle_streaming_cleanup_active = bool(
        len(angles) == 1 and _env_flag('YOLO_TTA_SINGLE_ANGLE_STREAMING_CLEANUP', True)
    )
    if int(args.batch) < 1:
        raise ValueError('--batch must be >= 1')
    set_inference_batch_size(int(args.batch))
    tilt_views = resolve_tilt_views(args.tilt_view)
    tilt_angles = resolve_tilt_angles(args.tilt_angle)
    tilt_directions = resolve_tilt_directions(args.tilt_direction)
    tile_configs = resolve_tile_configs(args.tile_size, args.tile_stride)
    enable_sagittal = bool(args.enable_sagittal)
    enable_coronal = bool(args.enable_coronal)
    # Default outputs stay transverse-only; active non-transverse views contribute to inference/union
    # but are not separately exported. (--save_sagittal/--save_coronal were fully deprecated and removed.)
    requested_azimuth_angle = None if args.azimuth_angle is None else float(args.azimuth_angle)

    # v13.0.0 multi-GPU scheduling + retina-mask-processor resolution.
    inference_devices = parse_device_list(args.device)
    gpu_device_count = len([d for d in inference_devices if str(d).startswith('cuda')])
    multi_gpu_active = bool(gpu_device_count > 1)
    # v13.2.2 bug #13 follow-up: --device uses torch LOGICAL indices into any inherited
    # CUDA_VISIBLE_DEVICES list. Validate BEFORE decode/model-load work so a submit script
    # still using the accidental v13.2.1 physical-id convention (e.g. --device 2,3 under
    # CUDA_VISIBLE_DEVICES=2,3) fails immediately with the correction instead of hours in.
    _inherited_cvd = os.environ.get('CUDA_VISIBLE_DEVICES')
    if _inherited_cvd is not None and gpu_device_count > 0:
        _visible_tokens = [tok.strip() for tok in str(_inherited_cvd).split(',') if tok.strip()]
        _logical = [int(str(d).split(':')[-1]) for d in inference_devices if str(d).startswith('cuda')]
        _bad = [idx for idx in _logical if idx < 0 or idx >= len(_visible_tokens)]
        if _bad:
            hint = (
                f'use --device {",".join(str(i) for i in range(len(_visible_tokens)))} to run on all allocated GPUs'
                if _visible_tokens else 'no GPUs are visible to this job'
            )
            raise SystemExit(
                f'--device index(es) {_bad} are out of range for the inherited '
                f'CUDA_VISIBLE_DEVICES={_inherited_cvd!r} ({len(_visible_tokens)} visible device(s)). '
                f'--device uses torch LOGICAL indices into that list (v13.2.2): {hint}.'
            )
    retina_processor, retina_processor_reason = resolve_retina_mask_processor(
        args.retina_mask_processor, inference_devices
    )
    set_retina_mask_processor(retina_processor)
    # v13.1.0 (#2.3): single-angle + gpu-retina fast path. When exactly one --angle is used and retina
    # masks are resolved on the GPU, the whole per-slice cleanup runs on the GPU: instances below
    # --min_conf are dropped before the union/flatten, the union+confidence planes are warped to
    # view-native space on the GPU, and --min_radius + 2D hole fill run on the GPU (cupy). Only the
    # finished view-native plane crosses PCIe. None disables the fast path (e.g. multi-angle, where the
    # full union and cross-angle max-confidence must be preserved before --min_conf is applied at the
    # volume level); multi-angle gpu runs still get the on-GPU flatten + warp (#2.2).
    single_angle_gpu_fastpath_active = bool(
        single_angle_streaming_cleanup_active and str(retina_processor).strip().lower() == 'gpu'
    )
    single_angle_gpu_fastpath_min_conf_value = (
        float(args.min_conf) if single_angle_gpu_fastpath_active else None
    )
    single_angle_gpu_fastpath_min_radius_value = (
        float(args.min_radius) if single_angle_gpu_fastpath_active else 0.0
    )
    set_single_angle_gpu_fastpath(
        single_angle_gpu_fastpath_min_conf_value, single_angle_gpu_fastpath_min_radius_value
    )
    print(
        f'Inference devices: {inference_devices} '
        f'(multi-GPU scheduling {"active" if multi_gpu_active else "inactive"}); '
        f'retina mask processor: {retina_processor} ({retina_processor_reason}).'
    )
    if single_angle_gpu_fastpath_active:
        print(
            'v13.1.0 single-angle GPU retina fast path active: retina masks are flattened, '
            f'confidence-filtered (--min_conf={float(args.min_conf):.3f}), warped to view-native space '
            f'(v13.3.0 R8: identity warps skipped, grids cached), and --min_radius={float(args.min_radius):g} '
            'is applied on the GPU before the PCIe copy when positive (cupy required; CPU fallback '
            'otherwise). v13.3.0 (R8): the per-frame GPU 2D hole fill is removed — the final per-view '
            'volume pass performs the hole fill once, in spec order.'
        )
    elif str(retina_processor).strip().lower() == 'gpu':
        print(
            'v13.1.0 GPU retina flatten active: the (n,H,W) retina-mask stack is reduced to union + '
            'max-confidence planes and warped to view-native space on the GPU before the PCIe copy.'
        )
    # v13.0.0: under multi-GPU each inference worker is its own process pinned (via
    # CUDA_VISIBLE_DEVICES) to a single physical GPU exposed as cuda:0, so CUDA input staging is
    # device-safe per worker and is left at its default. The main process performs no inference.
    # v13.3.1 (R4): with exactly one --angle, worker slice windows are disjoint per view, so
    # workers write results straight into the shared per-view union memmap (pre-created disk-
    # backed at task-build time) instead of per-task result files that the scheduler re-reads.
    mgpu_direct_union_active = bool(
        multi_gpu_active and len(angles) == 1 and mgpu_direct_union_enabled()
    )
    if mgpu_direct_union_active:
        print(
            'v13.3.1 (R4) multi-GPU direct union writes active: single-angle worker tasks write '
            'their disjoint slice windows straight into the disk-backed per-view union '
            '(no per-task result files, no scheduler-side OR pass). '
            'Set YOLO_TTA_MGPU_DIRECT_UNION=0 to restore the legacy result-file path.'
        )

    if args.min_conf > 0 and args.min_conf < args.conf:
        raise ValueError('--min_conf must be equal to or greater than --conf')
    if int(args.interpolate) < 0:
        raise ValueError('--interpolate must be >= 0')
    if int(args.interpolation_walk_back) < 0:
        raise ValueError('--interpolation_walk_back must be >= 0')
    if int(args.interpolation_candidates) < 1:
        raise ValueError('--interpolation_candidates must be >= 1')
    if int(args.interpolate_passes) < 1:
        raise ValueError('--interpolate_passes must be >= 1')
    if args.gaussian_smoothing is not None and float(args.gaussian_smoothing) < 0.0:
        raise ValueError('--gaussian_smoothing must be >= 0; use 0 to disable smoothing')
    if args.gaussian_smoothing_passes is not None and int(args.gaussian_smoothing_passes) < 0:
        raise ValueError('--gaussian_smoothing_passes must be >= 0; use 0 to disable smoothing')
    gaussian_smoothing_cli_requested = bool(args.gaussian_smoothing is not None or args.gaussian_smoothing_passes is not None)
    gaussian_smoothing_disabled_by_zero = bool(
        (args.gaussian_smoothing is not None and float(args.gaussian_smoothing) == 0.0)
        or (args.gaussian_smoothing_passes is not None and int(args.gaussian_smoothing_passes) == 0)
    )
    gaussian_smoothing_enabled, gaussian_smoothing_sigma, gaussian_smoothing_passes = resolve_gaussian_smoothing_settings(
        args.gaussian_smoothing,
        args.gaussian_smoothing_passes,
    )
    if float(args.interpolate_min_radius) < 0:
        raise ValueError('--interpolate_min_radius must be >= 0')
    if float(args.min_radius) < 0:
        raise ValueError('--min_radius must be >= 0')
    if int(args.keep_objects) < 0:
        raise ValueError('--keep_objects must be >= 0')
    if requested_azimuth_angle is not None and float(requested_azimuth_angle) < 0:
        raise ValueError('--azimuth_angle must be >= 0')
    for tilt_angle in tilt_angles:
        if not (0.0 < float(tilt_angle) <= 45.0):
            raise ValueError('--tilt_angle values must be greater than 0 and less than or equal to 45')
    if not (-90.0 < float(args.interpolation_search_angle) < 90.0):
        raise ValueError('--interpolation_search_angle must be greater than -90 and less than 90')
    low_quality_requested = bool(args.save_low_quality or args.save_low_quality_downbin is not None)
    # v13.2.0 (#2.6): NRRD component layers are produced only for --save_nrrd, so requesting only
    # low-quality outputs writes the low-quality videos but no NRRD output.
    # v13.2.1 (bug #2): when both --save_nrrd and a low-quality request are active, the low-quality
    # NRRD decomposition mirrors the full-quality layers (one downbinned single-layer NRRD per
    # component layer) on the same view-completion schedule, rather than one combined tail volume.
    nrrd_layers_needed = bool(args.save_nrrd)
    troubleshooting_outputs_enabled = bool(args.troubleshooting)
    # v12.2.0 --troubleshooting creates overlay MKVs only. Temporary scratch retention is a
    # separate hidden maintenance escape hatch so troubleshooting no longer changes cleanup semantics.
    keep_temp_artifacts = bool(_env_flag('YOLO_TTA_KEEP_TEMP', False))

    out_dir = Path(args.output).expanduser().resolve() if args.output else (Path.cwd() / input_path.stem)
    out_dir.mkdir(parents=True, exist_ok=True)

    temp_dir = choose_scratch_dir(None, out_dir, input_path.stem)
    expose_scratch_in_output(out_dir, temp_dir)
    print(f"Bulk scratch dir: {temp_dir}")

    info = ffprobe_info(input_path)
    input_W = int(info['width'])
    input_H = int(info['height'])
    input_T = int(info['num_frames'])
    fps = float(info['fps'])

    low_quality_downbin_specs, low_quality_downbin_warnings = resolve_low_quality_downbin_specs(
        args.save_low_quality_downbin,
        bool(low_quality_requested),
        (input_T, input_H, input_W),
    )

    # v13.2.0: --save_nrrd writes one single-layer NRRD per component layer (in source output
    # geometry X,Y,t) as the layers are produced during the intermediate pipeline steps. The sink
    # is configured here (output geometry is now known) and torn down in the tail after the final
    # global layers are materialized.
    # v13.2.1: when --save_low_quality is also active, the sink mirrors every component layer into
    # one downbinned single-layer NRRD per spec under low_quality/<token>/nrrd/, on the same
    # view-completion schedule as the full-quality layers (the tail no longer writes a combined
    # low-quality NRRD).
    # v13.2.4 (task #1, ruling A1): record the final source output geometry so radial/tilted
    # NRRD layer projections and the final backprojection queue target it directly (one resample).
    set_final_source_output_shape((input_T, input_H, input_W))

    nrrd_dir = out_dir / 'nrrd'
    if bool(args.save_nrrd):
        sink_low_quality_specs = list(low_quality_downbin_specs) if bool(low_quality_requested) else []
        set_nrrd_layer_sink(NrrdLayerSink(
            nrrd_dir=nrrd_dir,
            stem=input_path.stem,
            output_shape_tyx=(input_T, input_H, input_W),
            max_workers=nrrd_layer_sink_workers(),
            pigz_threads=nrrd_single_layer_pigz_threads(),
            low_quality_specs=sink_low_quality_specs,
            low_quality_root=(out_dir / 'low_quality'),
        ))
    else:
        set_nrrd_layer_sink(None)

    preprocess_streaming_active = bool(streaming_preprocess_enabled())
    vol_path = temp_dir / 'input_volume.gray8.dat'
    # v13.3.1 (R12): the cube-resize decision only needs the ffprobe dimensions, so resolve it
    # BEFORE decode. In multi-GPU runs the worker processes read the processing volume from a
    # file, so whichever array becomes the processing volume (the cube-resize output, or the
    # decode output when no resize applies) is allocated DISK-BACKED from the start — the page
    # cache keeps it RAM-speed and _ensure_source_volume_file_backed reuses it directly instead
    # of copying the whole volume to scratch between decode completion and the first GPU task.
    input_processing_shape = (int(input_T), int(input_H), int(input_W))
    legacy_cube_shape = compute_cube_resize_shape(input_T, input_H, input_W, tolerance=0.05)
    processing_mode = processing_volume_mode()
    cube_resize_will_apply = bool(should_resize_to_processing_cube(input_processing_shape, legacy_cube_shape))
    decode_prefer_memory = not (bool(multi_gpu_active) and not cube_resize_will_apply)
    if preprocess_streaming_active:
        print(
            'v12.2.15 streaming preprocessing active: ffmpeg decode returns its destination array immediately; '
            'Transverse/native consumers wait only for the needed decoded slice. Legacy cube resize, if explicitly enabled, also streams.'
        )
        input_volume_rgb = decode_video_to_memmap_gray8_streaming(
            input_video=input_path,
            out_dat=vol_path,
            num_frames=input_T,
            width=input_W,
            height=input_H,
            overwrite=False,
            prefer_memory=decode_prefer_memory,
        )
    else:
        input_volume_rgb = decode_video_to_memmap_gray8(
            input_video=input_path,
            out_dat=vol_path,
            num_frames=input_T,
            width=input_W,
            height=input_H,
            overwrite=False,
            prefer_memory=decode_prefer_memory,
        )
    (temp_dir / 'input_volume.meta.json').write_text(
        json.dumps({'shape': [input_T, input_H, input_W], 'dtype': 'uint8', 'channels': 1, 'fps': fps, 'streaming_preprocess': bool(preprocess_streaming_active)}, indent=2)
    )

    if cube_resize_will_apply:
        processing_shape = legacy_cube_shape
        print(
            'v13.0.0 processing geometry: approximately-cubic working volume (default). '
            f'input shape (t,Y,X)=({input_T},{input_H},{input_W}) -> '
            f'processing shape (t,Y,X)={processing_shape} (within 5% of the longest source axis).'
        )
        if preprocess_streaming_active:
            volume_rgb = resize_volume_to_processing_cube_gray8_streaming(
                input_volume_rgb,
                processing_shape,
                temp_dir / 'input_volume.v950_cube.gray8.dat',
                workers=max(1, default_worker_budget()),
                prefer_memory=not bool(multi_gpu_active),
            )
        else:
            volume_rgb = resize_volume_to_processing_cube_gray8(
                input_volume_rgb,
                processing_shape,
                temp_dir / 'input_volume.v950_cube.gray8.dat',
                workers=max(1, default_worker_budget()),
                prefer_memory=not bool(multi_gpu_active),
            )
    else:
        processing_shape = input_processing_shape
        volume_rgb = input_volume_rgb
        if processing_mode == 'cube' and legacy_cube_shape == input_processing_shape:
            print(f'v13.0.0 processing geometry: approximately-cubic (default), input already within 5% cube tolerance ({processing_shape}).')
        else:
            print(
                'v13.0.0 processing geometry: native decoded volume (YOLO_TTA_PROCESSING_VOLUME_MODE=native), no cube resize. '
                f'input/processing shape (t,Y,X)={processing_shape}; approximately-cubic target would have been {legacy_cube_shape}. '
                'Unset YOLO_TTA_PROCESSING_VOLUME_MODE to use the default approximately-cubic working geometry.'
            )

    T, H, W = (int(processing_shape[0]), int(processing_shape[1]), int(processing_shape[2]))
    resolved_azimuth_angle = resolve_radial_azimuth_angle(
        requested_azimuth_angle,
        enable_radial=bool(args.enable_radial),
        diameter=min(W, H),
    )
    if bool(args.enable_radial) and resolved_azimuth_angle > 0.0 and requested_azimuth_angle is None:
        print(f'Radial azimuth default: using full-coverage spacing {resolved_azimuth_angle:.8g}° for processing diameter {min(W, H)}')

    (temp_dir / 'processing_volume.meta.json').write_text(
        json.dumps({
            'input_shape_t_y_x': [input_T, input_H, input_W],
            'processing_shape_t_y_x': [T, H, W],
            'processing_volume_mode': processing_mode,
            'legacy_cube_shape_t_y_x': [int(legacy_cube_shape[0]), int(legacy_cube_shape[1]), int(legacy_cube_shape[2])],
            'cube_resize_applied': bool(tuple(int(x) for x in processing_shape) != tuple(int(x) for x in input_processing_shape)),
            'dtype': 'uint8',
            'channels': 1,
            'fps': fps,
            'azimuth_angle_deg': resolved_azimuth_angle,
            'enable_sagittal': bool(enable_sagittal),
            'enable_coronal': bool(enable_coronal),
            'tilt_views': list(tilt_views),
            'tilt_angles_deg': [float(v) for v in tilt_angles],
            'tilt_directions': list(tilt_directions),
        }, indent=2)
    )

    # v13.2.5 (speed #1): fold the --imgsz downscale into the radial native raster unless the
    # legacy full-pitch render is explicitly requested via YOLO_TTA_RADIAL_FOLD_IMGSZ=0.
    radial_fold_raster = int(args.imgsz) if _env_flag('YOLO_TTA_RADIAL_FOLD_IMGSZ', True) else 0
    views = get_view_infos(
        T=T,
        H=H,
        W=W,
        disable_multiplanar=None,
        enable_sagittal=bool(enable_sagittal),
        enable_coronal=bool(enable_coronal),
        azimuth_angle=float(resolved_azimuth_angle),
        include_radial=True,
        tilt_views=tilt_views,
        tilt_angles=tilt_angles,
        tilt_directions=tilt_directions,
        radial_native_raster=int(radial_fold_raster),
    )
    cartesian_views = orthogonal_views_only(views)
    transverse_inference_disabled = bool(args.disable_transverse)
    inference_views = [v for v in views if not (transverse_inference_disabled and v.name == 'transverse')]
    interpolating_views = [v for v in inference_views if _view_uses_interpolation(v, int(args.interpolate))]
    spec_notes: List[str] = []
    # v13.1.0 spec<->implementation conflict notes (see header docstring and suggested spec edits).
    spec_notes.append(
        'CONFLICT NOTE 1 (--min_radius): the task says --min_radius is now applied per view in each '
        'prediction set\'s own native 2D slice plane before backprojection. Spec flag #8 and item 5 '
        'already agree, but earlier prose ("transverse-plane radius", deferred Sagittal/Coronal pass, '
        'post-backprojection Radial/Tilted pass) conflicted. Per the task, --min_radius is now applied '
        'on every view\'s native slices during per-view cleanup and is NOT re-applied after '
        'backprojection. Suggested spec edit: delete every "transverse plane" reference for --min_radius '
        'and state "measured on the YOLO output masks in each prediction set\'s own native 2D slice '
        'plane, before backprojection, independently per active view".'
    )
    if str(retina_processor).strip().lower() == 'gpu':
        spec_notes.append(
            'v13.1.0 (#2.2): GPU retina-mask flatten + warp. The (n,H,W) retina-mask stack is reduced on '
            'the GPU to a union plane and a max-confidence plane, and both are warped to view-native space '
            'on the GPU (torch grid_sample), so only the view-native planes cross PCIe (O(2*H*W)); no '
            'affine warp and no per-instance loop run on the CPU.'
        )
    if single_angle_gpu_fastpath_active:
        spec_notes.append(
            'v13.1.0 (#2.3) + v13.3.0 (R8): single-angle GPU fast path. YOLO -> proto-resolution union '
            '(R9) -> --min_conf -> warp (identity-skipped/grid-cached) -> --min_radius (cupy, only when '
            'positive) run on the GPU, then one finished view-native plane is sent to the CPU. The '
            'per-frame GPU 2D hole fill is removed: the final per-view volume pass performs the hole '
            'fill once, preserving the spec order --min_conf -> --min_radius -> hole fill.'
        )
    if str(retina_processor).strip().lower() == 'gpu':
        spec_notes.append(
            'v13.3.0 (R9/R18/R1/R21): GPU retina unions are reduced at PROTO resolution inside a patched '
            'construct_result (one plane upsampled per frame instead of an (n, imgsz, imgsz) retina stack; '
            'YOLO_TTA_GPU_PROTO_UNION=0 restores the native path); the GPU postprocess tail runs on '
            'per-thread side CUDA streams with pinned D2H staging (YOLO_TTA_GPU_POSTPROCESS_STREAM / '
            'YOLO_TTA_GPU_POSTPROCESS_PINNED); and multi-GPU workers render full-frame views on their own '
            'GPU when the source volume fits resident (YOLO_TTA_GPU_RENDER / YOLO_TTA_GPU_RENDER_RESIDENT '
            '/ YOLO_TTA_GPU_RENDER_RESERVE_GIB), with radial tasks GPU-prerendered from streamed t-blocks '
            'otherwise (YOLO_TTA_GPU_RENDER_TBLOCK_SLICES).'
        )
    spec_notes.append(
        'v13.3.1 (R3/R4/R7b/R12/R16/R19/R24/R25): scratch memmap msync is opt-in (YOLO_TTA_MSYNC, '
        'default off — same-host page-cache coherence needs no synchronous flushes); single-angle '
        'multi-GPU workers write result slice windows directly into the disk-backed per-view union '
        '(YOLO_TTA_MGPU_DIRECT_UNION); NRRD payload writes stream bounded double-buffered blocks '
        '(YOLO_TTA_NRRD_Z_CHUNK_SLICES) filled by a GIL-releasing pool (YOLO_TTA_NRRD_FILL_WORKERS) '
        'that overlaps pigz; multi-GPU runs allocate the processing volume disk-backed from the start '
        '(no post-decode copy to scratch); foreground scans and the raw-bbox encoder no longer make '
        'full-slice cast copies, and interpolation bridge-delta layers reuse the pass added_voxels '
        'stat instead of rescanning; the interpolation merge visits only schedule-touched slices; '
        'NRRD pigz level defaults to 3 (YOLO_TTA_NRRD_PIGZ_LEVEL) and low-quality MP4s use x264 '
        'preset medium (YOLO_TTA_X264_PRESET).'
    )
    spec_notes.append(
        'v13.3.2 (R5/R6/R10/R14/R15/R21): CPU tilted rendering hoists all frame-invariant shear '
        'math into the render plan (contiguous row fast path where separable, single clipped flat '
        'gather otherwise); radial backprojection skips empty cross-sections and streams through '
        'the GPU when available (YOLO_TTA_GPU_BACKPROJECT); the interpolation compact relabel is '
        'bbox-restricted and numba-nogil when available; keep_objects harvests component areas '
        'during 2D labeling (no full-volume bincount, no compact relabel, untouched slices are '
        'never rewritten); tilted scatter and CUDA input staging drop redundant casts/copies '
        '(staging now ships pinned uint8 and normalizes on device); coronal frame reads and '
        'projection writes go through K-column transposed blocks (YOLO_TTA_CORONAL_BLOCK_COLS / '
        'YOLO_TTA_CORONAL_BLOCK_CACHE); global/transverse NRRD layers encode straight from the '
        'source volume (no pre-encode copy); and single-angle fast-path tasks accumulate their '
        'unions in an on-device volume with one chunked pinned D2H per task '
        '(YOLO_TTA_GPU_DEVICE_UNION) when VRAM allows.'
    )
    if preprocess_streaming_active:
        spec_notes.append(
            'v12.2.15 streaming preprocessing is active: decoded native slices become available as ffmpeg produces them. Transverse readers wait only for the needed decoded slice; stack-sampling view families wait for the completed decoded volume. Legacy cube resize, when explicitly enabled, still streams its output slices.'
        )
    else:
        spec_notes.append(
            'v12.2.15 streaming preprocessing is disabled by YOLO_TTA_STREAMING_PREPROCESS=0; decode finishes before inference scheduling begins, and legacy cube resize runs only when explicitly requested.'
        )
    if background_model_load_enabled():
        spec_notes.append(
            'v12.2.11 startup overlap is active: the YOLO model load is submitted before ffprobe/decode/native-volume preparation and joined only when the scheduler needs the model for prediction. Set YOLO_TTA_BACKGROUND_MODEL_LOAD=0 to restore synchronous model loading.'
        )
    if bool(single_angle_streaming_cleanup_active):
        spec_notes.append(
            'v12.2.8 single-angle streaming cleanup is active: exactly one --angle value was supplied, so YOLO result slices are confidence-filtered and view-native min_radius-filtered as they stream in. v13.1.0 applies the full --min_radius on every view\'s own native 2D slices (no deferred transverse-plane pass and no post-backprojection radius stage). 2D hole filling runs as a final per-view volume pass (after --min_conf and --min_radius) before interpolation.'
        )
    else:
        spec_notes.append(
            'v12.2.8 single-angle streaming cleanup is inactive because multiple --angle values are being accumulated or YOLO_TTA_SINGLE_ANGLE_STREAMING_CLEANUP=0; view cleanup therefore runs after all angle volumes for a view have accumulated.'
        )
    spec_notes.append('Input video channel handling: RGB/YUV inputs are flattened to one gray/luma channel during decode; single-channel Y/gray inputs remain single-channel, and YOLO receives H×W×1 frames.')
    spec_notes.append('Voxel-volume reporting, when enabled, counts the final binary mask after restoration to native input geometry, not imgsz or cubic working geometry.')
    spec_notes.append('v12.2.0 tilt-angle validation follows the specification: values must be greater than 0 and less than or equal to 45 degrees.')
    if low_quality_downbin_warnings:
        for warning in low_quality_downbin_warnings:
            print(f'Warning: {warning}')
            spec_notes.append(warning)
    if low_quality_downbin_specs:
        spec_notes.append(
            'Low-quality outputs use isotropic X/Y/t downbinning in native input space; frame count is resampled with the same scale as XY, rather than preserving the original frame count. '
            + '; '.join(
                f'{spec.raw_value}->(t,Y,X)={spec.output_shape_t_y_x}'
                for spec in low_quality_downbin_specs
            )
        )
        spec_notes.append(
            'v13.2.1 (bug #2): each low-quality downbin is submitted as an independent background job whose '
            'overlay and binary videos always run. When --save_nrrd is also enabled, the low-quality NRRD now '
            'follows the full-quality format and schedule: one downbinned single-layer NRRD per component layer '
            'under low_quality/<token>/nrrd/, written by the NrrdLayerSink as each view completes (sharing the '
            'full-quality layer suffixes and a per-downbin manifest), replacing the single combined tail volume. '
            'Requesting only low-quality outputs still produces the low-quality videos but no NRRD.'
        )
    if (int(T), int(H), int(W)) != (int(input_T), int(input_H), int(input_W)):
        spec_notes.append(
            f'Working volume resized to v12.2.0 approximately-cubic processing geometry '
            f'(t,Y,X)=({int(T)},{int(H)},{int(W)}). v13.2.4 (ruling A1): the final stage runs in the '
            f'original source geometry (t,Y,X)=({int(input_T)},{int(input_H)},{int(input_W)}) — '
            'Radial/Tilted results are backprojected directly to source dimensions in a single resample, '
            'Cartesian view stacks are restored with one resample during union assembly, and the global '
            'union / optional 3D void fill / Gaussian smoothing (sigma in source voxels) / --keep_objects '
            'all execute at source dimensions. No tail restore resample occurs.'
        )
    spec_notes.append(
        f'Sagittal enabled={bool(enable_sagittal)}, Coronal enabled={bool(enable_coronal)}; '
        'their non-90 degree Cartesian augmentations use clamp-to-frame black fill rather than expanded padding.'
    )
    if tilt_angles:
        active_tilt_labels = ', '.join(pretty_view_name(v) for v in views if is_tilted_view(v))
        spec_notes.append(
            f'Generalized v12 Tilted Views active from --tilt_view={list(tilt_views)}, '
            f'--tilt_direction={list(tilt_directions)}, --tilt_angle={[float(v) for v in tilt_angles]}. '
            'Tilted base views do not need to be enabled as upright Cartesian views; each base/direction/signed-angle configuration remains independent until final union. '
            f'Active tilted configurations: {active_tilt_labels}'
        )
    else:
        spec_notes.append('Tilted Views disabled because --tilt_angle resolved to 0/no non-zero angles.')
    if float(resolved_azimuth_angle) > 0.0:
        spec_notes.append(
            f'Radial enabled with azimuth spacing {float(resolved_azimuth_angle):.8g} degrees; '
            'Lanczos-3 radial sampling, wraparound Radial interpolation, and dense final backprojection are active.'
        )
    if any((v.family == 'radial' or is_tilted_view(v)) for v in views):
        spec_notes.append(
            'v12.2.11 final Radial and Tilted backprojection is CPU-only. The old CuPy/GPU backprojection slot is disabled so the GPU remains dedicated to YOLO inference; each backprojection set receives the full resolved CPU slice-worker budget.'
        )
    spec_notes.append(
        'v13.2.0 NRRD export (--save_nrrd) writes one single-layer 3-axis NRRD (X,Y,t) per component layer to '
        'nrrd/, named {Filestem}_{ViewToken|Global}_{layer}.seg.nrrd (model name dropped; v13.2.3 tags each file '
        'with the 3D Slicer segmentation header fields — segment named after the file, deterministic per-layer '
        'palette color). Layer families: full-frame '
        'YOLO masks, full-frame interpolation bridges per pass, tiled masks accepted by parent YOLO masks, tiled '
        'masks accepted by parent bridges, consolidated tile bridges per pass, Global_union_presmoothing, '
        'Global_smoothing_pass<N>, and Global_final_output. Each layer is restored to source output geometry while '
        'streaming, gzip-compressed in one pigz pass, and written by a background sink as the layer is produced '
        'during the intermediate pipeline steps (so the Transverse layer compresses while Tiled Transverse is still '
        'inferencing, and the global union layer is written while smoothing runs). A single '
        '{Filestem}_nrrd_manifest.json lists every written layer. Tune YOLO_TTA_NRRD_PIGZ_LEVEL, '
        'YOLO_TTA_NRRD_SINGLE_LAYER_PIGZ_THREADS, and YOLO_TTA_NRRD_LAYER_SINK_WORKERS if needed. The previous mega '
        f'4D decomposed NRRD (one file, trailing list axis) was removed. space={NRRD_SPACE}.'
    )
    spec_notes.append(
        'CONFLICT NOTE 2 (single-layer NRRD filenames): spec 7.2 lists layer family #5 ("Tiled Bridges") with the '
        'same filename token as family #4 ("Tiled YOLO masks accepted by Parent Bridges", '
        '{Filestem}_{ViewToken}_tile_yolo_parent_bridge), which would collide. The implementation keeps them '
        'distinct: tiles accepted by a parent bridge are {ViewToken}_tile_yolo_parent_bridge, while consolidated '
        'tile interpolation bridges are {ViewToken}_tile_bridge_pass<N>. Suggested spec edit: rename family #5 to '
        '{Filestem}_{ViewToken}_tile_bridge_pass<N> to match the per-pass consolidated tile bridge layers.'
    )
    spec_notes.append(
        'CONFLICT NOTE 3 (low-quality NRRD form): spec --save_low_quality says "low bitrate output videos and '
        'NRRDs". v13.2.1 (bug #2) makes the low-quality NRRD follow the full-quality NRRD format and scheduling: '
        'one downbinned single-layer NRRD per component layer under low_quality/<token>/nrrd/, restored from the '
        'same NrrdLayerRef and written as each view completes, with a per-downbin manifest whose layer suffixes '
        'match the full-quality nrrd/ folder. This supersedes the v13.2.0 single combined volume. It remains gated '
        'behind --save_nrrd (the decomposition is only meaningful when --save_nrrd is set). Suggested spec edit: '
        'state that low-quality NRRDs are emitted as one single-layer NRRD per component layer (downbinned) per '
        '--save_low_quality_downbin spec, only when --save_nrrd is enabled.'
    )
    spec_notes.append(
        'Task #2.5 review (single-angle fast path / tqdm): YOLO -> flatten -> --min_conf -> warp -> --min_radius -> '
        '2D hole fill all run on the GPU (cupy) and only the finished view-native plane crosses PCIe; the per-slice '
        'CPU cleanup is skipped via cleanup_done_on_gpu. No tqdm bar wraps the inference stream, so any tqdm the '
        'user sees that does not line up with GPU work is a separate post-inference progress bar (a purely visual '
        'artifact), not masks being shuttled CPU<->GPU. The fast path was left unchanged, as instructed.'
    )
    spec_notes.append(
        f'v13.0.0 inference devices: {inference_devices} '
        f'({"multi-GPU process-per-GPU scheduling" if multi_gpu_active else "single device"}). '
        + (
            'Multi-GPU runs one worker PROCESS per GPU (each pinned via CUDA_VISIBLE_DEVICES and loading its '
            'own model replica), pulling inference-ready full-frame/tile prediction volumes from a shared queue '
            'so every GPU stays busy while work remains. Processes avoid the CPython GIL serialization that makes '
            'thread-per-GPU inference no faster than a single GPU. Each worker renders+predicts+accumulates one '
            'volume into a file-backed per-volume result memmap; the main process unions those results into the '
            'per-view union (max-confidence) and runs all postprocessing/interpolation/output.'
            if multi_gpu_active else
            'Single-device inference uses the in-process serial GPU dispatch path.'
        )
    )
    if cpu_retina_masks_enabled():
        spec_notes.append(
            f'Retina mask processor: cpu ({retina_processor_reason}). Deferred CPU retina-mask reconstruction active: '
            'retina_masks=False is passed to YOLO; compact mask protos/coefficients/boxes/scores are moved to CPU and '
            'bbox-ROI retina-quality masks are reconstructed on the CPU by bilinear-upsampling mask logits within each '
            'detection ROI, thresholding at zero, and dropping empty masks, so the scheduler/model-stream thread does '
            'not perform per-slice full-mask GPU copies.'
        )
    else:
        spec_notes.append(
            f'Retina mask processor: gpu ({retina_processor_reason}). Ultralytics native retina_masks=True resolves '
            'full-resolution masks on the GPU, freeing CPU cores for view creation/postprocessing (preferred for '
            'multi-GPU, CPU-bound configurations).'
        )
    if bool(troubleshooting_outputs_enabled):
        spec_notes.append(
            '--troubleshooting active: writing FFV1 MKV overlays for each active full-frame native view and each available consolidated tiled prediction set; '
            'temporary scratch retention is not implied.'
        )
    if bool(keep_temp_artifacts):
        spec_notes.append('YOLO_TTA_KEEP_TEMP=1 active: temporary scratch artifacts are retained independently of --troubleshooting.')
    if bool(gaussian_smoothing_enabled):
        spec_notes.append(
            f'Gaussian smoothing active by v12.2.0 explicit-flag rule: sigma={float(gaussian_smoothing_sigma):g} voxel(s), '
            f'passes={int(gaussian_smoothing_passes)}; applied after final union/optional 3D void fill and before --keep_objects. '
            'The default smoothing backend attempts chunked GPU execution through CuPy/cupyx.scipy.ndimage with halo/core writes, then falls back to scipy.ndimage on CPU if the GPU backend is unavailable.'
        )
    else:
        if not bool(gaussian_smoothing_cli_requested):
            spec_notes.append('Gaussian smoothing disabled by v12.2.0 activation rule because neither Gaussian flag was explicitly set.')
        elif bool(gaussian_smoothing_disabled_by_zero):
            spec_notes.append('Gaussian smoothing disabled because at least one explicitly supplied Gaussian flag was set to 0.')
        else:
            spec_notes.append('Gaussian smoothing disabled because the resolved sigma or pass count was not positive.')
    spec_notes.append(
        'Interpolation endpoint discovery uses the per-slice connected-component scan backed by cached per-slice component tables. '
        'Projection candidate search runs on source-component local SDF crops, and variable-cost seed planning is consumed through a bounded unordered completion queue. '
        'v13.0.0 removed optional skeletonization entirely; interpolation never used skeletonization.'
    )
    spec_notes.append(
        f'Processing volume mode={processing_mode}; cube_resize_applied={bool(tuple(int(x) for x in processing_shape) != tuple(int(x) for x in input_processing_shape))}. '
        'v13.0.0 (bug fix) defaults to approximately-cubic virtual working geometry so the working dimensions '
        'stay within 5% of the longest source axis (spec item 2); the t/Transverse stacking axis is no longer left short. '
        f'Approximately-cubic target = {tuple(int(x) for x in legacy_cube_shape)}. Set YOLO_TTA_PROCESSING_VOLUME_MODE=native to opt back into v12.2.15 decoded-native geometry for regression. '
        f'Cube T-axis backend={_cube_t_axis_resize_backend()} (YOLO_TTA_CUBE_T_RESIZE_BACKEND=slice_exact restores the endpoint-aligned per-slice interpolation path).'
    )
    if transverse_inference_disabled:
        note = (
            'v12.2.0 specification note: Section 2.1.1 says Transverse is enabled by default, while '
            'View Flags item 1 adds --disable_transverse to skip Transverse inferencing. This implementation '
            'keeps Transverse geometry/output paths available and removes only the standard Transverse full-frame '
            'and tiled prediction jobs.'
        )
        spec_notes.append(note)
        print(note)

    if model_load_future is not None:
        print(f'Waiting for background model load to finish: {model_name} ({model_paths[0]})')
        yolo_model = model_load_future.result()
        if model_load_executor is not None:
            model_load_executor.shutdown(wait=True)
            model_load_executor = None
    else:
        print(f'Loading model: {model_name} ({model_paths[0]})')
        yolo_model = load_ultralytics_model(model_paths[0], task='segment')
    # v12.2.0/v13.0.0 has no multiple-model inference. A single-item list is retained only to
    # minimize churn in scheduling structures keyed by model stem. yolo_by_model_name still maps the
    # model stem to the primary replica (used by the single-GPU dispatch path).
    yolo_models: List[Tuple[str, object]] = [(model_name, yolo_model)]
    yolo_by_model_name: Dict[str, object] = {model_name: yolo_model}

    # pred_cfg describes the primary device used by the single-GPU/CPU in-process inference path.
    pred_cfg = PredictConfig(
        imgsz=args.imgsz,
        conf=args.conf,
        device=str(inference_devices[0]),
        half=bool(args.half),
        int8=bool(args.int8),
        batch=max(1, int(args.batch)),
    )

    if not multi_gpu_active:
        # Single-GPU / CPU: inference runs in the main process. Pin the model to its device and
        # pre-apply the global Ultralytics monkeypatches once on the main thread.
        ensure_yolo_ready_for_predict(yolo_model, pred_cfg)
        try:
            ensure_single_channel_yolo_preprocess_patch()
        except Exception as _patch_exc:  # pragma: no cover - patch is best-effort
            print(f'Warning: single-channel preprocess patch could not be pre-applied ({_patch_exc}).')
        if cpu_retina_masks_enabled():
            try:
                ensure_cpu_retina_mask_predictor_patch()
            except Exception as _patch_exc:  # pragma: no cover - patch is best-effort
                print(f'Warning: CPU retina predictor patch could not be pre-applied ({_patch_exc}).')
    else:
        # Multi-GPU: inference runs in one worker PROCESS per GPU (see _gpu_inference_worker_main).
        # Each worker loads its own model replica and applies the patches in its own interpreter, so
        # the main-process model stays on CPU and is not used for inference. This avoids the CPython
        # GIL serialization that makes thread-per-GPU inference no faster than a single GPU.
        print(
            f'Multi-GPU: inference will run in {gpu_device_count} per-GPU worker process(es) '
            f'{inference_devices}; the main-process model stays on CPU.'
        )


    # v13.1.0 (#2.1): size main-process pools GPU-count aware. In multi-GPU runs the per-GPU
    # inference subprocesses already consume ~visible_cpu render threads (the GPU-blocking pools), so
    # the main-process GPU-non-blocking pools take only the remaining headroom of the 2x box target.
    # Single-GPU keeps the full 2x budget (inference is in-process).
    worker_budget = int(main_process_worker_budget(int(gpu_device_count), bool(multi_gpu_active)))
    whole_box_worker_budget = int(default_worker_budget())
    augmentation_workers = resolve_worker_count(
        0,
        'YOLO_TTA_AUG_WORKERS',
        worker_budget,
        max_tasks=max(1, max((v.num_slices for v in inference_views), default=1)),
    )
    interpolation_workers = resolve_worker_count(
        0,
        'YOLO_TTA_INTERPOLATION_WORKERS',
        worker_budget,
        max_tasks=max(1, len(yolo_models) * max(1, len(interpolating_views))),
    )
    output_workers = resolve_worker_count(
        0,
        'YOLO_TTA_OUTPUT_WORKERS',
        worker_budget,
    )
    output_frame_workers = max(1, _env_int('YOLO_TTA_OUTPUT_FRAME_WORKERS', max(1, min(_cpu_count(), output_workers))))
    slice_postprocess_workers = max(1, int(augmentation_workers))
    predict_postprocess_cap = max(1, _env_int('YOLO_TTA_PREDICT_POSTPROCESS_MAX_WORKERS', max(1, int(worker_budget))))
    predict_postprocess_workers = max(
        1,
        min(
            int(predict_postprocess_cap),
            _env_int('YOLO_TTA_PREDICT_POSTPROCESS_WORKERS', slice_postprocess_workers),
        ),
    )

    parent_postprocess_workers = max(1, min(int(interpolation_workers), max(1, len(yolo_models) * max(1, len(inference_views)))))
    (
        parent_interpolation_overlap,
        parent_interpolation_task_workers_default,
        parent_interpolation_task_workers,
    ) = resolve_parent_interpolation_worker_allocation(
        worker_budget=int(worker_budget),
        parent_postprocess_workers=int(parent_postprocess_workers),
    )

    tile_postprocess_workers_default = int(worker_budget)
    tile_postprocess_workers = max(1, _env_int('YOLO_TTA_TILE_POSTPROCESS_WORKERS', tile_postprocess_workers_default))
    tile_slice_postprocess_workers_default = int(worker_budget)
    tile_slice_postprocess_workers = max(
        1,
        _env_int('YOLO_TTA_TILE_SLICE_WORKERS', tile_slice_postprocess_workers_default),
    )
    tile_interpolation_task_workers_default = max(1, _cpu_count())
    tile_interpolation_task_workers = max(
        1,
        _env_int('YOLO_TTA_TILE_INTERPOLATION_TASK_WORKERS', tile_interpolation_task_workers_default),
    )

    interpolation_process_backend_active = bool(interpolation_process_backend_enabled() and int(args.interpolate) > 0)
    # v13.3.3: default raised from min(2, ...) — 11 views queued behind 2 process GILs was the
    # dominant wall-clock tail. Each child allocates its own pass workspace (memory-gated with a
    # disk-backed fallback), so the cap trades RAM headroom for parallel interpolation GILs.
    interpolation_process_workers_default = max(
        1,
        min(
            int(INTERPOLATION_PROCESS_WORKER_DEFAULT_CAP),
            max(1, int(parent_postprocess_workers)) + (1 if len(tile_configs) > 0 else 0),
        ),
    )
    interpolation_process_workers = (
        max(1, _env_int('YOLO_TTA_INTERPOLATION_PROCESS_WORKERS', interpolation_process_workers_default))
        if bool(interpolation_process_backend_active) else 0
    )

    print(f'Allocated CPU count: {_cpu_count()}')
    print(f'Worker budget (main process): {worker_budget}')
    if bool(multi_gpu_active):
        _gpu_share = int(multi_gpu_worker_share(int(gpu_device_count)))
        print(
            'Worker oversubscription is intentional (whole-box target = 2x visible CPUs = '
            f'{whole_box_worker_budget}). Multi-GPU ({gpu_device_count} GPUs): each per-GPU inference '
            f'subprocess uses ~{_gpu_share} render thread(s) ({_gpu_share * int(gpu_device_count)} total '
            'for GPU-blocking work), so the GPU-non-blocking main-process pools are sized to the '
            f'remaining {worker_budget} to keep the box near 2:1 instead of oversubscribing it.'
        )
    else:
        print('Worker oversubscription is intentional (budget = 2x visible CPUs; inference is in-process).')
    print(f'Augmentation workers: {augmentation_workers}')
    print(f'Slice-parallel postprocess workers: {slice_postprocess_workers}')
    print(f'Inference postprocess workers: {predict_postprocess_workers}')
    print(
        'Parent full-frame postprocess workers: '
        f'{parent_postprocess_workers} (expected interpolation overlap: {parent_interpolation_overlap}, '
        f'per-parent interpolation workers: {parent_interpolation_task_workers})'
    )
    print(
        'Tile postprocess workers: '
        f'{tile_postprocess_workers} (per-tile slice workers: {tile_slice_postprocess_workers}, '
        f'consolidated-tile interpolation workers: {tile_interpolation_task_workers})'
    )
    if bool(interpolation_process_backend_active):
        print(
            'Interpolation process backend: enabled '
            f'(process workers: {int(interpolation_process_workers)}, start_method={interpolation_process_start_method()}, '
            f'child cv2_threads={interpolation_process_cv2_threads()}, compiled kernels: {interpolation_compiled_kernels_status()})'
        )
    else:
        print('Interpolation process backend: disabled (legacy in-process interpolation path).')
    print(f'Background output workers: {output_workers} (frame workers per labels/TIFF task: {output_frame_workers})')
    max_predict_video_frames = max(1, max((int(v.num_slices) for v in inference_views), default=1))
    example_cpu_mask_workers = max(1, min(int(predict_postprocess_workers), int(max_predict_video_frames)))
    example_cpu_mask_pending = cpu_mask_postprocess_pending_limit(int(example_cpu_mask_workers), int(max_predict_video_frames))
    spec_notes.append(
        'YOLO result accumulation is bounded per in-memory prediction source by the number of pending CPU postprocess futures. ' 
        'worker_count=max(1, min(YOLO_TTA_PREDICT_POSTPROCESS_WORKERS, num_frames)) for the live v12 in-memory source path; ' 
        'v12.2.15 keeps the v12.2.14 hard 32-worker ceiling removed and defaults YOLO_TTA_PREDICT_POSTPROCESS_MAX_WORKERS to the oversubscribed worker budget so CPU result processing can queue/drain behind the GPU instead of throttling inference. '
        'pending_limit=cpu_mask_postprocess_pending_limit(worker_count, num_frames) = max(worker_count, min(num_frames, max(YOLO_TTA_CPU_MASK_PENDING_FRAMES, worker_count*2))). ' 
        'The default YOLO_TTA_CPU_MASK_PENDING_FRAMES is 0, so the GPU-facing iterator can buffer all CPU result work for that prediction source; set it positive only to reintroduce a RAM cap. ' 
        f'For this run, the largest active prediction source has {int(max_predict_video_frames)} frame(s), ' 
        f'example worker_count={int(example_cpu_mask_workers)}, pending_limit={int(example_cpu_mask_pending)}.'
    )
    spec_notes.append(
        f'Batched inference active with --batch={int(args.batch)}. StreamingYoloVolumeSource is used by default for full-frame/tile sources: it renders a bounded CPU prefetch window of H×W×1 slices and pads the final batch by repeating the last real slice; CUDA input staging can additionally queue YOLO_TTA_GPU_INPUT_STAGING_BATCHES/GPU_PREFETCH_BATCHES complete preprocessed batches in VRAM ahead of inference; set YOLO_TTA_STREAMING_PREDICTION_SOURCES=0 to restore dense in-memory prediction-volume materialization.'
    )
    spec_notes.append(
        'Tiled masks are staged into one consolidated parent-view canvas per --tile_size/--tile_stride configuration before gating; '
        'the canvas gate is slice-local and connected-component based, so seam-split tile objects are reassembled before support testing. '
        'A tile mask shape guard validates/resizes every postprocessed tile to its parent view-native shape. '
        f'v12.2.11 keeps waiting tiles and tile-set/category accumulators in RAM by default (YOLO_TTA_SPILL_WAITING_TILES={int(waiting_tile_spill_enabled())}, YOLO_TTA_TILE_ACCUMULATORS_IN_RAM={int(tile_intermediate_accumulators_prefer_memory())}); disk ctile spill is now opt-in.'
    )
    spec_notes.append(
        'Postprocessed tiles waiting for parent support stay in RAM by default and use ctile-mask-v2-raw only when YOLO_TTA_SPILL_WAITING_TILES=1; decomposed NRRD/support layers use cvol-mask-v2-raw where enabled: empty slices are elided, '
        'nonempty slices are cropped to their nonzero bbox and written as raw uint8 payload bytes; bitpacking and LZ4 are not used. '
        'Storage review: dense gray8 source/processing volumes stay raw; uint8 confidence maps are allocated only when --min_conf > 0 and stay raw because they are not sparse binary masks; FFV1/MKV/TIFF outputs remain codec-compressed; labels/summary JSON are negligible; retained sparse binary scratch/tile accumulators can be archived as raw bbox cvol when YOLO_TTA_KEEP_TEMP and YOLO_TTA_ARCHIVE_TEMP_BINARY_VOLUMES are enabled.'
    )
    spec_notes.append(
        f'Fused cleanup backend={cleanup_backend()}; set YOLO_TTA_CLEANUP_BACKEND=scipy to use the previous scipy.ndimage cleanup path.'
    )
    spec_notes.append(
        'Interpolation labeling uses parallel 2D per-slice connected-component labeling, parallel adjacent-slice pair extraction, '
        'row-blocked parallel compact relabeling, and unordered prebuilt per-slice component tables for endpoint scanning. '
        f'Per-parent interpolation task workers default to worker_budget / expected_live_parent_overlap = {int(parent_interpolation_task_workers_default)} '
        f'using YOLO_TTA_INTERPOLATION_CONCURRENT_PARENTS={int(parent_interpolation_overlap)}; '
        'YOLO_TTA_INTERPOLATION_TASK_WORKERS still overrides the exact per-parent worker count. '
        'Tune YOLO_TTA_INTERPOLATION_LABEL_WORKERS, YOLO_TTA_INTERPOLATION_PAIR_WORKERS, YOLO_TTA_INTERPOLATION_COMPACT_WORKERS, '
        'YOLO_TTA_INTERPOLATION_COMPACT_RELABEL_ROWS, and YOLO_TTA_INTERPOLATION_CONCURRENT_PARENTS if needed.'
    )
    spec_notes.append(
        'v12.2.7 interpolation process isolation active by default: full-frame and consolidated-tile interpolation passes reopen uint8 mask volumes from disk-backed memmaps in a ProcessPoolExecutor worker and return only small stats. '
        f'Process backend enabled={bool(interpolation_process_backend_active)}, process_workers={int(interpolation_process_workers)}, start_method={interpolation_process_start_method()}, '
        f'fallback_on_worker_failure={bool(interpolation_process_fallback_enabled())}. Anonymous in-memory mask arrays are copied once to a process memmap before interpolation, avoiding multi-GiB pickle payloads.'
    )
    spec_notes.append(
        f'v12.2.7 compiled interpolation kernels: {interpolation_compiled_kernels_status()}. '
        'The compiled kernel accelerates projection-candidate discovery in seed planning with Numba nogil=True when numba is installed; the exact Python candidate search remains the fallback.'
    )

    output_manager = BackgroundOutputManager(max_workers=output_workers)

    if augmentation_workers > 1 or interpolation_workers > 1 or slice_postprocess_workers > 1 or output_workers > 1:
        try:
            cv2.setNumThreads(1)
        except Exception:
            pass

    interpolation_process_executor: Optional[ProcessPoolExecutor] = None
    if bool(interpolation_process_backend_active):
        interpolation_process_executor = create_interpolation_process_executor(int(interpolation_process_workers))
        set_interpolation_process_executor(interpolation_process_executor, int(interpolation_process_workers))
    else:
        set_interpolation_process_executor(None, 0)

    dense_tiling_active = len(tile_configs) > 0
    view_infos_by_name: Dict[str, ViewInfo] = {view.name: view for view in views}
    view_volumes_by_model: Dict[str, Dict[str, np.ndarray]] = {model_name: {} for model_name, _ in yolo_models}
    native_view_support_by_model: Dict[str, Dict[str, np.ndarray]] = {model_name: {} for model_name, _ in yolo_models}
    parent_mask_support_by_model: Dict[str, Dict[str, object]] = {model_name: {} for model_name, _ in yolo_models}
    parent_bridge_support_by_model: Dict[str, Dict[str, object]] = {model_name: {} for model_name, _ in yolo_models}
    radial_native_output_by_model: Dict[str, Dict[str, np.ndarray]] = {model_name: {} for model_name, _ in yolo_models}
    tilted_native_output_by_model: Dict[str, Dict[str, np.ndarray]] = {model_name: {} for model_name, _ in yolo_models}
    nrrd_layer_refs: List[NrrdLayerRef] = []
    view_volume_locks: Dict[Tuple[str, str], threading.Lock] = {
        (model_name, view.name): threading.Lock()
        for model_name, _ in yolo_models
        for view in views
    }

    aug_jobs_by_view: Dict[str, List[AugJob]] = {}
    aug_job_lookup_by_view: Dict[str, Dict[str, AugJob]] = {}
    tile_jobs_by_view_config: Dict[str, Dict[str, List[DenseTileJob]]] = {view.name: {} for view in views}
    tile_jobs_by_aug: Dict[Tuple[str, str], List[DenseTileJob]] = {}
    view_prediction_stats: Dict[str, int] = {
        'transverse': 0,
        'sagittal': 0,
        'coronal': 0,
        'radial': 0,
    }
    view_prediction_labels: Dict[str, str] = {
        'transverse': 'Transverse',
        'sagittal': 'Sagittal',
        'coronal': 'Coronal',
        'radial': 'Radial',
    }
    for _view_for_stats in views:
        if is_tilted_view(_view_for_stats):
            view_prediction_stats.setdefault(str(_view_for_stats.summary_family), 0)
            view_prediction_labels[str(_view_for_stats.summary_family)] = pretty_view_name(_view_for_stats)
    interpolation_stats: List[Dict[str, object]] = []

    inference_view_names = {v.name for v in inference_views}
    for view in views:
        jobs = build_aug_jobs_for_view(
            view=view,
            angles=angles,
            out_size=args.imgsz,
            temp_dir=temp_dir,
        )
        aug_jobs_by_view[view.name] = jobs
        aug_job_lookup_by_view[view.name] = {job.aug_id: job for job in jobs}
        if dense_tiling_active and view.name in inference_view_names:
            jobs_by_config: Dict[str, List[DenseTileJob]] = {}
            for tile_cfg in tile_configs:
                cfg_jobs: List[DenseTileJob] = []
                for aug_job in jobs:
                    built_jobs = build_dense_tile_jobs_for_aug(
                        view=view,
                        aug_job=aug_job,
                        tile_cfg=tile_cfg,
                        out_size=int(args.imgsz),
                        temp_dir=temp_dir,
                    )
                    cfg_jobs.extend(built_jobs)
                    tile_jobs_by_aug.setdefault((view.name, aug_job.aug_id), []).extend(built_jobs)
                if cfg_jobs:
                    jobs_by_config[tile_cfg.config_id] = cfg_jobs
            if jobs_by_config:
                tile_jobs_by_view_config[view.name] = jobs_by_config

    tile_expected_by_parent_config: Dict[Tuple[str, str, str], int] = {}
    tile_config_expected_by_parent: Dict[Tuple[str, str], int] = {}
    if dense_tiling_active:
        for view in inference_views:
            jobs_by_config = tile_jobs_by_view_config.get(view.name, {})
            if not jobs_by_config:
                continue
            expected_for_view = sum(len(jobs) for jobs in jobs_by_config.values())
            if expected_for_view <= 0:
                continue
            for model_name, _ in yolo_models:
                parent_key = (str(model_name), str(view.name))
                active_config_count = 0
                for config_id, cfg_jobs in jobs_by_config.items():
                    if not cfg_jobs:
                        continue
                    tile_expected_by_parent_config[(str(model_name), str(view.name), str(config_id))] = int(len(cfg_jobs))
                    active_config_count += 1
                tile_config_expected_by_parent[parent_key] = int(active_config_count)

    view_frame_caches: Dict[str, np.ndarray] = {}
    view_frame_cache_paths: Dict[str, Path] = {}
    view_frame_cache_lock = threading.Lock()

    def _get_view_frame_cache(view: ViewInfo) -> Optional[np.ndarray]:
        if not should_cache_view_frames(view, dense_tiling_active):
            return None
        cached = view_frame_caches.get(view.name)
        if cached is not None:
            return cached
        with view_frame_cache_lock:
            cached = view_frame_caches.get(view.name)
            if cached is not None:
                return cached
            wait_for_volume_ready(volume_rgb)
            cache_path = temp_dir / 'view_frames' / f'{view.name}.gray8.dat'
            cache_path.parent.mkdir(parents=True, exist_ok=True)
            cache_mm = build_view_frame_cache(
                volume_rgb=volume_rgb,
                view=view,
                out_path=cache_path,
                desc=f'{view.name} native frame cache',
                prefer_memory=True,
                workers=max(1, int(augmentation_workers)),
            )
            view_frame_caches[view.name] = cache_mm
            view_frame_cache_paths[view.name] = cache_path
            return cache_mm

    baseline_union_by_model_view: Dict[Tuple[str, str], np.ndarray] = {}
    baseline_confmap_by_model_view: Dict[Tuple[str, str], Optional[np.ndarray]] = {}
    baseline_union_paths: Dict[Tuple[str, str], Path] = {}
    baseline_confmap_paths: Dict[Tuple[str, str], Optional[Path]] = {}
    baseline_slice_locks_by_model_view: Dict[Tuple[str, str], List[threading.Lock]] = {}
    fullframe_remaining: Dict[Tuple[str, str], int] = {}
    # v13.3.3 (S2): slices per (model, view) hole-filled on device by the GPU workers; when the
    # sum reaches the view's slice count, the CPU per-view "2D hole fill" pass is skipped.
    view_device_hole_filled_slices: Dict[Tuple[str, str], int] = {}

    for view in inference_views:
        for model_name, _ in yolo_models:
            # v12.2.11 lazy allocation: do not zero every full-view accumulator before the
            # first prediction.  On 20+ view runs those eager zeros can touch hundreds of GiB
            # and dominate time-to-first-prediction.  Allocate a view's union/confidence
            # workspaces only when its first full-frame prediction is about to run.
            fullframe_remaining[(model_name, view.name)] = int(len(aug_jobs_by_view[view.name]))

    total_fullframe_jobs = sum(len(aug_jobs_by_view.get(view.name, [])) for view in inference_views)
    total_tile_prediction_jobs = sum(
        len(tile_jobs_by_aug.get((view.name, aug_job.aug_id), []))
        for view in inference_views
        for aug_job in aug_jobs_by_view[view.name]
    )
    total_prediction_volume_build_tasks = int(total_fullframe_jobs + total_tile_prediction_jobs)
    streaming_sources_active = bool(streaming_prediction_sources_enabled())
    max_prediction_source_frames = max(1, max((int(v.num_slices) for v in inference_views), default=1))
    prediction_render_workers = resolve_prediction_render_workers(
        max(1, int(worker_budget)),
        max_prediction_source_frames,
    )
    prediction_volume_queue_slots = resolve_prediction_source_queue_slots(
        total_prediction_volume_build_tasks,
        streaming_sources=bool(streaming_sources_active),
    )
    eager_gpu_input_staging_ahead_sources = (
        gpu_input_staging_ahead_sources(int(prediction_volume_queue_slots))
        if gpu_input_staging_enabled(pred_cfg)
        else 0
    )
    queued_streaming_cpu_warmup_sources = (
        queued_streaming_source_cpu_warmup_slots(int(prediction_volume_queue_slots))
        if bool(streaming_sources_active)
        else 0
    )
    active_build_slot_default = max(
        1,
        min(
            int(augmentation_workers),
            int(prediction_volume_queue_slots),
            max(1, int(total_prediction_volume_build_tasks)),
        ),
    )
    requested_build_workers = max(
        1,
        _env_int('YOLO_TTA_VOLUME_BUILD_WORKERS', int(active_build_slot_default)),
    )
    prediction_volume_builder_workers = max(
        1,
        min(
            int(augmentation_workers),
            int(prediction_volume_queue_slots),
            max(1, int(total_prediction_volume_build_tasks)),
            int(requested_build_workers),
        ),
    )
    legacy_per_prediction_volume_workers = max(1, int(max(1, augmentation_workers) // max(1, prediction_volume_builder_workers)))
    # Streaming sources submit only a bounded prefetch window, so a single active source should
    # see the full render pool instead of a divided-by-builder slice of the CPU allocation.
    per_prediction_volume_workers = int(prediction_render_workers) if bool(streaming_sources_active) else int(legacy_per_prediction_volume_workers)
    async_prediction_accumulation_active = bool(async_predict_postprocess_enabled())
    async_prediction_multiview_locking_active = bool(len(angles) > 1 and async_prediction_accumulation_active)
    # Queue slots are unbounded by default in v13, so do not size the lightweight join
    # executor from the total source count.  The join tasks mostly wait on result futures;
    # a CPU-count-sized pool is enough to overlap drains without spawning thousands of threads.
    async_prediction_join_worker_count = async_predict_join_workers(max(2, min(max(1, _cpu_count()), int(worker_budget))))
    default_async_result_workers = max(1, int(predict_postprocess_workers))
    async_prediction_result_worker_count = max(
        1,
        min(
            int(predict_postprocess_workers),
            _env_int('YOLO_TTA_ASYNC_PREDICT_RESULT_WORKERS', int(default_async_result_workers)),
        ),
    )
    if bool(async_prediction_accumulation_active):
        print(
            'Async prediction accumulation: enabled '
            f'(angles={len(angles)}, result workers={int(async_prediction_result_worker_count)}, '
            f'join workers={int(async_prediction_join_worker_count)}, '
            f'per-slice locks for multi-angle full-frame writes={bool(async_prediction_multiview_locking_active)})'
        )
        spec_notes.append(
            'v12.2.12 async prediction accumulation is active for all angle counts by default. '
            'YOLO result detach/copy, native inverse-mapping, and optional streaming cleanup are queued to a shared prediction-result executor; '
            'for multi-angle full-frame accumulation, per-slice locks protect shared union/confidence slices so the scheduler can start the next source while CPU result work drains.'
        )
    else:
        print('Async prediction accumulation: disabled by YOLO_TTA_ASYNC_PREDICT_POSTPROCESS=0; prediction sources are drained synchronously.')
        spec_notes.append(
            'v12.2.12 async prediction accumulation was disabled by configuration; prediction sources are drained synchronously.'
        )
    spec_notes.append(
        'v12.2.12 streaming prediction sources are active by default: full-frame and tiled YOLO inputs render only a bounded CPU prefetch window before model.predict starts, rather than materializing a complete (slice,--imgsz,--imgsz) volume first. '
        'Set YOLO_TTA_STREAMING_PREDICTION_SOURCES=0 to restore the legacy dense prediction-volume path; per-source prediction memmap flushes are still skipped by default unless YOLO_TTA_FLUSH_PREDICTION_VOLUME_ON_BUILD=1 or YOLO_TTA_PREDICT_FLUSH_EACH_VOLUME=1 is set.'
    )
    print(
        f'Streaming prediction-source preparers: {prediction_volume_builder_workers} '
        f'(per-source render workers: {per_prediction_volume_workers}, shared render workers: {prediction_render_workers}, '
        f'source tasks: {total_prediction_volume_build_tasks}, queued-source bound: {prediction_volume_queue_slots}, '
        f'CPU-warmed queued sources: {int(queued_streaming_cpu_warmup_sources)}, '
        f'eager CUDA-staged queued sources: {int(eager_gpu_input_staging_ahead_sources)})'
    )
    spec_notes.append(
        'v12.2.15 prediction scheduler active: full-frame and tiled YOLO sources normally stream H×W×1 frames through StreamingYoloVolumeSource. Streaming prediction-source creation is unbounded by default, so cheap source refs for every remaining view/tile can be queued immediately; expensive CPU rendering is separately bounded by the shared render pool and each source prefetch window. '
        f'The resolved queued-source bound is {int(prediction_volume_queue_slots)} source(s); set YOLO_TTA_PREDICTION_VOLUME_QUEUE_SLOTS to a positive value to cap it or 0 to force all remaining sources in legacy dense mode too. '
        f'Each active streaming source can submit enough work to use the full shared render pool ({int(prediction_render_workers)} worker thread(s)); legacy dense materialization still uses {int(legacy_per_prediction_volume_workers)} worker(s) per builder. '
        f'Up to {int(queued_streaming_cpu_warmup_sources)} ready queued source(s) are CPU-warmed at a time (YOLO_TTA_STREAMING_SOURCE_WARMUP_SOURCES), so source creation can be unbounded without every future source enqueueing a prefetch window. '
        f'Up to {int(eager_gpu_input_staging_ahead_sources)} queued source(s) are eagerly CUDA-staged before they become the active model.predict source (YOLO_TTA_GPU_INPUT_STAGING_AHEAD_SOURCES), with no fixed four-source default. '
        'v12.2.11 lazily allocates each full-view union/confidence workspace only when that view first reaches inference, avoiding an eager all-views zero-fill before the first prediction.'
    )
    if dense_tiling_active:
        spec_notes.append(
            'Tiled prediction sources follow the deterministic tile footprint, stride order, angle variant, '
            'and inverse-mapping rules from the v12.2.0 specification.'
        )

    prediction_render_executor: Optional[ThreadPoolExecutor] = None
    if bool(streaming_sources_active) and shared_streaming_render_pool_enabled():
        prediction_render_executor = ThreadPoolExecutor(max_workers=int(prediction_render_workers), thread_name_prefix='prediction-render')
        print(f'Shared streaming render pool: enabled ({int(prediction_render_workers)} worker thread(s))')
    elif bool(streaming_sources_active):
        print('Shared streaming render pool: disabled; each source owns its render executor.')

    prediction_volume_executor = ThreadPoolExecutor(max_workers=int(prediction_volume_builder_workers), thread_name_prefix='prediction-volume')
    prediction_result_executor = ThreadPoolExecutor(max_workers=int(async_prediction_result_worker_count), thread_name_prefix='predict-result')
    prediction_join_executor = ThreadPoolExecutor(max_workers=int(async_prediction_join_worker_count), thread_name_prefix='predict-join')
    parent_postprocess_executor = ThreadPoolExecutor(max_workers=int(parent_postprocess_workers), thread_name_prefix='parent-postprocess')
    tile_postprocess_executor = ThreadPoolExecutor(max_workers=int(tile_postprocess_workers), thread_name_prefix='tile-postprocess')

    pending_prediction_build_jobs: deque[Tuple[str, ViewInfo, object]] = deque()
    for view, aug_job in iter_aug_jobs_round_robin(inference_views, aug_jobs_by_view):
        pending_prediction_build_jobs.append(('fullframe', view, aug_job))
        if dense_tiling_active:
            for tile_job in tile_jobs_by_aug.get((view.name, aug_job.aug_id), []):
                pending_prediction_build_jobs.append(('tile', view, tile_job))

    prediction_volume_futures: Dict[Future, Tuple[str, ViewInfo, object]] = {}
    pending_prediction_volume_futures: set[Future] = set()
    ready_fullframe: deque[Tuple[ViewInfo, AugJob, PredictionVolumeRef]] = deque()
    ready_tile_infer: deque[Tuple[str, ViewInfo, DenseTileJob, PredictionVolumeRef]] = deque()
    tile_inference_done: set[Tuple[str, str, str]] = set()
    prediction_accumulation_futures: Dict[Future, Dict[str, object]] = {}
    streaming_cpu_warmup_started_refs: set[int] = set()

    view_processing_futures: Dict[Future, Tuple[str, str]] = {}
    view_processing_submitted: set[Tuple[str, str]] = set()
    tile_cleanup_futures: Dict[Future, Tuple[str, str, str, str]] = {}
    postprocessed_tiles_waiting_by_parent: Dict[Tuple[str, str], Dict[str, object]] = {}
    tile_finalize_futures: Dict[Future, Tuple[str, str, str, str]] = {}
    tile_config_gate_futures: Dict[Future, Tuple[str, str, str]] = {}
    tile_consolidation_futures: Dict[Future, Tuple[str, str]] = {}
    tile_config_accumulator_by_key: Dict[Tuple[str, str, str], np.ndarray] = {}
    tile_config_accumulator_paths: Dict[Tuple[str, str, str], Path] = {}
    tile_config_accumulator_locks: Dict[Tuple[str, str, str], threading.Lock] = {}
    tile_accumulator_by_parent: Dict[Tuple[str, str], np.ndarray] = {}
    tile_accumulator_paths: Dict[Tuple[str, str], Path] = {}
    tile_parent_mask_accumulator_by_parent: Dict[Tuple[str, str], np.ndarray] = {}
    tile_parent_bridge_accumulator_by_parent: Dict[Tuple[str, str], np.ndarray] = {}
    tile_completed_by_parent_config: Dict[Tuple[str, str, str], set[str]] = {}
    tile_config_gated_by_parent: Dict[Tuple[str, str], set[str]] = {}
    tile_config_gate_submitted: set[Tuple[str, str, str]] = set()
    tile_consolidation_submitted: set[Tuple[str, str]] = set()

    def _prediction_volume_queue_depth() -> int:
        return int(len(pending_prediction_volume_futures) + len(ready_fullframe) + len(ready_tile_infer))

    def _make_streaming_fullframe_ref(view: ViewInfo, aug_job: AugJob) -> PredictionVolumeRef:
        if not aug_job.meta_path.exists():
            write_aug_job_meta(aug_job, view)
        render_workers = streaming_prediction_source_workers(int(per_prediction_volume_workers), int(view.num_slices))
        prefetch_frames = streaming_prediction_source_prefetch_frames(max(1, int(args.batch)))

        def _render(idx: int) -> np.ndarray:
            return render_fullframe_frame_for_job(
                volume_rgb=volume_rgb,
                view=view,
                job=aug_job,
                frame_idx=int(idx),
                view_frames=_get_view_frame_cache(view),
            )

        name = f'Streaming full-frame prediction source {view.name}/{aug_job.aug_id}'
        source = StreamingYoloVolumeSource(
            _render,
            num_frames=int(view.num_slices),
            name=name,
            batch_size=max(1, int(args.batch)),
            out_size=int(aug_job.aff.out_size),
            render_workers=int(render_workers),
            prefetch_frames=int(prefetch_frames),
            autostart=bool(streaming_prediction_source_autostart_enabled()),
            shared_executor=prediction_render_executor,
        )
        return PredictionVolumeRef(
            array=None,
            path=None,
            name=name,
            view_name=str(view.name),
            job_id=str(aug_job.aug_id),
            kind='fullframe',
            source=source,
        )

    def _make_streaming_tile_ref(view: ViewInfo, tile_job: DenseTileJob) -> PredictionVolumeRef:
        if not tile_job.meta_path.exists():
            write_dense_tile_job_meta(tile_job)
        render_workers = streaming_prediction_source_workers(int(per_prediction_volume_workers), int(view.num_slices))
        prefetch_frames = streaming_prediction_source_prefetch_frames(max(1, int(args.batch)))

        def _render(idx: int) -> np.ndarray:
            return render_dense_tile_frame_for_job(
                volume_rgb=volume_rgb,
                view=view,
                tile_job=tile_job,
                frame_idx=int(idx),
                view_frames=_get_view_frame_cache(view),
            )

        name = f'Streaming tile prediction source {view.name}/{tile_job.tile_id}'
        source = StreamingYoloVolumeSource(
            _render,
            num_frames=int(view.num_slices),
            name=name,
            batch_size=max(1, int(args.batch)),
            out_size=int(tile_job.out_size),
            render_workers=int(render_workers),
            prefetch_frames=int(prefetch_frames),
            autostart=bool(streaming_prediction_source_autostart_enabled()),
            shared_executor=prediction_render_executor,
        )
        return PredictionVolumeRef(
            array=None,
            path=None,
            name=name,
            view_name=str(view.name),
            job_id=str(tile_job.tile_id),
            kind='tile',
            source=source,
        )

    def _submit_prediction_volume_build(kind: str, view: ViewInfo, job_obj: object) -> None:
        if str(kind) == 'fullframe':
            aug_job = job_obj
            assert isinstance(aug_job, AugJob)
            if streaming_prediction_sources_enabled():
                fut = prediction_volume_executor.submit(_make_streaming_fullframe_ref, view, aug_job)
            else:
                out_path = temp_dir / 'prediction_volumes' / 'fullframe' / view.name / f'{view.name}_{aug_job.aug_id}.u8.dat'
                fut = prediction_volume_executor.submit(
                    materialize_fullframe_prediction_volume_for_job,
                    volume_rgb,
                    view,
                    aug_job,
                    out_path=out_path,
                    view_frames=_get_view_frame_cache(view),
                    workers=int(per_prediction_volume_workers),
                    show_progress=False,
                )
        elif str(kind) == 'tile':
            tile_job = job_obj
            assert isinstance(tile_job, DenseTileJob)
            if streaming_prediction_sources_enabled():
                fut = prediction_volume_executor.submit(_make_streaming_tile_ref, view, tile_job)
            else:
                out_path = temp_dir / 'prediction_volumes' / 'tiles' / view.name / str(tile_job.config_id) / f'{tile_job.tile_id}.u8.dat'
                fut = prediction_volume_executor.submit(
                    materialize_dense_tile_prediction_volume_for_job,
                    volume_rgb,
                    view,
                    tile_job,
                    out_path=out_path,
                    view_frames=_get_view_frame_cache(view),
                    workers=int(per_prediction_volume_workers),
                    show_progress=False,
                )
        else:  # pragma: no cover
            raise ValueError(f'Unknown prediction volume build kind: {kind}')
        prediction_volume_futures[fut] = (str(kind), view, job_obj)
        pending_prediction_volume_futures.add(fut)

    def _pump_prediction_volume_build_queue() -> None:
        while pending_prediction_build_jobs and _prediction_volume_queue_depth() < int(prediction_volume_queue_slots):
            kind, view, job_obj = pending_prediction_build_jobs.popleft()
            _submit_prediction_volume_build(str(kind), view, job_obj)

    def _queued_gpu_staging_ref_count() -> int:
        seen: set[int] = set()
        count = 0
        for _view, _job, ref in list(ready_fullframe):
            rid = id(ref)
            if rid not in seen and _prediction_ref_has_gpu_input_staging(ref):
                seen.add(rid)
                count += 1
        for _model_name, _view, _tile_job, ref in list(ready_tile_infer):
            rid = id(ref)
            if rid not in seen and _prediction_ref_has_gpu_input_staging(ref):
                seen.add(rid)
                count += 1
        return int(count)

    def _maybe_eager_stage_prediction_ref(pred_ref: PredictionVolumeRef) -> PredictionVolumeRef:
        if int(eager_gpu_input_staging_ahead_sources) <= 0:
            return pred_ref
        if _prediction_ref_has_gpu_input_staging(pred_ref):
            return pred_ref
        if _queued_gpu_staging_ref_count() >= int(eager_gpu_input_staging_ahead_sources):
            return pred_ref
        return maybe_eager_stage_prediction_ref_on_gpu(pred_ref, pred_cfg)

    def _queued_cpu_warmup_ref_count() -> int:
        seen: set[int] = set()
        count = 0
        for _view, _job, ref in list(ready_fullframe):
            rid = id(ref)
            if rid in seen:
                continue
            if rid in streaming_cpu_warmup_started_refs or _prediction_ref_has_gpu_input_staging(ref):
                seen.add(rid)
                count += 1
        for _model_name, _view, _tile_job, ref in list(ready_tile_infer):
            rid = id(ref)
            if rid in seen:
                continue
            if rid in streaming_cpu_warmup_started_refs or _prediction_ref_has_gpu_input_staging(ref):
                seen.add(rid)
                count += 1
        return int(count)

    def _maybe_start_cpu_warmup_prediction_ref(pred_ref: PredictionVolumeRef) -> None:
        if int(queued_streaming_cpu_warmup_sources) <= 0:
            return
        if _prediction_ref_has_gpu_input_staging(pred_ref):
            return
        rid = id(pred_ref)
        if rid in streaming_cpu_warmup_started_refs:
            return
        if _queued_cpu_warmup_ref_count() >= int(queued_streaming_cpu_warmup_sources):
            return
        source = getattr(pred_ref, 'source', None)
        start_fn = getattr(source, 'start', None)
        if not callable(start_fn):
            return
        try:
            start_fn()
            streaming_cpu_warmup_started_refs.add(rid)
        except Exception as exc:
            print(f'Warning: queued CPU render warmup could not start for {pred_ref.name} ({exc}); source will start on demand.')

    def _warmup_ready_prediction_sources() -> None:
        if int(queued_streaming_cpu_warmup_sources) <= 0:
            return
        for _view, _job, ref in list(ready_fullframe):
            _maybe_start_cpu_warmup_prediction_ref(ref)
            if _queued_cpu_warmup_ref_count() >= int(queued_streaming_cpu_warmup_sources):
                return
        for _model_name, _view, _tile_job, ref in list(ready_tile_infer):
            _maybe_start_cpu_warmup_prediction_ref(ref)
            if _queued_cpu_warmup_ref_count() >= int(queued_streaming_cpu_warmup_sources):
                return

    def _drain_completed_prediction_volume_futures() -> None:
        for fut in list(pending_prediction_volume_futures):
            if not fut.done():
                continue
            pending_prediction_volume_futures.remove(fut)
            kind, view, job_obj = prediction_volume_futures.pop(fut)
            pred_ref = _maybe_eager_stage_prediction_ref(fut.result())
            if str(kind) == 'fullframe':
                assert isinstance(job_obj, AugJob)
                ready_fullframe.append((view, job_obj, pred_ref))
            else:
                assert isinstance(job_obj, DenseTileJob)
                for model_name, _ in yolo_models:
                    ready_tile_infer.append((str(model_name), view, job_obj, pred_ref))
        _pump_prediction_volume_build_queue()
        _warmup_ready_prediction_sources()

    def _ensure_baseline_workspaces(model_name: str, view: ViewInfo) -> None:
        key = (str(model_name), str(view.name))
        if key in baseline_union_by_model_view:
            return
        union_path = temp_dir / 'union' / str(model_name) / f'{view.name}.union.u8.dat'
        confmap_path = temp_dir / 'union' / str(model_name) / f'{view.name}.confmap.u8.dat'
        union_path.parent.mkdir(parents=True, exist_ok=True)

        # v13.2.5 (speed #4): views that will be interpolated allocate their baseline union
        # DIRECTLY as a disk memmap at union_path. The interpolation process backend can then
        # reopen the volume by path with ZERO copy (_ensure_process_backed_interpolation_volume
        # detects the backing file), eliminating the old full-volume RAM->disk handoff copy per
        # view per pass; page cache keeps reads/writes at RAM speed. Non-interpolating views
        # keep the anonymous-RAM preference.
        # v13.3.1 (R4): direct union writes require file-backed workspaces the workers can open.
        union_prefer_memory = not (
            (
                interpolation_process_backend_enabled()
                and _view_uses_interpolation(view, int(args.interpolate))
            )
            or mgpu_direct_union_active
        )
        baseline_union_by_model_view[key] = allocate_workspace_array(
            shape=(int(view.num_slices), int(view.src_h), int(view.src_w)),
            dtype=np.uint8,
            path=union_path,
            desc=f'{model_name}/{view.name} baseline union workspace',
            prefer_memory=bool(union_prefer_memory),
        )
        baseline_union_paths[key] = union_path
        baseline_slice_locks_by_model_view[key] = [threading.Lock() for _ in range(int(view.num_slices))]
        if float(args.min_conf) > 0.0:
            baseline_confmap_by_model_view[key] = allocate_workspace_array(
                shape=(int(view.num_slices), int(view.src_h), int(view.src_w)),
                dtype=np.uint8,
                path=confmap_path,
                desc=f'{model_name}/{view.name} baseline confidence workspace',
                prefer_memory=not mgpu_direct_union_active,
            )
            baseline_confmap_paths[key] = confmap_path
        else:
            baseline_confmap_by_model_view[key] = None
            baseline_confmap_paths[key] = None

    def _submit_view_prepare(model_name: str, view: ViewInfo) -> None:
        key = (str(model_name), str(view.name))
        if key in view_processing_submitted:
            return
        view_processing_submitted.add(key)
        union_mm = baseline_union_by_model_view.pop(key)
        confmap_mm = baseline_confmap_by_model_view.pop(key)
        union_path = baseline_union_paths.pop(key)
        confmap_path = baseline_confmap_paths.pop(key)
        baseline_slice_locks_by_model_view.pop(key, None)
        # v13.3.3 (S2): every slice of this view already hole-filled on device by the GPU
        # workers -> the CPU "2D hole fill (<view>)" pass is a no-op recompute; skip it.
        hole_fill_done_on_device = bool(
            int(view_device_hole_filled_slices.get(key, 0)) >= int(view.num_slices)
        )
        fut = parent_postprocess_executor.submit(
            prepare_view_volume_after_fullframe,
            model_name=str(model_name),
            view=view,
            union_mm=union_mm,
            confmap_mm=confmap_mm,
            union_path=union_path,
            confmap_path=confmap_path,
            temp_dir=temp_dir,
            dense_tiling_active=bool(dense_tiling_active),
            min_conf=float(args.min_conf),
            min_radius=float(args.min_radius),
            interpolate=int(args.interpolate),
            interpolation_walk_back=int(args.interpolation_walk_back),
            interpolation_candidates=int(args.interpolation_candidates),
            interpolate_passes=int(args.interpolate_passes),
            interpolate_min_radius=float(args.interpolate_min_radius),
            interpolation_search_angle=float(args.interpolation_search_angle),
            keep_temp=bool(keep_temp_artifacts),
            slice_workers=int(slice_postprocess_workers),
            interpolation_task_workers=int(parent_interpolation_task_workers),
            nrrd_layers_enabled=bool(nrrd_layers_needed),
            precleaned_slice_cleanup=bool(single_angle_streaming_cleanup_active),
            hole_fill_done_on_device=bool(hole_fill_done_on_device),
        )
        view_processing_futures[fut] = key

    def _get_tile_accumulator(model_name: str, view_name: str) -> np.ndarray:
        key = (str(model_name), str(view_name))
        acc = tile_accumulator_by_parent.get(key)
        if acc is not None:
            return acc
        view = view_infos_by_name[str(view_name)]
        acc_path = temp_dir / 'tile_consolidated' / str(model_name) / str(view_name) / 'gated_or.u8.dat'
        acc = allocate_workspace_array(
            shape=(int(view.num_slices), int(view.src_h), int(view.src_w)),
            dtype=np.uint8,
            path=acc_path,
            desc=f'{model_name}/{view_name} consolidated gated-tile accumulator',
            prefer_memory=tile_intermediate_accumulators_prefer_memory(),
            reserve_bytes=tile_intermediate_accumulator_reserve_bytes(),
        )
        tile_accumulator_by_parent[key] = acc
        tile_accumulator_paths[key] = acc_path
        return acc

    def _get_tile_config_accumulator(model_name: str, view_name: str, config_id: str) -> np.ndarray:
        key = (str(model_name), str(view_name), str(config_id))
        acc = tile_config_accumulator_by_key.get(key)
        if acc is not None:
            return acc
        view = view_infos_by_name[str(view_name)]
        acc_path = temp_dir / 'tile_consolidated_by_config' / str(model_name) / str(view_name) / str(config_id) / 'raw_canvas.u8.dat'
        acc = allocate_workspace_array(
            shape=(int(view.num_slices), int(view.src_h), int(view.src_w)),
            dtype=np.uint8,
            path=acc_path,
            desc=f'{model_name}/{view_name}/{config_id} raw consolidated tile-set canvas',
            prefer_memory=tile_intermediate_accumulators_prefer_memory(),
            reserve_bytes=tile_intermediate_accumulator_reserve_bytes(),
        )
        tile_config_accumulator_by_key[key] = acc
        tile_config_accumulator_paths[key] = acc_path
        tile_config_accumulator_locks.setdefault(key, threading.Lock())
        return acc


    def _get_tile_category_accumulator(model_name: str, view_name: str, category: str) -> np.ndarray:
        key = (str(model_name), str(view_name))
        category_norm = str(category)
        store = (
            tile_parent_mask_accumulator_by_parent
            if category_norm == 'parent_mask'
            else tile_parent_bridge_accumulator_by_parent
        )
        acc = store.get(key)
        if acc is not None:
            return acc
        view = view_infos_by_name[str(view_name)]
        acc_path = temp_dir / 'tile_consolidated' / str(model_name) / str(view_name) / f'gated_or_accepted_by_{category_norm}.u8.dat'
        acc = allocate_workspace_array(
            shape=(int(view.num_slices), int(view.src_h), int(view.src_w)),
            dtype=np.uint8,
            path=acc_path,
            desc=f'{model_name}/{view_name} consolidated gated-tile accumulator accepted by {category_norm}',
            prefer_memory=tile_intermediate_accumulators_prefer_memory(),
            reserve_bytes=tile_intermediate_accumulator_reserve_bytes(),
        )
        store[key] = acc
        return acc


    def _parent_destination_ready(model_name: str, view_name: str) -> bool:
        view = view_infos_by_name[str(view_name)]
        if view.family == 'radial':
            return str(view_name) in radial_native_output_by_model.get(str(model_name), {})
        if is_tilted_view(view):
            return str(view_name) in tilted_native_output_by_model.get(str(model_name), {})
        return str(view_name) in view_volumes_by_model.get(str(model_name), {})

    def _parent_destination_volume(model_name: str, view_name: str) -> np.ndarray:
        view = view_infos_by_name[str(view_name)]
        if view.family == 'radial':
            return radial_native_output_by_model[str(model_name)][str(view_name)]
        if is_tilted_view(view):
            return tilted_native_output_by_model[str(model_name)][str(view_name)]
        return view_volumes_by_model[str(model_name)][str(view_name)]

    def _maybe_submit_tile_consolidation(model_name: str, view_name: str) -> None:
        parent_key = (str(model_name), str(view_name))
        if parent_key in tile_consolidation_submitted:
            return
        expected_configs = int(tile_config_expected_by_parent.get(parent_key, 0))
        if expected_configs <= 0:
            return
        if len(tile_config_gated_by_parent.get(parent_key, set())) < expected_configs:
            return
        if not _parent_destination_ready(str(model_name), str(view_name)):
            return

        tile_consolidation_submitted.add(parent_key)
        acc = tile_accumulator_by_parent.get(parent_key)
        if acc is None:
            # All tile-set canvases completed but none had parent-supported components.
            return

        view = view_infos_by_name[str(view_name)]
        fut = tile_postprocess_executor.submit(
            finalize_consolidated_tile_volume_for_parent,
            model_name=str(model_name),
            view=view,
            tile_accumulator_mm=acc,
            destination_mm=_parent_destination_volume(str(model_name), str(view_name)),
            destination_lock=view_volume_locks[(str(model_name), str(view_name))],
            temp_dir=temp_dir,
            interpolate=int(args.interpolate),
            interpolation_walk_back=int(args.interpolation_walk_back),
            interpolation_candidates=int(args.interpolation_candidates),
            interpolate_passes=int(args.interpolate_passes),
            interpolate_min_radius=float(args.interpolate_min_radius),
            interpolation_search_angle=float(args.interpolation_search_angle),
            keep_temp=bool(keep_temp_artifacts),
            slice_workers=int(tile_slice_postprocess_workers),
            interpolation_task_workers=int(tile_interpolation_task_workers),
            nrrd_layers_enabled=bool(nrrd_layers_needed),
            tile_parent_mask_accumulator_mm=tile_parent_mask_accumulator_by_parent.get(parent_key),
            tile_parent_bridge_accumulator_mm=tile_parent_bridge_accumulator_by_parent.get(parent_key),
        )
        tile_consolidation_futures[fut] = parent_key

    def _mark_tile_config_gated(model_name: str, view_name: str, config_id: str) -> None:
        parent_key = (str(model_name), str(view_name))
        gated = tile_config_gated_by_parent.setdefault(parent_key, set())
        gated.add(str(config_id))
        _maybe_submit_tile_consolidation(str(model_name), str(view_name))

    def _maybe_submit_tile_config_gate(model_name: str, view_name: str, config_id: str) -> None:
        key = (str(model_name), str(view_name), str(config_id))
        if key in tile_config_gate_submitted:
            return
        expected = int(tile_expected_by_parent_config.get(key, 0))
        if expected <= 0:
            return
        if len(tile_completed_by_parent_config.get(key, set())) < expected:
            return
        support_by_view = native_view_support_by_model.get(str(model_name), {})
        if str(view_name) not in support_by_view:
            return

        tile_config_gate_submitted.add(key)
        config_acc = tile_config_accumulator_by_key.pop(key, None)
        config_acc_path = tile_config_accumulator_paths.pop(key, None)
        if config_acc is None:
            # Every tile in this size/stride configuration was empty or rejected before staging.
            _mark_tile_config_gated(str(model_name), str(view_name), str(config_id))
            return

        parent_key = (str(model_name), str(view_name))
        tile_accumulator_mm = _get_tile_accumulator(str(model_name), str(view_name))
        parent_mask_support_mm = None
        parent_bridge_support_mm = None
        tile_parent_mask_accumulator_mm = None
        tile_parent_bridge_accumulator_mm = None
        if bool(nrrd_layers_needed):
            parent_mask_support_mm = parent_mask_support_by_model.get(str(model_name), {}).get(str(view_name))
            parent_bridge_support_mm = parent_bridge_support_by_model.get(str(model_name), {}).get(str(view_name))
            tile_parent_mask_accumulator_mm = _get_tile_category_accumulator(str(model_name), str(view_name), 'parent_mask')
            if parent_bridge_support_mm is not None:
                tile_parent_bridge_accumulator_mm = _get_tile_category_accumulator(str(model_name), str(view_name), 'parent_bridge')

        config_result = TilePostprocessResult(
            model_name=str(model_name),
            view_name=str(view_name),
            config_id=str(config_id),
            tile_id=str(config_id),
            tile_mask_mm=config_acc,
            tile_mask_path=config_acc_path,
        )
        fut = tile_postprocess_executor.submit(
            gate_tile_volume_into_consolidated_parent,
            config_result,
            parent_support_mm=support_by_view[str(view_name)],
            tile_accumulator_mm=tile_accumulator_mm,
            tile_accumulator_lock=view_volume_locks[(str(model_name), str(view_name))],
            keep_temp=bool(keep_temp_artifacts),
            slice_workers=int(tile_slice_postprocess_workers),
            parent_mask_support_mm=parent_mask_support_mm,
            parent_bridge_support_mm=parent_bridge_support_mm,
            tile_parent_mask_accumulator_mm=tile_parent_mask_accumulator_mm,
            tile_parent_bridge_accumulator_mm=tile_parent_bridge_accumulator_mm,
            temp_dir=temp_dir,
        )
        tile_config_gate_futures[fut] = key

    def _mark_tile_staged(model_name: str, view_name: str, config_id: str, tile_id: str) -> None:
        key = (str(model_name), str(view_name), str(config_id))
        if key not in tile_expected_by_parent_config:
            return
        completed = tile_completed_by_parent_config.setdefault(key, set())
        completed.add(str(tile_id))
        _maybe_submit_tile_config_gate(str(model_name), str(view_name), str(config_id))

    def _submit_tile_finalize(result: TilePostprocessResult) -> None:
        parent_key = (str(result.model_name), str(result.view_name))
        support_by_view = native_view_support_by_model.get(result.model_name, {})
        if result.view_name not in support_by_view:
            waiting = postprocessed_tiles_waiting_by_parent.setdefault(parent_key, {})
            parent_view = view_infos_by_name[str(result.view_name)]
            if waiting_tile_spill_enabled():
                waiting[str(result.tile_id)] = spill_waiting_tile_result_to_raw_store(
                    result,
                    temp_dir,
                    workers=int(tile_slice_postprocess_workers),
                    keep_original=bool(keep_temp_artifacts),
                    expected_parent_shape=(int(parent_view.num_slices), int(parent_view.src_h), int(parent_view.src_w)),
                )
            else:
                # Keep the already-parent-sized postprocessed tile volume resident instead of
                # round-tripping through a raw ctile store while waiting for parent support.
                waiting[str(result.tile_id)] = result
            return

        waiting = postprocessed_tiles_waiting_by_parent.get(parent_key)
        if waiting is not None:
            waiting.pop(str(result.tile_id), None)
            if not waiting:
                postprocessed_tiles_waiting_by_parent.pop(parent_key, None)

        config_accumulator_mm = _get_tile_config_accumulator(result.model_name, result.view_name, result.config_id)
        config_lock = tile_config_accumulator_locks.setdefault(
            (str(result.model_name), str(result.view_name), str(result.config_id)),
            threading.Lock(),
        )
        fut = tile_postprocess_executor.submit(
            stage_tile_result_into_config_canvas,
            result,
            tile_set_accumulator_mm=config_accumulator_mm,
            tile_set_accumulator_lock=config_lock,
            keep_temp=bool(keep_temp_artifacts),
            slice_workers=int(tile_slice_postprocess_workers),
        )
        tile_finalize_futures[fut] = (str(result.model_name), str(result.view_name), str(result.config_id), str(result.tile_id))

    def _flush_ready_postprocessed_tiles() -> None:
        ready_results: List[TilePostprocessResult] = []
        for parent_key, waiting in list(postprocessed_tiles_waiting_by_parent.items()):
            model_name, view_name = parent_key
            if view_name not in native_view_support_by_model.get(model_name, {}):
                continue
            for wait_result in waiting.values():
                if isinstance(wait_result, DeferredTilePostprocessResult):
                    ready_results.append(load_waiting_tile_result_from_raw_store(wait_result))
                elif isinstance(wait_result, TilePostprocessResult):
                    ready_results.append(wait_result)
                else:
                    raise TypeError(f'Unsupported waiting tile result type: {type(wait_result)!r}')
            del postprocessed_tiles_waiting_by_parent[parent_key]

        for result in ready_results:
            _submit_tile_finalize(result)


    def _submit_prediction_accumulation_join(handle: PredictionAccumulationHandle, context: Dict[str, object]) -> None:
        fut = prediction_join_executor.submit(handle.wait)
        prediction_accumulation_futures[fut] = dict(context)

    def _drain_completed_prediction_accumulation_futures() -> None:
        for fut in list(prediction_accumulation_futures.keys()):
            if not fut.done():
                continue
            context = prediction_accumulation_futures.pop(fut)
            pred_stats = fut.result()
            kind = str(context.get('kind', ''))

            if kind == 'fullframe':
                model_name = str(context['model_name'])
                view = context['view']
                assert isinstance(view, ViewInfo)
                yolo_obj = context.get('yolo')
                if offload_between_jobs_enabled() and yolo_obj is not None:
                    offload_yolo_from_gpu(yolo_obj)
                view_prediction_stats[str(view.summary_family)] = int(view_prediction_stats.get(str(view.summary_family), 0)) + int(pred_stats.get('prediction_count', 0))
                remaining_key = (model_name, view.name)
                fullframe_remaining[remaining_key] = int(fullframe_remaining.get(remaining_key, 0)) - 1
                if int(fullframe_remaining.get(remaining_key, 0)) == 0:
                    _submit_view_prepare(model_name, view)
                continue

            if kind == 'tile':
                model_name = str(context['model_name'])
                view = context['view']
                tile_job = context['tile_job']
                assert isinstance(view, ViewInfo)
                assert isinstance(tile_job, DenseTileJob)
                tile_mask_mm = context['tile_mask_mm']
                tile_conf_mm = context.get('tile_conf_mm')
                tile_mask_path = Path(context['tile_mask_path'])
                tile_conf_path_obj = context.get('tile_conf_path')
                tile_conf_path = Path(tile_conf_path_obj) if tile_conf_path_obj is not None else None
                ready_key = (str(model_name), str(view.name), str(tile_job.tile_id))
                yolo_obj = context.get('yolo')
                if offload_between_jobs_enabled() and yolo_obj is not None:
                    offload_yolo_from_gpu(yolo_obj)
                tile_inference_done.add(ready_key)
                view_prediction_stats[str(view.summary_family)] = int(view_prediction_stats.get(str(view.summary_family), 0)) + int(pred_stats.get('prediction_count', 0))

                if int(pred_stats.get('frames_with_predictions', 0)) <= 0:
                    close_memmap_array(tile_mask_mm)
                    close_memmap_array(tile_conf_mm)
                    if not keep_temp_artifacts:
                        try:
                            tile_mask_path.unlink(missing_ok=True)
                        except Exception:
                            pass
                        if tile_conf_path is not None:
                            try:
                                tile_conf_path.unlink(missing_ok=True)
                            except Exception:
                                pass
                    _mark_tile_staged(str(model_name), str(view.name), str(tile_job.config_id), str(tile_job.tile_id))
                    continue

                task = TilePostprocessTask(
                    model_name=str(model_name),
                    view_name=str(view.name),
                    config_id=str(tile_job.config_id),
                    tile_id=str(tile_job.tile_id),
                    tile_mask_mm=tile_mask_mm,
                    tile_confmap_mm=tile_conf_mm,
                    tile_mask_path=tile_mask_path,
                    tile_confmap_path=tile_conf_path,
                    precleaned_slice_cleanup=bool(single_angle_streaming_cleanup_active),
                )
                tile_fut = tile_postprocess_executor.submit(
                    postprocess_tile_volume_after_inference,
                    task,
                    view=view,
                    min_conf=float(args.min_conf),
                    min_radius=float(args.min_radius),
                    keep_temp=bool(keep_temp_artifacts),
                    slice_workers=int(tile_slice_postprocess_workers),
                )
                tile_cleanup_futures[tile_fut] = (str(model_name), str(view.name), str(tile_job.config_id), str(tile_job.tile_id))
                continue

            raise RuntimeError(f'Unknown prediction accumulation kind: {kind!r}')

    def _drain_completed_background_futures() -> None:
        for fut in list(view_processing_futures.keys()):
            if not fut.done():
                continue
            result = fut.result()
            del view_processing_futures[fut]
            native_view_support_by_model[result.model_name][result.view_name] = result.native_support_mm
            if result.parent_mask_support_mm is not None:
                parent_mask_support_by_model[result.model_name][result.view_name] = result.parent_mask_support_mm
            if result.parent_bridge_support_mm is not None:
                parent_bridge_support_by_model[result.model_name][result.view_name] = result.parent_bridge_support_mm
            interpolation_stats.extend(result.interpolation_stats)
            nrrd_layer_refs.extend(result.nrrd_layers)

            view_info = view_infos_by_name[result.view_name]
            if result.final_view_volume_mm is not None:
                if view_info.family == 'radial':
                    radial_native_output_by_model[result.model_name][result.view_name] = result.final_view_volume_mm
                elif is_tilted_view(view_info):
                    tilted_native_output_by_model[result.model_name][result.view_name] = result.final_view_volume_mm
                else:
                    view_volumes_by_model[result.model_name][result.view_name] = result.final_view_volume_mm
            for config_key in list(tile_expected_by_parent_config.keys()):
                cfg_model, cfg_view, cfg_id = config_key
                if cfg_model == result.model_name and cfg_view == result.view_name:
                    _maybe_submit_tile_config_gate(cfg_model, cfg_view, cfg_id)

        for fut in list(tile_cleanup_futures.keys()):
            if not fut.done():
                continue
            ready_key = tile_cleanup_futures.pop(fut)
            result = fut.result()
            if result is None:
                _mark_tile_staged(str(ready_key[0]), str(ready_key[1]), str(ready_key[2]), str(ready_key[3]))
                continue
            _submit_tile_finalize(result)

        _flush_ready_postprocessed_tiles()

        for fut in list(tile_finalize_futures.keys()):
            if not fut.done():
                continue
            model_name, view_name, config_id, tile_id = tile_finalize_futures.pop(fut)
            fut.result()
            _mark_tile_staged(str(model_name), str(view_name), str(config_id), str(tile_id))

        for fut in list(tile_config_gate_futures.keys()):
            if not fut.done():
                continue
            model_name, view_name, config_id = tile_config_gate_futures.pop(fut)
            fut.result()
            _mark_tile_config_gated(str(model_name), str(view_name), str(config_id))

        for fut in list(tile_consolidation_futures.keys()):
            if not fut.done():
                continue
            parent_key = tile_consolidation_futures.pop(fut)
            result = fut.result()
            interpolation_stats.extend(result.interpolation_stats)
            nrrd_layer_refs.extend(result.nrrd_layers)

            # v13.2.2 bug #14: the interpolation process backend may have rebound the
            # consolidated accumulator to a fresh disk memmap that received the
            # interpolation bridge voxels. Re-point the registry (used below for
            # keep_temp archiving and later for troubleshooting overlays) at that final
            # volume and release the superseded pre-interpolation array.
            final_acc = result.final_accumulator_mm
            stale_acc = tile_accumulator_by_parent.get(parent_key)
            if final_acc is not None and stale_acc is not None and stale_acc is not final_acc:
                tile_accumulator_by_parent[parent_key] = final_acc
                final_acc_path = _memmap_backing_path(final_acc)
                if final_acc_path is not None:
                    tile_accumulator_paths[parent_key] = Path(final_acc_path)
                else:
                    tile_accumulator_paths.pop(parent_key, None)
                stale_acc_path = _memmap_backing_path(stale_acc)
                try:
                    close_memmap_array_without_flush(stale_acc)
                except Exception:
                    pass
                if stale_acc_path is not None and not bool(keep_temp_artifacts):
                    try:
                        Path(stale_acc_path).unlink(missing_ok=True)
                    except Exception:
                        pass

            # Once the consolidated tile volume has been unioned into its parent destination and
            # any NRRD layers have been materialized, category accumulators are no longer needed.
            # The main consolidated tile accumulator is retained until troubleshooting overlays are
            # scheduled when --troubleshooting is active; final cleanup archives/deletes any survivor.
            for label, store in (
                ('consolidated gated tiles', tile_accumulator_by_parent),
                ('tile components accepted by parent mask', tile_parent_mask_accumulator_by_parent),
                ('tile components accepted by parent bridge', tile_parent_bridge_accumulator_by_parent),
            ):
                if bool(troubleshooting_outputs_enabled) and label == 'consolidated gated tiles':
                    continue
                acc = store.pop(parent_key, None)
                if acc is not None:
                    archive_or_delete_binary_volume_storage(
                        acc,
                        keep_temp=bool(keep_temp_artifacts),
                        workers=int(tile_slice_postprocess_workers),
                        desc=f'{label} {parent_key[0]}/{parent_key[1]}',
                    )
                    if label == 'consolidated gated tiles':
                        tile_accumulator_paths.pop(parent_key, None)

        output_manager.reap_completed()

    last_scheduler_wait_log = 0.0

    def _log_scheduler_wait_state(force: bool = False) -> None:
        nonlocal last_scheduler_wait_log
        now = time.time()
        interval = max(5.0, _env_float('YOLO_TTA_SCHEDULER_STATUS_INTERVAL_SEC', 30.0))
        if not bool(force) and (now - float(last_scheduler_wait_log)) < float(interval):
            return
        last_scheduler_wait_log = float(now)
        waiting_tiles = sum(len(v) for v in postprocessed_tiles_waiting_by_parent.values())
        print(
            'Scheduler wait: no inference-ready in-memory volume; '
            f'pending_volume_builds={len(pending_prediction_volume_futures)}, '
            f'queued_build_jobs={len(pending_prediction_build_jobs)}, '
            f'prediction_accumulation={len(prediction_accumulation_futures)}, '
            f'parent_postprocess={len(view_processing_futures)}, '
            f'tile_cleanup={len(tile_cleanup_futures)}, '
            f'tile_finalize={len(tile_finalize_futures)}, '
            f'tile_config_gate={len(tile_config_gate_futures)}, '
            f'tile_consolidation={len(tile_consolidation_futures)}, '
            f'waiting_tiles_for_parent={waiting_tiles}, '
            f'ready_fullframe={len(ready_fullframe)}, ready_tiles={len(ready_tile_infer)}'
        )

    # --------------------------------------------------------------
    # --------------------------------------------------------------
    # v13.0.0 multi-GPU inference: one worker PROCESS per GPU (active only when >1 GPU).
    # CPython's GIL serializes Ultralytics' per-batch Python work across threads, so thread-per-GPU
    # inference is no faster than a single GPU. Each GPU therefore gets its own process (separate
    # interpreter + CUDA context). Workers render+predict+accumulate one prediction volume at a time
    # from a shared task queue and write the per-volume native-space result to a file-backed memmap;
    # the main process unions those results into the per-view union and runs all postprocessing.
    # --------------------------------------------------------------
    gpu_worker_processes: List[object] = []
    gpu_task_queue: object = None
    gpu_result_queue: object = None
    mgpu_tasks_by_id: Dict[int, Dict[str, object]] = {}
    mgpu_results_collected = 0
    mgpu_total_tasks = 0
    mgpu_result_dir = temp_dir / 'mgpu_results'

    def _ensure_source_volume_file_backed() -> Tuple[str, Tuple[int, int, int], str]:
        wait_for_volume_ready(volume_rgb)
        shape = (int(volume_rgb.shape[0]), int(volume_rgb.shape[1]), int(volume_rgb.shape[2]))
        backing = _memmap_backing_path(volume_rgb)
        if backing is not None:
            flush_array(volume_rgb)
            return str(backing), shape, str(np.asarray(volume_rgb).dtype)
        shared_path = temp_dir / 'mgpu_source_volume.gray8.dat'
        shared_mm = copy_workspace_array(
            np.asarray(volume_rgb), shared_path,
            desc='Multi-GPU shared source volume', prefer_memory=False, workers=int(worker_budget),
        )
        flush_array(shared_mm)
        return str(shared_path), shape, str(np.asarray(shared_mm).dtype)

    if multi_gpu_active:
        mgpu_result_dir.mkdir(parents=True, exist_ok=True)
        # Each GPU worker gets an equal share of the CPU allocation. Crucially the worker drives all
        # parallelism through its own render/postprocess THREAD POOLS, so OpenCV must run each call
        # single-threaded (cv2.setNumThreads(1)); otherwise OpenCV's per-process pool funnels every
        # warpAffine/resize through a handful of threads and the render pool starves the GPUs while
        # most cores sit idle. YOLO_TTA_MGPU_WORKER_CPU / YOLO_TTA_MGPU_WORKER_CV2_THREADS override.
        per_worker_workers = max(
            1, _env_int('YOLO_TTA_MGPU_WORKER_CPU', max(1, int(_cpu_count()) // max(1, gpu_device_count)))
        )
        worker_init = {
            'imgsz': int(args.imgsz), 'conf': float(args.conf),
            'half': bool(args.half), 'int8': bool(args.int8), 'batch': max(1, int(args.batch)),
            'retina_processor': str(retina_processor),
            'cv2_threads': max(1, _env_int('YOLO_TTA_MGPU_WORKER_CV2_THREADS', 1)),
            # v13.1.0 (#2.3): single-angle GPU fast-path (min_conf None when inactive) + min_radius.
            'single_angle_gpu_fastpath_min_conf': single_angle_gpu_fastpath_min_conf_value,
            'single_angle_gpu_fastpath_min_radius': single_angle_gpu_fastpath_min_radius_value,
        }
        # Torch LOGICAL indices (positions within any inherited CUDA_VISIBLE_DEVICES list);
        # validated against the inherited list early in main(), and each worker resolves
        # its physical pin via _pin_cuda_visible_device_token.
        gpu_logical_indices = [int(str(d).split(':')[-1]) for d in inference_devices]
        pinned_tokens = [
            _pin_cuda_visible_device_token(int(idx)) for idx in gpu_logical_indices
        ]
        # v13.3.5 (N1): discovery-driven GPU-worker -> NUMA-node CPU pin plan (None entries
        # stay unpinned). Computed from the PHYSICAL tokens before CUDA_VISIBLE_DEVICES is
        # narrowed inside the workers.
        worker_numa_plan = plan_gpu_worker_affinity(pinned_tokens)

        # v13.2.5 (speed #8): spawn the worker processes BEFORE blocking on decode/cube-resize
        # completion — workers idle in task_queue.get() while their CUDA context + model load
        # (~30-90 s each) overlaps the decode instead of running strictly after it. Tasks are
        # enqueued below once the shared source volume is ready.
        mp_ctx = mp.get_context('spawn')
        gpu_task_queue = mp_ctx.Queue()
        gpu_result_queue = mp_ctx.Queue()
        for worker_pos, gpu_index in enumerate(gpu_logical_indices):
            worker_init_i = dict(worker_init)
            worker_init_i['numa_affinity_cpus'] = worker_numa_plan[int(worker_pos)]
            proc = mp_ctx.Process(
                target=_gpu_inference_worker_main,
                args=(int(gpu_index), str(model_paths[0]), worker_init_i, gpu_task_queue, gpu_result_queue),
                name=f'gpu-worker-{gpu_index}', daemon=True,
            )
            proc.start()
            gpu_worker_processes.append(proc)
        print(
            f'Started {len(gpu_worker_processes)} GPU worker process(es) for logical devices {gpu_logical_indices} '
            f'(pinned to CUDA_VISIBLE_DEVICES tokens {pinned_tokens}); model load/CUDA init overlaps decode; '
            f'per-worker CPU workers={per_worker_workers}, cv2 threads=1. Tasks enqueue once the source volume is ready.'
        )
        # v13.3.4 (T4): the warm workers double as interpolation hosts once inference drains.
        if gpu_worker_aux_interpolation_enabled() and bool(interpolation_process_backend_active):
            set_gpu_worker_aux_interpolation_pool(
                _GpuWorkerAuxInterpolationPool(gpu_task_queue, len(gpu_worker_processes))
            )

        source_volume_path, source_volume_shape, source_volume_dtype = _ensure_source_volume_file_backed()
        # Split each full-frame volume into contiguous slice-range chunks so multiple GPUs can work
        # the SAME (often huge, e.g. full-coverage Radial) volume in parallel, instead of one GPU per
        # whole volume leaving the other GPUs idle at the tail. The chunk is large relative to the
        # render prefetch window so per-chunk render ramp-up stays amortized. Tiles are gated/
        # consolidated as whole volumes, so they are never slice-split.
        slice_chunk = max(64, _env_int('YOLO_TTA_MGPU_SLICE_CHUNK', 512))
        prefetch_frames = streaming_prediction_source_prefetch_frames(max(1, int(args.batch)))
        # v13.3.3 (S2): per-task device-side 2D hole fill is valid only when the spec steps that
        # precede hole fill (--min_conf, --min_radius) have no work, results stream through the
        # single-angle cleanup path, and the task writes a disjoint direct-union window.
        mgpu_device_hole_fill = bool(
            gpu_device_union_enabled()
            and gpu_device_hole_fill_enabled()
            and bool(single_angle_streaming_cleanup_active)
            and float(args.min_conf) <= 0.0
            and float(args.min_radius) <= 0.0
        )
        fullframe_subtasks_per_view: Dict[Tuple[str, str], int] = {}
        next_task_id = 0
        for kind, view, job_obj in list(pending_prediction_build_jobs):
            n_slices = int(view.num_slices)
            if str(kind) == 'fullframe':
                aug_job = job_obj
                m_out = np.asarray(aug_job.aff.M_out_to_src, dtype=np.float32)
                out_size = int(aug_job.aff.out_size)
                job_id = str(aug_job.aug_id)
                starts = list(range(0, max(1, n_slices), int(slice_chunk))) or [0]
                key_fv = (str(model_name), str(view.name))
                fullframe_subtasks_per_view[key_fv] = int(fullframe_subtasks_per_view.get(key_fv, 0)) + len(starts)
                prefix = f'{view.name}__{job_id}'
                if mgpu_direct_union_active:
                    # v13.3.1 (R4): pre-create the shared per-view union (and confmap) so every
                    # worker task can open it 'r+' and write its disjoint slice window directly.
                    _ensure_baseline_workspaces(str(model_name), view)
            else:
                tile_job = job_obj
                m_out = np.asarray(tile_job.M_out_to_src, dtype=np.float32)
                out_size = int(tile_job.out_size)
                job_id = str(tile_job.tile_id)
                starts = [0]
                prefix = f'tile__{view.name}__{job_id}'
            for chunk_idx, s0 in enumerate(starts):
                count = (min(int(slice_chunk), n_slices - int(s0)) if str(kind) == 'fullframe' else n_slices)
                # Size the render pool to this worker's CPU share (NOT streaming_prediction_source_workers,
                # which returns the full machine CPU count and would have each of N workers spin up an
                # N-times-too-large render pool). With cv2.setNumThreads(1) these are real render threads.
                render_workers = max(1, min(int(per_worker_workers), int(count)))
                if str(kind) == 'fullframe' and mgpu_direct_union_active:
                    # v13.3.1 (R4): the "result" paths are the shared per-view union files.
                    key_direct = (str(model_name), str(view.name))
                    rmask = baseline_union_paths[key_direct]
                    rconf = baseline_confmap_paths.get(key_direct)
                    result_mode = 'direct_union'
                else:
                    rmask = mgpu_result_dir / f'{prefix}__c{chunk_idx}.mask.u8.dat'
                    rconf = (mgpu_result_dir / f'{prefix}__c{chunk_idx}.conf.u8.dat') if float(args.min_conf) > 0.0 else None
                    result_mode = 'file'
                task = {
                    'task_id': int(next_task_id), 'kind': str(kind), 'model_name': str(model_name),
                    'view': view, 'job': job_obj, 'job_id': job_id, 'out_size': int(out_size),
                    'M_out_to_src': m_out,
                    'slice_start': int(s0), 'slice_count': int(count),
                    'source_volume_path': source_volume_path, 'source_shape': list(source_volume_shape),
                    'source_dtype': source_volume_dtype,
                    'result_mask_path': str(rmask), 'result_conf_path': (str(rconf) if rconf is not None else None),
                    'result_mode': str(result_mode), 'union_num_slices': int(n_slices),
                    'render_workers': int(render_workers), 'prefetch_frames': int(prefetch_frames),
                    'postprocess_workers': int(per_worker_workers),
                    'streaming_cleanup_enabled': bool(single_angle_streaming_cleanup_active),
                    'streaming_cleanup_min_conf': float(args.min_conf),
                    'streaming_cleanup_min_radius': float(_view_native_slice_min_radius(view, float(args.min_radius))),
                    'device_hole_fill': bool(
                        mgpu_device_hole_fill and str(kind) == 'fullframe' and str(result_mode) == 'direct_union'
                    ),
                }
                mgpu_tasks_by_id[int(next_task_id)] = task
                next_task_id += 1
        mgpu_total_tasks = int(next_task_id)
        # A full-frame view is finalized only after every (angle x slice-chunk) result for it has been
        # unioned, so override fullframe_remaining with the per-view sub-task count.
        for key_fv, cnt in fullframe_subtasks_per_view.items():
            fullframe_remaining[key_fv] = int(cnt)
        pending_prediction_build_jobs.clear()

        print(
            f'{mgpu_total_tasks} inference task(s) queued to the GPU workers (full-frame volumes '
            f'slice-chunked at {slice_chunk} slices for cross-GPU load balancing).'
        )
        for tid in range(mgpu_total_tasks):
            gpu_task_queue.put(mgpu_tasks_by_id[tid])

    def _finalize_fullframe_view_after_worker(model_name_s: str, view: ViewInfo) -> None:
        remaining_key = (str(model_name_s), str(view.name))
        fullframe_remaining[remaining_key] = int(fullframe_remaining.get(remaining_key, 0)) - 1
        if int(fullframe_remaining.get(remaining_key, 0)) == 0:
            _submit_view_prepare(str(model_name_s), view)

    def _handle_fullframe_worker_result(task: Dict[str, object], stats: Dict[str, int]) -> None:
        view = task['view']
        model_name_s = str(task['model_name'])
        view_prediction_stats[str(view.summary_family)] = int(view_prediction_stats.get(str(view.summary_family), 0)) + int(stats.get('prediction_count', 0))
        # v13.3.3 (S2): accumulate device-side hole-filled slice counts toward the per-view skip.
        _filled = int(stats.get('device_hole_filled_frames', 0))
        if _filled > 0:
            key_fill = (model_name_s, str(view.name))
            view_device_hole_filled_slices[key_fill] = int(view_device_hole_filled_slices.get(key_fill, 0)) + _filled
        if str(task.get('result_mode', 'file')) == 'direct_union':
            # v13.3.1 (R4): the worker already wrote its disjoint slice window straight into the
            # shared per-view union memmap — nothing to reopen, OR, flush, or unlink here, and
            # the scheduler thread is free to drain the next GPU result immediately.
            _finalize_fullframe_view_after_worker(model_name_s, view)
            return
        _ensure_baseline_workspaces(model_name_s, view)
        s0 = int(task.get('slice_start', 0))
        count = int(task.get('slice_count', int(view.num_slices)))
        # The worker result covers only this task's slice window; union it into that window of the
        # per-view union. Result handlers run only on the main thread, so concurrent sub-tasks of the
        # same view never race here.
        result_shape = (int(count), int(view.src_h), int(view.src_w))
        res_mask = open_existing_gray_memmap(task['result_mask_path'], result_shape, 'uint8', mode='r')
        res_conf = open_existing_gray_memmap(task['result_conf_path'], result_shape, 'uint8', mode='r') if task.get('result_conf_path') else None
        dst_mask = baseline_union_by_model_view[(model_name_s, str(view.name))]
        dst_conf = baseline_confmap_by_model_view.get((model_name_s, str(view.name)))
        union_conf_volume_into_volume_inplace(
            dst_mask[s0:s0 + count],
            (dst_conf[s0:s0 + count] if dst_conf is not None else None),
            res_mask, res_conf,
            workers=int(slice_postprocess_workers),
            desc=f'Union {view.name}[{s0}:{s0 + count}] worker result',
        )
        close_memmap_array(res_mask)
        if res_conf is not None:
            close_memmap_array(res_conf)
        if not keep_temp_artifacts:
            for pth in (task.get('result_mask_path'), task.get('result_conf_path')):
                if pth:
                    try:
                        Path(str(pth)).unlink(missing_ok=True)
                    except Exception:
                        pass
        _finalize_fullframe_view_after_worker(model_name_s, view)

    def _handle_tile_worker_result(task: Dict[str, object], stats: Dict[str, int]) -> None:
        view = task['view']
        model_name_s = str(task['model_name'])
        tile_job = task['job']
        view_prediction_stats[str(view.summary_family)] = int(view_prediction_stats.get(str(view.summary_family), 0)) + int(stats.get('prediction_count', 0))
        tile_inference_done.add((model_name_s, str(view.name), str(tile_job.tile_id)))
        if int(stats.get('frames_with_predictions', 0)) <= 0:
            if not keep_temp_artifacts:
                for pth in (task.get('result_mask_path'), task.get('result_conf_path')):
                    if pth:
                        try:
                            Path(str(pth)).unlink(missing_ok=True)
                        except Exception:
                            pass
            _mark_tile_staged(model_name_s, str(view.name), str(tile_job.config_id), str(tile_job.tile_id))
            return
        result_shape = (int(view.num_slices), int(view.src_h), int(view.src_w))
        tile_mask_path = Path(str(task['result_mask_path']))
        tile_mask_mm = open_existing_gray_memmap(tile_mask_path, result_shape, 'uint8', mode='r+')
        tile_conf_mm = None
        tile_conf_path = Path(str(task['result_conf_path'])) if task.get('result_conf_path') else None
        if tile_conf_path is not None:
            tile_conf_mm = open_existing_gray_memmap(tile_conf_path, result_shape, 'uint8', mode='r+')
        ptask = TilePostprocessTask(
            model_name=model_name_s, view_name=str(view.name),
            config_id=str(tile_job.config_id), tile_id=str(tile_job.tile_id),
            tile_mask_mm=tile_mask_mm, tile_confmap_mm=tile_conf_mm,
            tile_mask_path=tile_mask_path, tile_confmap_path=tile_conf_path,
            precleaned_slice_cleanup=bool(single_angle_streaming_cleanup_active),
        )
        fut = tile_postprocess_executor.submit(
            postprocess_tile_volume_after_inference, ptask,
            view=view, min_conf=float(args.min_conf), min_radius=float(args.min_radius),
            keep_temp=bool(keep_temp_artifacts), slice_workers=int(tile_slice_postprocess_workers),
        )
        tile_cleanup_futures[fut] = (model_name_s, str(view.name), str(tile_job.config_id), str(tile_job.tile_id))

    def _process_one_worker_result(msg: Dict[str, object]) -> None:
        nonlocal mgpu_results_collected
        mtype = str(msg.get('type'))
        if mtype == 'ready':
            print(f"GPU worker ready: device cuda:{msg.get('gpu_index')} (pid {msg.get('pid')}).")
            return
        if mtype == 'fatal':
            raise RuntimeError(
                f"GPU worker on device {msg.get('gpu_index')} failed to initialize: "
                f"{msg.get('error')}\n{msg.get('traceback')}"
            )
        if mtype == 'aux_result':
            # v13.3.4 (T4): auxiliary interpolation-pass result — route to the waiting
            # submitter thread; failures are ITS to handle (fallback/raise), not the
            # scheduler's, mirroring the interpolation ProcessPoolExecutor semantics.
            aux_pool = gpu_worker_aux_interpolation_pool()
            if aux_pool is not None:
                aux_pool.complete(
                    int(msg.get('task_id', -1)),
                    bool(msg.get('ok')),
                    msg.get('stats') if isinstance(msg.get('stats'), dict) else None,
                    str(msg.get('error') or '') + ('\n' + str(msg.get('traceback')) if msg.get('traceback') else ''),
                )
            return
        mgpu_results_collected += 1
        if not bool(msg.get('ok')):
            raise RuntimeError(
                f"GPU worker task {msg.get('task_id')} failed on device {msg.get('gpu_index')}: "
                f"{msg.get('error')}\n{msg.get('traceback')}"
            )
        task = mgpu_tasks_by_id[int(msg['task_id'])]
        stats = dict(msg.get('stats') or {})
        if str(task['kind']) == 'fullframe':
            _handle_fullframe_worker_result(task, stats)
        else:
            _handle_tile_worker_result(task, stats)
        # v13.3.4 (T4): every inference task is accounted for -> the workers are idle from here
        # on; open the aux interpolation pool so postprocess passes can use their GILs.
        if int(mgpu_total_tasks) > 0 and int(mgpu_results_collected) >= int(mgpu_total_tasks):
            aux_pool = gpu_worker_aux_interpolation_pool()
            if aux_pool is not None:
                aux_pool.enable()

    def _drain_process_inference_results() -> None:
        if gpu_result_queue is None:
            return
        while True:
            try:
                msg = gpu_result_queue.get_nowait()
            except queue.Empty:
                break
            _process_one_worker_result(msg)

    def _wait_for_one_process_result(timeout: float) -> None:
        if gpu_result_queue is None:
            return
        try:
            msg = gpu_result_queue.get(timeout=float(timeout))
        except queue.Empty:
            return
        _process_one_worker_result(msg)

    def _process_inference_outstanding() -> bool:
        return bool(multi_gpu_active and mgpu_results_collected < mgpu_total_tasks)

    def _check_gpu_workers_alive() -> None:
        # Fail fast (rather than hang) if a worker process died mid-task, e.g. CUDA OOM or a kill.
        aux_pool = gpu_worker_aux_interpolation_pool()
        aux_outstanding = int(aux_pool.outstanding()) if aux_pool is not None else 0
        if not _process_inference_outstanding() and aux_outstanding <= 0:
            return
        for proc in gpu_worker_processes:
            if not proc.is_alive():
                reason = (
                    f'GPU worker {getattr(proc, "name", "?")} exited unexpectedly '
                    f'(exitcode={getattr(proc, "exitcode", None)}) with '
                    f'{max(0, int(mgpu_total_tasks - mgpu_results_collected))} inference result(s) and '
                    f'{aux_outstanding} aux interpolation pass(es) still outstanding.'
                )
                if aux_pool is not None:
                    # v13.3.4 (T4): unblock any parent-postprocess threads waiting on aux passes
                    # before raising, so shutdown does not deadlock on their futures.
                    aux_pool.mark_failed(reason)
                raise RuntimeError(reason)

    def _shutdown_gpu_worker_processes() -> None:
        if not gpu_worker_processes:
            return
        # v13.3.4 (T4): on the normal path every aux interpolation pass has completed before
        # main reaches this finally (a no-op close); on abnormal paths this unblocks any
        # still-waiting or mid-submit threads so parent_postprocess_executor.shutdown(wait=True)
        # below cannot deadlock. mark_failed also refuses any racing late submission.
        aux_pool = gpu_worker_aux_interpolation_pool()
        if aux_pool is not None:
            aux_pool.mark_failed('GPU worker processes are shutting down')
            set_gpu_worker_aux_interpolation_pool(None)
        try:
            for _ in gpu_worker_processes:
                gpu_task_queue.put(None)
        except Exception:
            pass
        for proc in gpu_worker_processes:
            try:
                proc.join(timeout=30)
            except Exception:
                pass
            if proc.is_alive():
                try:
                    proc.terminate()
                except Exception:
                    pass

    try:
        _pump_prediction_volume_build_queue()
        while True:
            _drain_completed_prediction_volume_futures()
            _drain_completed_prediction_accumulation_futures()
            _drain_completed_background_futures()
            _pump_prediction_volume_build_queue()
            _warmup_ready_prediction_sources()

            if multi_gpu_active:
                # Inference runs in per-GPU worker processes; collect any completed results and union
                # them into the per-view unions / submit tile postprocessing. No in-process dispatch.
                _drain_process_inference_results()
                # Detect a hard worker death (CUDA OOM kill, segfault) within one iteration even while
                # CPU-side postprocess futures are still pending, instead of only on the idle branch.
                _check_gpu_workers_alive()

            if (not multi_gpu_active) and ready_fullframe:
                view, job, prediction_ref = ready_fullframe.popleft()
                print(f"Inferencing full-frame in-memory volume: {view.name}/{job.aug_id}")
                try:
                    for model_name, yolo in yolo_models:
                        _ensure_baseline_workspaces(str(model_name), view)
                        if bool(async_prediction_accumulation_active):
                            handle = predict_in_memory_volume_and_submit_accumulation(
                                model=yolo,
                                prediction_volume=prediction_ref,
                                num_frames=view.num_slices,
                                out_size=args.imgsz,
                                cfg=pred_cfg,
                                view_union_mm=baseline_union_by_model_view[(model_name, view.name)],
                                view_confmap_mm=baseline_confmap_by_model_view[(model_name, view.name)],
                                M_out_to_native=job.aff.M_out_to_src,
                                native_h=view.src_h,
                                native_w=view.src_w,
                                postprocess_executor=prediction_result_executor,
                                streaming_cleanup_enabled=bool(single_angle_streaming_cleanup_active),
                                streaming_cleanup_min_conf=float(args.min_conf),
                                streaming_cleanup_min_radius=_view_native_slice_min_radius(view, float(args.min_radius)),
                                slice_locks=baseline_slice_locks_by_model_view.get((str(model_name), str(view.name))),
                            )
                            _submit_prediction_accumulation_join(handle, {
                                'kind': 'fullframe',
                                'model_name': str(model_name),
                                'view': view,
                                'job': job,
                                'yolo': yolo,
                            })
                        else:
                            pred_stats = predict_in_memory_volume_and_accumulate(
                                model=yolo,
                                prediction_volume=prediction_ref,
                                num_frames=view.num_slices,
                                out_size=args.imgsz,
                                cfg=pred_cfg,
                                view_union_mm=baseline_union_by_model_view[(model_name, view.name)],
                                view_confmap_mm=baseline_confmap_by_model_view[(model_name, view.name)],
                                M_out_to_native=job.aff.M_out_to_src,
                                native_h=view.src_h,
                                native_w=view.src_w,
                                postprocess_workers=predict_postprocess_workers,
                                streaming_cleanup_enabled=bool(single_angle_streaming_cleanup_active),
                                streaming_cleanup_min_conf=float(args.min_conf),
                                streaming_cleanup_min_radius=_view_native_slice_min_radius(view, float(args.min_radius)),
                                slice_locks=baseline_slice_locks_by_model_view.get((str(model_name), str(view.name))),
                            )
                            if offload_between_jobs_enabled():
                                offload_yolo_from_gpu(yolo)
                            view_prediction_stats[str(view.summary_family)] = int(view_prediction_stats.get(str(view.summary_family), 0)) + int(pred_stats.get('prediction_count', 0))

                            remaining_key = (model_name, view.name)
                            fullframe_remaining[remaining_key] = int(fullframe_remaining.get(remaining_key, 0)) - 1
                            if int(fullframe_remaining.get(remaining_key, 0)) == 0:
                                _submit_view_prepare(model_name, view)
                finally:
                    close_prediction_volume_ref(prediction_ref, keep_temp=bool(keep_temp_artifacts))
                    _pump_prediction_volume_build_queue()
                continue

            if (not multi_gpu_active) and ready_tile_infer:
                model_name, view, tile_job, prediction_ref = ready_tile_infer.popleft()
                ready_key = (str(model_name), str(view.name), str(tile_job.tile_id))
                if ready_key in tile_inference_done:
                    close_prediction_volume_ref(prediction_ref, keep_temp=bool(keep_temp_artifacts))
                    continue

                print(f"Inferencing tile in-memory volume: {model_name}/{view.name}/{tile_job.tile_id}")
                tile_shape = (int(view.num_slices), int(view.src_h), int(view.src_w))
                tile_mask_path = temp_dir / 'tile_volumes' / model_name / view.name / f'{tile_job.tile_id}.u8.dat'
                tile_conf_path = temp_dir / 'tile_volumes' / model_name / view.name / f'{tile_job.tile_id}.confmap.u8.dat'
                tile_mask_path.parent.mkdir(parents=True, exist_ok=True)

                tile_mask_mm = allocate_workspace_array(
                    shape=tile_shape,
                    dtype=np.uint8,
                    path=tile_mask_path,
                    desc=f'{model_name}/{view.name}/{tile_job.tile_id} raw tile volume',
                    prefer_memory=True,
                )
                if float(args.min_conf) > 0.0:
                    tile_conf_mm = allocate_workspace_array(
                        shape=tile_shape,
                        dtype=np.uint8,
                        path=tile_conf_path,
                        desc=f'{model_name}/{view.name}/{tile_job.tile_id} raw tile confidence workspace',
                        prefer_memory=True,
                    )
                    tile_conf_store_path: Optional[Path] = tile_conf_path
                else:
                    tile_conf_mm = None
                    tile_conf_store_path = None

                yolo = yolo_by_model_name[str(model_name)]
                try:
                    if bool(async_prediction_accumulation_active):
                        handle = predict_in_memory_volume_and_submit_accumulation(
                            model=yolo,
                            prediction_volume=prediction_ref,
                            num_frames=view.num_slices,
                            out_size=int(args.imgsz),
                            cfg=pred_cfg,
                            view_union_mm=tile_mask_mm,
                            view_confmap_mm=tile_conf_mm,
                            M_out_to_native=tile_job.M_out_to_src,
                            native_h=view.src_h,
                            native_w=view.src_w,
                            postprocess_executor=prediction_result_executor,
                            streaming_cleanup_enabled=bool(single_angle_streaming_cleanup_active),
                            streaming_cleanup_min_conf=float(args.min_conf),
                            streaming_cleanup_min_radius=_view_native_slice_min_radius(view, float(args.min_radius)),
                        )
                        _submit_prediction_accumulation_join(handle, {
                            'kind': 'tile',
                            'model_name': str(model_name),
                            'view': view,
                            'tile_job': tile_job,
                            'tile_mask_mm': tile_mask_mm,
                            'tile_conf_mm': tile_conf_mm,
                            'tile_mask_path': tile_mask_path,
                            'tile_conf_path': tile_conf_store_path,
                            'yolo': yolo,
                        })
                    else:
                        pred_stats = predict_in_memory_volume_and_accumulate(
                            model=yolo,
                            prediction_volume=prediction_ref,
                            num_frames=view.num_slices,
                            out_size=int(args.imgsz),
                            cfg=pred_cfg,
                            view_union_mm=tile_mask_mm,
                            view_confmap_mm=tile_conf_mm,
                            M_out_to_native=tile_job.M_out_to_src,
                            native_h=view.src_h,
                            native_w=view.src_w,
                            postprocess_workers=predict_postprocess_workers,
                            streaming_cleanup_enabled=bool(single_angle_streaming_cleanup_active),
                            streaming_cleanup_min_conf=float(args.min_conf),
                            streaming_cleanup_min_radius=_view_native_slice_min_radius(view, float(args.min_radius)),
                        )
                        if offload_between_jobs_enabled():
                            offload_yolo_from_gpu(yolo)
                        tile_inference_done.add(ready_key)
                        view_prediction_stats[str(view.summary_family)] = int(view_prediction_stats.get(str(view.summary_family), 0)) + int(pred_stats.get('prediction_count', 0))

                        if int(pred_stats.get('frames_with_predictions', 0)) <= 0:
                            close_memmap_array(tile_mask_mm)
                            close_memmap_array(tile_conf_mm)
                            if not keep_temp_artifacts:
                                try:
                                    tile_mask_path.unlink(missing_ok=True)
                                except Exception:
                                    pass
                                if tile_conf_path is not None:
                                    try:
                                        tile_conf_path.unlink(missing_ok=True)
                                    except Exception:
                                        pass
                            _mark_tile_staged(str(model_name), str(view.name), str(tile_job.config_id), str(tile_job.tile_id))
                            continue

                        task = TilePostprocessTask(
                            model_name=str(model_name),
                            view_name=str(view.name),
                            config_id=str(tile_job.config_id),
                            tile_id=str(tile_job.tile_id),
                            tile_mask_mm=tile_mask_mm,
                            tile_confmap_mm=tile_conf_mm,
                            tile_mask_path=tile_mask_path,
                            tile_confmap_path=tile_conf_store_path,
                            precleaned_slice_cleanup=bool(single_angle_streaming_cleanup_active),
                        )
                        fut = tile_postprocess_executor.submit(
                            postprocess_tile_volume_after_inference,
                            task,
                            view=view,
                            min_conf=float(args.min_conf),
                            min_radius=float(args.min_radius),
                            keep_temp=bool(keep_temp_artifacts),
                            slice_workers=int(tile_slice_postprocess_workers),
                        )
                        tile_cleanup_futures[fut] = (str(model_name), str(view.name), str(tile_job.config_id), str(tile_job.tile_id))
                finally:
                    close_prediction_volume_ref(prediction_ref, keep_temp=bool(keep_temp_artifacts))
                    _pump_prediction_volume_build_queue()
                continue

            waitables: List[Future] = list(pending_prediction_volume_futures)
            waitables.extend(list(prediction_accumulation_futures.keys()))
            waitables.extend(list(view_processing_futures.keys()))
            waitables.extend(list(tile_cleanup_futures.keys()))
            waitables.extend(list(tile_finalize_futures.keys()))
            waitables.extend(list(tile_config_gate_futures.keys()))
            waitables.extend(list(tile_consolidation_futures.keys()))
            if not waitables:
                _flush_ready_postprocessed_tiles()
                _pump_prediction_volume_build_queue()
                if multi_gpu_active and _process_inference_outstanding():
                    # GPU worker processes are still inferencing but no CPU-side future is pending;
                    # block briefly on the process result queue so the loop wakes on the next result.
                    _wait_for_one_process_result(timeout=0.5)
                    _check_gpu_workers_alive()
                    continue
                if (
                    not pending_prediction_build_jobs and
                    not pending_prediction_volume_futures and
                    not prediction_accumulation_futures and
                    not _process_inference_outstanding() and
                    not ready_fullframe and
                    not ready_tile_infer and
                    not tile_finalize_futures and
                    not tile_config_gate_futures and
                    not tile_cleanup_futures and
                    not tile_consolidation_futures and
                    not view_processing_futures
                ):
                    break
                continue
            _log_scheduler_wait_state()
            # Under multi-GPU, also poll the process result queue periodically while CPU-side futures
            # run, so completed inference results are unioned without waiting for a future to finish.
            wait(waitables, timeout=(0.1 if multi_gpu_active else None), return_when=FIRST_COMPLETED)

    finally:
        if sys.exc_info()[0] is not None:
            # v13.2.2 bug #7 (completion): the wait=True shutdowns below block on render
            # tasks parked in wait_for_volume_ready() for still-running streaming
            # producers. Abort the producers FIRST on the error path, or a failure during
            # the decode-overlap window stalls teardown for the remaining multi-hour
            # decode before the exception can even propagate to __main__.
            abort_streaming_producers('scheduler error teardown')
            # v13.2.2 bug #3 (completion): queued eagerly pre-staged prediction sources
            # were never handed to a predict call, so nothing else closes them — their
            # producer threads would otherwise keep VRAM-staged batches and ledger
            # reservations alive (and spin) for the whole teardown.
            for _view, _job, ref in list(ready_fullframe):
                close_prediction_volume_ref(ref, keep_temp=bool(keep_temp_artifacts))
            ready_fullframe.clear()
            for _model_name, _view, _tile_job, ref in list(ready_tile_infer):
                close_prediction_volume_ref(ref, keep_temp=bool(keep_temp_artifacts))
            ready_tile_infer.clear()
        if multi_gpu_active:
            _shutdown_gpu_worker_processes()
        prediction_volume_executor.shutdown(wait=True)
        prediction_join_executor.shutdown(wait=True)
        prediction_result_executor.shutdown(wait=True)
        parent_postprocess_executor.shutdown(wait=True)
        tile_postprocess_executor.shutdown(wait=True)
        if prediction_render_executor is not None:
            try:
                prediction_render_executor.shutdown(wait=True, cancel_futures=True)
            except TypeError:
                prediction_render_executor.shutdown(wait=True)
        set_interpolation_process_executor(None, 0)
        if interpolation_process_executor is not None:
            try:
                interpolation_process_executor.shutdown(wait=True, cancel_futures=False)
            except TypeError:
                interpolation_process_executor.shutdown(wait=True)

    _drain_completed_prediction_volume_futures()
    _drain_completed_prediction_accumulation_futures()
    _drain_completed_background_futures()

    if preprocess_streaming_active:
        print('Ensuring streaming preprocessing producers have completed before final output/backprojection stages.')
        wait_for_volume_ready(volume_rgb)

    for cache_name, cache_mm in list(view_frame_caches.items()):
        close_memmap_array(cache_mm)
        cache_path = view_frame_cache_paths.get(cache_name)
        if not keep_temp_artifacts and cache_path is not None:
            try:
                cache_path.unlink(missing_ok=True)
            except Exception:
                pass
    view_frame_caches.clear()
    view_frame_cache_paths.clear()

    if not bool(keep_temp_artifacts):
        swept_mkvs = purge_remaining_temporary_mkvs(temp_dir, keep_temp=False)
        if int(swept_mkvs) > 0:
            print(f'Final legacy temporary MKV sweep removed {int(swept_mkvs)} leftover file(s).')
        spec_notes.append(
            'No prediction MKVs are produced by the v12 in-memory path. A best-effort final sweep still removes '
            f'{int(swept_mkvs)} legacy/interrupted scratch MKV file(s) when YOLO_TTA_KEEP_TEMP is disabled.'
        )
    else:
        spec_notes.append('YOLO_TTA_KEEP_TEMP retained scratch artifacts; the v12.2.0 in-memory inference path itself does not create prediction MKVs.')

    # v13.2.4 (task #1, ruling A1): radial/tilted results are backprojected DIRECTLY into the
    # original source geometry (single resample) instead of the working geometry.
    source_output_shape_tyx = (int(input_T), int(input_H), int(input_W))
    final_backprojection_jobs: List[ViewBackprojectionQueueJob] = []
    for view in views:
        if (view.family != 'radial' and not is_tilted_view(view)):
            continue
        for model_name, _ in yolo_models:
            if view.name in view_volumes_by_model[model_name]:
                continue
            if view.family == 'radial':
                native_source = radial_native_output_by_model[model_name].get(view.name)
            else:
                native_source = tilted_native_output_by_model[model_name].get(view.name)
            if native_source is None:
                native_source = native_view_support_by_model[model_name].get(view.name)
            if native_source is None:
                continue
            # v13.2.4 (task #2): with --save_nrrd, this view's component layers were already
            # projected into source geometry at materialization time (fullframe YOLO + per-pass
            # bridge deltas + any tile layers), and projection commutes exactly with union — so
            # the final projected volume is their OR, skipping a second full backprojection.
            if bool(nrrd_layers_needed):
                view_projected_layer_refs = [
                    ref for ref in nrrd_layer_refs
                    if str(getattr(ref, 'view_name', '')) == str(view.name)
                ]
                if view_projected_layer_refs and all(
                    tuple(int(v) for v in ref.shape) == source_output_shape_tyx
                    for ref in view_projected_layer_refs
                ):
                    print(
                        f'Final {model_name}/{view.name}: assembling projected volume as the union of '
                        f'{len(view_projected_layer_refs)} already-projected NRRD layer(s) '
                        f'(v13.2.4 task #2; no second backprojection).'
                    )
                    projected_volume = assemble_view_volume_from_projected_layers(
                        view_projected_layer_refs,
                        source_output_shape_tyx,
                        temp_dir / 'view_volumes' / str(model_name) / f'{view.name}.u8.dat',
                        f'Assembling final {model_name}/{view.name} from projected layers',
                        prefer_memory=True,
                        workers=int(slice_postprocess_workers),
                    )
                    view_volumes_by_model[model_name][view.name] = projected_volume
                    continue
            final_backprojection_jobs.append(ViewBackprojectionQueueJob(
                model_name=str(model_name),
                view=view,
                native_source=native_source,
                out_path=temp_dir / 'view_volumes' / str(model_name) / f'{view.name}.u8.dat',
                desc=f'Backprojecting final {model_name}/{view.name}',
                # v13.1.0 (spec): --min_radius is already applied in the view-native plane before
                # backprojection, so the queue no longer re-filters after backprojection.
                min_radius=0.0,
                workers=1,
                out_shape_tyx=source_output_shape_tyx,
            ))

    if final_backprojection_jobs:
        # v12.2.11: backprojection is CPU-only, so do not halve the CPU budget for a
        # nonexistent GPU slot.  Run one set at a time with the full slice-worker budget.
        per_backproject_workers = max(1, int(slice_postprocess_workers))
        final_backprojection_jobs = [
            ViewBackprojectionQueueJob(
                model_name=job.model_name,
                view=job.view,
                native_source=job.native_source,
                out_path=job.out_path,
                desc=job.desc,
                min_radius=job.min_radius,
                workers=int(per_backproject_workers),
                out_shape_tyx=job.out_shape_tyx,
            )
            for job in final_backprojection_jobs
        ]
        print(
            f'Final radial/tilted backprojection queue: tasks={len(final_backprojection_jobs)}, '
            f'max_active=1 CPU-only, per-set CPU workers={int(per_backproject_workers)}'
        )
        backproject_queue = HybridBackprojectionQueue(
            cpu_workers=int(per_backproject_workers),
        )
        for model_name_done, view_name_done, projected_volume in backproject_queue.run(final_backprojection_jobs):
            view_volumes_by_model[model_name_done][view_name_done] = projected_volume

    output_manager.reap_completed()

    print('\n=== Building final single-model view union after the global view union ===')
    # v13.2.4 (task #1, ruling A1): the union is assembled at ORIGINAL SOURCE dimensions.
    # Cartesian working stacks are restored working->source with one resample while merging;
    # radial/tilted volumes arrive already backprojected to source geometry. Void fill,
    # Gaussian smoothing (sigma in SOURCE voxels), and --keep_objects all run at source dims.
    final_union_mm = assemble_final_union_after_view_union(
        view_volumes_by_model=view_volumes_by_model,
        T=T,
        H=H,
        W=W,
        disable_multiplanar=None,
        out_path=temp_dir / 'final_union_volume.u8.dat',
        temp_dir=temp_dir,
        out_shape_tyx=source_output_shape_tyx,
        enable_3d_void_fill=bool(args.enable_3d_void_fill),
        keep_temp=bool(keep_temp_artifacts),
        prefer_memory=True,
        workers=slice_postprocess_workers,
    )

    if bool(nrrd_layers_needed):
        pre_smoothing_ref = materialize_nrrd_global_layer(
            final_union_mm,
            model_name=str(model_name),
            source='global',
            mask_kind='union',
            pass_index=0,
            stage='pre_smoothing',
            description='Global union after all active view/tile layers and optional 3D void fill, before Gaussian smoothing and keep_objects.',
            temp_dir=temp_dir,
            workers=int(slice_postprocess_workers),
        )
        if pre_smoothing_ref is not None:
            nrrd_layer_refs.append(pre_smoothing_ref)

    gaussian_smoothing_stats: Optional[Dict[str, object]] = None
    if bool(gaussian_smoothing_enabled):
        print('\n=== Applying Gaussian smoothing ===')
        gaussian_smoothing_stats = apply_gaussian_smoothing_inplace(
            final_union_mm,
            sigma=float(gaussian_smoothing_sigma),
            passes=int(gaussian_smoothing_passes),
            temp_dir=temp_dir,
            keep_temp=bool(keep_temp_artifacts),
            prefer_memory=True,
            workers=slice_postprocess_workers,
            nrrd_layers=nrrd_layer_refs if bool(nrrd_layers_needed) else None,
            nrrd_model_name=str(model_name),
        )

    keep_objects_stats: Optional[Dict[str, int]] = None
    if int(args.keep_objects) > 0:
        print(f'\n=== Keeping largest {int(args.keep_objects)} final object(s) ===')
        keep_objects_stats = apply_keep_largest_objects_inplace(
            final_union_mm,
            int(args.keep_objects),
            temp_dir=temp_dir,
            keep_temp=bool(keep_temp_artifacts),
            prefer_memory=True,
            workers=slice_postprocess_workers,
        )

    final_output_mask_mm = final_union_mm
    output_volume_rgb = input_volume_rgb
    output_T, output_H, output_W = int(input_T), int(input_H), int(input_W)
    # v13.2.4 (task #1, ruling A1): the final union is already assembled at source dimensions,
    # so this tail restore is an identity no-op kept purely as a shape safety net.
    if tuple(int(v) for v in final_union_mm.shape) != (output_T, output_H, output_W):
        print('\n=== Restoring final mask to original input geometry for default outputs ===')
        final_output_mask_mm = restore_mask_volume_to_original_shape(
            final_union_mm,
            (output_T, output_H, output_W),
            temp_dir / 'final_union_original_geometry.u8.dat',
            workers=int(slice_postprocess_workers),
            prefer_memory=True,
        )
    if bool(nrrd_layers_needed):
        # v13.2.0: the Global_final_output single-layer NRRD is materialized here (it was previously
        # appended inside the now-removed mega decomposed writer) and the sink writes it in the
        # background while the rest of the default outputs are produced.
        final_output_ref = materialize_nrrd_global_layer(
            final_output_mask_mm,
            model_name=str(model_name),
            source='global',
            mask_kind='union',
            pass_index=0,
            stage='final_output_after_all_postprocessing',
            description='Final binary output after view/tile union, optional smoothing, optional keep_objects, and geometry restoration. Not intended for recomposition.',
            temp_dir=temp_dir,
            workers=int(slice_postprocess_workers),
        )
        if final_output_ref is not None:
            nrrd_layer_refs.append(final_output_ref)

    final_output_volume_for_low_quality = output_volume_rgb
    final_paths: Dict[str, Path] = {}

    if bool(troubleshooting_outputs_enabled):
        print('\n=== Scheduling v12.2.0 troubleshooting overlays ===')
        consolidated_tile_masks_for_model = {
            str(view_name): mask
            for (tile_model, view_name), mask in tile_accumulator_by_parent.items()
            if str(tile_model) == str(model_name)
        }
        troubleshooting_paths, troubleshooting_futures = collect_troubleshooting_overlay_futures(
            output_manager.executor,
            volume_rgb=volume_rgb,
            model_name=str(model_name),
            views=inference_views,
            native_view_support=native_view_support_by_model.get(str(model_name), {}),
            consolidated_tile_masks=consolidated_tile_masks_for_model,
            out_dir=out_dir,
            stem=input_path.stem,
            fps=fps,
            show_progress=False,
        )
        final_paths.update(troubleshooting_paths)
        output_manager.submit(BackgroundOutputSubmission(
            label='troubleshooting overlays',
            result_paths=troubleshooting_paths,
            futures=troubleshooting_futures,
            resources=[],
        ))

    print('\n=== Scheduling final outputs in background ===')
    final_output_paths, final_futures = collect_pipeline_output_futures(
        output_manager.executor,
        volume_rgb=output_volume_rgb,
        mask_u8=final_output_mask_mm,
        out_dir=out_dir,
        stem=input_path.stem,
        fps=fps,
        save_binary_pattern_value=args.save_binary,
        save_labels_pattern_value=args.save_labels,
        save_nrrd_flag=bool(args.save_nrrd),
        tag=None,
        frame_workers=output_frame_workers,
        show_progress=False,
        nrrd_layer_refs=nrrd_layer_refs if bool(args.save_nrrd) else None,
        nrrd_temp_dir=temp_dir,
        nrrd_workers=output_frame_workers,
    )
    final_paths.update(final_output_paths)
    output_manager.submit(BackgroundOutputSubmission(
        label='final outputs',
        result_paths=final_output_paths,
        futures=final_futures,
        resources=[],
    ))

    if bool(low_quality_requested):
        print('\n=== Scheduling low-quality isotropic outputs in background ===')
        low_quality_paths, low_quality_futures = collect_low_quality_output_futures(
            output_manager.executor,
            volume_gray=final_output_volume_for_low_quality,
            mask_u8=final_output_mask_mm,
            out_dir=out_dir,
            stem=input_path.stem,
            fps=fps,
            downbin_specs=low_quality_downbin_specs,
            temp_dir=temp_dir,
            save_nrrd=bool(args.save_nrrd),
            workers=output_workers,
            show_progress=False,
        )
        final_paths.update(low_quality_paths)
        output_manager.submit(BackgroundOutputSubmission(
            label='low-quality outputs',
            result_paths=low_quality_paths,
            futures=low_quality_futures,
            resources=[],
        ))

    voxel_volume = None
    if bool(args.voxel_volume):
        voxel_counts = np.zeros((int(final_output_mask_mm.shape[0]),), dtype=np.int64)

        def _count_voxels(z: int) -> None:
            voxel_counts[int(z)] = np.int64(np.count_nonzero(np.asarray(final_output_mask_mm[int(z)])))

        parallel_for_indices(
            int(final_output_mask_mm.shape[0]),
            _count_voxels,
            max_workers=choose_slice_parallel_workers(int(slice_postprocess_workers), int(final_output_mask_mm.shape[0])),
            desc='Counting voxel_volume',
        )
        voxel_volume = int(np.sum(voxel_counts, dtype=np.int64))

    output_manager.wait()

    nrrd_manifest_path: Optional[Path] = None
    nrrd_layer_files_written = 0
    nrrd_low_quality_layer_files_written = 0
    layer_sink = nrrd_layer_sink()
    if layer_sink is not None:
        print('\n=== Finishing single-layer NRRD writes ===')
        layer_sink.wait()
        nrrd_layer_files_written = int(layer_sink.layer_count())
        nrrd_low_quality_layer_files_written = int(layer_sink.low_quality_layer_count())
        nrrd_manifest_path = layer_sink.write_manifest()
        layer_sink.shutdown()
        set_nrrd_layer_sink(None)
        final_paths['nrrd_dir'] = nrrd_dir
        if nrrd_manifest_path is not None:
            final_paths['nrrd_manifest'] = nrrd_manifest_path

    if bool(args.save_images):
        print('\n=== Saving active-view image sequences ===')
        for view in views:
            image_dir = write_view_images(
                volume_rgb=volume_rgb,
                view=view,
                out_dir=out_dir,
                stem=input_path.stem,
                workers=output_frame_workers,
                show_progress=False,
            )
            final_paths[f'{view.name}_images_dir'] = image_dir

    if bool(nrrd_layers_needed):
        spec_notes.append(
            f'NRRD decomposition (v13.2.0): {int(nrrd_layer_files_written)} single-layer NRRD file(s) written to '
            f'{nrrd_dir} as one uint8 binary mask per component layer (X,Y,t source geometry), named '
            '{Filestem}_{ViewToken|Global}_{layer}.seg.nrrd with the model name dropped, tagged as a 3D Slicer '
            'segmentation (v13.2.3: segment named after the file, deterministic per-layer color). Each layer is created during '
            'the intermediate pipeline steps (e.g. the Transverse layer compresses while Tiled Transverse is still '
            'inferencing) and the Global_union_presmoothing layer is written while smoothing runs; a single '
            f'{input_path.stem}_nrrd_manifest.json sidecar lists every written layer. The previous mega 4D '
            'decomposed NRRD (one file with a trailing list axis) has been removed.'
        )
        if int(nrrd_low_quality_layer_files_written) > 0:
            spec_notes.append(
                f'Low-quality NRRD decomposition (v13.2.1, bug #2): {int(nrrd_low_quality_layer_files_written)} '
                'downbinned single-layer NRRD file(s) written under low_quality/<token>/nrrd/, mirroring the '
                'full-quality component layers per --save_low_quality_downbin spec and written on the same '
                'view-completion schedule. Each downbin has its own {Filestem}_nrrd_manifest.json with layer '
                'suffixes matching the full-quality nrrd/ folder.'
            )

    summary_path = write_summary_file(
        out_dir / f'{input_path.stem}_Summary.txt',
        command=shlex.join([str(x) for x in sys.argv]),
        input_path=input_path,
        out_dir=out_dir,
        scratch_dir=temp_dir,
        source_shape_x_y_t=(input_W, input_H, input_T),
        volume_shape=(T, H, W),
        fps=fps,
        model_paths=model_paths,
        view_names=[
            (
                f'{v.name} ({int(v.num_slices)} frames; centers {int(v.tilt_frame_start)}..{int(v.tilt_frame_stop)})'
                if is_tilted_view(v)
                else f'{v.name} ({int(v.num_slices)} frames)'
            )
            for v in views
        ],
        view_prediction_stats=view_prediction_stats,
        interpolation_stats=interpolation_stats,
        view_prediction_labels=view_prediction_labels,
        enable_3d_void_fill=bool(args.enable_3d_void_fill),
        gaussian_smoothing_stats=gaussian_smoothing_stats,
        keep_objects_stats=keep_objects_stats,
        voxel_volume=voxel_volume,
        final_paths=final_paths,
        augmentation_workers=augmentation_workers,
        slice_postprocess_workers=slice_postprocess_workers,
        interpolation_workers=interpolation_workers,
        output_workers=output_workers,
        spec_notes=spec_notes,
    )

    if final_output_mask_mm is not final_union_mm:
        close_memmap_array(final_output_mask_mm)
    close_memmap_array(final_union_mm)
    for model_support in native_view_support_by_model.values():
        for mm in model_support.values():
            close_memmap_array(mm)
        model_support.clear()
    for model_views in radial_native_output_by_model.values():
        for mm in model_views.values():
            close_memmap_array(mm)
        model_views.clear()
    for model_views in tilted_native_output_by_model.values():
        for mm in model_views.values():
            close_memmap_array(mm)
        model_views.clear()
    for model_views in view_volumes_by_model.values():
        for mm in model_views.values():
            close_memmap_array(mm)
        model_views.clear()
    for model_support in parent_mask_support_by_model.values():
        for mm in model_support.values():
            close_raw_store_or_memmap_volume(mm, keep_temp=bool(keep_temp_artifacts))
        model_support.clear()
    for model_support in parent_bridge_support_by_model.values():
        for mm in model_support.values():
            close_raw_store_or_memmap_volume(mm, keep_temp=bool(keep_temp_artifacts))
        model_support.clear()
    for mm in tile_config_accumulator_by_key.values():
        archive_or_delete_binary_volume_storage(
            mm,
            keep_temp=bool(keep_temp_artifacts),
            workers=int(tile_slice_postprocess_workers),
            desc='remaining tile config accumulator',
        )
    tile_config_accumulator_by_key.clear()
    for mm in tile_accumulator_by_parent.values():
        archive_or_delete_binary_volume_storage(
            mm,
            keep_temp=bool(keep_temp_artifacts),
            workers=int(tile_slice_postprocess_workers),
            desc='remaining consolidated tile accumulator',
        )
    tile_accumulator_by_parent.clear()
    for mm in tile_parent_mask_accumulator_by_parent.values():
        archive_or_delete_binary_volume_storage(
            mm,
            keep_temp=bool(keep_temp_artifacts),
            workers=int(tile_slice_postprocess_workers),
            desc='remaining parent-mask tile category accumulator',
        )
    tile_parent_mask_accumulator_by_parent.clear()
    for mm in tile_parent_bridge_accumulator_by_parent.values():
        archive_or_delete_binary_volume_storage(
            mm,
            keep_temp=bool(keep_temp_artifacts),
            workers=int(tile_slice_postprocess_workers),
            desc='remaining parent-bridge tile category accumulator',
        )
    tile_parent_bridge_accumulator_by_parent.clear()
    for mm in baseline_union_by_model_view.values():
        close_memmap_array(mm)
    for mm in baseline_confmap_by_model_view.values():
        close_memmap_array(mm)
    for _, yolo in yolo_models:
        unload_yolo_model(yolo)
    if volume_rgb is not input_volume_rgb:
        close_memmap_array(volume_rgb)
    close_memmap_array(input_volume_rgb)
    trim_cuda_memory()
    gc.collect()

    if not keep_temp_artifacts:
        try:
            for child in list(temp_dir.iterdir()):
                try:
                    if child.is_dir():
                        shutil.rmtree(child, ignore_errors=True)
                    else:
                        child.unlink(missing_ok=True)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            if temp_dir != out_dir / 'temp':
                shutil.rmtree(temp_dir, ignore_errors=True)
                temp_link = out_dir / 'temp'
                if temp_link.is_symlink():
                    temp_link.unlink(missing_ok=True)
        except Exception:
            pass

    print('\nDone.')
    print(f'Output dir: {out_dir}')
    print(f'Scratch dir: {temp_dir}')
    print(f"Final overlay: {final_paths['overlay']}")
    print(f'Summary: {summary_path}')


if __name__ == "__main__":
    try:
        main()
    except BaseException:
        # v13.2.2 bug #7: cancel background streaming producers so a failing run exits
        # promptly instead of blocking interpreter shutdown behind a multi-hour decode.
        abort_streaming_producers('fatal error in main()')
        raise
